#define IsDigit(x) ((x) >= '0' && (x) <= '9')
using namespace std;

int n, m;
int dist[5001], b[201][5001], in_r[201][5001], in_l[201][5001], d[5002][5002];
struct Elem{
	int b, id;
	Elem() {}
	Elem(int x, int y)
		: b(x), id(y)
	{}
}s[5000];


int Read(void)
{
	int c, ret(0);

	c = getchar();
	while (!IsDigit(c))
		c = getchar();
	do
		ret = ret * 10 + c - '0';
	while ((c = getchar()) && IsDigit(c));
	return ret;
}


int main()
{
	int pos, l, r, ans(0), t;

	n = Read();
	m = Read();
	for (int i = 2; i <= n; ++i)
		dist[i] = Read() + dist[i - 1];
	for (int j = 1; j <= n; ++j)
		for (int i = 1; i <= m; ++i)
			b[i][j] = Read();
	for (int i = 1; i <= m; ++i) {
		pos = 0;
		s[pos++] = Elem(b[i][1], 1);
		for (int j = 2; j <= n; ++j) {
			while (pos && b[i][j] >= s[pos - 1].b) {
				in_r[i][s[pos - 1].id] = j - 1;
				--pos;
			}
			s[pos++] = Elem(b[i][j], j);
		}
		while (pos) {
			in_r[i][s[pos - 1].id] = n;
			--pos;
		}
		s[pos++] = Elem(b[i][n], n);
		for (int j = n - 1; j; --j) {
			while (pos && b[i][j] >= s[pos - 1].b) {
				in_l[i][s[pos - 1].id] = j + 1;
				--pos;
			}
			s[pos++] = Elem(b[i][j], j);
		}
		while (pos) {
			in_l[i][s[pos - 1].id] = 1;
			--pos;
		}
	}
	for (int i = 1; i <= m; ++i)
		for (int j = 1; j <= n; ++j) {
			l = in_l[i][j];
			r = in_r[i][j];
			t = b[i][j];
			d[l][j] += t;
			d[l][r + 1] -= t;
			d[j + 1][j] -= t;
			d[j + 1][r + 1] += t;
		}
	for (int i = 1; i <= n + 1; ++i)
		for (int j = i; j <= n + 1; ++j)
			d[i][j] += d[i - 1][j];
	for (int i = 1; i <= n + 1; ++i)
		for (int j = i; j <= n + 1; ++j)
			d[i][j] += d[i][j - 1];
	for (int i = 1; i <= n; ++i)
		for (int j = i; j <= n; ++j)
			ans < (t = d[i][j] - dist[j] + dist[i]) && (ans = t);
	printf("%d\n", ans);
	return 0;
}

