ll f(int s)
{
    for (int i = 0; i < m; i++)
    {
        d[i] = 0;
    }
    ll sum = 0;
    ll res = 0;
    for (int i = s; i < n; i++)
    {
        ll t = 0;
        for (int cur = 0; cur < m; cur++)
        {
            d[cur] = max(d[cur], c[i][cur]);
            t += d[cur];
        }
        res = max(res, t - sum);
        sum += a[i];
    }
    return res;
}

