class RangeAdd
{
private:
    vector<vector<long long> > data;
public:
    RangeAdd(int h, int w){
        data.assign(h+1, vector<long long>(w+1, 0));
    }
    void add(int y1, int x1, int y2, int x2, long long val){
        data[y1][x1] += val;
        data[y1][x2+1] -= val;
        data[y2+1][x1] -= val;
        data[y2+1][x2+1] += val;
    }
    void get(vector<vector<long long> >& ans){
        int h = data.size() - 1;
        int w = data[0].size() - 1;
        ans.assign(h, vector<long long>(w));
        for(int y=0; y<h; ++y){
            ans[y][0] = data[y][0];
            for(int x=1; x<w; ++x)
                ans[y][x] = ans[y][x-1] + data[y][x];
        }
        for(int y=1; y<h; ++y){
            for(int x=0; x<w; ++x){
                ans[y][x] += ans[y-1][x];
            }
        }
    }
};

int main()
{
    int n, m;
    cin >> n >> m;
    vector<int> a(n-1);
    for(int i=0; i<n-1; ++i)
        cin >> a[i];
    vector<vector<int> > b(m, vector<int>(n));
    for(int i=0; i<n; ++i){
        for(int j=0; j<m; ++j){
            cin >> b[j][i];
        }
    }

    RangeAdd ra(n, n);
    for(int i=0; i<m; ++i){
        vector<pair<int, int> > v(n);
        for(int j=0; j<n; ++j)
            v[j] = make_pair(b[i][j], j);
        sort(v.rbegin(), v.rend());

        set<int> s;
        s.insert(-1);
        s.insert(n);
        for(const auto& p : v){
            int val = p.first;
            int k = p.second;
            auto it = s.lower_bound(k);
            int b = *it;
            int a = *--it;

            ra.add(a+1, k, k, b-1, val);
            s.insert(k);
        }
    }

    vector<vector<long long> > v;
    ra.get(v);
    long long ans = 0;
    for(int i=0; i<n; ++i){
        ans = max(ans, v[i][i]);
        long long d = 0;
        for(int j=i+1; j<n; ++j){
            d += a[j-1];
            ans = max(ans, v[i][j] - d);
        }
    }
    cout << ans << endl;

    return 0;
}

