typedef long long int LL;
const int Max_N(5050);
const int Max_M(205);

/*
如果走到的店铺的最左点是l、最右点是r，收益 = Sum{max{B[i][j]   |   l <= i <= r}   |   1 <= j <= M} - Dist(l, r)
对于每个1 <= j <= M，考虑第j种优惠券在每个店铺上产生的价值序列B[1 ~ N][j]，把笛卡尔树建出来，那么一个B[i][j]产生的贡献是一个矩形
直接矩形加法预处理即可 
*/

int N, M, B[Max_N][Max_M], L[Max_N], R[Max_N];
LL V[Max_N][Max_N], Dist[Max_N], Ans;

inline void insert(int x1, int x2, int y1, int y2, int v)
{
	V[x1][y1] += v, V[x2 + 1][y1] -= v, V[x1][y2 + 1] -= v, V[x2 + 1][y2 + 1] += v;
}

int main()
{
	scanf("%d%d", &N, &M);
	for (int i = 2;i <= N;++i)
		scanf("%lld", Dist + i), Dist[i] += Dist[i - 1];
	for (int i = 1;i <= N;++i)
		for (int j = 1;j <= M;++j)
			scanf("%d", B[i] + j);
	for (int j = 1;j <= M;++j)
	{
		stack<int> S;
		for (int i = 1;i <= N;++i)
		{
			while (S.empty() == false && B[S.top()][j] < B[i][j])
				R[S.top()] = i - 1, S.pop();
			S.push(i);
		}
		while (S.empty() == false)
			R[S.top()] = N, S.pop();
		for (int i = N;i >= 1;--i)
		{
			while (S.empty() == false && B[S.top()][j] <= B[i][j])
				L[S.top()] = i + 1, S.pop();
			S.push(i);
		}
		while (S.empty() == false)
			L[S.top()] = 1, S.pop();
		for (int i = 1;i <= N;++i)
			insert(L[i], i, i, R[i], B[i][j]);
	}
	for (int l = 1;l <= N;++l)
		for (int r = 1;r <= N;++r)
		{
			V[l][r] += V[l - 1][r] + V[l][r - 1] - V[l - 1][r - 1];
			if (l <= r)
				Ans = max(Ans, V[l][r] - (Dist[r] - Dist[l]));
		}
	printf("%lld\n", Ans);
	return 0;
}

