const lli N=10000;
const lli LN=14;

struct rmq {
  static int ilog2(int x){ return 31 - __builtin_clz(x); }
  rmq(){
    FOR(i,LN) FOR(j,N) A[i][j]=-1;
  }
  lli n;
  lli A[LN][N];

  inline void build(){
    FOR(a, LN) if(a) {
      lli sa=1<<(a-1);
      FOR(i, n-(1<<a)) A[a][i] = max(A[a-1][i], A[a-1][i+sa]);
    }
  }

  inline lli query(lli x1, lli x2) {
    lli dx = x2-x1+1;
    lli sx = ilog2(dx);
    lli ax = 1<<sx;
    return max(A[sx][x1],A[sx][x2+1-ax]);
  };

};

lli n,m;
lli A[10000];
lli S[10000];
lli B[10000][200];
rmq R[200];
lli ans=0;

void calc(lli l,lli r,lli optL,lli optR){
  lli mi = (l+r)/2;
  lli optM=optL; lli curval=0;
  FORU(k, max(mi,optL-2), min(optR+2,n-1)){
    lli val = 0;
    FOR(j,m) val += R[j].query(mi, k);
    val -= (S[k]-S[mi]);
    if(val > curval) { curval = val; optM = k; }
  }
  ans = max(ans, curval);
  if(l<r-1) {
    calc(l,mi,optL,optM);
    calc(mi,r,optM,optR);
  }
}

int main(){
  ios::sync_with_stdio(0); cin.tie(0);
  cin >> n >> m;
  FOR(i,10000) A[i]=(1ll<<50);
  FOR(i,n-1) cin >> A[i];
  FOR(i,n+100) S[i+1]=S[i]+A[i];
  FOR(i,n) FOR(j,m) cin >> B[i][j];
  FOR(j,m) {
    R[j].n = n+1;
    FOR(i,n) R[j].A[0][i] = B[i][j];
    R[j].build();
  }
  calc(0,n-1,0,n-1);
  cout << ans << endl;

  return 0;
}

