#define repu(i,x,y) for (int i=x; i<=y; ++i)
#define repd(i,x,y) for (int i=x; i>=y; --i)
using namespace std;

typedef long long LL;
int n,m,a[210][5010];
LL d[5010],sum[5010][5010],ans;

int getint()
{
    char ch;
    while (!isdigit(ch=getchar()));
    int x=ch-'0';
    for (; isdigit(ch=getchar()); x=x*10+ch-'0');
    return x;
}

void add(int x1,int x2,int y1,int y2,int w)
{
    sum[x1][y1]+=w;
    sum[x1][y2+1]-=w;
    sum[x2+1][y1]-=w;
    sum[x2+1][y2+1]+=w;
}

void solve(int *a)
{
    static int l[5010],r[5010],stk[5010],top;
    stk[top=0]=0;
    repu(i,1,n)
    {
        for (; top && a[stk[top]]<a[i]; --top);
        l[i]=stk[top]+1,stk[++top]=i;
    }
    stk[top=0]=n+1;
    repd(i,n,1)
    {
        for (; top && a[stk[top]]<=a[i]; --top);
        r[i]=stk[top]-1,stk[++top]=i;
        add(i,r[i],l[i],i,a[i]);
    }
}

int main()
{
    scanf("%d%d",&n,&m);
    repu(i,2,n)
        d[i]=d[i-1]+getint();
    repu(i,1,n)
        repu(j,1,m)
            a[j][i]=getint();
    repu(i,1,m)
        solve(a[i]);
    repu(i,1,n)
        repu(j,1,i+1)
        {
            sum[i][j]+=sum[i-1][j]+sum[i][j-1]-sum[i-1][j-1];
            ans=max(ans,sum[i][j]-d[i]+d[j]);
        }
    printf("%lld\n",ans);
    return 0;
}

