struct node{
    node *left, *right;
    ll ans, rem;
    int l, r, m;
    node() {
        l = r = NULL;
        ans = 0, rem = 0;
    }
    void Build(int u, int v) {
        l = u, r = v;
        if (u == v)
            return;
        m = u + v >> 1;
        left = new node();
        right = new node();
        left->Build(l, m);
        right->Build(m + 1, r);
    }
    void Push() {
        left->ans += rem;
        left->rem += rem;
        right->ans += rem;
        right->rem += rem;
        rem = 0;
    }
    void Update(int u, int v, ll val) {
        if (l > v || r < u)
            return;
        if (u <= l && r <= v) {
            rem += val;
            ans += val;
            return;
        }
        Push();
        left->Update(u, v, val);
        right->Update(u, v, val);
        ans = max(left->ans,  right->ans);
    }
};
