template<class T>
struct RangeMax {
    vector<vector<T>> st;
    vi lg;
    RangeMax (int n) : lg(n + 1) {
        for (int i = 2; i <= n; i++) lg[i] = lg[i >> 1] + 1;
        st.assign(lg[n] + 1, vi(n));
    }
    T& at (int i) { return st[0][i]; } // array must be manually read
    void build (int n) {
        for (int j = 1; j <= lg[n]; j++) for (int i = 0; i + (1 << j) <= n; i++)
            st[j][i] = max(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
    }
    T query (int l, int r) {        // 0-based indexation, closed intervals
        int k = lg[r - l + 1];
        return max(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

const int N = 5e3 + 10;

vector<RangeMax<int>> st;
ll sub[N];

ll rangeSum (int l, int r) {
    if (r == 0) {
        return 0;
    } else if (l == 0) {
        return sub[r - 1];
    } else {
        return sub[r - 1] - sub[l - 1];
    }
}

ll dp[N];

// TODO cost of taking subarray [l, r] as a block
ll cost (int l, int r) {
    ll ans = -rangeSum(l, r);
    for (auto& it : st) {
        ans += it.query(l, r);
    }
    return ans;
}

void solve (int l, int r, int pl, int pr) {
    if (r < l) return;
    int m = l + r >> 1;
    pair<ll, int> opt;
    // NOTE: objective function is maximized
    opt.first = numeric_limits<ll>::min();
    for (int i = pl; i <= pr; i++) {
        if (i > m) break;
        // NOTE: objective function is maximized
        opt = max(opt, {cost(i, m), i});
    }
    dp[m] = opt.first;
    solve(l, m - 1, pl, opt.second);
    solve(m + 1, r, opt.second, pr);
}

