    forn (i, m)
        p[i] = MAXN;

    ll ans = -INF * INF;

    for (int i = n - 1; i >= 0; --i) {
        forn (j, m) {
            int& pt = p[j];

            for (; pt < MAXN && b[S[j][pt]][j] <= b[i][j]; ++pt) {
