                add[S[j][pt]] -= b[i][j];

            add[S[j][--pt] = i] += b[i][j];
        }

        ll cur = 0;

        for (int j = i; j < n; ++j)
            ans = max(ans, (cur += add[j] - (j > i ? a[j - 1] : 0ll)));
