Stack stack[M];

int get_id(int l, int r)
{
    return l + r | l != r;
}

void add(int l, int r, int a, int b, long long c)
{
    if (b < l || r < a) {
        return;
    }
    int id = get_id(l, r);
    if (a <= l && r <= b) {
        delta[id] += c;
        maximum[id] += c;
    } else {
        int m = l + r >> 1;
        add(l, m, a, b, c);
        add(m + 1, r, a, b, c);
        maximum[id] = std::max(maximum[get_id(l, m)], maximum[get_id(m + 1, r)]) + delta[id];
    }
}

void update(Stack& s, int k, int b)
{
    int last = 0;
    while (s.back().first <= b) {
        // printf("+ %d %d %d\n", s.back().second + 1, k, s.back().first - last);
        add(0, n - 1, s.back().second + 1, k, s.back().first - last);
        last = s.back().first;
        s.pop_back();
    }
    // printf("+ %d %d %d\n", s.back().second + 1, k, b - last);
    add(0, n - 1, s.back().second + 1, k, b - last);
    s.emplace_back(b, k);
}

