void solv(int i,int j,int x){//i~j,xというチケットについて考える。
    if(i<j){
        int ma=0;
        int nma;
        for(int k=i;k<j;k++){
            if(B[k][x]>ma){
                ma=B[k][x];
                nma=k;
            }
        }
        ans[i][nma]+=ma;
        ans[i][j]-=ma;
        ans[nma+1][nma]-=ma;
        ans[nma+1][j]+=ma;
        solv(i,nma,x);
        solv(nma+1,j,x);
    }
}



