void push(int id, int l, int r){
	if(add[id]){
		mx[id] += add[id];
		if(l != r){
			add[id<<1] += add[id];
			add[id<<1|1] += add[id];
		}
		add[id] = 0;
	}
}
void add_to_range(int id, int l, int r, int x, int y, long long v){
	push(id, l, r);
	if(l > y || r < x) return;
	if(x <= l && r <= y){
		add[id] += v;
		push(id, l, r);
		return;
	}
	int mid = (l+r)>>1;
	add_to_range(id<<1, l, mid, x, y, v);
	add_to_range(id<<1|1, mid + 1, r, x, y, v);
	mx[id] = max(mx[id<<1], mx[id<<1|1]);
}
long long get_max(int id, int l, int r, int x, int y){
	push(id, l, r);
	if(l > y || r < x) return -inf;
	if(x <= l && r <= y) return mx[id];
	int mid = (l + r)>>1;
	return max(get_max(id<<1, l, mid, x, y), get_max(id<<1|1, mid + 1, r, x, y));
}
