const ii INF=mp(-1,-1);
struct SparseTable //Warning : Change query return value manually if needed. INF is the dummy val
{
	pair<int,int> st[LG][MX];
	pair<int,int> initial[MX];

	pair<int,int> combine(pair<int,int> a, pair<int,int> b) //warning : change if neccesary
	{
		if(a>b) return a;
		return b;
	}

	SparseTable()
	{
		for(int i = 0; i < MX; i++) initial[i] = INF;
	}

	void init()
	{
		for(ll j = 0; j < LG; j++)
		{
			for(ll i = 0; i < MX; i++)
			{
				st[j][i] = INF;
				if(i + (1<<j) - 1 < MX)
				{
					if(j == 0) st[j][i] = initial[i];
					else st[j][i] = combine(st[j-1][i], st[j-1][i + (1<<(j-1))]);
				}
			}
		}
	}

	pair<int,int> query(int l, int r)
	{
		int k = 31 - __builtin_clz(r-l);
		if(l==r) k=0;
		return combine(st[k][l], st[k][r - (1<<k) + 1]);
	}
};

