	auto f = [](vll a, vll b) {
		vll ret(M + 1);
		repn(i, M)ret[i] = max(a[i], b[i]);
		return ret;
	};
	vll unit(M + 1, 0);

	Segment_Tree<vector<ll>> seg(N, f, unit);




	vector<ll> A(N);
	repn(i, N - 1)cin >> A[i];
	repn(i, N) {
		vll b(M + 1);
		repn(j, M) cin >> b[j];
		seg.update(i, b);
	}


	vll dis(N + 1, 0);
	repn(i, N - 1)dis[i + 1] = dis[i] + A[i];

	vll mx(N + 1);

	vector<pair<ll, ll>> p(N + 1);
	repn(i, N) {
		ll x = i;
		ll c = 0;
		while (x % 2 != 0) { x /= 2; c++; }
		p[i] = { c,i };
	}

	sort(++p.begin(), p.end(), greater <pair<ll, ll>>());
	set<ll> st;


	repn(i, N) {
		ll x = p[i].second;
		auto itr = st.upper_bound(x);
		ll s, t;

		if (itr == st.end()) { t = N; }
		else { t = mx[*itr]; }

		if (itr == st.begin()) { s = x; }
		else { s = max(x, mx[*(--itr)]); }

		ll mxval = hap(x, s, dis, seg);
		ll mxind = s;
		for (ll j = s + 1; j <= t; j++) {
			ll now = hap(x, j, dis, seg);
			if (now > mxval) { mxind = j; mxval = now; }
		}

		mx[x] = mxind;
		st.insert(x);

	}


	ll ans = -INF;

	repn(i, N) {
	//	cout << i << " " << mx[i] << endl;
		ans = max(ans, hap(i, mx[i], dis, seg));
	}
	cout << ans << endl;



}

