void solve(ll N, ll M, vector<ll> A, vector<vector<ll>> B) {
  ll res = 0, len = 0;
  int index = 0;
  vector<ll> ma(M);
  REP(i,N) {
    if (i > 0) len += A[i-1];
    REP(j,M) chmax(ma[j], B[i][j]);
    ll sum = 0;
    REP(j,M) sum += ma[j];
    if (sum - len >= res) {
      res = sum - len;
      index = i;
    }
  }
  // cout << index << endl;
  B.resize(index + 1);
  A.resize(index);
  reverse(ALL(B));
  reverse(ALL(A));
  res = 0; len = 0;
  ma.assign(M, 0);
  REP(i,B.size()) {
    if (i > 0) len += A[i-1];
    REP(j,M) chmax(ma[j], B[i][j]);
    ll sum = 0;
    REP(j,M) sum += ma[j];
    if (sum - len >= res) {
      res = sum - len;
    }
  }
