template <class T>
class RMQ{
	private:
	int n;
	vector<T> rmq;
	T Queryfunc(int a,int b,int k,int l,int r){
		if(r<=a||b<=l) return -1;
		if(a<=l&&r<=b) return rmq[k];
		int m=(l+r)/2;
		T vl=Queryfunc(a,b,k*2+1,l,m);
		T vr=Queryfunc(a,b,k*2+2,m,r);
		return (vl>vr)?vl:vr;
	}
	public:
	RMQ(int n_){
		n=1;
		while(n<n_) n*=2;
		rmq=vi(2*n-1,-1);
	}
	void Update(int k,int x){
		k+=n-1;
		rmq[k]=x;
		while(k>0){
			k=(k-1)/2;
			rmq[k]=max(rmq[k*2+1],rmq[k*2+2]);
		}
	}
	T Query(int a,int b){
		return Queryfunc(a,b,0,0,n);
	}
	void Clear(){
		for(int i=0;i<2*n-1;i++) rmq[i]=-1;
	}
	T Open(int k){
		return rmq[k+n-1];
	}
};

