int search(int b, int e, int x, int y) {
	if(b == e) {
		// cout << getVal(x, b) << ' ' << getVal(y, b) << endl;
		return getVal(x, b) >= getVal(y, b) ? b : n + 1;
	}
	int mid = (b + e) >> 1;
	if(getVal(x, mid) >= getVal(y, mid)) {
		return search(b, mid, x, y);
	} else {
		return search(mid + 1, e, x, y);
	}
}
int better(int x, int y) {
	return search(max(x, y), n, x, y);
}

