			}
		}
		out = max(out, tmp);
		tmp -= d[i];
	}
	ans = max(ans, out);
	return res[x] = out;
}

void sa(int l, int r, double speed)
{
	int cur = rand() % (r - l + 1) + l;
	double t = 1e3;

	while (t > 0.001)
	{
		ll old = calc(cur);
		ll range = ceil(t);
		int rl = max((ll) l, cur - range);
		int rr = min((ll) r, cur + range);
		int nxt = rand() % (rr - rl + 1) + l;
		ll delta = old - calc(nxt);
		//if (calc(nxt) > old) cerr << exp(-delta / t) << endl;
		if (exp(-delta / t) > (double) rand() / RAND_MAX) cur = nxt;
		t *= speed;
		if (cnt > MAXOP) break;
	}

	blres[l] = max(blres[l], calc(cur));
}

