// EOT

const int MAXN = 5e3 + 5, MAXM = 205;

int N, M;
LL A[MAXN];
LL B[MAXN][MAXM];

void input()
{
    read(N); read(M);
    for (int i = 1; i < N; ++i) {
        read(A[i]);
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            read(B[i][j]);
        }
    }
}

void solve()
{
    static LL add[MAXN][MAXN];

    for (int i = 1; i <= M; ++i) {
        static int st[MAXN];
        int top = 0;

        st[++top] = 1;
        for (int j = 2; j <= N; ++j) {
            for (; top > 0 && B[st[top]][i] < B[j][i]; --top) {
                add[st[top - 1] + 1][j] += B[j][i] - B[st[top]][i];
                add[st[top] + 1][j] -= B[j][i] - B[st[top]][i];
            }
            st[++top] = j;
        }
    }

    static LL curadd[MAXN];
    LL ans = 0;

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            curadd[j] += add[i][j];
        }

        LL cur = 0;
        for (int j = 1; j <= M; ++j) {
            cur += B[i][j];
        }
        for (int j = i; j <= N; ++j) {
            cur += curadd[j];
            chkmax(ans, cur);
            cur -= A[j];
        }
    }

    printf("%lld\n", ans);
}

