ll a[N];
int n, m;
ll numlog[N], pref[N];
ll b[N][203], ans;
int table[203][20][N];

void build (int pos) {
    for (int i = 0; i <= numlog[n]; i++) {
        for (int j = 1; j <= n; j++) {
            if (!i) {
                table[pos][i][j] = b[j][pos];
                continue;
            }
            int curlen = min((1 << i), n);
            table[pos][i][j] = max(table[pos][i - 1][j], table[pos][i - 1][j + curlen / 2]);
        }
    }
}

int get (int pos, int l, int r) {
    int curlog = numlog[r - l + 1];
    return max(table[pos][curlog][l], table[pos][curlog][r - (1 << curlog) + 1]);
}

void divide (int l, int r, int optl, int optr) {
    if (l > r) return ;
    int mid = (l + r) >> 1, opt = -1;
    ll c = 0;
    for (int i = optl; i <= min(mid, optr); i++) {
        ll res = 0;
        for (int j = 1; j <= m; j++)
            res += get(j, i, mid);
        res -= pref[mid - 1] - pref[i - 1];
        if (res > c) {
            c = res;
            opt = i;
        }
    }
    ans = max(ans, c);
    divide(l, mid - 1, optl, opt);
    divide(mid + 1, r, opt, optr);
}

