struct maxQueue {
  deque <int> q;
  int l, r;
  int prev = -1;
  int *a;
  maxQueue (int *a) : a(a) {}
  maxQueue(){}

  void set (int lvl) {     
    if (prev < lvl) {
      q.clear();    
      l = 1, r = 0;
    }        
    prev = lvl;
  }    
  void add (int p) {
    while (!q.empty() && a[p] > a[q.back()])
      q.pop_back();
    q.push_back (p);
  }
  void move (int L, int R) {
    while (r < R)
      add (++r);
    l = L;            
    while (q.front() < l)
      q.pop_front();
  }     
  int getmax() {   
    assert (!q.empty());  
    return a[q.front()];
  }       
} T[K + 1];

struct node {
  int l, r;
  int tl, tr;
  int lvl;
} t[4*N];

queue <int> q;
void solve (int v) { 
  node &a = t[v];
  int m = (a.l + a.r) >> 1;
  for (int i = 1; i <= k; i++)
    T[i].set (a.lvl);

  ll mx = -1;
  int opt = 0;   
  for (int j = a.tl; j <= min (a.tr, m); j++) {
    ll cost = -(dist[m] - dist[j]);  
    for (int i = 1; i <= k; i++) {
      T[i].move (j, m);    
      cost += T[i].getmax ();
    }                 
    if (mx < cost) {
      mx = cost;
      opt = j;
    }
