  ans = max (ans, mx);
  if (a.l != a.r) {
    t[v<<1] = {a.l, m, a.tl, opt, a.lvl + 1};
    t[v<<1|1] = {m + 1, a.r, opt, a.tr, a.lvl + 1};
  }      
}    

