int n, m;
int x[N];
int a[M];
LL tag[N << 2];
LL maxv[N << 2];
vector<pair<int, int> > st[M];

void modify(int t, int l, int r, int a, int b, LL v)
{
    if (b < l || r < a) return;
    if (a <= l && r <= b) {
        tag[t] += v;
        maxv[t] += v;
        return;
    }
    if (tag[t]) {
        tag[t << 1] += tag[t];
        maxv[t << 1] += tag[t];
        tag[t << 1 | 1] += tag[t];
        maxv[t << 1 | 1] += tag[t];
        tag[t] = 0;
    }
    int mid = (l + r) >> 1;
    modify(t << 1, l, mid, a, b, v);
    modify(t << 1 | 1, mid + 1, r, a, b, v);
    maxv[t] = max(maxv[t << 1], maxv[t << 1 | 1]);
}

LL query(int t, int l, int r, int a, int b)
{
    if (b < l || r < a) return 0;
    if (a <= l && r <= b) {
        return maxv[t];
    }
    if (tag[t]) {
        tag[t << 1] += tag[t];
        maxv[t << 1] += tag[t];
        tag[t << 1 | 1] += tag[t];
        maxv[t << 1 | 1] += tag[t];
        tag[t] = 0;
    }
    int mid = (l + r) >> 1;
    return max(query(t << 1, l, mid, a, b), query(t << 1 | 1, mid + 1, r, a, b));
}

