void Compute (int l, int r, int opl, int opr)
{
    if (l > r) return;

    int md = (l + r) >> 1, opt;

    for (int j = 1; j <= m; j++)
        cur[j] = inf;

    for (int i = md; i > opr; i--)
    {
        for (int j = 1; j <= m; j++)
            cur[j] = max( cur[j], ar[i][j] );
    }

    for (int i = min(opr, md); i >= opl; i--)
    {
        long long ans = 0;
        for (int j = 1; j <= m; j++)
        {
            cur[j] = max( cur[j], ar[i][j] );
            ans += cur[j];
        }
        if (dp[md] < ans - (pref[md] - pref[i]) )
        {
            dp[md] = ans - (pref[md] - pref[i]);
            opt = i;
        }
    }
    Compute(l, md - 1, opl, opt);
    Compute(md + 1, r, opt, opr);
}
