ll calc(int x)
{
	if (res[x]) return res[x];
	ll out = 0, tmp = 0;
	memset(mx, 0, sizeof(mx));
	cnt += (n - x + 1) * m;
	for (int i = x; i <= n; ++i)
	{
		for (int j = 1; j <= m; ++j)
		{
		    int wij = w[i][j];
		    int & mxj = mx[j];
			if (wij > mxj)
			{
				tmp += wij - mxj;
				mxj = wij;
			}
		}
		out = max(out, tmp);
		tmp -= d[i];
	}
	ans = max(ans, out);
	return res[x] = out;
}

void sa(int l, int r, double speed)
{
	int cur = (l + r) >> 1;
	double t = 1e3;

	while (t > 0.001)
	{
		ll old = calc(cur);
		ll range = ceil(t);
		int rl = max((ll) l, cur - range);
		int rr = min((ll) r, cur + range);
		int nxt = rand() % (rr - rl + 1) + l;
		if (calc(nxt) >= old) cur = nxt;
		t *= speed;
		if (cnt > MAXOP) break;
	}

	blres[l] = max(blres[l], calc(cur));
}

