#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int N, M, A[5009], B[5009][209];
ll PA[5009], ans;

void dnc(int s, int e, int l, int r) {
	if(e < s) return;
	int m = s+e >> 1;
	vector<int> mx(M+1, 0);
	ll ret = -1, id = -1;
	for(int i=m; i>=l; i--) {
		ll s = 0;
		for(int j=1; j<=M; j++) {
			mx[j] = max(mx[j], B[i][j]);
			s += mx[j];
		}
		if(ret < s - (PA[m-1] - PA[i-1])) ret = s - (PA[m-1] - PA[i-1]), id = i;
	}
	ans = max(ans, ret);
	if(ret == -1) return;
	dnc(s, m-1, l, id);
	dnc(m+1, e, id, r);
}

int main() {
	scanf("%d%d",&N,&M);
	for(int i=1; i<N; i++) {
		scanf("%d",&A[i]);
		PA[i] = PA[i-1] + A[i];
	}
	for(int i=1; i<=N; i++) {
		for(int j=1; j<=M; j++) {
			scanf("%d",&B[i][j]);
		}
	}
	dnc(1, N, 1, N);
	printf("%lld", ans);
	return 0;
}

