pair<int, int> rmq[N][14];
long long ans;
long long f[N][N];

pair<int, int> get(int l, int r) {
	int k = lg[r - l + 1];
	return max(rmq[l][k], rmq[r - (1 << k) + 1][k]);
}

void upd(int x, int y, int u, int v, int val) {
	++u; ++v;
	f[x][y] += val; f[x][v] -= val;
	f[u][y] -= val; f[u][v] += val;
}

void solve(int l, int r) {
	if (l > r) return;
	pair<int, int> g = get(l, r);
	int opt = g.second, val = g.first;
	upd(l, opt, opt, r, val);
	solve(l, opt - 1); solve(opt + 1, r);
}

