ll sum[N + 10][N + 10];

void add(int x1, int y1, int x2, int y2, int d) {
    sum[x1][y1] += d;
    sum[x1][y2 + 1] -= d;
    sum[x2 + 1][y1] -= d;
    sum[x2 + 1][y2 + 1] += d;
}

int main() {
    //ios_base::sync_with_stdio(false);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n, m;
    scanf("%d%d", &n, &m);
    for(int i = 1; i <= n - 1; i++) {
        scanf("%d", &a[i]);
    }
    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= m; j++)
            scanf("%d", &b[i][j]);
    for(int j = 1; j <= m; j++) {
        vector<int> l(n + 1, 1), r(n + 1, n), s;
        for(int i = 1; i <= n; i++) {
            while(!s.empty() && b[s.back()][j] <= b[i][j])
                s.pop_back();
            if(!s.empty())
                l[i] = s.back() + 1;
            s.push_back(i);
        }
        s.clear();
        for(int i = n; i >= 1; i--) {
            while(!s.empty() && b[s.back()][j] < b[i][j])
                s.pop_back();
            if(!s.empty())
                r[i] = s.back() - 1;
            s.push_back(i);
        }
        for(int i = 1; i <= n; i++) {
            //cout << l[i] << " " << i << " " << i << " " << r[i] << " " << b[i][j] << "\n";
            add(l[i], i, i, r[i], b[i][j]);
        }
    }
    for(int i = 1; i <= n; i++) {
        for(int j = 1; j <= n; j++) {
            sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
            //cout << sum[i][j] << " ";
        }
        //cout << "\n";
    }
    ll ans = 0;
    for(int i = 1; i <= n; i++) {
        ll diff = 0;
        for(int j = i; j <= n; j++) {
            ans = max(ans, sum[i][j] - diff);
            diff += a[j];
        }
    }
    cout << ans << "\n";
    return 0;
}

