	VEC(int, a, n - 1);
	MAT(int, b, n, m);

	std::vector<int> c(n, 0);
	REP(i, n - 1) c[i + 1] = c[i] + a[i];

	REP(k, m) {
		std::vector<int> l(n);
		{
			std::stack<PAIR> st;
			st.push({ INFINT, -1 });
			REP(i, n) {
				while (b[i][k] > st.top().first) st.pop();
				l[i] = st.top().second + 1;
				st.push({ b[i][k], i });
			}
		}
		std::vector<int> r(n);
		{
			std::stack<PAIR> st;
			st.push({ INFINT, n });
			RREP(i, n) {
				while (b[i][k] > st.top().first) st.pop();
				r[i] = st.top().second;
				st.push({ b[i][k], i });
			}
		}

		REP(i, n) {
			dp[l[i]][i] += b[i][k];
			dp[i + 1][i] -= b[i][k];
			dp[l[i]][r[i]] -= b[i][k];
			dp[i + 1][r[i]] += b[i][k];
		}
	}

	REP(i, n) REP(j, n) dp[i + 0][j + 1] += dp[i][j];
	REP(j, n) REP(i, n) dp[i + 1][j + 0] += dp[i][j];

	int ans = 0;
	REP(i, n) FOR(j, i, n) {
		CHMAX(ans, dp[i][j] - (c[j] - c[i]));
	}
	OUT(ans)BR;

	return 0;
}

