    ll sum = 0;
    REP(j,M) {
      int en = i;
      while (!vec[j].empty() && vec[j].back().second < B[i][j]) {
        sky.add(vec[j].back().first, en, -(B[i][j] - vec[j].back().second));
        en = vec[j].back().first;
        vec[j].pop_back();
      }
      vec[j].emplace_back(en, B[i][j]);
      sum += B[i][j];
    }
    sky.add(i, i + 1, -sum);
    if (i > 0) sky.add(0, i, A[i-1]);
    res = max(res, -sky.minimum(0, i + 1));
  }
  cout << res << endl;
}

