				q.pop_front();
			}
			seg.add(i, q.size() ? q[0] : n, b[i][j]);
			q.push_front(i);
		}
		//dbg(i); for(int j = i; j < n; j++) dbg(j, seg.query(j, j + 1));

		ans = max(ans, seg.query(i, n));
