struct Segtree_sum {
	ll n;
	ll d[262244];	// caution : 2^x
	void init(ll nmin) {
		for (n = 1; n < nmin; n *= 2);
		memset(d, 0, 2 * n);
	}
	void update(ll i, ll x) {
		d[n + i] = x;
		for (ll k = (n + i) / 2; k > 0; k >>= 1)
			d[k] = d[k * 2] + d[k * 2 + 1];
	}
	ll get(ll l, ll r) const {
		ll m = 0;
		for (; l && l + (l&-l) <= r; l += l&-l)
			m += d[(n + l) / (l&-l)];
		for (; l < r; r -= r&-r)
			m += d[(n + r) / (r&-r) - 1];
		return m;
	}
};

struct RMQ {
	ll n;
	ll d[262244];	// caution : 2^x
	void init(ll nmin) {
		for (n = 1; n < nmin; n *= 2);
		rep(i, 2 * n) {
			d[i] = (ll)1 << 58;
		}
	}
	void update(ll i, ll x) {
		d[n + i] = x;
		for (ll k = (n + i) / 2; k > 0; k >>= 1)
			d[k] = min(d[k * 2], d[k * 2 + 1]);
	}
	ll get(ll l, ll r) const {
		ll m = (ll)1 << 58;
		for (; l && l + (l&-l) <= r; l += l&-l)
			m = min(m, d[(n + l) / (l&-l)]);
		for (; l < r; r -= r&-r)
			m = min(m, d[(n + r) / (r&-r) - 1]);
		return m;
	}
};

