#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int N = 5005, M = 205, LG = 15;

int n, m, a[N], b[M][N], st[M][N][LG];
ll f[N][N];

void calc(int j, int l, int r) {
  int k = log2(r - l + 1);
  int p = st[j][l][k];
  if (b[j][p] < b[j][st[j][r - (1 << k) + 1][k]])
    p = st[j][r - (1 << k) + 1][k];
  // add b[j][p] to rectangle (l, p) -> (p, r)
  f[l][p] += b[j][p];
  f[p + 1][p] -= b[j][p];
  f[l][r + 1] -= b[j][p];
  f[p + 1][r + 1] += b[j][p];
  if (l <= p - 1) calc(j, l, p - 1);
  if (r >= p + 1) calc(j, p + 1, r);
}

int main() {
  ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);
  cin >> n >> m;
  for (int i = 1; i < n; ++i) {
    cin >> a[i];
  }
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      cin >> b[j][i];
      st[j][i][0] = i;
    }
  }
  for (int j = 1; j <= m; ++j) {
    for (int k = 1; (1 << k) <= n; ++k) {
      for (int i = 1; i + (1 << k) - 1 <= n; ++i){
        if (b[j][st[j][i][k - 1]] > b[j][st[j][i + (1 << (k - 1))][k - 1]])
          st[j][i][k] = st[j][i][k - 1];
        else
          st[j][i][k] = st[j][i + (1 << (k - 1))][k - 1];
      }
    }
    calc(j, 1, n);
  }

  ll ans = LLONG_MIN;
  for (int l = 1; l <= n; ++l) {
    ll dist = 0;
    for (int r = l; r <= n; ++r) {
      f[l][r] += f[l - 1][r] + f[l][r - 1] - f[l - 1][r - 1];
      ans = max(ans, f[l][r] - dist);
      dist += a[r];
    }
  }
  cout << ans;
  return 0;
}

