	scanf("%d%d", &n, &m);
	for (int i = 1; i < n; i++) scanf("%d", &A[i]);
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
			scanf("%d", &B[i][j]);
	for (int i = 1; i <= m; i++) {
		int top = 0;
		for (int j = 1; j <= n; j++) {
			while (top && B[j][i] > B[S[top]][i])
				R[S[top--]] = j;
			L[j] = S[top]; S[++top] = j; 
		}
		for (int j = 1; j <= top; j++) R[S[j]] = n + 1;
		/*for (int j = 1; j <= n; j++)
			printf("[%d,%d] ", L[j], R[j]);
		puts("");*/
		for (int j = 1; j <= n; j++) {
			sum[L[j] + 1][j] += B[j][i];
			sum[L[j] + 1][R[j]] -= B[j][i];
			sum[j + 1][j] -= B[j][i];
			sum[j + 1][R[j]] += B[j][i];
		}
	}
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			sum[i][j] += sum[i][j - 1];
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			sum[i][j] += sum[i - 1][j];	
	int ans = 0;
	for (int i = 1; i <= n; i++) {
		int tmp = 0;
		for (int j = i; j <= n; j++) {
			ans = max(ans, sum[i][j] - tmp);
			/*if (ans == 13) {
				printf("%d %d %d %d\n", i, j, sum[i][j], tmp);
				return 0;
			}*/
			tmp += A[j];
		}
	}
	printf("%d\n", ans);
	return 0;
}

