int N, M, A[5010], B[5010][210], l[5010][210], r[5010][210];
long long f[5010][5010], dis[5010], ans;

int main(){
	scanf("%d%d", &N, &M);
	for(int i=1; i<N; i++){
		scanf("%d", &A[i]);
		dis[i+1]=dis[i]+1LL*A[i];
	}
	for(int i=1; i<=N; i++)
		for(int j=1; j<=M; j++){
			scanf("%d", &B[i][j]);
			int x=i-1;
			while(B[x][j]<B[i][j] && x)	r[x][j]=i, x--;
			l[i][j]=x, r[i][j]=N+1;
		}
	for(int i=1; i<=N; i++)
		for(int j=1; j<=M; j++)
			f[l[i][j]+1][i]+=1LL*B[i][j], 
			f[i+1][r[i][j]]+=1LL*B[i][j],
			f[l[i][j]+1][r[i][j]]-=1LL*B[i][j],
			f[i+1][i]-=1LL*B[i][j];
	for(int i=1; i<=N; i++)
		for(int j=1; j<=N; j++)
			f[i][j]+=f[i-1][j]+f[i][j-1]-f[i-1][j-1];
	for(int i=1; i<=N; i++)
		for(int j=i; j<=N; j++)
			ans=max(ans, f[i][j]-dis[j]+dis[i]);
	printf("%lld", ans);
	return 0;
}

