#define int long long

using namespace std;
const int N = 6e3;
const int M = 3e2;

int n, m;
int a[N], b[N][M], Max[M];

int read(void)
{
	int s = 0, w = 0; char c = getchar();
	while (c < '0' || c > '9') w |= c == '-', c = getchar();
	while (c >= '0' && c <= '9') s = s*10+c-48, c = getchar();
	return w ? -s : s;
}

signed main(void)
{
	n = read(), m = read();
	for (int i=2;i<=n;++i)
		a[i] = read();
	for (int i=1;i<=n;++i)
	    for (int j=1;j<=m;++j)
		    b[i][j] = read();
	int ans = 0;
	for (int i=1,sum=0;i<=n;++i)
	{
		sum -= a[i];
		int s = sum;
		for (int j=1;j<=m;++j)
		{
			Max[j] = max(Max[j],b[i][j]);
			s += Max[j];
		}	
		ans = max(ans,s);
	} 
	cout << ans << endl;
	return 0;
}

#include <cstdio>

typedef long long ll;

template<typename T> inline bool chkmax(T &x, T y){ x < y ? x = y, true : false; }

const int MAXN = 5e3 + 1;

int n, m;
ll a[MAXN], b[MAXN][MAXN], mat[MAXN][MAXN];
int L[MAXN][MAXN], R[MAXN][MAXN];

int s[MAXN], top = 0;

int main() {
    scanf("%d%d", &n, &m);
    a[0] = a[1] = 0;
    for (int i = 2; i <= n; ++i) {    
        ll x;
        scanf("%lld", &x);
        a[i] = a[i - 1] + x;
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            scanf("%lld", &b[i][j]);

    for (int j = 1; j <= m; ++j) {
        top = 0;
        for (int i = 1; i <= n; ++i) {
            while (top and b[s[top]][j] < b[i][j])
                --top;
            L[i][j] = top ? s[top] + 1 : 1;
            s[++top] = i;
        }
        top = 0;
        for (int i = n; i; --i) {
            while (top and b[s[top]][j] < b[i][j])
                --top;
            R[i][j] = top ? s[top] - 1 : n;
            s[++top] = i;
        }

        for (int i = 1; i <= n; ++i) {
            mat[L[i][j]][i] += b[i][j];
            mat[i + 1][R[i][j] + 1] += b[i][j];
            mat[i + 1][i] -= b[i][j];
            mat[L[i][j]][R[i][j] + 1] -= b[i][j];
        }
    }

    ll ans = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j)
            mat[i][j] += mat[i - 1][j] + mat[i][j - 1] - mat[i - 1][j - 1];
        for (int j = i; j <= n; ++j)
            chkmax(ans, mat[i][j] - a[j] + a[i]);
    }

    printf("%lld\n", ans);

    return 0;
}

