template<class V, class Merge> struct SegmentTree {
	const int n;
	const V unit_value;
	vector<V> val;

	SegmentTree(int _n) : n(1 << (32-__builtin_clz(_n-1))), unit_value(Merge::unit()), val(n * 2, unit_value) {}

	V get(int i) const { return val[i + n]; }
	void set(int i, const V &v) { val[i + n] = v; }

	void build() {
		for (int i = n - 1; i > 0; i--) val[i] = Merge::merge(val[i * 2], val[i * 2 + 1]);
	}

	void update(int i, const V &v) {
		i += n;
		val[i] = v;
		while (i > 1) {
			i >>= 1;
			val[i] = Merge::merge(val[i * 2], val[i * 2 + 1]);
		}
	}

	V query(int l, int r) const {
		l = max(0, min(n, l)) + n;
		r = max(0, min(n, r)) + n;
		V ret = unit_value;
		for (; l < r; l >>= 1, r >>= 1) {
			if (l & 1) ret = Merge::merge(ret, val[l++]);
			if (r & 1) ret = Merge::merge(ret, val[--r]);
		}
		return ret;
	}
};
template<class V, class Merge> ostream& operator<<(ostream& os, const SegmentTree<V, Merge>& seg) {
	vector<V> vec;
	for (int i = 0; i < seg.n; i++) {
		vec.emplace_back(seg.get(i));
	}
	os << vec;
	return os;
}

template <class V> struct MergeRangeMaxQ {
	static V merge(const V &l, const V &r) { return l > r ? l : r; }
	static V unit() { return numeric_limits<V>::min(); }
};
template<class V> using SegTreeMax = SegmentTree<V, MergeRangeMaxQ<V>>;

template <class T> struct CumulativeSum2D {
	bool built = false;
	vector<vector<T>> A;

	CumulativeSum2D(int h, int w) : A(h + 1, vector<T>(w + 1)) {}

	void add(int y, int x, T v) {
		A[y + 1][x + 1] += v;
	}

	void add(int t, int b, int l, int r, T v) {
		A[t][l] += v;
		A[b][r] += v;
		A[t][r] -= v;
		A[b][l] -= v;
	}

	void build() {
		for (size_t y = 0; y < A.size(); y++) {
			for(size_t x = 1; x < A[y].size(); x++) {
				A[y][x] += A[y][x - 1];
			}
		}
		for (size_t y = 1; y < A.size(); y++) {
			for(size_t x = 0; x < A[y].size(); x++) {
				A[y][x] += A[y - 1][x];
			}
		}
		built = true;
	}

	T query(int t, int b, int l, int r) {
		assert(built);
		return (A[b][r] - A[b][l] - A[t][r] + A[t][l]);
	}

	T query_hw(int t, int l, int h, int w) {
		return query(t, t+h, l, l+w);
	}
};

ll solve() {
	int n = ri(), m = ri();
	vector<ll> A(n);
	rep(i, 1, n) A[i] = ri() + A[i-1];

	vvi B(n, vi(m));
	rep(i, n) rep(j, m) B[i][j] = ri();

	SegTreeMax<pii> seg(n);
	CumulativeSum2D<ll> csum(n, n);

	rep(j, m) {
		rep(i, n) seg.set(i, {B[i][j], i});
		seg.build();

		function<void(int, int)> rec = [&](int l, int r) {
			if (l == r) return;
			int t, i;
			tie(t, i) = seg.query(l, r);
			csum.add(i, r, l, i+1, t);
			rec(l, i);
			rec(i+1, r);
		};
		rec(0, n);
	}

	csum.build();
	out(csum.A);

	ll ans = 0;
	rep(i, n) rep(j, i, n) {
		ll cand = csum.A[j][i] - (A[j] - A[i]);
		amax(ans, cand);
	}
	return ans;
}

