void solve(long long N, long long M, vector<long long> A, vector<vector<long long>> B){

	memset(idx,-1,sizeof(idx));
	long long ans = 0;
	for(int i = 0 ; i < N ; i++){
		long long sub = 0;
		for(int j = 0 ; j < M ; j++){	
			sub += B[i][j];
		}
		ans = max(sub,ans);
	}
	for(int i = 1 ; i < A.size() ; i++)
		A[i] = A[i-1] + A[i];
	//cout << "><" << endl;
	for(int i = 0 ; i < M ; i++){
		deque<long long> X;
		deque<long long> Y;

		X.push_front(INF);
		Y.push_front(N);

		for(int j = N - 1 ; j >= 0 ; j--){
			int l = 0, r = X.size() - 1;
			while( l != r ){
				int m = (l+r) / 2;
				if( X[m] > B[j][i] ){
					r = m;
				}else{
					l = m + 1;
				}
			}
			idx[i][j] = Y[r];
			//cout << "idx[" << i << "][" << j << "]" << "=" << Y[r] << "(" << B[j][i] << ")" << endl;
			assert(j < Y[r]);

			while( X.front() <= B[j][i] ){
				X.pop_front();
				Y.pop_front();
			}
			X.push_front(B[j][i]);
			Y.push_front(j);
		}
	}

	deque<int> rnd;
	//N = 100;
	for(int i = 0 ; i < N ; i++)
		rnd.push_back(i);
	if( rnd.size() > 20 ){
		rotate(rnd.begin(),rnd.begin() + rnd.size()-10, rnd.end());
		random_shuffle(rnd.begin()+20,rnd.end());
	}
	//for( auto i : rnd ) cout << i << " " << endl;

	for( auto i : rnd ){
		en = clock();
		//cout << en << endl;
		if( 1.0 * (en - st) / CLOCKS_PER_SEC > 1.9  ) break;
		//cout << 1.0 * (en - st) / CLOCKS_PER_SEC  << endl;
		long long mx[200]={};
		int id[200]={};
		long long dist = 0;


		for(int j = i ; j < N ; ){

			for(int k = 0 ; k < M ; k++){	
				mx[k] = max(mx[k],B[j][k]);
			}
			long long sub = 0;
			for(int k = 0 ; k < M ; k++){	
				sub += mx[k];
			}
			ans = max(sub-dist,ans);
			//cout << sub << "|" <<  dist << "[" << i << "," << j << "]" << endl;
			int nx = N;

			for(int k = 0 ; k < M ; k++)
				id[k] = max(id[k], idx[k][j]);

			for(int k = 0 ; k < M ; k++)
				nx = min(id[k],nx);
			dist += A[nx-1] - (j?A[j-1]:0);
			//cout << j << "->" << nx << " " << N << endl;
			j = nx;
			//cout << i << " " << nx << endl;


		}
	}
	cout << ans << endl;
}

