inline void Modify(int i, int j) {
    mat[L[i][j]][j] += b[i][j];
    mat[j + 1][R[i][j] + 1] += b[i][j];
    mat[L[i][j]][R[i][j] + 1] -= b[i][j];
    mat[j + 1][j] -= b[i][j]; 
}

void Calc() {
    for (int i = 1; i <= m; ++i) {
        top = 0;
        for (int j = 1; j <= n; ++j) {
            while (top and w[top] < b[i][j])
                --top;
            L[i][j] = top ? s[top] + 1 : 1;
            s[++top] = j; w[top] = b[i][j];
        }
        top = 0;
        for (int j = n; j; --j) {
            while (top and w[top] < b[i][j])
                --top;
            R[i][j] = top ? s[top] - 1 : n;
            s[++top] = j; w[top] = b[i][j];
        }
        for (int j = 1; j <= n; ++j) 
            Modify(i, j);
    }
}

