struct segtree {
	vector<int> T;
	void init(vector<int> &A, int idx, int s, int e) {
		if(s == e) {
			T[idx] = A[s];
			return;
		}
		int m = s+e >> 1;
		init(A, idx*2, s, m);
		init(A, idx*2+1, m+1, e);
		T[idx] = max(T[idx*2], T[idx*2+1]);
	}
	int get(int idx, int s, int e, int l, int r) {
		if(e < l || r < s) return -1e9;
		if(l <= s && e <= r) return T[idx];
		int m = s+e >> 1;
		return max(get(idx*2, s, m, l, r), get(idx*2+1, m+1, e, l, r));
	}
};

int N, M, A[5009], B[5009][209];
ll PA[5009], ans;
segtree seg[509];

void dnc(int s, int e, int l, int r) {
	if(e < s) return;
	int m = s+e >> 1;
	vector<int> mx(M+1, 0);
	ll ret = -1, id = -1;
	for(int i=1; i<=M; i++) mx[i] = seg[i].get(1, 1, N, min(m, r), m);
	for(int i=min(m, r); i>=l; i--) {
		ll s = 0;
		for(int j=1; j<=M; j++) {
			mx[j] = max(mx[j], B[i][j]);
			s += mx[j];
		}
		if(ret < s - (PA[m-1] - PA[i-1])) ret = s - (PA[m-1] - PA[i-1]), id = i;
	}
	ans = max(ans, ret);
	if(ret == -1) return;
	dnc(s, m-1, l, id);
	dnc(m+1, e, id, r);
}

