const int N = 5009;

struct Node{    
    ll value;
    ll lazy;
};

Node T[N * 4 + 512];

void push(int node, int cl, int cr){
    T[node].value += T[node].lazy;
    if(cl != cr){
        T[node * 2].lazy += T[node].lazy;   
        T[node * 2 + 1].lazy += T[node].lazy;
    }
    T[node].lazy = 0;
}

void update(int node, int cl, int cr, int tl, int tr, ll vl){
    push(node, cl, cr);
    if(cr < tl)
        return;
    if(cl > tr)
        return;
    if(cl >= tl && cr <= tr){
        T[node].lazy = vl;
        push(node, cl, cr);
        return;
    }
    int mid = (cl + cr) / 2;
    update(node * 2, cl, mid, tl, tr, vl);
    update(node * 2 + 1, mid + 1, cr, tl, tr, vl);
    T[node].value = max(T[node * 2].value, T[node * 2 + 1].value);
}

const ll inf = (ll)1e16;

ll query(int node, int cl, int cr, int tl, int tr){
    push(node, cl, cr);
    if(cr < tl)
        return -inf;
    if(cl > tr)
        return -inf;
    if(cl >= tl && cr <= tr)
        return T[node].value;
    int mid = (cl + cr) / 2;
    return max(query(node * 2, cl, mid, tl, tr), query(node * 2 + 1, mid + 1, cr, tl, tr));
}

