template<typename T>
struct imos2d{
	int n,m;
	T mod;
	vector<vector<T>>sum;
	bool flag=false;

	imos2d(){}
	imos2d(int n,int m,T mod=-1)
		:n(n),m(m),mod(mod),sum(vector<vector<T>>(n+2,vector<T>(m+2))){}

	void add(int x1,int y1,int x2,int y2,T t){
		assert(!flag);
		x1++;y1++;x2++;y2++;
		sum[x1][y1]+=t;
		sum[x1][y2+1]-=t;
		sum[x2+1][y1]-=t;
		sum[x2+1][y2+1]+=t;
		if(mod!=-1){
			sum[x1][y1]%=mod;
			(sum[x1][y2+1]+=mod)%=mod;
			(sum[x2+1][y1]+=mod)%=mod;
			sum[x2+1][y2+1]%=mod;
		}
	}

	void calc(){
		flag=true;
		rep(i,n+1)for(int j=1;j<=m;j++){
			sum[i][j]+=sum[i][j-1];
			if(mod!=-1)sum[i][j]%=mod;
		}
		rep(i,m+1)for(int j=1;j<=n;j++){
			sum[j][i]+=sum[j-1][i];
			if(mod!=-1)sum[j][i]%=mod;
		}
	}

	T get(int x,int y){
		if(!flag)calc();
		x++;y++;
		return sum[x][y];
	}
};

template<typename T>
struct sum1d{
	int n;
	T mod;
	vector<T>sum;
	bool flag=false;

	sum1d(){}
	sum1d(int n,T mod=-1):n(n),mod(mod),sum(vector<T>(n+2)){}

	void add(int x,T t){
		x++;
		sum[x]+=t;
		if(mod!=-1)sum[x]%=mod;
	}

	void calc(){
		flag=true;
		for(int i=1;i<=n;i++){
			sum[i]+=sum[i-1];
			if(mod!=-1)sum[i]%=mod;
		}
	}

	T get(int l,int r){//[l,r)
		T res=sum[r]-sum[l];
		if(mod!=-1){
			while(res<mod)res+=mod;
			res%=mod;
		}
		return res;
	}
};

P dat[20000];
int N;
void init(int n){
	N=1;while(N<n)N<<=1;
	for(int i=N;i<2*N;i++)dat[i].second=i-N;
}
void update(int k,int x){
	k+=N;
	dat[k].first=x;
	while(k>1){
		k=(k-1)/2;
		dat[k]=max(dat[k*2],dat[k*2+1]);
	}
}
P query(int l,int r){
	P res=P(0,0);
	for(l+=N,r+=N;l<r;l>>=1,r>>=1){
		if(l&1)res=max(res,dat[l++]);
		if(r&1)res=max(res,dat[--r]);
	}
	return res;
}

