        for (int j=1;j<=n;j++)
        {
            sum[L[i][j]][j] += b[i][j];
            sum[L[i][j]][R[i][j]+1] -= b[i][j];
            sum[j+1][j] -= b[i][j];
            sum[j+1][R[i][j]+1] += b[i][j];
        }
    }
    for (int i=1;i<=n;i++)
        for (int j=1;j<=n;j++)
            sum[i][j] += sum[i-1][j] + sum[i][j-1] - sum[i-1][j-1];
    for (int i=1;i<=n;i++)
        for (int j=i;j<=n;j++)
            ans = max( ans , sum[i][j] - a[j] + a[i] );
}
