int tr(int x, int y){ return (x - 1) * n + y - 1; }
long long S[1 << 18], Lazy[1 << 18], a[100010], Ans;
void Pd(int u)
{
	if(Lazy[u])
	{
		S[u << 1] += Lazy[u]; Lazy[u << 1] += Lazy[u];
		S[u << 1 | 1] += Lazy[u]; Lazy[u << 1 | 1] += Lazy[u];
		Lazy[u] = 0;
	}
}
void MD(int u, int Ls, int Rs, int l, int r, long long val)
{
	if(l <= Ls && Rs <= r) 
	{
		S[u] += val;
		Lazy[u] += val;
		return ;
	}
	Pd(u);
	int Mid = Ls + Rs >> 1;
	if(l <= Mid) MD(u << 1, Ls, Mid, l, r, val);
	if(r > Mid) MD(u << 1 | 1, Mid + 1, Rs, l, r, val);
	S[u] = Max(S[u << 1], S[u << 1 | 1]);
}
long long QU(int u, int Ls, int Rs, int l, int r)
{
	if(l <= Ls && Rs <= r) return S[u];
	Pd(u);
	int Mid = Ls + Rs >> 1; long long t1 = 0, t2 = 0;
	if(l <= Mid) t1 = QU(u << 1, Ls, Mid, l, r);
	if(r > Mid) t2 = QU(u << 1 | 1, Mid + 1, Rs, l, r);
	return Max(t1, t2);
}
std::stack<int> Q[5010];
int RMQ_Pos(int l, int r, int p)
{
	int len = Log[r - l + 1], ll = tr(p, l), rr = tr(p, r - (1 << len) + 1);
	//printf("| %d %d [%d] [%d]| -> (%d %d) (%d %d)\n", l, r, ll, rr, W[ll][len], P[ll][len], W[rr][len], P[rr][len]);
	if(W[ll][len] > W[rr][len]) return P[ll][len];
	return P[rr][len];
}
int RMQ_Val(int l, int r, int p)
{
	int len = Log[r - l + 1], ll = tr(p, l), rr = tr(p, r);
	return Max(W[ll][len], W[rr - (1 << len) + 1][len]);
}
