inline ll calc(int l, int r)
{
	ll res = 0;
	int len = bit[r - l + 1]; 
	for (int i = 0; i < m; i++)
		res += std::max(st[i][len][l], st[i][len][r - (1 << len) + 1]); 
	return res - pre[r] + pre[l]; 
}
