			st[i][0][j] = val[i][j]; 
		for (int j = 1; j < 15; j++)
		{
			for (int k = 0; k + (1 << j) <= n; k++)
				st[i][j][k] = std::max(st[i][j - 1][k], st[i][j - 1][k + (1 << j - 1)]); 
		}
	}
	for (int i = 0; i < n; i++)
	{
		int l = i, r = n - 1; 
		while (l < r - 1)
		{
			int m1 = l + r >> 1, m2 = m1 + r >> 1;  
			if (calc(i, m1) < calc(i, m2))
				r = m2; 
			else
				l = m1; 
		}
		ans = std::max(ans, std::max(calc(i, l), calc(i, r))); 
	}
