// f[l] - > optimal r so that val(l,r) -> optimal
// f[l] <= f[l + 1]
// assume f[l] > f[l + 1] then why (l,f[l + 1]) is worse than (l,f[i]) ??-> false

void Cal(int b[maxn] , int P[maxn][logn])
{
    for(int i = 1 ; i <= n ; ++i){
        P[i][0] = b[i];
        if((1 << (ln[i - 1] + 1)) == i)ln[i] = ln[i - 1] + 1;
        else ln[i] = ln[i - 1];
    }
    for(int j = 1 ; j < logn ; ++j)
        for(int i = 1 ; i <= n ; ++i)
        {
            P[i][j] = P[i][j - 1];
            if(i > (1 << (j - 1)))
                P[i][j] = max(P[i][j],P[i - (1 << (j - 1))][j - 1]);
        }
}

int query(int type , int l , int r)
{
    int len = ln[r - l + 1];
    return max(P[type][r][len] , P[type][l + (1 << len) - 1][len]);
}
ll compute(int l , int r)
{
    if(l > r)return -1e18;
    ll res = 0;
    for(int i = 1 ; i <= m ; ++i)
        res += query(i , l , r);
    return res - (sum[r] - sum[l]);
}

ll res = 0;

void Cal(int l , int r , int optl , int optr)
{
    if(l > r)return;
    int mid = l + r >> 1;
    int opt = mid;ll ans = 0;
    for(int i = max(mid , optl) ; i <= optr ; ++i)
    {
        ll now = compute(mid , i);
        if(now > ans)
        {
            ans = now;
            opt = i;
        }
    }
    res = max(res , ans);
    Cal(l , mid - 1 , optl , opt);
    Cal(mid + 1 , r , opt , optr);
}

#define brute 0

void solve()
{
    for(int j = 1 ; j <= m ; ++j)
        Cal(b[j] , P[j]);
    if(brute)
    {
        ll res = 0;
        for(int i = 1 ; i <= n ; ++i)
            for(int j = i ; j <= n ; ++j)
                res = max(res , compute(i,j));
        cout << res;
    }
    else
    {
        Cal(1,n,1,n);
        cout << res;
    }
}

