using namespace std;

class SegTree {
public:
	enum { N = 8192 };
	SegTree() : val(2*N-1), idx(2*N-1) {}
	void init(){
		for(int i=0;i<val.size();i++){
			val[i] = idx[i] = 0;
		}
	}
	void setVal(int v, int i){
		int t = i + N - 1;
		val[t] = v;
		idx[t] = i;
		while(t){
			t = (t-1)/2;
			if(val[t] < v){
				val[t] = v;
				idx[t] = i;
			}
		}
	}
	pair<int, int> get(int l, int r, int p=0, int a=0, int b=N){
		if(b <= l || r <= a) return make_pair(-1, -1);
		if(l <= a && b <= r) return make_pair(val[p], idx[p]);
		return max(get(l, r, 2*p+1, a, (a+b)/2), get(l, r, 2*p+2, (a+b)/2, b));
	}
private:
	vector<int> val;
	vector<int> idx;
};

long long cost[5001][5001];
SegTree seg;

void update(int l, int r){
	if(l >= r) return;
	pair<int, int> p = seg.get(l, r);
	cost[l][p.second] += p.first;
	cost[l][r] -= p.first;
	cost[p.second+1][p.second] -= p.first;
	cost[p.second+1][r] += p.first;
	update(l, p.second);
	update(p.second+1, r);
}

