#include <bits/stdc++.h>

using namespace std;

const int N = 5e3 + 10;
const int M = 205;

struct segtree
{
  int n;
  vector<int> base;
  vector<int> c;
  void init(vector<int> sd)
  {
    n = 1;
    while(n < (int) sd.size()) n <<= 1;
    base = sd;
    c = vector<int> (n << 1, 0);
  }
  void update(int node, int l, int r, int ind)
  {
    if(l > ind || r < ind) return;
    if(l == r)
    {
      c[node] = ind;
      return;
    }
    update(node << 1, l, (l + r) / 2, ind);
    update((node << 1) + 1, (l + r) / 2 + 1, r, ind);
    c[node] = base[c[node << 1]] > base[c[(node << 1) + 1]] ? c[node << 1] : c[(node << 1) + 1];
  }
  void update(int ind)
  {
    update(1, 0, n - 1, ind);
  }
  int rmq(int node, int l, int r, int i, int j)
  {
    if(l > j || r < i) return -1;
    if(l >= i && r <= j) return c[node];
    int p1 = rmq(node << 1, l, (l + r) / 2, i, j), p2 = rmq((node << 1) + 1, (l + r) / 2 + 1, r, i, j);
    if(p1 == -1) return p2;
    if(p2 == -1) return p1;
    return base[p1] > base[p2] ? p1 : p2;
  }
  int rmq(int i, int j)
  {
    return rmq(1, 0, n - 1, i, j);
  }
  int getVal(int i)
  {
    return base[i];
  }
} st[M];

vector<vector<long long>> imos(N, vector<long long> (N, 0));

void solve(int m, int l, int r)
{
  if(l > r) return;
  int pos = st[m].rmq(l, r);
  imos[l][pos] += (long long) st[m].getVal(pos);
  imos[pos + 1][pos] -= (long long) st[m].getVal(pos);
  imos[l][r + 1] -= (long long) st[m].getVal(pos);
  imos[pos + 1][r + 1] += (long long) st[m].getVal(pos);
  solve(m, l, pos - 1);
  solve(m, pos + 1, r);
}

