}
inline void solve(void)
{
    for (int i=1;i<=m;i++)
    {
        for (int j=1;j<=n;j++)
        {
            while ( top && b[i][j] >= b[i][st[top]] )
                R[i][st[top]] = j-1 , top--;
            st[++top] = j;
        }
        while ( top ) R[i][st[top]] = n , top--;
        for (int j=n;j>=1;j--)
        {
            while ( top && b[i][j] >= b[i][st[top]] )
                L[i][st[top]] = j+1 , top--;
            st[++top] = j;
        }
        while ( top ) L[i][st[top]] = 1 , top--;
        for (int j=1;j<=n;j++)
        {
            sum[L[i][j]][j] += b[i][j];
            sum[L[i][j]][R[i][j]+1] -= b[i][j];
            sum[j+1][j] -= b[i][j];
            sum[j+1][R[i][j]+1] += b[i][j];
        }
    }
    for (int i=1;i<=n;i++)
        for (int j=1;j<=n;j++)
            sum[i][j] += sum[i-1][j] + sum[i][j-1] - sum[i-1][j-1];
    for (int i=1;i<=n;i++)
        for (int j=i;j<=n;j++)
            ans = max( ans , sum[i][j] - a[j] + a[i] );
}
