template<typename T>
struct imos2d{
	int n,m;
	T mod;
	vector<vector<T>>sum;
	bool flag=false;

	imos2d(){}
	imos2d(int n,int m,T mod=-1)
		:n(n),m(m),mod(mod),sum(vector<vector<T>>(n+2,vector<T>(m+2))){}

	void add(int x1,int y1,int x2,int y2,T t){
		assert(!flag);
		x1++;y1++;x2++;y2++;
		sum[x1][y1]+=t;
		sum[x1][y2+1]-=t;
		sum[x2+1][y1]-=t;
		sum[x2+1][y2+1]+=t;
		if(mod!=-1){
			sum[x1][y1]%=mod;
			(sum[x1][y2+1]+=mod)%=mod;
			(sum[x2+1][y1]+=mod)%=mod;
			sum[x2+1][y2+1]%=mod;
		}
	}

	void calc(){
		flag=true;
		rep(i,n+1)for(int j=1;j<=m;j++){
			sum[i][j]+=sum[i][j-1];
			if(mod!=-1)sum[i][j]%=mod;
		}
		rep(i,m+1)for(int j=1;j<=n;j++){
			sum[j][i]+=sum[j-1][i];
			if(mod!=-1)sum[j][i]%=mod;
		}
	}

	T get(int x,int y){
		if(!flag)calc();
		x++;y++;
		return sum[x][y];
	}
};
