#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int N, M;
vector <vector<int>> sparseTable;
vector <vector<int>> B;
vector<ll> dist;

void builldSparseTable(int ind, vector <int> &arr){
    int log_len_ceil = 32 - __builtin_clz(N);
    sparseTable[ind].resize(N*log_len_ceil+1);
    int potencias_2 = 2;
    for (int i = 0; i < log_len_ceil; i++) {
        potencias_2 *= 2;
        if (i == 0){
            potencias_2 = 0;
        } else if (i == 1){
            potencias_2 = 1;
        }
        for (int j = 0; j < N; ++j) {
            if (i == 0){
                sparseTable[ind][j] = arr[j];
            } else {
                sparseTable[ind][i*N+j] = max(sparseTable[ind][(i-1)*N + j], sparseTable[ind][(i-1)*N + j + potencias_2]);
            }
            if (j == N - potencias_2){
                break;
            }
        }
    }
}

int query(int b, int i, int j){ //inclusive
    if (i>j) swap(i,j);
    int log_query = 31 - __builtin_clz(j-i+1);
    int largo_query = 1 << log_query;
    return max(sparseTable[b][N*log_query + i], sparseTable[b][N*log_query + j-largo_query+1]);
}

ll total_dist(int i, int j){
    if (!j) return 0;
    j--;
    ll ans = dist[j];
    if (i) ans -= dist[i-1];
    return ans;
}

ll memo[5050];

void dp(int l, int r, int optl, int optr){
    if (l>r) return;
    int mid = (l+r)/2;
    ll val = -1e18, pos = 0;
    for (int i = optl; i <= min(mid, optr); ++i) {
        ll aux = -total_dist(i, mid);
        for (int j = 0; j < M; ++j) {
            aux += query(j, i, mid);
        }
        if (aux > val) val = aux, pos = i;
    }
    memo[mid] = val;
    dp(l, mid-1, optl, pos);
    dp(mid+1, r, pos, optr);
}


int main() {
    ios::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);
    cin >> N >> M;
    dist.resize(N-1);
    for (int i = 0; i < N-1; ++i) {
        cin >> dist[i];
        if (i) dist[i] += dist[i-1];
    }
    B.assign(M, vector<int>(N));
    for (int j = 0; j < N; ++j) for (int i = 0; i < M; ++i) cin >> B[i][j];
    sparseTable.assign(M, vector<int>());
    for (int k = 0; k < M; ++k) {
        builldSparseTable(k, B[k]);
    }
    ll ans = -1e18;
    dp(0, N-1, 0, N-1);
    for (int l = 0; l < N; ++l) {
        ans = max(ans, memo[l]);
    }
    cout << ans << "\n";
}

