vector<ll> psum;
vector<vector<int> > B;
vector<ll> P;
vector<stack<pair<ll, int> > > st;

int main() {
    scanf("%d %d", &N, &M);

    A.resize(N - 1);
    for(int i = 0; i < N - 1; i++) {
        scanf("%d", &A[i]);
    }
    psum.resize(N - 1);
    for(int i = 0; i < N - 1; i++) {
        psum[i] = A[i];
        if(i) psum[i] += psum[i - 1];
    }

    B = vector<vector<int> >(N, vector<int>(M));
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < M; j++) {
            scanf("%d", &B[i][j]);
        }
    }

    P = vector<ll>(N, 0);
    st = vector<stack<pair<ll, int> > >(M);
    ll ans = 0;

    for(int i = N - 1; i >= 0; i--) {
        ll sum = 0;
        for(int j = 0; j < M; j++) {
            while(!st[j].empty() && st[j].top().first <= B[i][j]) {
                pair<ll, int> t = st[j].top();
                st[j].pop();
                if(!st[j].empty()) P[ st[j].top().second ] -= (B[ st[j].top().second ][j] - t.first);
            }
            if(!st[j].empty()) P[ st[j].top().second ] += (B[ st[j].top().second ][j] - B[i][j]);
            st[j].push(make_pair(B[i][j], i));

            sum += B[i][j];
        }
        ans = max(ans, sum);
        for(int j = i + 1; j < N; j++) {
            sum += P[j];
            ans = max(ans, sum - (psum[j - 1] - (i == 0? 0 : psum[i - 1])));
        }
    }

