inline void add(int x, int y, int z, int w, ll val){
	y ++; w ++;
	ans[x][z] += val;
	ans[y][z] -= val;
	ans[x][w] -= val;
	ans[y][w] += val;
	return;
}

int main(){
	ios::sync_with_stdio(false); cin.tie(0);
	int n, m; cin >> n >> m;

	for(int i = 0; i < n - 1; i ++) cin >> a[i], ps[i + 1] = ps[i] + a[i];

	for(int i = 0; i < n; i ++)
		for(int j = 0; j < m; j ++)
			cin >> b[i][j];

	for(int i = 0; i < m; i ++){
		v.clear();
		for(int j = 0; j < n; j ++)
			v.pb({b[j][i], j});
		fill(l, l + n, -1);
		fill(r, r + n, n);
		c.clear();
		for(int j = 0; j < n; j ++){
			while(c.size() and v[c.back()].F < v[j].F){
				r[c.back()] = j;
				c.pop_back();
			}
			c.pb(j);
		}
		c.clear();
		for(int j = n - 1; j > -1; j --){
			while(c.size() and v[c.back()].F <= v[j].F){
				l[c.back()] = j;
				c.pop_back();
			}
			c.pb(j);
		}

		for(int j = 0; j < n; j ++){
			add(l[j] + 1, j, j, r[j] - 1, v[j].F);
		}
	}

	for(int i = 0; i < n; i ++){
		for(int j = 0; j < n; j ++){
			if(i) ans[i][j] += ans[i - 1][j];
			if(j) ans[i][j] += ans[i][j - 1];
			if(i and j) ans[i][j] -= ans[i - 1][j - 1];
		}
	}

	ll fans = 0;
	for(int i = 0; i < n; i ++){
		for(int j = 0; j < n; j ++){
			ans[i][j] -= ps[j] - ps[i];
			fans = max(fans, ans[i][j]);

		}
	}

	cout << fans << endl;

	return 0;	
}

