    for(ll r=l;r<N;r++){
      repeat(j,M){
        if(mB[j]<B[r][j]){
          sum += -mB[j]+B[r][j];
          mB[j]=B[r][j];
        }
      }
      ans = max(ans,sum-(A[r]-A[l]));
    }
  }
  cout << ans << endl;
  return 0;
}

