ll cum[5050];
void solve() {
    cin >> N >> M;
    A.resize(N - 1);
    REP(i, N - 1) {
        cin >> A[i];
        cum[i + 1] = cum[i] + A[i];
    }
    REP(j, M) {
        val[j].resize(N);
        vp[j].resize(N);
    }
    REP(i, N) REP(j, M) {
        cin >> val[j][i];
        vp[j][i] = {val[j][i], i};
    }
    auto f = [](pii a, pii b) { return max(a, b); };
    vector<SegmentTree<pii>> seg(M, SegmentTree<pii>(N, {0, 0}, f));
    REP(j, M) {
        REP(i, N) { seg[j].update(i, vp[j][i]); }
    }
    REP(j, M) {
        // DEBUG(j);
        auto func = [&](auto f, int l, int r) -> void {
            if (l >= r) return;
            // DEBUG(l);
            // DEBUG(r);
            pii p = seg[j].query(l, r);
            int i = p.second;
            // DEBUG(i);
            int v = p.first;
            sum[l][i + 1] += v;
            sum[i + 1][r + 1] += v;
            sum[i + 1][i + 1] -= v;
            sum[l][r + 1] -= v;
            f(f, l, i);
            f(f, i + 1, r);
        };
        // print("a");
        func(func, 0, N);
        // print("b");
    }
    REP(i, N + 1) {
        REP(j, N + 1) {
            sum[i + 1][j] += sum[i][j];
            sum[i][j + 1] += sum[i][j];
            sum[i + 1][j + 1] -= sum[i][j];
        }
    }
    // REP(i, N + 1) {
    //     REP(j, N + 1) { cout << sum[i][j] << " "; }
    //     cout << endl;
    // }
    ll ans = 0;
    REP(l, N) {
        FOR(r, l + 1, N + 1) {
            ll res = -(cum[r - 1] - cum[l]);
            res += sum[l][r];
            chmax(ans, res);
        }
    }
    print(ans);
}

