const int depth = 13;
class SegTree {
public:
	int data[1 << 14][200];
	int ssum[1 << 14];
	SegTree() { for (int i = 0; i < (1 << (depth + 1)); i++){ ssum[i] = 0; for (int j = 0; j < m; j++) data[i][j] = 0; } }

	void insert(int x, int b[]) {
		x = x + (1 << depth) - 1;
		ssum[x] = 0;
		for (int i = 0; i < m; i++) { data[x][i] = b[i]; ssum[x] += b[i]; }

		while (x > 0) {
			x = (x - 1) / 2;

			ssum[x] = 0;
			for (int i = 0; i < m; i++) {
				data[x][i] = max(data[2 * x + 1][i], data[2 * x + 2][i]);
				ssum[x] += data[x][i];
			}
		}
	}

	//[l, r)
	int query(int l, int r, int a = 0, int b = (1 << depth), int id = 0) {
		if (a >= r || b <= l) {
			return 0;
		}
		if (l <= a && b <= r) {
			return ssum[id];
		}

		int u = query(l, r, a, a + (b - a) / 2, id * 2 + 1);
		int v = query(l, r, a + (b - a) / 2, b, id * 2 + 2);
		return u + v;
	}
}seg;

