	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> M;
	for (int i = 1; i < N; i++) {
		cin >> A[i];
	}
	for (int i = 1; i < N; i++) {
		A[i] += A[i-1];
	}

	for (int i = 0; i < N; i++) {
		for (int j = 0; j < M; j++) {
			cin >> B[i][j];
		}
	}

	for (int z = 0; z < M; z++) {
		vector<int> v(N);
		for (int i = 0; i < N; i++) {
			v[i] = B[i][z];
		}
		vector<int> lInd(N);
		vector<int> rInd(N);

		{
			vector<int> st;
			for (int i = 0; i < N; i++) {
				while (!st.empty() && v[st.back()] < v[i]) {
					st.pop_back();
				}
				lInd[i] = (st.empty() ? 0 : st.back() + 1);
				st.push_back(i);
			}
		}

		{
			vector<int> st;
			for (int i = N-1; i >= 0; i--) {
				while (!st.empty() && v[st.back()] < v[i]) {
					st.pop_back();
				}
				rInd[i] = (st.empty() ? N-1 : st.back() - 1);
				st.push_back(i);
			}
		}

		auto update = [&](int xlo, int xhi, int ylo, int yhi, int d) -> void { // half open
			assert(xlo < xhi && ylo < yhi);
			sum[xlo][ylo] += d;
			sum[xlo][yhi] -= d; 
			sum[xhi][ylo] -= d;
			sum[xhi][yhi] += d;
		};

		for (int i = 0; i < N; i++) {
			update(lInd[i], i+1, i, rInd[i]+1, v[i]);
		}
	}

	for (int i = 0; i < N; i++) {
		for (int j = 1; j < N; j++) {
			sum[i][j] += sum[i][j-1];
		}
	}
	for (int j = 0; j < N; j++) {
		for (int i = 1; i < N; i++) {
			sum[i][j] += sum[i-1][j];
		}
	}

	ll ans = -INF;
	for (int l = 0; l < N; l++) {
		for (int r = l; r < N; r++) {
			ll cost = -A[r] + A[l] + sum[l][r];
			ans = max(ans, cost);
		}
	}
	cout << ans << '\n';

	return 0;
}

