class SegTree {
public:
    enum { N = 8192 };
    SegTree() : val(2*N-1){}
    void init(){
        val.assign(val.size(), make_pair(0, 0));
    }
    void update(int v, int i){
        int t = i + N - 1;
        val[t] = make_pair(v, i);
        while(t){
            t = (t-1)/2;
            if(val[t].first < v){
                val[t] = make_pair(v, i);
            }
        }
    }
    pair<int, int> get(int l, int r, int p=0, int a=0, int b=N){
        if(b <= l || r <= a) return make_pair(-1, -1);
        if(l <= a && b <= r) return val[p];
        return max(get(l, r, 2*p+1, a, (a+b)/2), get(l, r, 2*p+2, (a+b)/2, b));
    }
private:
    vector< pair<int, int> > val;
};


ll F[5002][5002];
ll A[5002];
ll B[202][5002];
SegTree st;


void dfs(int l, int r){
    if (r <= l) return;

    pair<int, int> p = st.get(l, r);

    F[l][p.second] += p.first;
    F[l][r] -= p.first;
    F[p.second+1][p.second] -= p.first;
    F[p.second+1][r] += p.first;

    dfs(l, p.second);
    dfs(p.second+1, r);
}


