const ll MOD = 1000000007;
const int INF = 1<<29;

int N, M;
ll x[5002];
ll F[5002][5002];
ll B[202][5002];

class IndexSegmentTree{
private:
    int n;
    vector<int> dat;
    vector<int> v;
public:
    void init(int p){
        n = 1;
        while(n < N) n *= 2;
        v.assign(n, INF);
        for(int i=0;i<N;i++){
            v[i] = -B[i][p];
        }
        dat.resize(2*n-1);
        for(int i=0;i<N;i++){
            dat[i+n-1] = i;
        }
        for(int i=N+n-1;i<2*n-1;i++){
            dat[i] = -1;
        }
        for(int k=n-2;k>=0;k--){
            if(dat[k*2+2]==-1 || v[dat[k*2+1]]<=v[dat[k*2+2]]){
                dat[k] = dat[k*2+1];
            }else{
                dat[k] = dat[k*2+2];
            }
        }
    }
    // k: index(0-indexed), a: value
    void update(int k, int a){
        v[k] = a;
        k += n-1;
        while(k>0){
            k = (k-1)/2;
            if(dat[k*2+2]==-1 || v[dat[k*2+1]]<=v[dat[k*2+2]]){
                dat[k] = dat[k*2+1];
            }else{
                dat[k] = dat[k*2+2];
            }
        }
    }
    // query(a, b) =>  minimum in [a,b)
    int query(int a, int b){
        return _query(a, b-1, 0, 0, n-1);
    }
    // v[dat[k]] is minimum in [l,r]
    int _query(int a, int b, int k, int l, int r){
        if(r<a||b<l) return -1;
        if(a<=l&&r<=b){
            return dat[k];
        }else{
            int vl = _query(a, b, k*2+1, l, (l+r)/2);
            int vr = _query(a, b, k*2+2, (l+r)/2+1, r);
            if(vr==-1){
                return vl;
            }else if(vl==-1){
                return vr;
            }else{
                if (v[vl]>v[vr]){
                    return vr;
                }else{
                    return vl;
                }
            }
        }
    }
    // k: index(0-indexed)
    int get(int k){
        return v[k];
    }
};

void dfs(int p, int l, int r, IndexSegmentTree& st){
    if (l < 0 || N < r || r <= l) return;

    int max_idx = st.query(l, r);

    ll v = B[max_idx][p];
    F[l][max_idx] += v;
    if (r < N) F[l][r] -= v;
    if (max_idx+1 < N) F[max_idx+1][max_idx] -= v;
    if (max_idx+1 < N && r < N) F[max_idx+1][r] += v;

    dfs(p, l, max_idx-1, st);
    dfs(p, max_idx+1, r, st);
}

