Long ans[MX][MX];
pair<Long,Long> st[MX<<2];

void build(Long l, Long r, Long nodo, Long t){
	if(l == r){
		st[nodo] = {cel[l][t],l};
		return;
	}
	Long med = (l+r)/2;
	build(l,med,nodo*2,t);
	build(med+1,r,nodo*2+1,t);
	st[nodo] = max(st[nodo * 2],st[2 * nodo + 1]);
	return;
}

pair<Long,Long> query(Long ini, Long fin, Long l, Long r, Long nodo){
	if(fin<l || r<ini) return {0ll,0ll};
	if(ini<=l && r<=fin) return st[nodo];
	Long med=(l+r)/2;
	pair<Long,Long> L = query(ini,fin,l,med,nodo*2);
	pair<Long,Long> R = query(ini,fin,med+1,r,nodo*2+1);
	return max(L,R);
}

void updateAns(Long l, Long r, Long n){
	if(l > r) return;
	pair<Long,Long> aux = query(l,r,0,n-1,1);
	Long mnx = l;
	Long mny = aux.second;
	Long mxx = aux.second;
	Long mxy = r;
	//cout << l << " " << r << " " << aux.first << " " << aux.second << " -> " << mnx << " " << mny << " | " << mxx << " " << mxy << endl;
	ans[mnx][mny] += aux.first;
	ans[mnx][mxy + 1] -= aux.first;
	ans[mxx + 1][mny] -= aux.first;
	ans[mxx + 1][mxy + 1] += aux.first;
	updateAns(l,aux.second - 1,n);
	updateAns(aux.second + 1,r,n);
	return;
}

