void up(int x){t[x]=max(t[lc(x)],t[rc(x)]);}
void dn(int x)
{
	if(!tag[x])return;
	t[lc(x)]+=tag[x];tag[lc(x)]+=tag[x];
	t[rc(x)]+=tag[x];tag[rc(x)]+=tag[x];
	tag[x]=0;
}
void build(int x,int l,int r)
{
	if(l==r){t[x]=a[l];return;}
	int mid=(l+r)>>1;
	build(lc(x),l,mid);
	build(rc(x),mid+1,r);
	up(x);
}
void modify(int x,int l,int r)
{
	if(L<=l&&r<=R){t[x]+=val;tag[x]+=val;return;}
	dn(x);int mid=(l+r)>>1;
	if(L<=mid)modify(lc(x),l,mid);
	if(R>mid)modify(rc(x),mid+1,r);
	up(x);
}
void query(int x,int l,int r)
{
	if(L<=l&&r<=R){anss=max(anss,t[x]);return;}
	dn(x);int mid=(l+r)>>1;
	if(L<=mid)query(lc(x),l,mid);
	if(R>mid)query(rc(x),mid+1,r);
}
