		if(l&1) {
			int a = st[l++][id];
			if(w[a][id] > w[ma][id]) {
				ma = a;
			}
		}
		if(r&1) {
			int a = st[--r][id];
			if(w[a][id] > w[ma][id]) {
				ma = a;
			}
		}
	}
	return ma;
}
void get(int l, int r, int id) {
	if(l >= r) {return;}
	int val = qu(l,r,id);
	res[l][val] += w[val][id];
	res[val+1][val] -= w[val][id];
	res[l][r] -= w[val][id];
	res[val+1][r] += w[val][id];
	get(l,val,id);
	get(val+1,r,id);
}
ll resolve() {
	for(int j=0;j<n;j++) {
		for(int i=0;i<n;i++) {
			res[i+1][j] += res[i][j];
		}
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<n;j++) {
			res[i][j+1] += res[i][j];
		}
	}
	ll ma = -INF;
	for(int i=0;i<n;i++) {
		for(int j=i;j<n;j++) {
			//cout << "ij " << i << " " << j << " = " << res[i][j] << "-" << pr[j]-pr[i] << '\n';
			res[i][j] -= pr[j]-pr[i];
			ma = max(ma,res[i][j]);
		}
	}
	return ma;
}
int main() {
	ios::sync_with_stdio(0);cin.tie(0);
	cin >> n >> m;
	memset(res,0,sizeof(res));
	pr[0] = 0;
	for(int i=0;i<n-1;i++) {
		cin >> cs[i];
		pr[i+1] = pr[i]+cs[i];
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<m;j++) {
			cin >> w[i][j];
			st[i+n][j] = i;
		}
	}
	build();
	for(int i=0;i<m;i++) {
		get(0,n,i);
	}
	cout << resolve() << '\n';
}

