struct rmq {
  static int ilog2(int x){ return 31 - __builtin_clz(x); }
  rmq(){
    FOR(i,LN) FOR(j,N) A[i][j]=-1;
  }
  int n;
  lli A[LN][N];

  inline void build(){
    FOR(a, LN) if(a) {
      int sa=1<<(a-1);
      FOR(i, n-(1<<a)) A[a][i] = max(A[a-1][i], A[a-1][i+sa]);
    }
  }

  inline int query(int x1, int x2) {
    int dx = x2-x1+1;
    int sx = ilog2(dx);
    int ax = 1<<sx;
    return max(A[sx][x1],A[sx][x2+1-ax]);
  };

};

lli n,m;
