rmq R[200];
lli ans=0;

void calc(lli l,lli r,lli optL,lli optR){
  lli mi = (l+r)/2;
  lli optM=optL; lli curval=0;
  FORU(k, max(mi,optL), optR){
    lli val = 0;
    FOR(j,m) val += R[j].query(mi, k);
    val -= (S[k]-S[mi]);
    if(val > curval) { curval = val; optM = k; }
  }
  ans = max(ans, curval);
  if(l<r-1) {
    calc(l,mi,optL,optM);
    calc(mi,r,optM,optR);
  }
}

