void addblock(int x1, int x2, int y1, int y2, ll x) {
	S[x1][x2] += x;
	S[x1][y2] -= x;
	S[y1][x2] -= x;
	S[y1][y2] += x;
}


void dfs(int a, int b, int mi, int mj) {
	if(a == b) return;
	pl p = seg.get(a, b).v;
	ll v = p.fst; int t = p.sec;
	addblock(mi, t, t + 1, mj, v);
	dfs(a, t, mi, t);
	dfs(t + 1, b, t + 1, mj);
}

