void solve(int i, int l, int r) {
  int most = 0;
  int opt = 0;
  if(l == r) return;

  for(int j = l; j < r; j++) {
    if(most < b[j][i]) {
      opt = j;
      most = b[j][i];
    }
  }

  table[l][opt] += most;
  table[l][r] -= most;
  table[opt+1][opt] -= most;
  table[opt+1][r] += most;

  solve(i,l,opt);
  solve(i,opt+1,r);
}

