    vector<vector<int>> B(N, vector<int>(M));
    for (auto &row : B) for (auto &b : row) cin >> b;
    vector<vector<int>> C(N, vector<int>(M, 1e9));
    for (int i = 0; i < M; i++) {
        set<pair<int, int>> S;
        for (int a = N - 1; a >= 0; a--) {
            auto it = S.lower_bound(make_pair(B[a][i] + 1, 0));
            if (it == S.end()) {
                S.emplace(B[a][i], a);
            } else {
                C[a][i] = it->second;
                auto it2 = S.emplace(B[a][i], a).first;
                while (it2 != S.begin()) {
                    S.erase(prev(it2));
                }
            }
        }
    }
    vector<vector<bool>> used(N, vector<bool>(M));
    vector<Int> diff(N);
    for (int i = 1; i < N; i++) {
        diff[i] = -A[i - 1];
    }
    Int ans = 0;
    for (int start = 0; start < N; start++) {
        for (int i = 0; i < M; i++) {
            int a = start;
            int b = C[start][i];
            while (b < N && !used[b][i]) {
                diff[b] += B[b][i] - B[a][i];
                used[b][i] = true;
                a = b;
                b = C[b][i];
            }
        }
        Int tmp = 0;
        for (int i = 0; i < M; i++) {
            tmp += B[start][i];
        }
        ans = max(ans, tmp);
        for (int i = start + 1; i < N; i++) {
            tmp += diff[i];
            ans = max(ans, tmp);
        }
        for (int i = 0; i < M; i++) {
            int a = start;
            int b = C[start][i];
            if (b < N) {
                diff[b] -= B[b][i] - B[a][i];
                used[b][i] = false;
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

