void pwd(int k,int l,int r){
	if(l==r) return;
	l=k<<1,r=k<<1|1;
	if(t[k].add){
		t[l].add+=t[k].add;
		t[r].add+=t[k].add;
		t[l].mx+=t[k].add;
		t[r].mx+=t[k].add;
		t[k].add=0;
	}
}
void build(int k,int l,int r){
	if(l==r){
		t[k].mx=b[l];
		return;
	}
	int mid=l+r>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
	t[k].mx=max(t[k<<1].mx,t[k<<1|1].mx);
}
void update(int k,int l,int r,int L,int R,ll val){
	pwd(k,l,r);
	if(L<=l&&R>=r){
		t[k].add+=val;
		t[k].mx+=val;
		return;
	}
	int mid=l+r>>1;
	if(L<=mid) update(k<<1,l,mid,L,R,val);
	if(R>mid) update(k<<1|1,mid+1,r,L,R,val);
	t[k].mx=max(t[k<<1].mx,t[k<<1|1].mx);
}
