void join(int p, int q)
{
	if (mate[p] == p) {
		if (mate[q] == q) {
			mate[p] = q;
			mate[q] = p;
		} else {
			mate[p] = mate[q];
			mate[mate[q]] = p;
		}
	} else {
		if (mate[q] == q) {
			mate[q] = mate[p];
			mate[mate[p]] = q;
		} else {
			mate[mate[p]] = mate[q];
			mate[mate[q]] = mate[p];
		}
	}
}

