		for (int j = 0; j < M; ++j) scanf("%lld", &(B[i][j]));
	}
	for (int i = 0; i < M; ++i) {
		vector<pair<i64, int> > cand;
		for (int j = 0; j < N; ++j) cand.push_back({ B[j][i], j });
		sort(cand.begin(), cand.end());

		for (int j = 0; j <= N + 1; ++j) {
			vis[j] = false;
			mate[j] = j;
		}
		for (auto p : cand) {
			int idx = p.second + 1;
			int lf = idx, rg = idx;
			vis[idx] = true;
			if (vis[idx - 1]) {
				lf = mate[idx - 1];
				join(idx - 1, idx);
			} 
			if (vis[idx + 1]) {
				rg = mate[idx + 1];
				join(idx, idx + 1);
			}
		//	printf("%d--%d, %d--%d %lld\n", lf, idx, idx, rg, p.first);
			imos[lf][idx] += p.first;
			imos[lf][rg + 1] -= p.first;
			imos[idx + 1][idx] -= p.first;
			imos[idx + 1][rg + 1] += p.first;
		}
	}
	for (int i = 0; i <= N; ++i) {
		for (int j = 1; j <= N; ++j) {
			imos[i][j] += imos[i][j - 1];
		}
	}
	for (int i = 1; i <= N; ++i) {
		for (int j = 0; j <= N; ++j) {
			imos[i][j] += imos[i - 1][j];
