  }
  REP( i , n-1 ){
    as[i+1] = as[i] + a[i];
  }
  REP( i , n ){
    REP( j , m ){
      b[i][j] = in();
      v[j].pb( b[i][j] , i );
    }
  }
  REP( i , m ){
    SORT( v[i] );
    REVERSE( v[i] );
    set<int> used;
