			return tuple<ll, P, P, P>(sum, { sum, b[l] }, { sum, b[l] }, { sum, b[l] });
		}
		auto p = f(l, r - (r - l) / 2);
		auto q = f(r - (r - l) / 2, r);

		ll sum = max(get<0>(p), get<0>(q));
		{
			ll x_sum = -(a_sum[r - 1] - a_sum[l]);
			REP(i, m) x_sum += max(get<3>(p).second[i], get<1>(q).second[i]);
			sum = max(sum, x_sum);
		}

		auto l_v = get<1>(p);
		{
			vl x(m);
			ll x_sum = -(a_sum[r - 1] - a_sum[l]);
			REP(i, m) {
				x[i] = max(get<2>(p).second[i], get<1>(q).second[i]);
				x_sum += x[i];
			}
			sum = max(sum, x_sum);
			if (l_v.first < x_sum) l_v = { x_sum, move(x) };
		}

		auto r_v = get<3>(q);
		{
			vl x(m);
			ll x_sum = -(a_sum[r - 1] - a_sum[l]);
			REP(i, m) {
				x[i] = max(get<3>(p).second[i], get<2>(q).second[i]);
				x_sum += x[i];
			}
			sum = max(sum, x_sum);
			if (r_v.first < x_sum) r_v = { x_sum, move(x) };
		}

		P all_v;
		all_v.first = -(a_sum[r - 1] - a_sum[l]);
		all_v.second = vl(m);
		REP(i, m) {
			all_v.second[i] = max(get<2>(p).second[i], get<2>(q).second[i]);
			all_v.first += all_v.second[i];
		}
		sum = max(sum, all_v.first);
		if (r_v.first < all_v.first) r_v = all_v;
		if (l_v.first < all_v.first) r_v = all_v;

		return tuple<ll, P, P, P>(sum, l_v, all_v, r_v);
	};

	auto x = f(0, n);
