void Compute (int l, int r, int opl, int opr)
{
    if (l > r) return;

    int md = (l + r) >> 1, opt;

    for (int i = min(opr, md); i >= opl; i--)
    {
        long long ans = 0;
        for (int j = 1; j <= m; j++)
        {
            cur[j] = max( cur[j], ar[i][j] );
            ans += cur[j];
