    rep(i, n-1) cin >> a[i+1];
    rep(i, n) rep(j, m) cin >>b[j][i];

    rep(i, m) {
        auto& v = b[i];
        vi idx(n);
        rep(i, n) idx[i] = i;
        sort(all(idx), [&](int a, int b) {return v[a] > v[b];});
        set<int> st;
        for(const auto& id : idx) {
            int l = 0, r = n-1;
            auto pre = st.lower_bound(id);
            if(pre != st.begin()) {
                --pre;
                l = *pre;
                ++l;
            }
            auto nxt = st.upper_bound(id);
            if(nxt != st.end()) {
                r = *nxt;
                --r;
            }
            d[l][id] += v[id];
            d[l][r+1] -= v[id];
            d[id+1][id] -= v[id];
            d[id+1][r+1] += v[id];

            st.insert(id);
        }
    }
    rep(i, n) rep(j, n+1) {
        d[i+1][j] += d[i][j];
    }  
    rep(i, n+1) rep(j, n) {
        d[i][j+1] += d[i][j]; 
    }

    rep(i, n-1) {
        a[i+1] += a[i];
    }
    ll ans = 0LL;
    rep(i, n) REP(j, i, n) {
        ans = max(ans, d[i][j] - (a[j] - a[i]));
    } 
    cout << ans << endl;
    return 0;
}

