            _n = _vec.size();
            for (int i = 1; i < _n; i++) {
                _vec[i] += _vec[i - 1];
            }
        };

        T interval(int l, int r){
            if(l > r){
                return 0;
            }
            T ans = _vec[r];
            if(l > 0){
                ans -= _vec[l - 1];
            }
            return ans;
        }
    private:
        vector<T> _vec;
        int _n;
    };
}

