using namespace dalt;

vector<ll> as;
vector<vector<int>> bs;
vector<int> head;
vector<int> tail;
deque<int> deq;
vector<vector<ll>> intervals;
presum<ll> ps;


class arc067_d {
public:

    void solve(std::istream &in, std::ostream &out) {
        int n, m;
        in >> n >> m;
        as.resize(n - 1);
        bs.resize(n, vector<int>(m));
        head.resize(n);
        tail.resize(n);
        intervals.resize(n, vector<ll>(n));

        for (int i = 0; i < n - 1; i++) {
            in >> as[i];
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                in >> bs[i][j];
            }
        }

        for (int i = 0; i < m; i++) {
            deq.clear();
            for (int j = 0; j < n; j++) {
                while (!deq.empty() && bs[deq.back()][i] <= bs[j][i]) {
                    tail[deq.back()] = j - 1;
                    deq.pop_back();
                }
                deq.push_back(j);
            }
            while (!deq.empty()) {
                tail[deq.back()] = n - 1;
                deq.pop_back();
            }
            deq.clear();
            for (int j = n - 1; j >= 0; j--) {
                while (!deq.empty() && bs[deq.front()][i] <= bs[j][i]) {
                    head[deq.front()] = j + 1;
                    deq.pop_front();
                }
                deq.push_front(j);
            }
            while (!deq.empty()) {
                head[deq.front()] = 0;
                deq.pop_front();
            }

            for (int j = 0; j < n; j++) {
                intervals[head[j]][tail[j]] += bs[j][i];
                if (head[j] < j) {
                    intervals[head[j]][j - 1] -= bs[j][i];
                }
                if (tail[j] > j) {
                    intervals[j + 1][tail[j]] -= bs[j][i];
                }
                //std::cerr << j << "=(" << head[j] << ", " << tail[j] << ")" << endl;
            }
        }

        ps.populate(as);
        for (int i = 0; i < n; i++) {
            for (int j = n - 1; j >= i; j--) {
                if (i - 1 >= 0) {
                    intervals[i][j] += intervals[i - 1][j];
                }
                if (j + 1 <= n - 1) {
                    intervals[i][j] += intervals[i][j + 1];
                }
                if (i - 1 >= 0 && j + 1 <= n - 1) {
                    intervals[i][j] -= intervals[i - 1][j + 1];
                }
            }
        }

        ll ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                ll s = intervals[i][j] - ps.interval(i, j - 1);
                ans = max(ans, s);
            }
        }

        out << ans;

    }

private:
};


