			ll sum = 0; REP(i, m) sum += b[l][i];
			return tuple<ll, P, P, P>(sum, { sum, b[l] }, { sum, b[l] }, { sum, b[l] });
		}
		auto p = f(l, r - (r - l) / 2);
		auto q = f(r - (r - l) / 2, r);

		ll sum = max(get<0>(p), get<0>(q));
		{
			ll x_sum = -(a_sum[r - 1] - a_sum[l]);
			REP(i, m) x_sum += max(get<3>(p).second[i], get<1>(q).second[i]);
			sum = max(sum, x_sum);
		}

		auto l_v = get<1>(p);
		{
			vl x(m);
			ll x_sum = -(a_sum[r - 1] - a_sum[l]);
			REP(i, m) {
				x[i] = max(get<2>(p).second[i], get<1>(q).second[i]);
				x_sum += x[i];
			}
			sum = max(sum, x_sum);
			if (l_v.first < x_sum) l_v = { x_sum, move(x) };
		}

		auto r_v = get<3>(q);
		{
			vl x(m);
			ll x_sum = -(a_sum[r - 1] - a_sum[l]);
			REP(i, m) {
				x[i] = max(get<3>(p).second[i], get<2>(q).second[i]);
