			all_v.second[i] = max(get<2>(p).second[i], get<2>(q).second[i]);
			all_v.first += all_v.second[i];
		}
		sum = max(sum, all_v.first);
		if (r_v.first < all_v.first) r_v = all_v;
		if (l_v.first < all_v.first) l_v = all_v;

		return tuple<ll, P, P, P>(sum, l_v, all_v, r_v);
	};

	auto x = f(0, n);
	cout << get<0>(x) << endl;

	return 0;
}

