}


void update(ll L,ll R,ll node,ll l,ll r,ll v){
    if(l<=L && R<=r){
        lazy[node]+=v;
        seg[node]+=v;
        return;
    }
    if(R<=l || r<=L){
        return ;
    }
    ll mid=(L+R)/2;
    shift(node);
    update(L,mid,2*node  ,l,r,v);
    update(mid,R,2*node+1,l,r,v);
    seg[node]=max(seg[2*node],seg[2*node+1]);
}
