    A[i] += A[i - 1];
  }
  std::vector<std::vector<i64>> B_impl(M, std::vector<i64>(N));
  for (size_t i = 0; i < N; ++i) {
    for (size_t j = 0; j < M; ++j) {
      std::cin >> B_impl[j][i];
    }
  }
  std::vector<disjoint_sparse_table<range_max>> B(M);
  for (size_t i = 0; i < M; ++i) {
    B[i].build(B_impl[i]);
  }
  struct query { size_t l, r, d, u; };
  std::queue<query> que;
  que.push(query{ 0, N, 0, N - 1 });
  i64 ans = -inf64;
  while (!que.empty()) {
    auto q = que.front();
    que.pop();
    size_t ml = (q.l + q.r) / 2;
    i64 max = -inf64;
    size_t mr = ml;
    for (size_t i = std::max(ml, q.d); i <= q.u; ++i) {
