      }
      if (chmax(max, sum)) {
        mr = i;
      }
    }
    chmax(ans, max);
    if (q.r - q.l > 1) {
      que.push(query{ q.l, ml, q.d, mr });
      que.push(query{ ml, q.r, mr, q.u });
    }
  }
  std::cout << ans << '\n';
  return 0;
