using P = pair<ll, int>;
struct Max
{
    using T = P;
    T operator()(const T& a, const T& b) const { return max(a, b); }
    static constexpr T identity() { return P{-INF<ll>, -INF<int>}; }
};
template <typename Base>
class SparseTable
{
public:
    using T = typename Base::T;
    using SemiLattice = Base;
    SparseTable(const vector<T>& val) : size(val.size()), lg2(size + 1, 0)
    {
        for (int i = 2; i <= size; i++) {
            lg2[i] = lg2[i / 2] + 1;
        }
        table.resize(size, vector<T>(lg2[size] + 1));
        for (int i = 0; i < size; i++) {
            table[i][0] = val[i];
        }
        for (int j = 0; j < lg2[size]; j++) {
            const int w = 1 << j;
            for (int i = 0; i <= size - (w << 1); i++) {
                T tl = table[i][j], tr = table[i + w][j];
                table[i][j + 1] = op(tl, tr);
            }
        }
    }
    T accumulate(const int l, const int r) const
    {
        assert(0 <= l and l < r and r <= size);
        const int j = lg2[r - l];
        return op(table[l][j], table[r - (1 << j)][j]);
    }

private:
    const int size;
    vector<int> lg2;
    vector<vector<T>> table;
    const SemiLattice op{};
};
using ST = SparseTable<Max>;
int N, M;
void rec(const int inf, const int sup, vector<vector<ll>>& imos, const ST& stable)
{
    if (inf >= sup) return;
    const auto p = stable.accumulate(inf, sup);
    const int ind = p.second;
    const ll v = p.first;
    imos[ind][ind] += v;
    if (inf > 0) {
        imos[ind][inf - 1] -= v;
        if (sup < N) {
            imos[sup][inf - 1] += v;
        }
    }
    if (sup < N) {
        imos[sup][ind] -= v;
    }
    rec(inf, ind, imos, stable);
    rec(ind + 1, sup, imos, stable);
}

