template<class T> struct IRXQ {
    static const int npos = -1;

    int n, g; T *d;
    IRXQ() : n(0), g(0), d(NULL) {}
    template<class Iter> IRXQ(Iter begin, Iter end) : n(0), g(0), d(0) { build(begin, end); }
    IRXQ(const IRXQ &y) : n(y.n), g(0), d(NULL) { if (y.n) build(y.d[0], y.d[0] + n); }
    IRXQ(IRXQ &&y) : n(0), g(0), d(NULL) { swap(*this, y); }
    ~IRXQ() { if (n) { n = 0; delete d; d = NULL; } }
    friend void swap(IRXQ &x, IRXQ &y) { swap(x.n, y.n); swap(x.g, y.g); swap(x.d, y.d); }
    IRXQ& operator=(IRXQ y) { swap(*this, y); return *this; }

    template<class Iter> void build(Iter begin, Iter end) { // random access iterator
	n = end - begin;
	if (n == 0) return;
	g = __lg(n);
	d = new T[n*(g+1)];
	REP (i, n) { d[i] = *begin; ++begin; }
	for (int t=0, b=0; t<g; t++, b+=n) for (int i=0, j=1<<t; j<=n-(1<<t); i++, j++)
	    d[b+n+i] = (d[b+i] < d[b+j]? d[b+j]: d[b+i]);
    }

    const T at(int i) const { return d[i]; }

    const T max_v(int l, int r) const {
	int h = __lg(r - l), b = n * h;
	r -= 1<<h;
	return d[b+l] < d[b+r]? d[b+r]: d[b+l];
    }

    int max_i(int l, int r) const {
	return first_more_equal(l, max_v(l, r));
    }

    // for i in [l .. n-1]:
    //   if at(i) > v: return i;
    // return npos;
    int first_more_than(int l, const T v) const {
	for (int t=g+1; t--; )
	    if (l + (1<<t) <= n && !(v < d[n*t+l]))
		l += 1 << t;
	return l<n? l: npos;
    }

    // for i in [l .. n-1]:
    //   if v <= at(i): return i;
    // return npos;
    int first_more_equal(int l, const T v) const {
	for (int t=g+1; t--; )
	    if (l + (1<<t) <= n && d[n*t+l] < v)
		l += 1 << t;
	return l<n? l: npos;
    }

    // for i in [r-1 .. 0]:
    //   if v < at(i): return i;
    // return npos;
    int last_more_than(int r, const T v) const {
	for (int t=g+1; t--; )
	    if (0 <= r - (1<<t) && !(v < d[n*t+r-(1<<t)]))
		r -= 1 << t;
	return r? r-1: npos;
    }

    // for i in [r-1 .. 0]:
    //   if v <= at(i): return i;
    // return npos;
    int last_more_equal(int r, const T v) const {
	for (int t=g+1; t--; )
	    if (0 <= r - (1<<t) && d[n*t+r-(1<<t)] < v)
		r -= 1 << t;
	return r? r-1: npos;
    }
};

int N, M;
int A[5011];
int B[201][5011];

LL S[5011][5011];

void MAIN() {
    scanf("%d%d", &N, &M);
    REP (i, N-1) scanf("%d", A+i);

    REP (i, N) REP (j, M) scanf("%d", &B[j][i]);

    stack<pair<int, int> > st;
    REP (j, M) {
	IRXQ<int> rxq(B[j], B[j]+N);
	st.emplace(0, N);
	while (!st.empty()) {
	    int l = st.top().first;
	    int r = st.top().second;
	    st.pop();
	    int k = rxq.max_i(l, r);

	    S[k][k+1] += B[j][k];
	    S[k][r+1] -= B[j][k];
	    if (l) {
		S[l-1][k+1] -= B[j][k];
		S[l-1][r+1] += B[j][k];
	    }
	    if (l < k) st.emplace(l, k);
	    if (k+1 < r) st.emplace(k+1, r);
	}
    }

    REP (i, N+1) {
	REP (j, N+1) S[i][j+1] += S[i][j];
    }
    for (int i=N; i>=0; i--) {
	REP (j, N+1) S[i][j] += S[i+1][j];
    }

    LL ans = 0;
    REP (l, N) {
	LL tmp = 0;
	for (int r=l+1; r<=N; r++) {
	    amax(ans, S[l][r] - tmp);
	    tmp += A[r-1];
	}
    }
    printf("%lld\n", ans);
}

int main() {
    int TC = 1;
//    scanf("%d", &TC);
    REP (tc, TC) MAIN();
    return 0;
