template<typename T1, typename T2>
inline bool cmx (T1& a, T2 b) {
  if (a < b) {
    a = b;
    return true;
  }
  return false;
}
int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n, m; std::cin >> n >> m;
  std::vector<long long> a(n, 0);
  for (int i = 1; i < n; i++) {
    std::cin >> a[i];
    a[i] += a[i - 1];
  }
  std::vector<std::vector<int>> b(m, std::vector<int>(n));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      std::cin >> b[j][i];
    }
  }
  std::vector<std::vector<long long>> dp(n + 1, std::vector<long long>(n + 1, 0));
  auto add = [&] (int i0, int i1, int j0, int j1, long long x) {
    if (i1 <= n && j1 <= n) dp.at(i1).at(j1) += x;
    if (i1 <= n) dp.at(i1).at(j0) -= x;
    if (j1 <= n) dp.at(i0).at(j1) -= x;
    dp.at(i0).at(j0) += x;
  };
  auto cum = [&] {
    auto ep = dp;
    for (int i = 0; i <= n; i++) {
      for (int j = 0; j <= n; j++) {
        if (i > 0) ep.at(i).at(j) += ep.at(i - 1).at(j);
        if (j > 0) ep.at(i).at(j) += ep.at(i).at(j - 1);
        if (i > 0 && j > 0) ep.at(i).at(j) -= ep.at(i - 1).at(j - 1);
      }
    }
    return ep;
  };
  for (auto const& c :  b) {
    assert((int)c.size() == n);
    auto ord = [&]{
      std::vector<int> ord(n);
      std::iota(ord.begin(), ord.end(), 0);
      std::sort(ord.begin(), ord.end(), [&c](int i, int j){return c[i] > c[j];});
      return ord;
    }();
    std::vector<int> ckd;
    for (auto x : ord) {
      auto lb = std::lower_bound(ckd.begin(), ckd.end(), x);
      int l = (lb == ckd.begin() ? 0 : *std::prev(lb) + 1);
      int r = (lb == ckd.  end() ? n : *lb);
      if (x == r) continue;
      ckd.insert(lb, x);
      add(l, x + 1, x + 1, r + 1, c[x]);
    }
  }
  dp = cum();
  long long ret = 0;
  for (int l = 0; l <= n; l++) {
    for (int r = l + 1; r <= n; r++) {
      cmx(ret, dp[l][r] - (a[r - 1] - a[l]));
    }
  }
  std::cout << ret << std::endl;
  return 0;
}

