LL ans[N];

int calc(int x, int l, int r) {
	l = max(l, x);
	static int mx[M]; memset(mx, 0, sizeof(mx));
	ans[x] = 0; int mxa = 0;
	rep(i,l,r) {
		LL s = 0;
		rep(j,1,m) mx[j] = max(mx[j], b[i][j]), s += mx[j];
