	}
	return mxa;
}

void solve(int l, int r, int a, int b) {
	int mid = (l + r) >> 1;
	int t = calc(mid, a, b);
	if (l < mid) solve(l, mid - 1, a, t);
	if (mid < r) solve(mid + 1, r, t, b);
}

