      auto ite = used.lower_bound( w.se );
      int r = (*ite);
      ite--;
      int l = (*ite) + 1;
      s[l][w.se+1] += w.fi;
      s[l][r+1] -= w.fi;
      s[w.se+1][w.se+1] -= w.fi;
      s[w.se+1][r+1] += w.fi;
      used.insert( w.se );
    }
  }

  REP( i , n+1 ){
    REP( j , n+1 ){
      s[i+1][j] += s[i][j];
    }
  }
  REP( i , n+1 ){
    REP( j , n+1 ){
      s[i][j+1] += s[i][j];
    }
  }

  ll ans = 0;
  REP( j , n+1 ){
    REP( i , j ){
      chmax( ans , s[i][j] - ( as[j-1] - as[i] ) );
    }
  }

  cout << ans << endl;

  return 0;
}

