	f[x][y] += val; f[x][v] -= val;
	f[u][y] -= val; f[u][v] += val;
}

void solve(int x, int l, int r) {
	if (l > r) return;
	pair<int, int> g = get(x, l, r);
	int opt = g.second, val = g.first;
	upd(l, opt, opt, r, val);
	solve(x, l, opt - 1); solve(x, opt + 1, r);
}

