        pref[i] = pref[i - 1] + a[i];
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            scanf ("%I64d", &b[i][j]);
        }
    }
    for (int i = 1; i <= m; i++) {
        build(i);
    }
}

