template <typename T, typename Func>
class SegmentTree{
protected:
  const int depth, size, hsize;
  const T e;
  const Func f;
  std::vector<T> data;

public:
  SegmentTree(int n, const T &e, const Func &f):
    depth(n > 1 ? 32-__builtin_clz(n-1) + 1 : 1),
    size((1 << depth) - 1),
    hsize(size / 2 + 1),
    e(e),
    f(f),
    data(size + 1, e)
  {}

  inline T operator[](int i) const {
    return at(i);
  }

  inline T at(int i) const {
    return data[hsize + i];
  }

  inline T get(int x, int y) const { // [x,y)
    int l = x + hsize, r = y + hsize;
    T ret = e;

    // must be commutative
    while(l < r){
      if(r & 1) ret = f(ret, data[--r]);
      if(l & 1) ret = f(ret, data[l++]);
      l >>= 1, r >>= 1;
    }

    return ret;
  }

  inline void update(int i, const T &x){
    i += hsize;
    data[i] = x;
    while(i > 1){
      i >>= 1;
      data[i] = f(data[i << 1 | 0], data[i << 1 | 1]);
    }
  }

  inline void init(const T &val){
    data.assign(size + 1, e);
    for(int i = 0; i < hsize; ++i) data[hsize + i] = val;

    for(int i = hsize-1; i >= 1; --i){
      data[i] = f(data[i << 1 | 0], data[i << 1 | 1]);
    }
  }

  inline void init_with_vector(const std::vector<T> &val){
    data.assign(size + 1, e);
    for(int i = 0; i < (int)val.size(); ++i) data[hsize + i] = val[i];

    for(int i = hsize-1; i >= 1; --i){
      data[i] = f(data[i << 1 | 0], data[i << 1 | 1]);
    }
  }

  void debug(){
#ifdef DEBUG
    std::cerr << "{";
    for(int i = 0; i < hsize; ++i){
      if(i) std::cerr << ",";
      std::cerr << data[hsize + i];
    }
    std::cerr << "}" << std::endl;
#endif
  }
};



template <typename T, typename Func>
class SegmentTreeRangeArgmax : public SegmentTree<std::pair<T, int>, Func>{
  using super = SegmentTree<std::pair<T, int>, Func>;

public:
  SegmentTreeRangeArgmax(int n, const std::pair<T, int> &e, const Func &f): super(n, e, f){}

  inline void update(int i, const T &val){
    super::update(i, std::make_pair(val, i));
  }
};

template <typename T>
auto make_segment_tree_range_argmax(int size, const T &e){
  auto f =
    [](const auto &a, const auto &b){
      if(a.first == b.first){
        return std::make_pair(std::max(a.first, b.first), std::min(a.second, b.second));
      }else{
        return std::max(a, b);
      }
    };

  return SegmentTreeRangeArgmax<T, decltype(f)>(size, std::make_pair(e, INT_MAX), f);
}




template <typename T> struct Imos2D{
  std::vector<std::vector<T>> vec;
  int n, m;
  Imos2D(int n, int m): vec(n+1, std::vector<T>(m+1)), n(n), m(m){}

  void add(int a1, int b1, int a2, int b2, const T &val){ // [a1,a2) [b1,b2)
    vec[a1][b1] += val;
    vec[a2][b2] += val;
    vec[a1][b2] -= val;
    vec[a2][b1] -= val;
  }

  void calc(){
    for(int i = 0; i < n; ++i){
      for(int j = 0; j < m+1; ++j){
        vec[i+1][j] += vec[i][j];
      }
    }

    for(int i = 0; i < n+1; ++i){
      for(int j = 0; j < m; ++j){
        vec[i][j+1] += vec[i][j];
      }
    }
  }

  inline const std::vector<T>& operator[](size_t i) const {return vec[i];}
};


template <typename F>
struct FixPoint : F{
  explicit constexpr FixPoint(F &&f) noexcept : F(std::forward<F>(f)){}

  template <typename... Args>
  constexpr decltype(auto) operator()(Args &&... args) const {
    return F::operator()(*this, std::forward<Args>(args)...);
  }
};

template <typename F>
static inline constexpr decltype(auto) make_fix_point(F &&f){
  return FixPoint<F>(std::forward<F>(f));
}



