  rep(i, N) {
    rep(j, M) {
      scanf("%lld", &B[i][j]);
    }
  }

  LazySeg seg(vector<LL>(N, -INF/2)); 
  ans = Calc(0);
  seg.Move(0, 1, ans);
  rep(i, M) {
    decs[i].eb(pii(0x3fffffff, -1));
    decs[i].eb(pii(B[0][i], 0));
  }

  reps(i, 1, N) {
    seg.Add(0, i, -A[i]);
