      while (1) {
        auto p = decs[j].back();
        if (p.X >= B[i][j]) break;
        decs[j].pop_back();
        int l = decs[j].back().Y + 1;
        int r = p.Y + 1;
        seg.Add(l, r, B[i][j] - p.X);
      }

      decs[j].eb(pii(B[i][j], i));
    }
    seg.Move(i, i+1, Calc(i));

    MX(ans, seg.Get(0, N));
  }
