void init_mx(int m, int n1){
  nn_mx = 1;

  while(nn_mx < n1)nn_mx *= 2;

  rep(j,0,m){
  	for(int i = 0; i < 2 * nn_mx - 1; i++){
    	dat_mx[j][i] = -INF;
  	}
  }
}

void update_mx(int p, int k, long long a){
  k += nn_mx - 1;
  dat_mx[p][k] = a;
  while(k > 0){
    k = (k - 1) / 2;
    dat_mx[p][k] = max(dat_mx[p][k * 2 + 1], dat_mx[p][k * 2 + 2]);
  }
}

long long query_mx(int p, int a, int b, int k, int l, int r){
  if(r <= a || b <= l)return -INF;

  if(a <= l && r <= b){
    return dat_mx[p][k];
  }
  else{
    long long vl = query_mx(p, a, b, k * 2 + 1, l, (l + r) / 2);
    long long vr = query_mx(p, a, b, k * 2 + 2, (l + r) / 2, r);
    return max(vl, vr);
  }
}

long long query_mx1(int a, int b, int k, int l, int r){
  if(r <= a || b <= l)return -INF;

