#include<bits/stdc++.h>
const int M = 205;
const int N = 5005;
using namespace std;

stack <int> ms[M];
int n, m, b[N][M];
long long it[N << 2], lz[N << 2], a[N], ans;

void dolazy(int i, int l, int r){
    if (l != r){
        lz[i << 1] += lz[i];
        lz[i << 1 | 1] += lz[i];
    }
    it[i] += lz[i]; lz[i] = 0;
}

void update(int i, int l, int r, int L, int R, int val){
    dolazy(i, l, r);
    if (L > r || l > R) return;
    if (L <= l && r <= R){
        lz[i] = val;
        dolazy(i, l, r);
        return;
    }
    int mid = (l + r) >> 1;
    update(i << 1, l, mid, L, R, val); update(i << 1 | 1, mid+1, r, L, R, val);
    it[i] = max(it[i << 1], it[i << 1 | 1]);
}

long long get(int i, int l, int r, int L, int R){
    dolazy(i, l, r);
    if (L > r || l > R) return (int)(-1e9);
    if (L <= l && r <= R) return it[i];
    int mid = (l + r) >> 1;
    return max(get(i << 1, l, mid, L, R), get(i << 1 | 1, mid+1, r, L, R));
}

int main(){
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    cin >> n >> m;
    for (int i = 2; i <= n; i++) cin >> a[i];
    for (int i = 1; i <= n; i++) for (int j = 1; j <= m; j++) cin >> b[i][j];
    for (int i = 1; i <= n; i++){
        a[i] += a[i-1];
        update(1, 1, n, i, i, a[i]);
    }
    for (int i = 1; i <= n; i++){
        for (int j = 1; j <= m; j++){
            update(1, 1, n, i, i, b[i][j]);
            while (ms[j].size() && b[ms[j].top()][j] < b[i][j]){
                int r = ms[j].top(), val = b[ms[j].top()][j];
                ms[j].pop();
                int l = (ms[j].size() ? ms[j].top() : 0);
                update(1, 1, n, l+1, r, b[i][j] - val);
            }
            ms[j].push(i);
        }
        ans = max(ans, get(1, 1, n, 1, i) - a[i]);
    }
    cout << ans;
}

