const int N=5e3+5,M=200+5;
int a[N][M],L[N][M],R[N][M],q[N];
LL s[N],add[N][N];
int n,m;
/*
暴力n^2m:枚举用餐券的餐馆的区间，每种餐券都用在区间内收益最大的餐馆即可

考虑： a[i,j]能对那些区间产生贡献：
找到第一个l<i,a[l,j]>=a[i,j],第一个r>i,a[r,j]>=a[i,j]
显然a[i,j]只对在[l+1,r+1]内的包含i的区间产生贡献，差分一下即可
*/
int main()
{
    n=read(); m=read();
    For(i,2,n) s[i]=s[i-1]+read();
    For(i,1,n) For(j,1,m) a[i][j]=read();
    For(i,1,m)
    {
        int r=0;
        For(j,1,n)
        {
            while(r&&a[q[r]][i]<a[j][i]) --r;
            L[j][i]=q[r]+1; q[++r]=j;
        }
        r=0;
        Rep(j,n,1)
        {
            while(r&&a[q[r]][i]<a[j][i]) --r;
            R[j][i]=(r?q[r]-1:n); q[++r]=j;
        }
    }
    // For(i,1,n) For(j,1,m) printf("%d %d\n",L[i][j],R[i][j]);
    For(i,1,n) For(j,1,m)
    {
        add[L[i][j]][i]+=a[i][j];
        add[L[i][j]][R[i][j]+1]-=a[i][j];
        add[i][i]-=a[i][j];
        add[i][R[i][j]+1]+=a[i][j];
    }
    For(i,1,n) For(j,1,n) add[i][j]+=add[i][j-1];
    For(j,1,n) For(i,1,n) add[i][j]+=add[i-1][j];
    LL ans=0;
    For(i,1,n) For(j,i,n) ans=max(ans,add[i][j]+s[j]-s[i]);
    printf("%lld\n",ans);
    return 0;
}

