int n, m;
int a[MAXN];
int b[MAXN][MAXM];
ll c[MAXN][MAXN];

PII lst[MAXN];

int main(){
	scanf("%d%d", &n, &m);
	for (int i = 1; i < n; ++i)
		scanf("%d", a + i);
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
			scanf("%d", b[i] + j);
	for (int i = 1; i <= m; ++i){
		set<int> st;
		st.insert(0), st.insert(n + 1);
		for (int j = 1; j <= n; ++j){
			lst[j] = PII(b[j][i], j);
			st.insert(j);
		}
		sort(lst + 1, lst + n + 1);
		for (int j = 1; j <= n; ++j){
			int u = lst[j].nd;
			auto p = st.find(u);
			int l = *prev(p) + 1, r = *next(p) - 1;
			st.erase(p);
			c[l][u] += lst[j].st, c[u + 1][r + 1] += lst[j].st;
			c[l][r + 1] -= lst[j].st, c[u + 1][u] -= lst[j].st;
		}
	}
	ll ans = 0;
	for (int i = 1; i <= n; ++i){
		for (int j = 1; j <= n; ++j)
			c[i][j] += c[i][j - 1];
		ll dist = 0;
		for (int j = i; j <= n; ++j){
			c[i][j] += c[i - 1][j];
			ans = max(ans, c[i][j] - dist);
			dist += a[j];
		}
	}
	printf("%lld\n", ans);
	return 0;
}

