			for(int j=0;j<M;j++) cin >> B[i][j];
		}
		for(int i=0;i<M;i++){
			seg.init();
			for(int j=0;j<N;j++) seg.setVal((int)B[j][i], j);
			update(0, N);
		}
		for(int i=0;i<N;i++){
			for(int j=0;j<N;j++) cost[i][j+1] += cost[i][j];
		}
		for(int i=0;i<N;i++){
			for(int j=0;j<N;j++) cost[j+1][i] += cost[j][i];
		}
