long long max(long long a, long b)
{
    return (a < b) ? b : a;
}
struct pii
{
    int first, second;
    pii(int f, int s)
    : first(f), second(s) {}
};
int n, m, a[nmax+1], b[nmax+1][mmax+1], cl, cr, cv;
std::stack<pii> stk[mmax+1];
long long smt[nmax*4+1], lazy[nmax*4+1];
void propg(int id, int leaf)
{
    if(!leaf){
      smt[id << 1] += lazy[id];
      lazy[id << 1] += lazy[id];
      smt[id << 1 | 1] += lazy[id];
      lazy[id << 1 | 1] += lazy[id];
    }
    lazy[id] = 0;
}
void upd(int id, int l, int r)
{
    if(cl <= l && r <= cr){
      smt[id] += cv;
      lazy[id] += cv;
      propg(id, l == r);
      return;
    }
    propg(id, 0);
    int mid = (l + r) >> 1;
    if(cl <= mid) upd(id << 1, l, mid);
    if(mid < cr) upd(id << 1 | 1, mid + 1, r);
    smt[id] = max(smt[id << 1], smt[id << 1 | 1]);
}
