void init()
{
    N_ = 1;
    while(N_ <= N)N_ *= 2;
    for(int i = 0; i < N_ * 2 - 1; i++)
        for(int j = 0; j < M; j++)seg[i][j] = mk(0,0);
    return;
}

void up_date(ll k,ll x,ll p,int m)
{
    pii data = mk(x,p);
    k += N_ - 1;
    seg[k][m] = data;
    while(k > 0)
    {
        k = (k - 1) / 2;
        seg[k][m] = max(seg[k * 2 + 1][m],seg[k * 2 + 2][m]);
    }
    return;
}

pii get_min(int a,int b,int m,int k = 0,int l = 0,int r = N_)
{
    if(b <= l || r <= a)return mk(-1,0);

    if(a <= l && r <= b)return seg[k][m];

    pii res1,res2;
    res1 = get_min(a,b,m,k * 2 + 1,l,(l + r) / 2);
    res2 = get_min(a,b,m,k * 2 + 2,(l + r) / 2,r);

    return max(res1,res2);
}

void con(ll l,ll r,int m)
{
    if(l >= r)return;
    pii now = get_min(l,r,m);
    fid[now.se + 1][l + 1] += now.fi;
    fid[r + 1][l + 1] -= now.fi;
    fid[now.se + 1][now.se + 2] -= now.fi;
    fid[r + 1][now.se + 2] += now.fi;
    con(now.se + 1,r,m);
    con(l,now.se,m);
    return;
}

