struct niku { 
  ll i, b; 
  bool operator< (const niku &x) const { return b<x.b||(b==x.b&&i<x.i); };
  bool operator> (const niku &x) const { return b>x.b||(b==x.b&&i>x.i); };
};

struct SegTree {
  int size;
  vector<niku> pos;
  SegTree(ll N) { size = 1; while(size<N) size<<=1; pos.resize(size*2,{0,0}); }
  niku operator[](const ll &x) const { return pos[x+size]; }

  void build() { per(i,size) operate(i); }
  void set(ll x, const niku v) { pos[x+size] = v; }
  void update(ll x, const niku v) { set(x,v); x+=size; while (x>>=1) operate(x); }
  niku query(ll a, ll b) {
    niku L = {0,0}, R = {0,0};
    for (a+=size, b+=size; a<b; a>>=1, b>>=1) {
      if (a&1) { L = q(L,pos[a]); a++; }
      if (b&1) { b--; R = q(pos[b],R); }
    }
    return q(L,R);
  }
  void operate(ll i) { pos[i] = max(pos[i*2], pos[i*2+1]); }
  niku q(niku x, niku y) { return max(x, y); }
};

