                ST.update(1, 1, n, s[i][top[i] - 1] + 1, s[i][top[i]], -b[i][s[i][top[i]]]);
                top[i]--;
            }
            ST.update(1, 1, n, s[i][top[i]] + 1, r, b[i][r]);
            s[i][++top[i]] = r;
        }
        ans = max(ans, ST.get(1, 1, n, 1, r));
        if (r < n)
            ST.update(1, 1, n, 1, r, -a[r]);
    }
    cout << ans;
    return 0;
}

