void Init() {
	for(int i = 2; i <= N; i++)
		log_2[i] = log_2[i >> 1] + 1;
	for(int i = 1; i <= M; i++) {
		for(int j = 1; j <= N; j++)
			tab[i][j][0] = B[j][i];
		for(int k = 1; k <= Maxlog; k++)
			for(int j = 1; j + (1 << k) <= N + 1; j++)
				tab[i][j][k] = max(tab[i][j][k - 1],
					tab[i][j + (1 << (k - 1))][k - 1]);
	}
}
inline int query(int typ, int lef, int rig) {
	int t = log_2[rig - lef + 1];
	return max(tab[typ][lef][t], tab[typ][rig - (1 << t) + 1][t]);
}

