void DFS(int lb, int ub, int optl, int optr) {
	if(lb > ub) return;
	int mid = (lb + ub) >> 1, pos;
	for(int i = optl; i <= optr && i <= mid; i++) {
		ll tmp = dis[i] - dis[mid];
		for(int j = 1; j <= M; j++)
			tmp += query(j, i, mid);
		if(tmp > f[mid]) f[mid] = tmp, pos = i;
	}
	DFS(lb, mid - 1, optl, pos);
	DFS(mid + 1, ub, pos, optr);
}

