void update(int id, int l, int r, int u, int v, int val)
{
    if (l >= u && r <= v)
    {
        st[id].lz += val;
        return;
    }
    if (l > v || r < u) return;
    int mid = (l + r) >> 1;
    st[id * 2].lz += st[id].lz;
    st[id * 2 + 1].lz += st[id].lz;
    st[id].lz = 0;
    update(id * 2, l, mid, u, v, val);
    update(id * 2 + 1, mid + 1, r, u, v, val);
    st[id].maxx = max(st[id * 2].maxx + st[id * 2].lz, st[id * 2 + 1].maxx + st[id * 2 + 1].lz);
}

