ll query(int x, int l, int r) {
  int k = __lg(r - l + 1);
  return max(B[x][l][k], B[x][r - (1 << k) + 1][k]);
}
ll calc(int l, int r) {
  ll sum = 0;
  for(int i = 1 ; i <= m ; ++i) sum += query(i, l, r);
  return sum - (A[r] - A[l]);
}
void DP(int l, int r, int ql, int qr) {
  if(l > r) return;
  int mid = l + (r - l) / 2;
  ll val = -inf, pos = 0;
  for(int i = ql ; i <= min(mid, qr) ; ++i) {
    ll ret = calc(i, mid);
    if(ret > val) val = ret, pos = i;
  }
  dp[mid] = val;
  DP(l, mid - 1, ql, pos);
  DP(mid + 1, r, pos, qr);
}

