    for(int j = 1 ; j <= m ; ++j) cin >> B[j][i][0];
  }
  for(int k = 1 ; k <= m ; ++k) {
    for(int j = 1 ; (1 << j) <= n ; ++j) {
      for(int i = 1 ; i + (1 << j) - 1 <= n ; ++i) {
        B[k][i][j] = max(B[k][i][j - 1], B[k][i + (1 << (j - 1))][j - 1]);
      }
    }
  }
}
void solve() {
  DP(1, n, 1, n);
  ll ans = -inf;
  for(int i = 1 ; i <= n ; ++i) ans = max(ans, dp[i]);
  cout << ans << '\n';
}

