using namespace std;
const int maxn=5005;
const int maxm=205;
int a[maxn],change[maxn][maxm];
int q[maxm][maxn],top[maxm];
int n,m;
long long lazy[maxn<<2];
long long _max[maxn<<2];
void init()
{
    memset(lazy,0,sizeof(lazy));
    memset(_max,0,sizeof(_max));
    memset(top,0,sizeof(top));
}
void read()
{
    scanf("%d%d",&n,&m);
    a[1]=0;
    for(int i=2;i<=n;i++)
        scanf("%d",a+i);
    for(int j=1;j<=m;j++)
        change[0][j]=1e9+7;
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=m;j++)
            scanf("%d",&change[i][j]);
    }
}
void Push_down(int id)
{
    lazy[id<<1]+=lazy[id];
    lazy[id<<1|1]+=lazy[id];
    _max[id<<1]+=lazy[id];
    _max[id<<1|1]+=lazy[id];
    lazy[id]=0;
}
void Push_up(int id)
{
    _max[id]=max(_max[id<<1],_max[id<<1|1]);
}
void updata(int id,int l,int r,int tl,int tr,int w)
{
    if(l==tl&&r==tr){
        lazy[id]+=w;
        _max[id]+=w;
        return;
    }
    if(lazy[id]){
        Push_down(id);
    }
    int mid=(l+r)>>1;
    if(tr<=mid) updata(id<<1,l,mid,tl,tr,w);
    else if(tl>mid) updata(id<<1|1,mid+1,r,tl,tr,w);
    else{
        updata(id<<1,l,mid,tl,mid,w);
        updata(id<<1|1,mid+1,r,mid+1,tr,w);
    }
    Push_up(id);
}
long long Q(int id,int l,int r,int tl,int tr)
{
    if(l==tl&&r==tr){
        return _max[id];
    }
    int mid=(l+r)>>1;
    if(lazy[id]) Push_down(id);
    if(tr<=mid) return Q(id<<1,l,mid,tl,tr);
    else if(tl>mid) return Q(id<<1|1,mid+1,r,tl,tr);
    else return max(Q(id<<1,l,mid,tl,mid),Q(id<<1|1,mid+1,r,mid+1,tr));
}
void solve()
{
    for(int j=1;j<=m;j++)
        q[j][top[j]++]=0;
    long long ans=0;
    for(int i=1;i<=n;i++)
    {
        updata(1,1,n,1,i,-a[i]);
        for(int j=1;j<=m;j++)
        {
            while(top[j]&&change[q[j][top[j]-1]][j]<=change[i][j])
            {
                updata(1,1,n,q[j][top[j]-2]+1,q[j][top[j]-1],-change[q[j][top[j]-1]][j]);
                top[j]--;
            }
            updata(1,1,n,q[j][top[j]-1]+1,i,change[i][j]);
            q[j][top[j]++]=i;
        }
        updata(1,1,n,i,i,a[i]);
        ans=max(ans,Q(1,1,n,1,n));
    }
    printf("%lld\n",ans);
}
int main()
{
    init();
    read();
    solve();
    return 0;
}

