typedef long long ll;

const int Nmax = 5005, Mmax = 205, lg = 12;

ll D[Nmax], best[Nmax];
int rmq[Mmax][Nmax][lg+2], opt[Nmax], val[Nmax], a[Nmax][Mmax], loog[Nmax];
int n, m;

void Rmq()
{
    int i, j, t;
    for(i=1; i<=m; ++i)
        for(j=1; j<=n; ++j)
            rmq[i][j][0] = a[j][i];

    for(i=2; i<=n; ++i) loog[i] = loog[i>>1] + 1;

    for(t=0; t<lg; ++t)
    {
        for(i=1; i<=m; ++i)
            for(j=1; j + (1<<(t+1)) - 1 <= n; ++j)
                rmq[i][j][t+1] = max( rmq[i][j][t], rmq[i][j+(1<<t)][t] );
    }
}

void refresh(int x, int y)
{
    int p = loog[y-x+1], i;
    for(i=1; i<=m; ++i)
        val[i] = max( rmq[i][x][p], rmq[i][y - (1<<p) + 1][p] );
}

void divide(int st, int dr, int L, int R)
{
    int mid = (st+dr) / 2, i, j;

    if(L > mid)
        for(i=1; i<=m; ++i) refresh(mid, L-1);
    else for(i=1; i<=m; ++i) val[i] = 0;

    ll act = 0;
    for(i=1; i<=m; ++i) act += val[i];

    best[mid] = -1e18;

    for(i = max(L, mid); i <= R; ++i)
    {
        for(j=1; j<=m; ++j)
            if(a[i][j] > val[j])
            {
                act += a[i][j] - val[j];
                val[j] = a[i][j];
            }

        if(act - D[i] > best[mid])
            best[mid] = act - D[i], opt[mid] = i;
    }

    best[mid] += D[mid];
    if(st < mid) divide(st, mid-1, L, opt[mid]);
    if(mid < dr) divide(mid+1, dr, opt[mid], R);
}

int main()
{
  //  freopen("input", "r", stdin);
    cin.sync_with_stdio(false);

    int i, j;

    cin >> n >> m;
    for(i=2; i<=n; ++i) cin >> D[i], D[i] += D[i-1];

    for(i=1; i<=n; ++i)
        for(j=1; j<=m; ++j)
            cin >> a[i][j];

    Rmq();
    divide(1, n, 1, n);

    ll ans = 0;
    for(i=1; i<=n; ++i)
        ans = max(ans, best[i]);
    cout << ans << '\n';
    return 0;
}

