#include <bits/stdc++.h>

#define MAXN (5010)
#define MAXM (210)
#define MAXB (14)
#define ll long long

int n, m;
ll a[MAXN], imos[MAXN][MAXN];
int b[MAXN][MAXM];
std::pair<int, int> seg[(1 << MAXB) + 10];

void build_tree(int j){
	memset(seg, 0, sizeof(seg));
	for(int i = (1 << MAXB); i < (1 << MAXB) + n; ++ i){
		seg[i] = {b[i - (1 << MAXB) + 1][j], i - (1 << MAXB) + 1};
	}
	for(int i = (1 << MAXB) - 1; i; -- i){
		seg[i] = std::max(seg[i << 1], seg[(i << 1) + 1]);
	}
}

std::pair<int, int> query_tree(int l, int r){
	std::pair<int, int> ret = {0, 0};
	l += (1 << MAXB) - 1;
	r += (1 << MAXB);
	for( ; l < r; l >>= 1, r >>= 1){
	    if(l & 1){
		    ret = std::max(ret, seg[l ++]);
		}
		if(r & 1){
			ret = std::max(ret, seg[-- r]);
		}
	}
	return ret;
}

void solve(int l, int r){
	if(l > r) return;
	std::pair<int, int> p = query_tree(l, r);
	int x = p.first, sit = p.second;
	imos[l][sit] += x;
	imos[l][r + 1] -= x;
	imos[sit + 1][sit] -= x;
	imos[sit + 1][r + 1] += x; 
	solve(l, sit - 1);
	solve(sit + 1, r);
}

