#include "bits/stdc++.h"
using namespace std;
typedef long long ll;
typedef pair<ll, int> P;
const ll MOD = 1e9 + 7;
const int INF = 1 << 30;
class BiOp {
public:
	P operator()(P a, P b) const {
		return max(a, b);
	}
};

template<typename T, typename BiOp>
struct SegmentTree {
	vector<T> data;
	T e;
	BiOp op;
	int size;
	SegmentTree() {}
	SegmentTree(int n, T e, BiOp op) : e(e), op(op) {
		size = 1;
		while (size < n) size *= 2;
		data.resize(2 * size - 1);
		for (int i = 0; i < 2 * size - 1; i++) data[i] = e;
	}

	void update(int k, T v) {
		k += size - 1;
		data[k] = v;
		while (k > 0) {
			k = (k - 1) / 2;
			data[k] = op(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}

	T query(int a, int b, int k, int l, int r) const {
		if (b <= l || r <= a) return e;
		if (a <= l && r <= b) return data[k];
		return op(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	T query(int a, int b) {
		return query(a, b, 0, 0, size);
	}

	T get(int i) {
		return data[i + size - 1];
	}
};
SegmentTree<P, BiOp> seg[200];
ll B[5000][200];
ll dist[5000];
ll imos[5000][5000];
int N, M;
void solve(int l, int r, int x) {
	P opt = seg[x].query(l, r + 1);
	imos[opt.second][l] += opt.first;
	if (opt.second + 1 < N) imos[opt.second][opt.second + 1] -= opt.first;
	if (r + 1 < N) {
		imos[r + 1][l] -= opt.first;
		imos[r + 1][opt.second + 1] += opt.first;
	}
	if (l < opt.second) solve(l, opt.second - 1, x);
