template<typename T>
class SegmentTree {
private:
    int n;
    T dat[(1<<18)-1];
public:
    SegmentTree(int n_) {
	n = 1;
	while (n < n_) n *= 2;
	for (int i = 0; i < 2*n-1; i++) dat[i] = make_pair(0, 0);
    }

    void update(int k, T a) {
	k += n - 1;
	dat[k] = a;
	while (k > 0) {
	    k = (k - 1) / 2;
	    dat[k] = max(dat[k*2+1], dat[k*2+2]);
	}
    }

    // call query(a, b)
    T query(int a, int b) { return query(a, b, 0, 0, n); }
    T query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l) return make_pair(0, 0);

	if (a <= l && r <= b) return dat[k];
	else {
	    T vl = query(a, b, k*2+1, l, (l+r)/2);
	    T vr = query(a, b, k*2+2, (l+r)/2, r);
	    return max(vl, vr);
	}
    }
};

SegmentTree<P> st(5010);

void calc(int i, int j) {
    if (i >= j) return;
    P p = st.query(i, j);
    ll v = p.first;
    int u = p.second;
    sum[i][u] += v; sum[u+1][u] -= v;
    sum[i][j] -= v; sum[u+1][j] += v;
    calc(i, u);
    calc(u+1, j);
}

ll dist(int i, int j) {
    return d[j] - d[i];
}

ll solve() {
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            st.update(j, make_pair(b[j][i], j));
        }
        calc(0, n);
    }

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++)
            sum[i][j+1] += sum[i][j];
    }
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++)
            sum[i+1][j] += sum[i][j];
    }

    for (int i = 0; i < n-1; i++) d[i+1] = d[i] + a[i];

    ll res = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            res = max(res, sum[i][j] - dist(i, j));
        }
    }
    return res;
}

