void solve(int s, int e){
	if(s == e){
		return;
	}
	int mid = (s+e)/2;
	solve(s, mid);
	solve(mid+1, e);
	for(int i=1; i<=m; i++){
		pref[mid][i] = b[mid][i];
		suff[mid+1][i] = b[mid+1][i];
	}
	for(int i=mid-1; i>=s; i--){
		for(int j=1; j<=m; j++){
			pref[i][j] = max(b[i][j], pref[i+1][j]);
		}
	}
	for(int i=mid+2; i<=e; i++){
		for(int j=1; j<=m; j++){
			suff[i][j] = max(b[i][j], suff[i-1][j]);
		}
	}
	for(int j=1; j<=m; j++){
		int p = e;
		for(int i=s; i<=mid; i++){
			while(p > mid && suff[p][j] >= pref[i][j]) p--;
			ans[i][mid + 1] += pref[i][j];
			ans[i][p + 1] -= pref[i][j];
		}
	}
}

