void upd(int x,int l,int r,int lq,int rq,ll val) {
    //printf("upd l:%d r:%d lq:%d rq:%d st:%lld\n",l,r,lq,rq,st[x]);
    if (lq<=l&&r<=rq) {
        st[x]+=val;
        tag[x]+=val;
        return;
    }
    if (l>=rq||lq>=r) return;
    push(x);
    int m=(l+r)>>1;
    upd(2*x,l,m,lq,rq,val);
    upd(2*x+1,m,r,lq,rq,val);
    st[x]=max(st[2*x],st[2*x+1]);
}

ll query(int x,int l,int r,int lq,int rq) {
    //printf("query l:%d r:%d lq:%d rq:%d st:%lld\n",l,r,lq,rq,st[x]);
    if (lq<=l&&r<=rq) return st[x];
    if (l>=rq||lq>=r) return 0;
    push(x);
    int m=(l+r)>>1;
    return max(query(2*x,l,m,lq,rq),query(2*x+1,m,r,lq,rq));
}

