            update0[i]+=diff[i][j];
            rui[j]=max(rui[j],B[i][j]);
            v[j][i]=B[i][j];
        }
    }
    auto f=[](ll a,ll b){return max(a,b);};
    vector<SegmentTree<ll>> seg(M,SegmentTree<ll>(N,f,0));
    for (int i=0;i<M;++i) seg[i].build(v[i]);
    ll ans=0;
    for (int l=0;l<N;++l){
        ll sum=0;
        for (int i=0;i<N;++i) update[i]=update0[i];
        for (int i=0;i<M;++i){
            sum+=B[l][i];
            auto check=[&](ll x){return x>B[l][i];};
            int pos=seg[i].find(l+1,N,check);
            if (~pos) update[pos]+=B[pos][i]-B[l][i]-diff[pos][i];
        }
        ans=max(ans,sum);
        for (int r=l+1;r<N;++r){
            sum+=update[r]-A[r-1];
            ans=max(ans,sum);
        }
    }
    cout << ans << '\n';
}

