inline ll Get(int l,int r){int t=lg2[r-l+1];return Sum(st[t][l],st[t][r-(1<<t)+1]);}

void solve(int l,int r,int s,int t){
	if(l>r)return;
	int m=(l+r)>>1;
	ll best=-inf;int p;
	for(int i=s;i<=m&&i<=t;i++){
