void Go(int l, int r, int opL, int opR) {
	if (l > r) return;
	int mid = (l + r) >> 1;
	int opMid = opL;
	long long val = calF(opMid, mid);
	For(i,opL + 1, opR) if (i <= mid) {
		long long z = calF(i, mid);
		if (z > val) {
			val = z;
			opMid = i;
		}
	}
	dp[mid] = val;
	Go(l, mid - 1, opL, opMid);
	Go(mid + 1, r, opMid, opR);
}

