const int MAXN = 5005;
const int MAXM = 205;

int A[MAXN][MAXM];
ll B[MAXN];

ll Ans;
int N, M;

int MX[MAXM];
void f(int s, int e, int p, int q) {
	if(s > e || p > q) return;
	int m = (s+e) >> 1;
	ll hc = -INFLL; int hi = -1;
	memset(MX, 0, (M+2)<<2);
	ll sum = 0;
	for(int i = p; i <= q; i++) {
		if(i < m) continue;
		for(int j = 1; j <= M; j++) {
			if(A[i][j] <= MX[j]) continue;
			sum += -MX[j] + A[i][j];
			MX[j] = A[i][j];
		}
		ll t = sum - B[i];
		if(t <= hc) continue;
		hc = t; hi = i;
	}
	if(Ans < hc) Ans = hc;
	f(s, m-1, p, hi);
	f(m+1, e, hi, q);
}

int main() {
