    now[i] = B[0][i];
    ans += now[i];
    q[i].push(0);
  }
  p = 0;
  for (i=1; i<N; ++i) {
    A[i] += A[i-1];
    for (j=0; j<M; ++j) {
      while (!q[j].empty() && B[q[j].front()][j] < B[i][j])
	q[j].pop();
      q[j].push(i);
    }
    sum = 0;
    while (p < i) {
      for (j=0; j<M; ++j)
	if (q[j].front() == p)
