typedef long long ll;


struct MinsegTree2D {
	int H, W, H_, W_;
	ll dat[9000000];
	MinsegTree2D() {}
	MinsegTree2D(vector<vector<ll>> &f) {
		init(f);
	}
	int x(int i, int j) {
		return i * W_ + j;
	}
	void init(vector<vector<ll>> &f) {
		H = W = 1;
		while(H < (int)f.size()) H <<= 1;
		while(W < (int)f[0].size()) W <<= 1;
		H_ = 2 * H - 1, W_ = 2 * W - 1;
		for(int i = 0; i < (int)f.size(); i++)
			for(int j = 0; j < (int)f[0].size(); j++)
				dat[x(i + H - 1, j + W - 1)] = f[i][j];
		for(int i = 2 * H - 2; i > H - 2; i--)
			for(int j = W - 2; j >= 0; j--)
				dat[x(i, j)] = max(dat[x(i, 2 * j + 1)], dat[x(i, 2 * j + 2)]);
		for(int i = H - 2; i >= 0; i--)
			for(int j = 0; j < 2 * W - 1; j++)
				dat[x(i, j)] = dat[x(2 * i + 1, j)] + dat[x(2 * i + 2, j)];
	}
	int query(int li, int lj, int ri, int rj) { return query_h(li, lj, ri, rj, 0, H, 0); }
	int query_h(int li, int lj, int ri, int rj, int si, int ti, int k) {
		if(ri <= si || ti <= li) return 0;
		if(li <= si && ti <= ri) return query_w(lj, rj, 0, W, k, 0);
		const int mi = (si + ti) / 2;
		return query_h(li, lj, ri, rj, si, mi, 2 * k + 1) + query_h(li, lj, ri, rj, mi, ti, 2 * k + 2);
	}
	int query_w(int lj, int rj, int sj, int tj, int i, int k) {
		if(rj <= sj || tj <= lj) return 0;
		if(lj <= sj && tj <= rj) return dat[x(i, k)];
		const int mj = (sj + tj) / 2;
		return max(query_w(lj, rj, sj, mj, i, 2 * k + 1), query_w(lj, rj, mj, tj, i, 2 * k + 2));
	}
};

