ll seg[N*4],lazy[N*4];
int dist[N];

void push(int pos,int l,int r) {
  if(lazy[pos]!=0) {
    seg[pos] += lazy[pos];
    if(l!=r) {
      lazy[pos*2] += lazy[pos];
      lazy[pos*2+1] += lazy[pos];
    }
    lazy[pos] = 0;
  }
}
void update(int pos,int l,int r,int ql,int qr,ll val) {
  push(pos,l,r);
  if(r<ql || qr<l) {
    return;
  }
  if(ql<=l && r<=qr) {
    lazy[pos] = val;
    push(pos,l,r);
    return;
  }
  int mid = (l+r)/2;
  update(pos*2,l,mid,ql,qr,val);
  update(pos*2+1,mid+1,r,ql,qr,val);
  seg[pos] = max(seg[pos*2],seg[pos*2+1]);
}

ll query(int pos,int l,int r,int ql,int qr) {
  push(pos,l,r);
  if(r<ql || qr<l) {
    return LLONG_MIN;
  }
  if(ql<=l && r<=qr) {
    return seg[pos];
  }
  int mid = (l+r)/2;
  return max(query(pos*2,l,mid,ql,qr), query(pos*2+1,mid+1,r,ql,qr));
}

vector<pair<int,int> > q[N];

int B[N][M];
void solve() {
  int n,m;
  scanf("%d %d ", &n,&m);
  for(int i=1;i<=n-1;++i) {
    scanf("%d ", &dist[i]);
  }

  for(int i=1;i<=n;++i) {
    for(int j=1;j<=m;++j) {
      scanf("%d ", &B[i][j]);
    }
  }
  for(int i=1;i<=m;++i) {
    q[i].push_back({INT_MAX,0});
  }
  ll ret = 0;
  for(int i=1;i<=n;++i) {
    if(i-1>=1) {
      update(1,1,n,1,i-1,-dist[i-1]);
    }
    for(int j=1;j<=m;++j) {
      while(true) {
        if(q[j].back().first<=B[i][j]) {
          pair<int,int> top = q[j].back();
          q[j].pop_back();
          int ind = q[j].back().second;
          update(1,1,n,ind+1,top.second,-top.first);
        } else {
          break;
        }
      }
      int ind = q[j].back().second;
      q[j].push_back(make_pair(B[i][j],i));
      update(1,1,n,ind+1,i,B[i][j]);
    }
    ret = max(ret, query(1,1,n,1,i));
  }
  printf("%lld\n", ret);
}

