        }
    }

    for(int i = 1; i < N; i++) {
        psum[i] = A[i - 1];
        psum[i] += psum[i - 1];
    }

    bit.init();
    for(int i = 0; i < N; i++) {
        bit.upd(i, i, -psum[i], 0, N - 1, 1);
    }
    for(int i = 0; i < M; i++) {
        stk[i].push({ 2e9, N });
    }
    ll ans = 0;
    for(int i = N - 1; i >= 0; i--) {
        for(int j = 0; j < M; j++) {
            bit.upd(i, i, B[i][j], 0, N - 1, 1);
            while(!stk[j].empty() && stk[j].top().first <= B[i][j]) {
                pii t = stk[j].top(); stk[j].pop();
                bit.upd(t.second, stk[j].top().second - 1, B[i][j] - t.first, 0, N - 1, 1);
            }
            stk[j].push({ B[i][j], i });
        }
        ans = max(ans, bit.quer(i, N - 1, 0, N - 1, 1) + psum[i]);
    }
