inline int read()
{
	int x=0,f=1; char ch=getchar();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1; ch=getchar();}
	while(ch>='0'&&ch<='9'){x=x*10+ch-'0'; ch=getchar();}
	return x*f;
}
int n,m,A[N],B[200][N],ss[200][N],tpp[200];
ll tree[N<<2],Add[N<<2];
inline void deal(int ls,int rs,int x,int y)
{
	tree[x]+=y; Add[x]+=y;
}
inline void pushup(int rt)
{
	tree[rt]=max(tree[rt<<1],tree[rt<<1|1]);
}
inline void pushdown(int ls,int rs,int rt)
{
	if(Add[rt])
	{
		deal(ls,rs,rt<<1,Add[rt]);
		deal(ls,rs,rt<<1|1,Add[rt]);
		Add[rt]=0;
	}
}
inline void updata(int L,int R,int x,int l,int r,int rt)
{
	if(L>R) return ;
  	if(L<=l&&r<=R) 
	{
		deal(L,R,rt,x); return ;
	}int mid=(l+r)>>1; pushdown(L,R,rt);
	if(mid>=L) updata(L,R,x,l,mid,rt<<1);
	if(mid<R) updata(L,R,x,mid+1,r,rt<<1|1);
	pushup(rt);
}
inline void built(int l,int r,int rt)
{
	if(l==r){tree[rt]=A[l]; return ;}
	int mid=(l+r)>>1;
	built(l,mid,rt<<1); built(mid+1,r,rt<<1|1);
	pushup(rt);
}
inline ll query(int L,int R,int l,int r,int rt)
{
	if(L>R) return 0;
	if(L<=l&&r<=R) return tree[rt];
	int mid=(l+r)>>1; pushdown(L,R,rt);
	if(mid<L) return query(L,R,mid+1,r,rt<<1|1);
	if(mid>=R) return query(L,R,l,mid,rt<<1);
	return max(query(L,R,l,mid,rt<<1),query(L,R,mid+1,r,rt<<1|1));
}
inline void work(int x,int y)
{
	//cerr <<"SPE:"<< x << " " << y << endl;
	updata(x,x,B[y][x],1,n,1);
	int nw=ss[y][tpp[y]];
	//cerr << "cg:" << endl;
	while(B[y][x]>B[y][ss[y][tpp[y]]]&&tpp[y])
	{
	//	cout << nw << " ";		
		updata(ss[y][tpp[y]-1]+1,nw,B[y][x]-B[y][ss[y][tpp[y]]],1,n,1);
		nw=ss[y][tpp[y]-1]; tpp[y]--;
	}
	//cout << endl;
	ss[y][++tpp[y]]=x;
}
