#include <bits/stdc++.h>

using namespace std;

const long long N = 5e3 + 10;
const long long M = 205;

struct segtree
{
  long long n;
  vector<long long> base;
  vector<long long> c;
  void init(vector<long long> sd)
  {
    n = 1;
    while(n < (long long) sd.size()) n <<= 1;
    base = sd;
    c = vector<long long> (n << 1, 0);
  }
  void update(long long node, long long l, long long r, long long ind)
  {
    if(l > ind || r < ind) return;
    if(l == r)
    {
      c[node] = ind;
      return;
    }
    update(node << 1, l, (l + r) / 2, ind);
    update((node << 1) + 1, (l + r) / 2 + 1, r, ind);
    c[node] = base[c[node << 1]] > base[c[(node << 1) + 1]] ? c[node << 1] : c[(node << 1) + 1];
  }
  void update(long long ind)
  {
    update(1, 0, n - 1, ind);
  }
  long long rmq(long long node, long long l, long long r, long long i, long long j)
  {
    if(l > j || r < i) return -1;
    if(l >= i && r <= j) return c[node];
    long long p1 = rmq(node << 1, l, (l + r) / 2, i, j), p2 = rmq((node << 1) + 1, (l + r) / 2 + 1, r, i, j);
    if(p1 == -1) return p2;
    if(p2 == -1) return p1;
    return base[p1] > base[p2] ? p1 : p2;
  }
  long long rmq(long long i, long long j)
  {
    return rmq(1, 0, n - 1, i, j);
  }
  long long getVal(long long i)
  {
    return base[i];
  }
} st[M];

vector<vector<long long>> imos(N, vector<long long> (N, 0));

void solve(long long m, long long l, long long r)
{
  if(l > r) return;
  long long pos = st[m].rmq(l, r);
  imos[l][pos] += st[m].getVal(pos);
  imos[pos + 1][pos] -= st[m].getVal(pos);
  imos[l][r + 1] -= st[m].getVal(pos);
  imos[pos + 1][r + 1] += st[m].getVal(pos);
  solve(m, l, pos - 1);
  solve(m, pos + 1, r);
}

