//k種類目のチケットを値域[i,j)においてみる
void bury(imos2d<LL>&imos, int k, int i, int j)
{
	if (i == j)return;
	auto ret = vec[k].query(i, j);
	LL val = ret.first;
	int index = ret.second;
	int lef = i;
	int upp = index;
	int wid = index - i + 1;
	int hei = j - index;
	imos.splat(lef, upp, wid, hei, val);
	bury(imos, k, i, index);
	bury(imos, k, index + 1, j);
}


