const int NMAX = 5e3 + 5;
const int MMAX = 2e2 + 5;
const int LMAX = 1e1 + 4;

long long dp[NMAX], dst[NMAX];
int rmq[MMAX][LMAX][NMAX], pos[NMAX], pwr[NMAX];

inline int getmax(int p, int l, int r) {
    int k = pwr[r - l + 1];
    return max(rmq[p][k][l], rmq[p][k][r - (1 << k) + 1]);
}

void solve(int le, int ri, int m) {
    int md = (le + ri) >> 1;

    if (le > ri)
        return;

    for (int k = min(md, pos[ri + 1]); k >= pos[le - 1]; --k) {
        long long cst = dst[k] - dst[md];

        for (int i = 1; i <= m; ++i)
            cst += getmax(i, k, md);

        if (dp[md] < cst)
            dp[md] = cst, pos[md] = k;
    }

    solve(le, md - 1, m);
    solve(md + 1, ri, m);
    return;
}

