int id[5011], id2[5011];

int getCost(int l, int r) {
    int k = 0;
    int s = k++;
    FOR(i,l,r) id[i] = k++;
    FOR(i,1,m) id2[i] = k++;
    int t = k++;

    MinCostFlow<int,int> flow(k);
    FOR(i,l,r) flow.addEdge(s, id[i], m, 0);
    FOR(i,1,m) flow.addEdge(id2[i], t, 1, 0);

    FOR(i,l,r) FOR(j,1,m) flow.addEdge(id[i], id2[j], 1, -cost[i][j]);

    auto res = flow.minCostFlow(s, t);
    return x[l] - x[r] -res.second;
}


