int N, M;
ll dist[MAXN], cost[MAXN][MAXM] ;
ll memo[MAXM];
stack < pair<int, ll> > Q[MAXM];


void input() {
  cin >> N >> M;
  for (int i = 2 ; i <= N ; i++) {
    cin >> dist[i];
    memo[i] = -dist[i];
  }
  for (int i = 1 ; i <= N ; i++) {
    for (int j = 1 ; j <= M ; j++) {
      cin >> cost[i][j];
    }
  }
}


void preprocess() {
}


void solve() {
  ll ans = 0;
  for (int start = N ; start >= 1 ; start--) {
    for (int i = 1 ; i <= M ; i++) {
      memo[start] += cost[start][i];
      while (!Q[i].empty()) {
        int consider = Q[i].top().first;
        if (cost[consider][i] <= cost[start][i]) {
          memo[consider] -= Q[i].top().second;
          Q[i].pop();
        } else {
          memo[consider] -= Q[i].top().second;
          Q[i].top().second = cost[consider][i] - cost[start][i];
          memo[consider] += Q[i].top().second;
          break;
        }
      }
      Q[i].push({start, cost[start][i]});
    }
    ll cur = dist[start];
    for (int ending = start ; ending <= N ; ending++) {
      cur += memo[ending];
      ans = max(ans, cur);
    }
  }
  cout << ans;
}


