    int i = RMQ(l, r + 1);
    dp[l][i] += MX[0][i].first;
    dp[i + 1][i] -= MX[0][i].first;
    dp[l][r + 1] -= MX[0][i].first;
    dp[i + 1][r + 1] += MX[0][i].first;
    Solve(l, i - 1); Solve(i + 1, r);
}
