template<typename T, typename U> static void amin(T &x, U y) { if (y < x) x = y; }
template<typename T, typename U> static void amax(T &x, U y) { if (x < y) x = y; }

int main() {
	int N; int M;
	while (~scanf("%d%d", &N, &M)) {
		vector<int> A(N - 1);
		for (int i = 0; i < N - 1; ++i)
			scanf("%d", &A[i]);
		vector<vector<int> > B(N, vector<int>(M));
		for (int i = 0; i < N; ++i) for (int j = 0; j < M; ++j)
			scanf("%d", &B[i][j]);
		vector<ll> pos(N, 0);
		rep(i, N - 1)
			pos[i + 1] = pos[i] + A[i];
		ll ans = -INFL;
		rep(i, N) {
			ll sum = accumulate(B[i].begin(), B[i].end(), 0LL);
			amax(ans, sum);
		}
		function<void(int, int)> rec = [&](int left, int right) {
			if (left + 1 == right) return;
			int size = right - left, half = size / 2;

			vector<int> maxVal(size);
			vector<vector<ll>> add(size, vector<ll>(size + 1, 0));
			rep(j, M) {
				for (int i = half - 1; i >= 0; --i)
					maxVal[i] = max(B[left + i][j], i == half - 1 ? -INF : maxVal[i + 1]);
				for (int i = half; i < size; ++i)
					maxVal[i] = max(B[left + i][j], i == half ? -INF : maxVal[i - 1]);
				for (int i = half - 1, j = half; i >= 0; --i) {
					for (; j < size && maxVal[i] >= maxVal[j]; ++j);
					add[i][0] += maxVal[i];
					add[i][j] -= maxVal[i];
				}
				for (int i = half, j = half; i < size; ++i) {
					for (; j > 0 && maxVal[i] > maxVal[j - 1]; --j);
					add[i][j] += maxVal[i];
					add[i][half] -= maxVal[i];
				}
			}
			rep(i, size) rep(j, size)
				add[i][j + 1] += add[i][j];
			rep(i, half) reu(j, half, size) {
				ll sum = 0;
				sum += add[i][j];
				sum += add[j][i];
				ll dist = pos[left + j] - pos[left + i];
				ll value = sum - dist;
				amax(ans, value);
			}

			rec(left, left + half);
			rec(left + half, right);
		};
		rec(0, N);
		printf("%lld\n", ans);
	}
	return 0;
}

