using ll = long long;
const ll inf = 1e18;

template<typename T> struct segtree {

    T merge(T x, T y) {
	return max(x,y);
    }
    int n;
    vector<ll> t;
    void init(int n) {
	n += 10;
	this->n = n;
	t.resize(n*4);
    }

    void upd(int v, int tl, int tr, int i, T dx) {
	if (tl == tr) {
	    t[v] = merge(t[v], dx);
	} else {
	    int tm = (tl+tr)/2;
	    if (i<=tm) {
		upd(2*v,tl,tm,i,dx);
	    } else {
		upd(2*v+1,tm+1,tr,i,dx);
	    }
	    t[v] = merge(t[2*v], t[2*v+1]);
	}
    }

    T qry(int v, int tl, int tr, int l, int r) {
	if (l>tr || r<tl) {
	    return -inf;
	}
	if (l <= tl && tr <= r) {
	    return t[v];
	}
	int tm = (tl+tr)/2;
	return merge(qry(2*v,tl,tm,l,r), qry(2*v+1,tm+1,tr,l,r));
    }
};



const int maxn = 6e3;
const int maxm = 222;

int n, m;

ll a[maxn];
ll b[maxn][maxm];

segtree<ll> t[maxm];

ll qry(int l, int r) {
    ll walk = a[r-1]-a[l-1];
    ll res = 0;
    for (int i=1; i<=m; i++) {
	res += t[i].qry(1,1,n,l,r);
    }
    return res - walk;
}




// As we increase end loc i, starting loc j does not decrease.

ll dp[maxn]; // dp[i]: max value if we end at loc i
// compute dp[tl],dp[tl+1]...dp[tr], assuming optimal starting loc is in [ql,qr]
void solve(int tl, int tr, int ql, int qr) {
    if (tl>tr) return;
    int tm = (tl+tr)/2;

    int opt = 0;
    ll best = -inf;

    // compute dp[tm]
    for (int i=ql; i<=min(tm, qr); i++) {
	dp[tm] = max(dp[tm], qry(i, tm));
	if (dp[tm] > best) {
	    best = dp[tm];
	    opt = i;
	}
    }

    solve(tl,tm-1,ql,opt); // no point in going past opt, [tl,tm-1] < tm, and tm didn't find something past opt useful
    solve(tm+1,tr,opt,qr); // no point in trying to start before opt, tm < [tm+1,tr], and start loc doesn't decrease after end loc increases.
}


