		for (int j = 1; j <= m; ++ j)
			cin >> b[i][j];
    for (int j = 1; j <= m; ++ j){
    	while (st.size()) st.pop();
    	for (int i = 1; i <= n; ++ i){
    		while (st.size() && b[st.top()][j] <= b[i][j]) st.pop();
    		if (st.size()) nxt[i][j] = st.top();
    		st.push(i);
		}
	}
	for (int i = 1; i <= n; ++ i)
		for (int j = 1; j <= m; ++ j)
			vec[nxt[i][j]][j].push_back(i);
	for (int i = 1; i <= n; ++ i){
		for (int j = 1; j <= m; ++ j){
			res[j] = max(res[j], b[i][j]);
			c[i][j] = res[j];
			sum[i] += c[i][j];
		}
		ans = max(ans, sum[i] - part[i]);
	}
	for (int L = 2; L <= n; ++ L){
		for (int j = 1; j <= m; ++ j){
			for (int i : vec[L - 1][j]){
				sum[i] -= c[i][j];
				c[i][j] = b[i][j];
				sum[i] += c[i][j];
			}
		}
		for (int R = L; R <= n; ++ R) ans = max(ans, sum[R] - part[R] + part[L]);
	}
	cout << ans << endl;

    return 0;
}

