/*
一个区间[l,r]确定的时候,答案就确定了 就是每个m的最大值减去路程
这个可以用st表来做 每个m都建一个st表
如果n^2枚举左右端点的话，复杂度太高
而且[l,r],[l,r+1]的答案可能会是一样的，存在重复计算的情况 
然后对于一个区间[l,r],如果l是r的最优的左端点
那么当r往右移时，l一定不会往左移
可以理解为r的决策点满足单调性 就可以用分治做了
定义dp[r]表示以r作为区间右端点的最优的值 
*/
int rd()
{
	int f=1,x=0;char c=getchar();
	while(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}
	while(c>='0'&&c<='9'){x=(x<<3)+(x<<1)+(c^48);c=getchar();}
	return f*x;
}
int n,m;
LL s[N],dp[N],ans;
int lg[N],st[M][N][20];
int Max(int i,int l,int r)
{
	int l1=lg[r-l+1];
	return max(st[i][l][l1],st[i][r-(1<<l1)+1][l1]);
}
void dfs(int l,int r,int optl,int optr)
{
	if(l>r) return ;
	int mid=(l+r)>>1,optm;
	LL res=0;
	for(int i=optl;i<=min(optr,mid);i++)
	{//枚举mid的左端点 
		LL tot=s[i]-s[mid];//先减去路程 
		for(int j=1;j<=m;j++)
			tot+=Max(j,i,mid);//i~mid的食物j的最大值
		if(tot>res) res=tot,optm=i;
	}
	dp[mid]=res;
	dfs(l,mid-1,optl,optm);
	dfs(mid+1,r,optm,optr);
}
