	}
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)
			st[j][i][0]=rd();
	for(int i=1;i<=m;i++)
		for(int k=1;k<20;k++)
			for(int j=1;j+(1<<(k-1))<=n;j++)
				st[i][j][k]=max(st[i][j][k-1],st[i][j+(1<<(k-1))][k-1]);
	dfs(1,n,1,n);
	for(int i=1;i<=n;i++)
		ans=max(ans,dp[i]);
	printf("%lld\n",ans);
}

