void input()
{
    read(N); read(M);
    for (int i = 1; i < N; ++i) {
        read(A[i]);
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            read(B[i][j]);
        }
    }
}

void solve()
{
    static LL add[MAXN][MAXN];

    for (int i = 1; i <= M; ++i) {
        static int st[MAXN];
        int top = 0;

        st[++top] = 1;
        for (int j = 2; j <= N; ++j) {
            for (; top > 0 && B[st[top]][i] < B[j][i]; --top) {
                add[st[top]][j] += B[j][i] - B[st[top]][i];
            }
            st[++top] = j;
        }
    }

    for (int i = N; i >= 1; --i) {
        for (int j = 1; j <= N; ++j) {
            chkmax(add[i][j], add[i + 1][j]);
        }
    }

    LL ans = 0;

    for (int i = 1; i <= N; ++i) {
        LL cur = 0;
        for (int j = 1; j <= M; ++j) {
            cur += B[i][j];
        }
        for (int j = i; j <= N; ++j) {
            cur += add[i][j];
            chkmax(ans, cur);
            cur -= A[j];
        }
    }

    printf("%lld\n", ans);
}

