struct MIN_BIT{
	vector<int> bit;
	void add(int i, int x){
		i++;
		while (i < bit.size()){
			bit[i] = min(bit[i], x);
			i += i&-i;
		}
	}
	void resize(int i){
		bit.assign(i, INT_MAX);
	}
	int sum(int i){
		int r = INT_MAX;
		i++;
		while (i){
			r = min(r, bit[i]);
			i -= i&-i;
		}
		return r;
	}
};
struct MAX_BIT{
	vector<int> bit;
	void add(int i, int x){
		i++;
		while (i < bit.size()){
			bit[i] = max(bit[i], x);
			i += i&-i;
		}
	}
	void resize(int i){
		bit.assign(i, -1);
	}
	int sum(int i){
		int r = -1;
		i++;
		while (i){
			r = max(r, bit[i]);
			i -= i&-i;
		}
		return r;
	}
};

vector<pair<pair<int, int>, int> > ev[MAX];


void add_rect(int a, int b, int c, int d,int x){
	if (a > b){
		swap(a, b);
	}
	if (c > d){
		swap(c, d);
	}
	ev[a].push_back(make_pair(make_pair(c, d), x));
	ev[b+1].push_back(make_pair(make_pair(c, d), -x));
}

struct st{
	long long int val;
	long long int lazy;
	st(){
		val = 0;
		lazy = 0;
	}
};
st seg[MAX * 4];

void update(int b){
	seg[b].val += seg[b].lazy;
	if (b * 2 + 2 < MAX * 4){
		seg[b * 2 + 1].lazy += seg[b].lazy;
		seg[b * 2 + 2].lazy += seg[b].lazy;
	}
	seg[b].lazy = 0;
}
inline void add(int b, int l, int r, int ll, int rr, int x){
	update(b);
	if (rr <= l || r <= ll){
		return;
	}
	if (ll <= l&&r <= rr){
		seg[b].lazy += x;
		update(b);
		return;
	}
	add(b * 2 + 1, l, (l + r) >> 1, ll, rr, x);
	add(b * 2 + 2, (l + r) >> 1, r, ll, rr, x);
	seg[b].val = max(seg[b * 2 + 1].val , seg[b * 2 + 2].val);
}

