ll get(int l, int r){
	if(l >= r)return 0;
	return acc[r-1] - acc[l-1];
}
ll ans;
void calc(int take, int s, int e, int optL, int optR){
	if(s > e)return;
	///dp resturant's taken
	///dp[take][res] = comb(dp[take-1][j])
	int md = (s+e)>>1;
	int optI = optL;
	dp[take][md].first = -inf;
	dp[take][md].second.assign(m+1,0);
	for(int i = optL; i <= min(optR, md); i++){
	  auto x = dp[take-1][i];
    x.first -= get(i,md);
    for(int j = 1; j <= m; j++){
      if(taste[j][md] > x.second[j]){
        x.first -= x.second[j];
        x.first += taste[j][md];
        x.second[j] = taste[j][md];
      }
    }
		if(x.first > dp[take][md].first){
			dp[take][md] = x;
			optI = i;
		}
	}
	ans = max(ans, dp[take][md].first);
	calc(take,s,md-1,optL,optI);
	calc(take,md+1,e,optI,optR);
}
