void dnc(int s,int e,int x,int y){
	int mi=(s+e)/2;
	LL cbest=0;int ci=max(mi,x);
	REPP(i,max(mi,x),y+1){
		LL nv=qu(mi,i);
		if(nv>cbest){
			cbest=nv;ci=i;
		}
	}
	fans=max(fans,cbest);
	if(mi>s)dnc(s,mi-1,x,ci);
	if(e>mi)dnc(e,mi+1,ci,y);
}

