using namespace std;
using ll = long long;
template<class T> using vec = vector<T>;
template<class T> using vvec = vector<vec<T>>;

ll calc(int M,vec<ll>& LA,vvec<ll>& LB,vec<ll>& RA,vvec<ll>& RB){
    int nl = LA.size(),nr = RA.size();
    vvec<ll> L(nl,vec<ll>(M,0)),R(nr,vec<ll>(M,0));
    for(int j=0;j<M;j++){
        for(int l=0;l<nl;l++) L[l][j] = max(LB[l][j],(l!=0? L[l-1][j]:0));
        for(int r=0;r<nr;r++) R[r][j] = max(RB[r][j],(r!=0? R[r-1][j]:0));
    }
    ll res = 0;

    auto getsum = [&](int l,int r){
        ll res = 0;
        for(int j=0;j<M;j++) res += max(L[l][j],R[r][j]);
        return res;
    };

    auto check = [&](int l,int r){
        ll res = RA[r]-RA[r-1]-getsum(l,r);
        res += getsum(l,r-1);
        return res>0;
    };

    int r = nr-1;
    for(int l=0;l<nl;l++){
        while(r>0 && check(l,r)) r--;
        res = max(res,getsum(l,r)-(RA[r]-LA[l]));
    }
    return res;
}

ll solve(vec<ll>& A,vvec<ll>& B){
    int N = A.size(),M = B[0].size();
    if(A.empty()) return 0;
    if(A.size()==1){
        ll sum = 0;
        for(int i=0;i<M;i++) sum += B[0][i];
        return sum;
    }
    vec<ll> LA,RA;
    vvec<ll> LB,RB;
    ll res = 0;
    for(int i=0;i<N;i++){
        if(i<N/2){
            LA.push_back(A[i]);
            vec<ll> l;
            for(int j=0;j<M;j++){
                l.push_back(B[i][j]);
            }
            LB.push_back(l);
        }else{
            RA.push_back(A[i]);
            vec<ll> r;
            for(int j=0;j<M;j++){
                r.push_back(B[i][j]);
            }
            RB.push_back(r);
        }
    }
    res = max({res,solve(LA,LB),solve(RA,RB)});
    reverse(LA.begin(),LA.end());
    reverse(LB.begin(),LB.end());
    res = max(res,calc(M,LA,LB,RA,RB));
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N,M;
    cin >> N >> M;
    vec<ll> A(N);
    for(int i=1;i<N;i++){
        cin >> A[i];
        A[i] += A[i-1];
    }
    vvec<ll> B(N,vec<ll>(M,0));
    for(int i=0;i<N;i++) for(int j=0;j<M;j++) cin >> B[i][j];
    cout << solve(A,B) << endl;
}

