        }
    }
    vector<ll> rui(M),update(N),update0(N);
    vector<vector<ll>> diff(N,vector<ll>(M)),v(M,vector<ll>(N));
    for (int i=0;i<N;++i){
        for (int j=0;j<M;++j){
            diff[i][j]=(!i?0:max(0LL,B[i][j]-rui[j]));
            update0[i]+=diff[i][j];
            rui[j]=max(rui[j],B[i][j]);
            v[j][i]=B[i][j];
        }
    }
    auto f=[](ll a,ll b){return max(a,b);};
    vector<SegmentTree<ll>> seg(M,SegmentTree<ll>(N,f,0));
    for (int i=0;i<M;++i) seg[i].build(v[i]);
    ll ans=0;
    for (int l=0;l<N;++l){
        ll sum=0;
        for (int i=0;i<N;++i) update[i]=update0[i];
