            sum+=B[l][i];
            auto check=[&](ll x){return x>B[l][i];};
            int pos=seg[i].find(i+1,N,check);
            if (~pos) update[pos]+=B[pos][i]-B[l][i]-diff[pos][i];
        }
        ans=max(ans,sum);
        for (int r=l+1;r<N;++r){
            sum+=update[r]-A[r-1];
            ans=max(ans,sum);
        }
    }
    cout << ans << '\n';
