P seg[20000];
void init(int n){
	while(segn < n)segn *= 2;
	rep(i,2*n)seg[i].fi = 0;
}
//k番目の値をxに変更
void add(int k, int x){
	k += segn-1;
	seg[k] = P(x, k-(segn-1));
	while(k > 0){
		k = (k-1)/2;
		seg[k] = max(seg[k*2+1], seg[k*2+2]);
	}
}
//[a,b)の最大値を求める
P get(int a, int b, int k, int l, int r){
	if(b <= l || r <= a)return P(0, 0);
	if(a <= l && r <= b)return seg[k];
	P vl = get(a, b, k*2+1, l, (l+r)/2);
	P vr = get(a, b, k*2+2, (l+r)/2, r);
	return max(vl, vr);
}

