const int N = 5000 + 5;
const int M = 200 + 5;

int n, m;
int q[N][M], top[M];
LL A[N];
LL B[N][M];
LL mx[N << 2], tag[N << 2];

void upd(int x) {mx[x] = max(mx[lc], mx[rc]);}
void make_tag(int x, LL val) {mx[x] += val; tag[x] += val;}
void push_down(int x) {
	if (tag[x]) {
		make_tag(lc, tag[x]);
		make_tag(rc, tag[x]);
		tag[x] = 0;
	}
}

void modify(int x, int l, int r, int s, int t, LL val) {
	if (s <= l && r <= t) return void(make_tag(x, val));
	push_down(x);
	int m = (l + r) >> 1;
	if (s <= m) modify(lc, l, m, s, t, val);
	if (m < t)  modify(rc, m + 1, r, s, t, val);
	upd(x);
}

LL getmax(int x, int l, int r, int s, int t) {
	if (s <= l && r <= t) return mx[x];
	push_down(x);
	int m = (l + r) >> 1; LL ans = -(1 << 60);
	if (s <= m) ans = max(ans, getmax(lc, l, m, s, t));
	if (m < t)  ans = max(ans, getmax(rc, m + 1, r, s, t));
	return ans;
}

int main() {
	read(n), read(m);
	for (int i = 2; i <= n; i++) read(A[i]), A[i] += A[i - 1];
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++) read(B[i][j]);
	for (int i = 1; i <= m; i++) B[n + 1][i] = (1LL << 60);
	for (int i = 1; i <= m; i++) q[++top[i]][i] = n + 1;
	LL ans = 0;
	for (int i = n; i; i--) {
		modify(1, 1, n, i, i, -A[i]);
		for (int j = 1; j <= m; j++) {
			while (top[j] && B[i][j] > B[q[top[j]][j]][j]) {
				modify(1, 1, n, q[top[j]][j], q[top[j] - 1][j] - 1, -B[q[top[j]][j]][j]);
				top[j]--;
			}
			modify(1, 1, n, i, q[top[j]][j] - 1, B[i][j]);
			q[++top[j]][j] = i;
		}
		ans = max(ans, getmax(1, 1, n, i, n) + A[i]);
	}
	printf("%lld\n", ans);
	return 0;
}

