void startSparseTable(){
	for(int k=0; k<m; k++){
		for(int i=0; i<n; i++){
			ST[k][i][0] = b[i][k];
		}
		for(int d=1; 1<<d <= n; d++){
			int dis = 1<<(d-1);
			for(int i=0; i+2*dis <= n; i++){
				ST[k][i][d] = max(ST[k][i][d-1],ST[k][i+dis][d-1]);
			}
