int getMax(int k, int x, int y){
	if(x == y) return b[x][k];
	int d = y-x+1;
	int bit = 31 - __builtin_clz(d);
	int dis = 1<<bit;
	return max(ST[k][x][bit],ST[k][y-dis+1][bit]);
}

ll solve(int i, int j){
