template<typename Monoid>
struct SegmentTree{
    typedef function<Monoid(Monoid,Monoid)> F;
    int n;
    F f;
    Monoid id;
    vector<Monoid> dat;
    SegmentTree(int n_,F f,Monoid id):f(f),id(id){init(n_);}
    void init(int n_){
        n=1;
        while(n<n_) n<<=1;
        dat.assign(n<<1,id);
    }
    void build(const vector<Monoid> &v){
        for (int i=0;i<v.size();++i) dat[i+n]=v[i];
        for (int i=n-1;i;--i) dat[i]=f(dat[i<<1|0],dat[i<<1|1]);
    }
    void update(int k,Monoid x){
        dat[k+=n]=x;
        while(k>>=1) dat[k]=f(dat[k<<1|0],dat[k<<1|1]);
    }
    Monoid query(int a,int b){
        if (a>=b) return id;
        Monoid vl=id,vr=id;
        for (int l=a+n,r=b+n;l<r;l>>=1,r>>=1){
            if (l&1) vl=f(vl,dat[l++]);
            if (r&1) vr=f(dat[--r],vr);
        }
        return f(vl,vr);
    }
    Monoid operator[](int i){
        return dat[i+n];
    }
    // most left position that meets condition "check"
    template<typename C>
    int find(int a,int b,const C &check,int k,int l,int r){
        if (!check(dat[k])||r<=a||b<=l) return -1;
        if (l+1==r) return k-n;
        int vl=find(a,b,check,k<<1|0,l,(l+r)>>1);
        if (~vl) return vl;
        return find(a,b,check,k<<1|1,(l+r)>>1,r);
    }
    template<typename C>
    int find(int a,int b,const C &check){
        return find(a,b,check,1,0,n);
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N,M; cin >> N >> M;
    vector<ll> A(N-1);
    vector<vector<ll>> B(N,vector<ll>(M));
    for (int i=0;i<N-1;++i) cin >> A[i];
    for (int i=0;i<N;++i){
        for (int j=0;j<M;++j){
            cin >> B[i][j];
        }
    }
    vector<ll> rui(M,0),update(N),update0(N,0);
    vector<vector<ll>> diff(N,vector<ll>(M)),v(M,vector<ll>(N));
    for (int i=0;i<N;++i){
        for (int j=0;j<M;++j){
            diff[i][j]=(!i?0:max(0LL,B[i][j]-rui[j]));
            update0[i]+=diff[i][j];
            rui[j]=max(rui[j],B[i][j]);
            v[j][i]=B[i][j];
        }
    }
    auto f=[](ll a,ll b){return max(a,b);};
    vector<SegmentTree<ll>> seg(M,SegmentTree<ll>(N,f,0));
    for (int i=0;i<M;++i) seg[i].build(v[i]);
    ll ans=0;
    for (int l=0;l<N;++l){
        ll sum=0;
        for (int i=0;i<N;++i) update[i]=update0[i];
        for (int i=0;i<M;++i){
            sum+=B[l][i];
            auto check=[&](ll x){return x>B[l][i];};
            int pos=seg[i].find(l+1,N,check);
            if (~pos) update[pos]+=B[pos][i]-B[l][i]-diff[pos][i];
        }
        ans=max(ans,sum);
        for (int r=l+1;r<N;++r){
            sum+=update[r]-A[r-1];
            ans=max(ans,sum);
        }
    }
    cout << ans << '\n';
}

