namespace loquat {
template <typename T, typename Func>
class segment_tree {
public:
	using value_type = T;
private:
	size_t m_actual_size;
	std::vector<value_type> m_values;
	Func m_function;
	void initialize(){
		const auto m = m_values.size() / 2;
		for(size_t i = 0; i < m; ++i){
			const auto k = m - 1 - i;
			m_values[k] = m_function(
				m_values[k * 2 + 1], m_values[k * 2 + 2]);
		}
	}
public:
	segment_tree(
		size_t size,
		const Func& func = Func())
		: m_actual_size(size)
		, m_values(bitmanip::clp2(m_actual_size) * 2 - 1)
		, m_function(func)
	{
		const auto it = m_values.begin() + m_values.size() / 2;
		std::fill(it, it + m_actual_size, value_type());
		initialize();
	}
	template <typename Iterator>
	segment_tree(
		Iterator first,
		Iterator last,
		const Func& func = Func())
		: m_actual_size(std::distance(first, last))
		, m_values(bitmanip::clp2(m_actual_size) * 2 - 1)
		, m_function(func)
	{
		const auto it = m_values.begin() + m_values.size() / 2;
		std::copy(first, last, it);
		initialize();
	}
	value_type query(size_t left, size_t right) const {
		const auto m = m_values.size() / 2;
		left += m; right += m;
		bool l_valid = false, r_valid = false;
		value_type l_value, r_value;
		while(left < right){
			if((left & 1u) == 0u){
				const auto& x = m_values[left];
				l_value = (l_valid ? m_function(l_value, x) : x);
				l_valid = true;
			}
			if((right & 1u) == 0u){
				const auto& x = m_values[right - 1];
				r_value = (r_valid ? m_function(x, r_value) : x);
				r_valid = true;
			}
			left  = left / 2;
			right = (right - 1) / 2;
		}
		if(l_valid && r_valid){ return m_function(l_value, r_value); }
		if(l_valid){ return l_value; }
		if(r_valid){ return r_value; }
		return m_values.front();
	}
};
}
using namespace std;
struct max_func {
	int operator()(int a, int b) const { return std::max(a, b); }
};
using ll = long long;
using max_segment_tree = loquat::segment_tree<int, max_func>;
int main(){
	ios_base::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<int> a(n - 1);
	for(int i = 0; i < n - 1; ++i){ cin >> a[i]; }
	vector<vector<int>> b(n, vector<int>(m));
	for(int i = 0; i < n; ++i){
		for(int j = 0; j < m; ++j){ cin >> b[i][j]; }
	}
	vector<max_segment_tree> segtrees(m, max_segment_tree(n));
	for(int j = 0; j < m; ++j){
		vector<int> c(n);
		for(int i = 0; i < n; ++i){ c[i] = b[i][j]; }
		segtrees[j] = max_segment_tree(c.begin(), c.end());
	}
	vector<int> best_table(m);
	ll sum = 0, answer = 0;
	for(int l = 0, r = 0; r < n; ++r){
		if(r != 0){ sum -= a[r - 1]; }
		for(int j = 0; j < m; ++j){
			const int best = max(best_table[j], b[r][j]);
			sum += best - best_table[j];;
			best_table[j] = best;
		}
		while(l + 1 < r){
			ll loss = 0;
			vector<int> narrow_best(m);
			for(int j = 0; j < m; ++j){
				narrow_best[j] = segtrees[j].query(l + 1, r);
			}
			for(int j = 0; j < m; ++j){
				loss += best_table[j] - narrow_best[j];
			}
			if(loss >= a[l]){ break; }
			best_table = move(narrow_best);
			sum -= loss;
			sum += a[l];
			++l;
		}
		answer = max(answer, sum);
	}
	cout << answer << endl;
	return 0;
}

