int st[2*MN][MM];
ll w[MN][MM];
ll res[MN][MN];
ll cs[MN],pr[MN];
int n,m;
void build() {
	for(int i=0;i<m;i++) {
		for(int j=n-1;j>0;j--) {
			int a = st[j<<1][i],b = st[j<<1|1][i];
			if(w[a][i] > w[b][i]) {
				st[j][i] = a;
			} else {
				st[j][i] = b;
			}
		}
	}
}
int qu(int l, int r, int id) {
	l += n;r += n;
	int ma = l;
	for(;l<r;l>>=1,r>>=1) {
		if(l&1) {
			int a = st[l++][id];
			if(w[a][id] > w[ma][id]) {
				ma = a;
			}
		}
		if(r&1) {
			int a = st[--r][id];
			if(w[a][id] > w[ma][id]) {
				ma = a;
			}
		}
	}
	return ma;
}
void get(int l, int r, int id) {
	if(l >= r) {return;}
	int val = qu(l,r,id);
	res[l][val] += w[val][id];
	res[val+1][val] -= w[val][id];
	res[l][r] -= w[val][id];
	res[val+1][r] += w[val][id];
	get(l,val,id);
	get(val+1,r,id);
}
ll resolve() {
	for(int j=0;j<n;j++) {
		for(int i=0;i<n;i++) {
			res[i+1][j] += res[i][j];
		}
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<n;j++) {
			res[i][j+1] += res[i][j];
		}
	}
	ll ma = -INF;
	for(int i=0;i<n;i++) {
		for(int j=i;j<n;j++) {
			//cout << "ij " << i << " " << j << " = " << res[i][j] << "-" << pr[j]-pr[i] << '\n';
			res[i][j] -= pr[j]-pr[i];
			ma = max(ma,res[i][j]);
		}
	}
	return ma;
}
