		pr[i+1] = pr[i]+cs[i];
	}
	for(int i=0;i<n;i++) {
		for(int j=0;j<m;j++) {
			cin >> w[i][j];
			st[i+n][j] = i;
		}
	}
	build();
	for(int i=0;i<m;i++) {
		get(0,n,i);
	}
