void build(int n, ll *a) {
    cnt_v = 1;
    while (cnt_v < n) {
        cnt_v <<= 1;
    }
    rep(i, 0, n) {
        tree[cnt_v - 1 + i] = a[i];
    }
    repb(i, cnt_v - 2, -1) {
        tree[i] = max(tree[i * 2 + 1], tree[i * 2 + 2]);
    }
}

void push(int x) {
    tree[x * 2 + 1] += add[x];
    add[x * 2 + 1] += add[x];
    tree[x * 2 + 2] += add[x];
    add[x * 2 + 2] += add[x];
    add[x] = 0;
}

void upd(int x, int lx, int rx, int l, int r, ll v) {
    if (lx >= r || l >= rx) {
        return;
    } else if (lx >= l && rx <= r) {
        tree[x] += v;
        add[x] += v;
    } else {
        push(x);
        upd(x * 2 + 1, lx, (lx + rx) / 2, l, r, v);
        upd(x * 2 + 2, (lx + rx) / 2, rx, l, r, v);
        tree[x] = max(tree[x * 2 + 1], tree[x * 2 + 2]);
    }
}

ll get(int x, int lx, int rx, int l, int r) {
    if (lx >= r || l >= rx) {
        return -big;
    } else if (lx >= l && rx <= r) {
        return tree[x];
    } else {
        push(x);
        return max(get(x * 2 + 1, lx, (lx + rx) / 2, l, r), get(x * 2 + 2, (lx + rx) / 2, rx, l, r));
    }
}

