constexpr ll TEN(int n) { return (n==0) ? 1 : 10*TEN(n-1); }

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    ll a[n];
    for (int i = 0; i < n-1; i++) {
        scanf("%lld", a+i);
    }
    a[n-1] = 0;

    ll b[5050][220];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            scanf("%lld", &(b[i][j]));
        }
    }

    ll mp[5050][5050] = {};

    for (int num = 0; num < m; num++) {
        using P = pair<ll, int>;
        vector<P> v(n);
        for (int i = 0; i < n; i++) {
            v[i] = P(b[i][num], i);
        }
        sort(begin(v), end(v), greater<P>());
        set<int> s; s.insert(-1); s.insert(n);
        set<int, greater<int>> rs; rs.insert(-1); rs.insert(n);
        for (auto x: v) {
            int i = x.second;
            ll d = x.first;
            int lw = *rs.lower_bound(i) + 1;
            int up = *s.lower_bound(i) - 1;
            s.insert(i); rs.insert(i);
            mp[lw][i] += d;
            mp[lw][up+1] -= d;
            mp[i+1][i] -= d;
            mp[i+1][up+1] += d;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 1; j < n; j++) {
            mp[i][j] += mp[i][j-1];
        }
    }
    for (int j = 0; j < n; j++) {
        for (int i = 1; i < n; i++) {
            mp[i][j] += mp[i-1][j];
        }
    }
    ll ans = -TEN(18);
    for (int l = 0; l < n; l++) {
        ll dist = 0;
        for (int r = l; r < n; r++) {
            ans = max(ans, mp[l][r] - dist);
            dist += a[r];
        }
    }
    printf("%lld\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define maxn 5005
#define int long long
#define maxm 250 
int n, m, dis[maxn], val[maxn][maxm];
int Ans, ans[maxn][maxn], Q[maxn];

int read()
{
	int x = 0, k = 1;
	char c; c = getchar();
	while(c < '0' || c > '9') { if(c == '-') k = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * k;
}

struct node
{
	int num, id;
	node(int _id = 0, int _num = 0) { num = _num, id = _id; }
}S[maxm][maxn];

signed main()
{
	n = read(), m = read();
	for(int i = 2; i <= n; i ++) dis[i] = read() + dis[i - 1];
	for(int i = 1; i <= n; i ++) 
		for(int j = 1; j <= m; j ++) val[i][j] = read();
	for(int i = 1; i <= m; i ++) S[i][0].id = n + 1;
	for(int i = n; i >= 1; i --)
	{
		for(int j = 1; j <= m; j ++)
		{
			int top = Q[j];
			ans[i][i] += val[i][j]; ans[i][i + 1] -= val[i][j];
			while(top && S[j][top].num <= val[i][j]) 
			{
				int l = S[j][top].id, r = S[j][top - 1].id;
				int t = val[i][j] - S[j][top].num; 
				ans[i][l] += t, ans[i][r] -= t; 
				top --;
			}
			S[j][++ top] = node(i, val[i][j]);
			Q[j] = top;
		}
	}
	for(int i = n; i; i --)
	{
		for(int j = i; j <= n; j ++)
			ans[i][j] += ans[i][j - 1];
		for(int j = i; j <= n; j ++) ans[i][j] += ans[i + 1][j];
		for(int j = i; j <= n; j ++) 
			Ans = max(Ans, ans[i][j] - dis[j] + dis[i]); 
	}
	printf("%lld\n", Ans);
	return 0;
}

