void Init() {
	scanf("%d%d",&n,&m);
	for (int i=2;i<=n;++i) scanf("%lld",&A[i]),A[i]+=A[i-1];
	for (int i=1;i<=n;++i)
		for (int j=1;j<=m;++j) scanf("%d",&B[i][j]);
}

void Add(int l,int r,int v) { 
	a[l-1]-=v; a[r]+=v;
}

void Solve() {
	LL ans=0;
	for (int r=1;r<=n;++r) {
		for (int j=1;j<=m;++j) {
			while (t[j] && B[r][j]>=B[q[j][t[j]]][j]) {
				Add(q[j][t[j]-1]+1,q[j][t[j]],-B[q[j][t[j]]][j]);
				t[j]--;
			}
			Add(q[j][t[j]]+1,r,B[r][j]); q[j][++t[j]]=r;
		}
		for (int l=r,sum=0;l>=1;--l) sum+=a[l],ans=max(ans,sum-(A[r]-A[l]));
	}
	printf("%lld\n",ans);
}

