void solve (int t) {
	vector < pair <int, int> > v;

	for (int i = 0; i < n; i++)
		v.push_back ({-b[i][t], i});

	sort (v.begin(), v.end());

	set <int> s;

	for (auto a : v) {
		int v = -a.first, l, r, x = a.second;

		auto it = s.upper_bound (x);

		if (it == s.end ()) r = n - 1;
		else r = *it - 1;

		if (it == s.begin ()) l = 0;
		else l = *(--it) + 1;
