			LL hoge = -(AS[j + i - 1] - AS[j]);//つかれ
			REP(k, M) {
				LL max = 0;
				LL findA = j;
				LL findB = j + i;
				while (true) {

					LL now = 0;
					LL tasu = 8192;
					LL gomi = 2;
					REP(nyan, 13) {
						if (findA%gomi == 0&&findA+gomi<=findB) {
							now += tasu;
							tasu = tasu / 2;
							gomi = gomi * 2;
						}
						else {
							break;
						}
					}
					gomi = gomi / 2;
					if (B[now + findA / gomi][k] > max) {
						max = B[now + findA / gomi][k];
					}
					findA += gomi;
					if (findA == findB) { break; }
				}
				hoge += max;
			}
			if (hoge > ans) { ans = hoge; }
		}
	}
	cout << ans << endl;
}

