#define ALL(c) (c).begin(),(c).end()

const int MN = 5010;
const int MM = 210;

const int SZ = 1 << 13;

struct segtree {
	vector<pii> dat;

	void init() {
		dat.resize(SZ * 2);
		rep(i, SZ * 2) dat[i] = mp(-1, -1);
	}

	void update(int pos, int x) {
		pos += SZ - 1;
		dat[pos] = mp(x, pos - (SZ - 1));

		while (pos > 0) {
			pos = (pos - 1) / 2;
			dat[pos] = max(dat[pos * 2 + 1], dat[pos * 2 + 2]);
		}
	}

	pii get(int a, int b, int k = 0, int l = 0, int r = SZ) {
		if (b <= l || r <= a) return mp(-1, -1);
		if (a <= l && r <= b) return dat[k];
		return max(get(a, b, k * 2 + 1, l, (l + r) / 2), get(a, b, k * 2 + 2, (l + r) / 2, r));
	}
} seg;

int N, M;
ll A[MN];
ll B[MN][MM];
ll imos[MN][MN];

inline void add(int a, int b, int c, int d, ll t) {
	imos[a][b] += t;
	imos[c][d] += t;
	imos[a][d] -= t;
	imos[c][b] -= t;
}

void solve(int id, int l, int r) {
	if (l + 1 > r) return ;

	pii res = seg.get(l, r);
	int m = res.se;
	add(l, m, m + 1, r, res.fi);
	solve(id, l, m);
	solve(id, m + 1, r);
}

