		}
	}

	rep(id, M) {
		seg.init();
		rep(i, N) seg.update(i, B[i][id]);
		solve(id, 0, N);
	}

	ll ret = LLONG_MIN;

	rep(i, N) {
		rep(j, N) {
			imos[i][j+1] += imos[i][j];
		}
	}

	rep(i, N) {
		rep(j, N) {
			imos[i+1][j] += imos[i][j];
		}
	}

	for (int i = 0; i < N; ++i) {
		for (int j = i; j < N; ++j) {
			ret = max(ret, imos[i][j] - (A[j] - A[i]));
		}
	}

	cout << ret << endl;

	return 0;
}

