void init() {
    for (int i = 0; i < 15; i++)
        pw[i] = (1 << i);
    for (int i = 1; i < maxn; i++)
        ptr[i] = ptr[i - 1] + (i == 2 * pw[ptr[i - 1]]);
}

void build(int cm) {
    for (int i = 0; i < n; i++)
        st[cm][0][i] = b[cm][i];
    for (int j = 1; j <= ptr[n]; j++) {
        for (int i = 0; i < n; i++) {
            if (i + pw[j] > n) break;
            st[cm][j][i] = max(st[cm][j - 1][i], st[cm][j - 1][i + pw[j - 1]]);
        }
    }
}

inline int get(int cm, int l, int r) {
    return max(st[cm][ptr[r - l + 1]][l],
               st[cm][ptr[r - l + 1]][r + 1 - pw[ptr[r - l + 1]]]);
}

void dnq(int l, int r, int cl, int cr) {
    //cout << "! " << l << ' ' << r << " - " << cl << ' ' << cr << '\n';
    if (r <= l) return;
    int md = (l + r) / 2;
    int ci;
    for (int i = max(md, cl); i < cr; i++) {
        int cs = 0;
        for (int j = 0; j < m; j++)
            cs += get(j, md, i);
        dp[md] = max(dp[md], cs - pf[i + 1] + pf[md]);
        if (dp[md] == cs - pf[i + 1] + pf[md])
            ci = i;
    }
    if (r - l == 1) return;
    dnq(l, md, cl, ci + 1);
    dnq(md + 1, r, ci, cr);
}

