void solve(int l, int r, int kmin, int kmax) {
    if (l > r) return;

    int mid = (l+r)/2;
    int best = -1;
    vector<int> maxB(m, 0);

    fdto(i, min(kmax, mid), kmin) {
        ll val = 0;
        fto(j, 0, m-1) {
            maxB[j] = max(maxB[j], b[i][j]);
            val += maxB[j];
        }
        val -= x[mid] - x[i];
        if (best == -1 || val > maxVal[mid]) {
            maxVal[mid] = val;
            best = i;
        }
    }

    solve(l, mid-1, kmin, best);
    solve(mid+1, r, best, kmax);
}

