      ord[j]=j;
    }
    sort(all(ord),[=](const ll& a,const ll& b){
      return B[a] < B[b];
    });

    UnionFind uf(N);
    rep(j,N)uf.l[j]=uf.r[j]=j;
    for(ll j:ord){
      if(j>0&&B[j-1]<=B[j])uf.unite(j-1,j);
