SegmentTree seg;

void dfs(int l, int r) {
  if(l >= r) return;
  Pi p = seg.query(l, r);
  dp[l][p.second] += p.first;
  dp[p.second+1][p.second] -= p.first;
  dp[l][r] -= p.first;
  dp[p.second+1][r] += p.first;
  dfs(l, p.second);
  dfs(p.second+1, r);
}

