  for (int j = 1; j <= m; ++j) {
    for (int i = 1; i <= n; ++i)
        st[i][0] = i;
    for (int k = 1; (1 << k) <= n; ++k) {
      for (int i = 1; i + (1 << k) - 1 <= n; ++i){
        if (b[j][st[i][k - 1]] > b[j][st[i + (1 << (k - 1))][k - 1]])
          st[i][k] = st[i][k - 1];
        else
          st[i][k] = st[i + (1 << (k - 1))][k - 1];
      }
    }
    calc(j, 1, n);
  }

  for (int l = 1; l <= n; ++l) {
    for (int r = 1; r <= n; ++r) {
      f[l][r] += f[l - 1][r] + f[l][r - 1] - f[l - 1][r - 1];
    }
  }

  ll ans = LLONG_MIN;
  for (int l = 1; l <= n; ++l) {
