enum {
  MAXN = 5000 + 5,
  MAXM = 200 + 5
};

struct data {
  int l, r, x;
  data() {
    l = r = x = 0;
  }
  data(int _l, int _r, int _x):
    l(_l), r(_r), x(_x) {}
};

struct RMQ {
  int log2[MAXN];
  int max[20][MAXN];

  void exec(int *a, int N) {
    int i, d;
    for (i=0; i<N; ++i)
      max[0][i] = a[i];
    for (log2[0]=log2[1]=0, i=2; i<=N; ++i)
      log2[i] = log2[i>>1]+1;
    for (d=1; 1<<d <= N; ++d)
      for (i=0; i+(1<<d) <= N; ++i)
	max[d][i] = std::max(max[d-1][i], max[d-1][i + (1<<(d-1))]);
  }

  int getmax(int l, int r) {
    int d = log2[r-l];
    return std::max(max[d][l], max[d][r-(1<<d)]);
  }
} rmq[MAXM];

int N, M;
long long A[MAXN];
int B[MAXM][MAXN];

int top;
data st[MAXN];

long long getans(int l, int r) {
  int i;
  long long res(-(A[r]-A[l]));
  for (i=0; i<M; ++i) {
    res += rmq[i].getmax(l, r+1);
  }
  return res;
}

void exec() {
  int i, j;
  long long ans(0);
  int l, r, mid;
  scanf("%d%d", &N, &M);
  for (i=1; i<N; ++i) {
    scanf("%lld", &A[i]);
    A[i] += A[i-1];
  }
  for (i=0; i<N; ++i)
    for (j=0; j<M; ++j)
      scanf("%d", &B[j][i]);
  for (j=0; j<M; ++j)
    rmq[j].exec(B[j], N);
  for (i=0; i<N; ++i) {
    while (top && st[top-1].r >= i) {
      l = std::max(st[top-1].l, i);
      if (getans(i, l) >= getans(st[top-1].x, l))
  	--top;
      else {
  	r = st[top-1].r;
  	while (l+1 < r) {
  	  mid = l + (r-l) / 2;
  	  (getans(i, mid) >= getans(st[top-1].x, mid)? r : l) = mid;
  	}
  	st[top-1].r = l+1;
  	if (r != st[top-1].r)
  	  st[top] = data(r, st[top-1].r, i), ++top;
  	break;
      }
    }
    if (top == 0)
      st[top++] = data(0, N, i);
    for (j=0; j<top; ++j)
      if (st[j].l <= i && i < st[j].r)
  	ans = std::max(ans, getans(st[j].x, i));
  }
  printf("%lld\n", ans);
}

