static int32_t b[5000][208] __attribute__((aligned(16))) = { { 0 } };

int main(){
	ios_base::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<int> a(n - 1);
	for(int i = 0; i < n - 1; ++i){ cin >> a[i]; }
	for(int i = 0; i < n; ++i){
		for(int j = 0; j < m; ++j){ cin >> b[i][j]; }
	}
	int64_t answer = 0;
	for(int l = 0; l < n; ++l){
		int32_t c[208] __attribute__((aligned(16))) = { 0 };
		int64_t move_sum = 0;
		for(int r = l; r < n; ++r){
			const int32_t *d = &(b[r][0]);
			__m128i sum_i64 = _mm_setzero_si128();
			for(int i = 0; i < m; i += 16){
				const __m128i c0 = _mm_load_si128((const __m128i *)(c + i +  0));
				const __m128i d0 = _mm_load_si128((const __m128i *)(d + i +  0));
				const __m128i c1 = _mm_load_si128((const __m128i *)(c + i +  4));
				const __m128i d1 = _mm_load_si128((const __m128i *)(d + i +  4));
				const __m128i c2 = _mm_load_si128((const __m128i *)(c + i +  8));
				const __m128i d2 = _mm_load_si128((const __m128i *)(d + i +  8));
				const __m128i c3 = _mm_load_si128((const __m128i *)(c + i + 12));
				const __m128i d3 = _mm_load_si128((const __m128i *)(d + i + 12));
				const __m128i e0 = _mm_max_epi32(c0, d0);
				const __m128i e1 = _mm_max_epi32(c1, d1);
				const __m128i e2 = _mm_max_epi32(c2, d2);
				const __m128i e3 = _mm_max_epi32(c3, d3);
				_mm_store_si128((__m128i *)(c + i +  0), e0);
				_mm_store_si128((__m128i *)(c + i +  4), e1);
				_mm_store_si128((__m128i *)(c + i +  8), e2);
				_mm_store_si128((__m128i *)(c + i + 12), e3);
				const __m128i f01 = _mm_add_epi32(e0, e1);
				const __m128i f23 = _mm_add_epi32(e2, e3);
				const __m128i g   = _mm_add_epi32(f01, f23);
				const __m128i h0  = _mm_cvtepu32_epi64(g);
				const __m128i h1  = _mm_cvtepu32_epi64(_mm_srli_si128(g, 8));
				sum_i64 = _mm_add_epi64(sum_i64, _mm_add_epi64(h0, h1));
			}
			int64_t buffer[2] __attribute__((aligned(16)));
			_mm_store_si128((__m128i *)buffer, sum_i64);
			answer = max(answer, buffer[0] + buffer[1] - move_sum);
			move_sum += a[r];
		}
	}
	cout << answer << endl;
	return 0;
}

