void pre() {

	for(int i = 2; i <= N; ++i) {
		A[i] += A[i - 1];
	}

	for(int j = 1; j <= M; ++j) {
		top = 0;
		for(int i = 1; i <= N; ++i) {
			while(top > 0 && B[stk[top]][j] < B[i][j]) {
				Rm[stk[top]][j] = i - 1;
				--top;
			}
			Lm[i][j] = stk[top] + 1;
			stk[++top] = i;
		}
		while(top > 0) {
			Rm[stk[top]][j] = N;
			--top;
		}
	}
}

