				F[Lm[i][j]][i] += B[i][j];
				F[Lm[i][j]][Rm[i][j] + 1] -= B[i][j];
				F[i + 1][i] -= B[i][j];
				F[i + 1][Rm[i][j] + 1] += B[i][j];
			}
		}

		for(int i = 1; i <= N; ++i) {
			for(int j = 1; j <= N; ++j) {
				F[i][j] += F[i - 1][j] + F[i][j - 1] - F[i - 1][j - 1];
			}
		}

		for(int i = 1; i <= N; ++i) {
			for(int j = i; j <= N; ++j) {
				Ans = Max(Ans, F[i][j] - (A[j] - A[i]));
			}
		}

		printf("%lld", Ans);
	}
}

