int N, M;
int A[5000];
SegmentTree<Monoid::Maximum<PP>>* segs[200];
LL P[5002][5002];

LL post() {
	REP(i, 0, N + 1) {
		REP(j, 0, N + 1) {
			P[i + 1][j + 1] += P[i + 1][j] + P[i][j + 1] - P[i][j];
		}
	}

	LL mx = 0;
	REP(i, 0, N) {
		REP(j, i, N) {
			mx = max(mx, P[i + 1][j + 1] - (A[j] - A[i]));
		}
	}
	return mx;
}

void add(LL val, int li, int lj, int ri, int rj) {
	P[li + 1][lj + 1] += val;
	P[li + 1][rj + 1] -= val;
	P[ri + 1][lj + 1] -= val;
	P[ri + 1][rj + 1] += val;
}

void rec(int i, int l, int r) {
	if (l == r) return;
	PP mxp = segs[i]->query(l, r);
	LL val = mxp.first;
	int mxi = mxp.second;

	add(val, l, mxi, mxi + 1, r);

	rec(i, l, mxi);
	rec(i, mxi + 1, r);
}

void sub(int i) {
	rec(i, 0, N);
}

int main() {
	cin >> N >> M;
	int sum = 0;
	REP(i, 1, N) {
		sum += Next<int>();
		A[i] = sum;
	}

	REP(i, 0, M) {
		segs[i] = new SegmentTree<Monoid::Maximum<PP>>(13);
	}

	REP(j, 0, N) {
		REP(i, 0, M) {
			segs[i]->update(j, PP(Next<int>(), j));
		}
	}

	REP(i, 0, M) {
		sub(i);
	}

	cout << post() << endl;

	REP(i, 0, M) {
		delete segs[i];
	}

	return 0;
}

