#define int long long
const int N = 5002;
const int INF = 1e15 + 239;

int n;
int cost[N];
int val[N][N];

void add(int i1, int i2, int j1, int j2, int x) {
	val[i1][j1] += x;
	val[i2][j1] -= x;
	val[i1][j2] -= x;
	val[i2][j2] += x;
} 

void resolve() {
	auto gv = [&](int i, int j) {
		if (i < 0 || j < 0) return (int)0;
		return val[i][j];
	};
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			val[i][j] += gv(i - 1, j) + gv(i, j - 1) - gv(i - 1, j - 1);
		}
	}
}

void apply(vector<int> a) {
	vector<int> l(n);
	vector<int> r(n);
	{
		vector<int> st;
		for (int i = 0; i < n; i++) {
			while (!st.empty() && a[st.back()] <= a[i]) {
				st.pop_back();
			}
			if (st.empty()) {
				l[i] = -1;
			} else {
				l[i] = st.back();
			}
			st.push_back(i);
		}
	}
	{
		vector<int> st;
		for (int i = n - 1; i >= 0; i--) {
			while (!st.empty() && a[st.back()] < a[i]) {
				st.pop_back();
			}
			if (st.empty()) {
				r[i] = n;
			} else {
				r[i] = st.back();
			}
			st.push_back(i);
		}
	}
	for (int i = 0; i < n; i++) {
		add(l[i] + 1, i + 1, i, r[i], a[i]);
	}
}

signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);	

	int m;
	cin >> n >> m;
	for (int i = 0; i + 1 < n; i++) {
		cin >> cost[i];
	}
	vector<vector<int>> a(m);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			int x;
			cin >> x;
			a[j].push_back(x);
		}
	}
	for (int i = 0; i < m; i++) {
		apply(a[i]);
	}
	resolve();
	int ans = -INF;
	for (int i = 0; i < n; i++) {
		int cs = 0;
		for (int j = i; j < n; j++) {
			ans = max(ans, val[i][j] - cs);
			if (j + 1 < n) {
				cs += cost[j];
			}
		}
	}
	cout << ans << endl;
}

