int main(){
	n = read();m = read();
	for(int i = 1; i < n; ++i) a[i] = read(), dis[i] = dis[i - 1] + a[i];
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j)
			b[i][j] = read();
	for(int i = 1; i <= m; ++i){
		for(int j = 1; j <= n; ++j){
			int x = b[j][i];
			while(!st.empty() && st.top().first <= x){
				int p = st.top().second;st.pop();
				r[p][i] = j - 1;
			}
			st.push(mkp(x, j));
		}
		while(!st.empty()){
			int p = st.top().second;
			r[p][i] = n;st.pop();
		}
		for(int j = n; j; --j){
			int x = b[j][i];
			while(!st.empty() && st.top().first < x){
				int p = st.top().second;st.pop();
				l[p][i] = j + 1;
			}
			st.push(mkp(x, j));
		}
		while(!st.empty()){
			int p = st.top().second;
			l[p][i] = 1;st.pop();
		}
	}
	for(int i = 1; i <= m; ++i)
		for(int j = 1; j <= n; ++j){
			int xl = l[j][i], xr = r[j][i], x = b[j][i];
			g[xl][j] += x;g[xl][xr + 1] -= x;
			g[j + 1][j] -= x;g[j + 1][xr + 1] += x;
		}
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= n; ++j)
			g[i][j] += g[i][j - 1];
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= n; ++j)
			g[j][i] += g[j - 1][i];
	ll ans = 0;
	for(int i = 1; i <= n; ++i)
		for(int j = i; j <= n; ++j)
			ans = max(ans, g[i][j] - dis[j - 1] + dis[i - 1]);
	cout << ans << endl;
	return 0;
}

