const int LG = 13;
ll mx[N][M][LG] , pref[N];
void build(){
    for(int i = 0; i < N; ++i)
        for(int j = 0 ; j  < M; ++j){
            mx[i][j][0] = B[i][j];
        }
    for(int st = 1 ; st < LG; ++st){
        for(int i = 0 ; i + (1<<st) <= N ;++i){
            for(int j = 0 ; j < M; ++j){
                mx[i][j][st] = max(mx[i][j][st-1] , mx[i+(1<<(st-1))][j][st-1]);
            }
        }
    }
}
int get_mx(int l , int r , int m){
    int bt = 32 - __builtin_clz(r - l + 1) - 1;
//    if(!((r-(1<<bt)+1) >= l)){
//        cout << l << ' ' << r << ' ' << bt << '\n';
//    }
    return max(mx[l][m][bt] , mx[r - (1<<bt)+1][m][bt]);
}
void solve(int l , int r,  int optl , int optr){
    int mid = (l + r) >> 1;
    /// we wonder to find fucking opt
    int opt = -1;
    fill(MX , MX + M , 0);
    ll cur = 0 , d = 0;
    for(int j = max(mid , optl); j <= optr; ++j){
        cur = 0;
        for(int f = 0 ; f < M; ++f){
            cur += get_mx(mid , j, f);
        }
        cur -= (pref[j] - pref[mid]);
        if(answer[mid] < cur){
            answer[mid] = cur;
            opt = j;
        }
    }
    if(l <= mid - 1)
        solve(l , mid-1 , optl , opt);
    if(mid + 1 <= r)
        solve(mid + 1 , r , opt , optr);
}
