const int N = 1 << 13;
pair<int, int> seg[N * 2 - 1];
void update(int k, int x){
  int i = k + N - 1;
  seg[i] = {x, k};
  while (i){
    i = (i - 1) / 2;
    seg[i] = max(seg[i * 2 + 1], seg[i * 2 + 2]);
  }
}
pair<int, int> query(int l, int r, int k = 0, int a = 0, int b = N){
  if (r <= a || b <= l) return {-inf, -inf};
  if (l <= a && b <= r) return seg[k];
  int m = (a + b) / 2;
  auto vl = query(l, r, k * 2 + 1, a, m);
  auto vr = query(l, r, k * 2 + 2, m, b);
  return max(vl, vr);
}

