const int N=5e3+10;

struct segment_tree
{
    ll it[N*4],lazy[N*4];

    void down(int id)
    {
        ll tmp=lazy[id];
        lazy[id]=0;
        it[id*2]+=tmp;
        it[id*2+1]+=tmp;
        lazy[id*2]+=tmp;
        lazy[id*2+1]+=tmp;
    }

    void update(int id,int l,int r,int u,int v,ll x)
    {
        if (l>v || r<u) return;
        if (u<=l && r<=v)
        {
            it[id]+=x;
            lazy[id]+=x;
            return;
        }
        int mid=(l+r)/2;
        down(id);
        update(id*2,l,mid,u,v,x);
        update(id*2+1,mid+1,r,u,v,x);
        it[id]=max(it[id*2],it[id*2+1]);
    }

    ll get(int id,int l,int r,int u,int v)
    {
        if (l>v || r<u) return 0;
        if (u<=l && r<=v) return it[id];
        int mid=(l+r)/2;
        down(id);
        return max(get(id*2,l,mid,u,v),get(id*2+1,mid+1,r,u,v));
    }
};

