void add(int x1,int x2,int y1,int y2,int w)
{
    sum[x1][y1]+=w;
    sum[x1][y2+1]-=w;
    sum[x2+1][y1]-=w;
    sum[x2+1][y2+1]+=w;
}

void solve(int *a)
{
    static int l[5010],r[5010],stk[5010],top;
    stk[top=0]=0;
    repu(i,1,n)
    {
        for (; top && a[stk[top]]<a[i]; --top);
        l[i]=stk[top]+1,stk[++top]=i;
    }
    stk[top=0]=n+1;
    repd(i,n,1)
    {
        for (; top && a[stk[top]]<=a[i]; --top);
        r[i]=stk[top]-1,stk[++top]=i;
        add(i,r[i],l[i],i,a[i]);
    }
}

