					sub += mx[k];
				}
				ans = max(sub-dist,ans);
				//cout << sub << "|" <<  dist << "[" << i << "," << j << "]" << endl;
				int nx = N;

				for(int k = 0 ; k < M ; k++)
					id[k] = max(id[k], idx[k][j]);

				for(int k = 0 ; k < M ; k++)
					nx = min(id[k],nx);
				dist += A[nx-1] - (j?A[j-1]:0);
				//cout << j << "->" << nx << " " << N << endl;
				j = nx;
				//cout << i << " " << nx << endl;


			}
		}

	for( auto i : rnd ){
		en = clock();
		//cout << en << endl;
		if( 1.0 * (en - st) / CLOCKS_PER_SEC > 1.95  ) break;
		//cout << 1.0 * (en - st) / CLOCKS_PER_SEC  << endl;
		long long mx[200]={};
		int id[200]={};
		long long dist = 0;


		for(int j = i ; j < N ; ){

			for(int k = 0 ; k < M ; k++){	
				mx[k] = max(mx[k],B[j][k]);
			}
			long long sub = 0;
			for(int k = 0 ; k < M ; k++){	
				sub += mx[k];
			}
			ans = max(sub-dist,ans);
			//cout << sub << "|" <<  dist << "[" << i << "," << j << "]" << endl;
			int nx = N;

			for(int k = 0 ; k < M ; k++)
				id[k] = max(id[k], idx[k][j]);

			for(int k = 0 ; k < M ; k++)
				nx = min(id[k],nx);
			dist += A[nx-1] - (j?A[j-1]:0);
			//cout << j << "->" << nx << " " << N << endl;
			j = nx;
			//cout << i << " " << nx << endl;


		}
	}
	cout << ans << endl;
}

