        sum[i + 1] = sum[i] + a[i];
    }
    forn(i, n) forn(j, m) {
        scanf("%d", b[i] + j);
    }
    stBuild();
    solve(0, n - 1, 0, n - 1);
    cout << ans << endl;
    return 0;
}

