			l[j]=stk[top];  stk[++top]=j; 
		}
		top=0;
		for(int j=N;j>=1;j--){
			for(;top&&B[stk[top]][i]<B[j][i];--top);
			r[j]=top?stk[top]:N+1; stk[++top]=j;
		}
		for(int j=1;j<=N;j++){
			int x=l[j]+1,y=j,X=j,Y=r[j]-1;
		 	C[x][y]+=B[j][i]; C[X+1][Y+1]+=B[j][i];
		 	C[x][Y+1]-=B[j][i];
