int N, M, A[5010], B[5010][210];
int d[5010];
int t[5010][5010];

const int BT = 64 * 128 * 2;
struct segtree {
    int index;
    ll seg[BT];
    int mum;

    void init(int n, int ind)
    {
        index = ind;
        mum = 1;
        while (mum < n)
            mum <<= 1;
        for (int i = 0; i < mum * 2; i++)
            seg[i] = 0;
    }
    void add(int k, ll x)
    {
        k += mum - 1;
        seg[k] = x;
        while (k > 0) {
            k = (k - 1) / 2;
            //seg[k] = max(seg[k * 2 + 1], seg[k * 2 + 2]);
            if (B[seg[k * 2 + 1]][index] > B[seg[k * 2 + 2]][index]) {
                seg[k] = seg[k * 2 + 1];
            } else {
                seg[k] = seg[k * 2 + 2];
            }
        }
    }
    ll get(int a, int b, int k, int l, int r)
    {
        if (b <= l || r <= a)
            return 5000;
        if (a <= l && r <= b)
            return seg[k];
        else {
            ll vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
            //return max(vl, vr);
            if (B[vl][index] > B[vr][index]) {
                return vl;
            } else {
                return vr;
            }
        }
    }
    ll get(int a, int b)
    {
        return get(a, b, 0, 0, mum);
    }
};
