ll mx[N<<2],tag[N<<2];

void Push_down(int x)
{
	int lc=x<<1,rc=lc|1;
	tag[lc]+=tag[x];
	tag[rc]+=tag[x];
	mx[lc]+=tag[x];
	mx[rc]+=tag[x];
	tag[x]=0;	
}

void Modify(int x,int L,int R,int l,int r,int del)
{
	//cout<<x<<" "<<L<<" "<<R<<" "<<l<<" "<<r<<endl;
	if (L==l && R==r)
	{
		mx[x]+=del;
		tag[x]+=del;
		return;
	}
	Push_down(x);

	int Mid=(L+R)>>1,lc=x<<1,rc=lc|1;
	if (l<=Mid) Modify(lc,L,Mid,l,min(Mid,r),del);
	if (r> Mid) Modify(rc,Mid+1,R,max(l,Mid+1),r,del);
	mx[x]=max(mx[lc],mx[rc]);
}

ll Query(int x,int L,int R,int l,int r)
{
	if (L==l && R==r) return mx[x];

	int Mid=(L+R)>>1;
	if (r<=Mid) return Query(x<<1,L,Mid,l,r);
	if (l> Mid) return Query(x<<1|1,Mid+1,R,l,r);
	return max(Query(x<<1,L,Mid,l,Mid),Query(x<<1|1,Mid+1,R,Mid+1,r));
}

