struct STree {
  const static int maxn = (1 << 13);
  long long a[2 * maxn][2];
  int n;

  void build(int n_) {
    for (n = 1; n < n_; n <<= 1) ;
    assert(n <= maxn);
    for (int i = 1; i < 2 * n; ++i) {
      a[i][0] = a[i][1] = 0;
    }
  }

  long long get() const {
    return a[1][0];
  }

  void add(int v, int l, int r, int l0, int r0, long long toadd) {
    if (l0 >= r || l >= r0) {
      return;
    }

    if (l0 <= l && r <= r0) {
      a[v][0] += toadd;
      a[v][1] += toadd;
      return;
    }

    int m = (l + r) / 2;
    add(2 * v, l, m, l0, r0, toadd);
    add(2 * v + 1, m, r, l0, r0, toadd);

    a[v][0] = max(a[2 * v][0], a[2 * v + 1][0]) + a[v][1];
  }

  void add(int v, long long toadd) {
    //eprintf("add [%d..inf)  %lld\n", v, toadd);
    add(1, 0, n, v, n, toadd);
  }
} tree;

