void solve() {
  for (int i = 0; i < m; ++i) {
    st[i].clear();
  }
  tree.build(n);

  long long res = 0;
  for (int i = n - 1; i >= 0; --i) {
    for (int j = 0; j < m; ++j) {
      int last = 0;
      while (sz(st[j]) && b[j][st[j].back()] <= b[j][i]) {
        tree.add(st[j].back(), last - b[j][st[j].back()]);
        last = b[j][st[j].back()];
        st[j].pop_back();
      }
      if (sz(st[j])) {
        tree.add(st[j].back(), last - b[j][i]);
      }
      st[j].pb(i);
      tree.add(i, b[j][i]);
    }

    res = max(res, tree.get());
    if (i) {
      tree.add(i, -a[i - 1]);
    }
  }
  printf("%lld\n", res);
}

