using namespace std;
typedef long long ll;

const int MAXN = 5005;
const int MAXM = 205;
const int MX = 8192;

struct SEG {
	int d[MX*2];

	void upd(int x, int r) {
		for(x += MX; x; x >>= 1)
			if(d[x] < r) d[x] = r;
	}
	int get(int s, int e) {
		int r = 0; for(s += MX, e += MX; s <= e; s >>= 1, e >>= 1) {
			if(s&1) { if(r < d[s]) r = d[s]; s++; }
			if(~e&1) { if(r < d[e]) r = d[e]; e--; }
		}
		return r;
	}
} seg[MAXM];

int A[MAXN][MAXM];
ll B[MAXN];

ll Ans;
int N, M;

int mx[MAXM];
void f(int s, int e, int p, int q) {
	if(s > e || p > q) return;
	int m = (s+e) >> 1;
	ll sum = 0, hc = -1; int hi = -1;
	for(int j = 1; j <= M; j++)
		sum += (mx[j] = seg[j].get(m, p-1));
	for(int i = p; i <= q; i++) if(m <= i) {
		for(int j = 1; j <= M; j++) {
			if(A[i][j] <= mx[j]) continue;
			sum += -mx[j] + A[i][j];
			mx[j] = A[i][j];
		}
		ll ret = sum - B[i] + B[m];
		if(ret <= hc) continue;
		hc = ret; hi = i;
	}
	if(Ans < hc) Ans = hc;
	f(s, m-1, p, hi);
	f(m+1, e, hi, q);
}

int main() {
	ios::sync_with_stdio(false);

	cin >> N >> M;
	for(int i = 2; i <= N; i++) {
		cin >> B[i];
		B[i] += B[i-1];
	}
	for(int i = 1; i <= N; i++) {
		for(int j = 1; j <= M; j++) {
			cin >> A[i][j];
			seg[j].upd(i, A[i][j]);
		}
	}

	f(1, N, 1, N);
	cout << Ans << endl;
	return 0;
}

