ll n,m;
ll a[N],b[N][201];
ll p[N],rs,mx;

ll table[20][N * 4][201],cur;
ll numlog[N];

void build() {
    numlog[1] = 0;
    for (int i = 2; i <= n; i++)
        numlog[i] = numlog[i / 2] + 1;

    for (int i = 0; i <= numlog[n]; i++) {
        int curlen = 1 << i;
        for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= m; k ++) {
            if (i == 0) {
                table[i][j][k] = b[j][k];
                continue;
            }
            table[i][j][k] = max(table[i - 1][j][k], table[i - 1][j + curlen / 2][k]);
                }
        }
    }
}

int get(int l, int r,int k) {
    int curlog = numlog[r - l + 1];
    return max(table[curlog][l][k], table[curlog][r - (1 << curlog) + 1][k]);
}
ll calc (ll l,ll r) {
        ll res = 0;
        for (ll k = 1; k <= m; k ++) {
                res += get(l,r,k);
        }
        return res;
}
void compute(ll l,ll r,ll L,ll R) {
        if (l > r || L == -1 || R == -1)
                return;

        ll md = (l + r) >> 1;

        ll cur = -1;
        ll opt = -1;
        for (ll i = L; i <= min(md,R); i ++) {
                ll now = calc(i,md) - (p[md] - p[i]);
                if (now > cur)
                        cur = now,opt = i;
        }
        mx = max(mx,cur);

        compute(l,md - 1,L,opt);
        compute(md + 1,r,opt,R);
}
