inline void dfs(int l, int r, SparseTable<int>& sp)
{
    if(r <= l) return;
    P p = sp.query(l,r);
    dp[l][r] += p.fi, dp[l][p.se] -= p.fi, dp[p.se+1][r] -= p.fi, dp[p.se+1][p.se] += p.fi;
    dfs(l,p.se,sp), dfs(p.se+1,r,sp);
}

