LL tag[N << 1];
LL maxv[N << 1];
vector<pair<int, int> > st[M];

void push(int x) {
    if (tag[x]) {
        tag[2*x] += tag[x];
        maxv[2*x] += tag[x];
        tag[2*x+1] += tag[x];
        maxv[2*x+1] += tag[x];
        tag[x] = 0;
    }
}

void modify(int t, int l, int r, int a, int b, LL v)
{
    if (a <= l && r <= b) {
        tag[t] += v;
        maxv[t] += v;
        return;
    }
    if (b <= l || r <= a) return;
    push(t);
    int mid = (l + r) >> 1;
    modify(t << 1, l, mid, a, b, v);
    modify(t << 1 | 1, mid + 1, r, a, b, v);
    maxv[t] = max(maxv[t << 1], maxv[t << 1 | 1]);
}

LL query(int t, int l, int r, int a, int b)
{
    if (a <= l && r <= b) {
        return maxv[t];
    }
    if (b <= l || r <= a) return 0;
    push(t);
    int mid = (l + r) >> 1;
    return max(query(t << 1, l, mid, a, b), query(t << 1 | 1, mid + 1, r, a, b));
}

void solve()
{
