      {
            scanf("%lld", &pref[i]);
            pref[i] += pref[i - 1];
      }

      for(int i = 1; i <= n; i ++)
            for(int j = 1; j <= m; j ++)
                  scanf("%d", &a[i][j]);

      for(int i = 1; i <= m; i ++)
            build(i);

      dv(1, n, 1, n);

      cout << ans << endl;
}

#include <iostream>
