		inv[1]=fact[0]=factr[0]=1;
		for (int i=2;i<=NUM_;++i) inv[i] = inv[mo % i] * (mo - mo / i) % mo;
		for (int i=1;i<=NUM_;++i) fact[i]=fact[i-1]*i%mo, factr[i]=factr[i-1]*inv[i]%mo;
	}
	if(C_<0 || C_>N_) return 0;
	return factr[C_]*fact[N_]%mo*factr[N_-C_]%mo;
}

ll dfs(int a,int l) {
	int i;

	ll& ret=memo[a][l];
	if(ret) return ret;

	ret=0;
	if(l==0) {
		ret = 1;
	}
	else {
		if(a>B) return 0;
		ret += dfs(a+1,l);
		ll v=1;
		for(i=1;i<=D && a<=l;i++) {
			(v *= combi(l,a))%=mo;
			l-=a;
			(v *= inv[i])%=mo;

			if(i>=C && i<=D) {
				ret += v*dfs(a+1,l)%mo;
			}
		}
	}
	ret%=mo;
	return ret;

}

