template<typename T>
struct SegmentTree{
    const T INF = 1e18;
    int n, width;
    vector<T> dat;

    void init(int x){
        n = x;
        width = 1;
        while (width < n) width *= 2;
        dat.assign(2*width-1, -INF);
    }

    void update(int i, T x){
        i += width - 1;
        dat[i] = x;
        while (i > 0){
            i = (i - 1) / 2;
            dat[i] = max(dat[i*2+1], dat[i*2+2]);
        }
    }

    T query(int a, int b, int k, int l, int r){
        if (r <= a || b <= l) return -INF;
        if (a <= l && r <= b) return dat[k];
        T vl = query(a, b, k*2+1, l, (l+r)/2);
        T vr = query(a, b, k*2+2, (l+r)/2, r);
        return max(vl, vr);
    }

    // [l, r)
    T query(int l, int r){
        return query(l, r, 0, 0, width);
    }
};

int n, m;
VL s, ans;
vector<SegmentTree<ll> > seg;

ll score(int l, int r){
    if (r <= l) return -1;
    ll ret = - (s[r-1] - s[l]);
    REP(i,m) ret += seg[i].query(l, r);
    return ret;
}

void calc(int l, int r, int x, int y){
    y = min(y, n);
    // cout << l << " " << r << "   " << x << " " << y << endl;
    if (l == r) return;
    int m = (l + r) / 2;
    if (ans[m] != -1) return;
    ll ma = 0;
    int pos;
    FOR(i,x+1,y){
        ll sc = score(m, i);
        if (sc > ma){
            ma = sc;
            pos = i;
        }
    }
    ans[m] = ma;
    cout << m << " " << ma << endl;
    calc(l, m, x, pos + 1);
    calc(m, r, pos, y);
}

int main() {
    cin >> n >> m;
    VL a(n-1);
    REP(i,n-1) a[i] = lin();
    VVL b(n, VL(m));
    REP(i,n) REP(j,m) b[i][j] = lin();

    s.resize(n);
    REP(i,n-1) s[i+1] = s[i] + a[i];

    seg.resize(m);
    REP(i,m){
        seg[i].init(n);
        REP(j,n) seg[i].update(j, b[j][i]);
    }

    ans.assign(n, -1);

    calc(0, n, 0, n);

    cout << *max_element(ALL(ans)) << endl;

    return 0;
}

