void rmq()
{
    for (long j = 1; j <= m; j++)
    {
        for (long i = 1; i <= n; i++)
        {
            M[j][i][0] = b[i][j];
        }
    }

    for (long j = 1; j <= m; j++)
    {
        for (long k = 1; (1 << k) <= n; k++)
        {
            for (long i = 1; i + (1 << k) - 1 <= n; i++)
            {
                M[j][i][k] = max(M[j][i][k - 1], M[j][i + (1 << (k - 1))][k - 1]);
            }
        }
    }
}

long long get(long j, long u, long v)
{
    long k = log2(v - u + 1);
    return max(M[j][u][k], M[j][v - (1 << k) + 1][k]);
}

long long ans(long l, long r)
{
    long long re = 0;
    for (long i = 1; i <= m; i++) re += get(i, l, r);
    re -= (s[r - 1] - s[l - 1]);
    return re;
}

void sub()
{
    rmq();
    for (long i = 1; i <= n - 1; i++) s[i] = s[i - 1] + a[i];
    long long res = 0;
    long j = 1;
    for (long i = 2; i <= n; i++)
    {
        if (ans(1, i) >= ans(1, j)) j = i;
    }
    res = ans(1, j);
    long block = sqrt(n);
    for (long i = 2; i <= n; i++)
    {
        j = max(j, i);
        while (j < n && ans(i, j + 1) >= ans(i, j))
        {
            j++;
        }
        res = max(res, ans(i, j));
        if (done[i / block] == false)
        {
            done[i / block] = true;
            for (long k = i ; k <= n; k++)
            {
                if (ans(1, k) >= ans(1, j)) j = k;
            }
            res = max(res, ans(i, j));
        }
    }
    cout << res;
}

