ll dp[5010][5010];
SegTree<pair<ll,int>, 1 << 13> st;
void pre() {
	rep(j, 0, M) {
		rep(i, 0, N) st.update(i, { B[i][j], i });

		queue<pair<int, int>> que;
		que.push({ 0, N - 1 });
		while (!que.empty()) {
			auto p = que.front();
			que.pop();

			int l = p.first;
			int r = p.second;

			auto pp = st.getval(l, r);
			ll ma = pp.first;
			int c = pp.second;

			dp[l][l] += ma;
			dp[l][r + 1] -= ma;
			dp[r + 1][l] -= ma;
			dp[r + 1][r + 1] += ma;
			if (l < c) {
				dp[l][l] -= ma;
				dp[l][c] += ma;
				dp[c][l] += ma;
				dp[c][c] -= ma;
				que.push({ l, c - 1 });
			}

			if (c < r) {
				dp[c + 1][c + 1] -= ma;
				dp[c + 1][r + 1] += ma;
				dp[r + 1][c + 1] += ma;
				dp[r + 1][r + 1] -= ma;
				que.push({ c + 1, r });
			}
		}
	}

	rep(i, 0, N) rep(j, 1, N) dp[i][j] += dp[i][j - 1];
	rep(i, 0, N) rep(j, 1, N) dp[i][j] += dp[i - 1][j];
}
