		st.emplace(INT_MAX, 0);
		for(int i = 1; i <= n; i++) {
			while(st.top().first < b[i][j]) st.pop(); // cannot be <=, or else intersect
			l[i] = st.top().second + 1;
			st.emplace(b[i][j], i);
		}
		while(!st.empty()) st.pop();
		st.emplace(INT_MAX, n+1);
		for(int i = n; i >= 1; i--) {
			while(st.top().first < b[i][j]) st.pop();
			r[i] = st.top().second - 1;
			st.emplace(b[i][j], i);
		}
		for(int i = 1; i <= n; i++) add(l[i], i, i, r[i], b[i][j]);
	}
	for(int i = 1; i <= n; i++) for(int j = 1; j <= n; j++) dp[i][j] += dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1];
	for(int i = 1; i <= n; i++) {
		long long sum = 0;
		for(int j = i; j <= n; j++) {
			sum += a[j] * (j > i);
			ans = max(dp[i][j] - sum, ans);
		}
	}
	cout << ans;
}

