const ll MOD=1e9+7;
const int N=1<<13;
const ll INF=2e15;
struct NODE{
  ll mx;
  ll d;
  NODE(ll v=-INF):mx(v){
    d=0;
  }
};
//ostream& operator<<(ostream &os, NODE &t) { return os<<"("<<t.sum<<","<<t.x<<","<<t.d<<")";}
NODE seg[2*N+10];

inline void lazy_eval(int k,int a,int b){
  if(!seg[k].d) return;
  seg[k].mx+=seg[k].d;
  if(2*k<=2*N+5){
    (seg[2*k+1].d+=seg[k].d)%=MOD;
    (seg[2*k+2].d+=seg[k].d)%=MOD;
  }
  seg[k].d=0;
}

inline void update_node(int k){
  seg[k].mx=max(seg[2*k+1].mx,seg[2*k+2].mx);
}

void update(int l,int r,ll d,int k=0,int a=0,int b=N){
  //cout<<"update:"<<l<<","<<r<<","<<x<<","<<d<<","<<a<<","<<b<<endl;
  lazy_eval(k,a,b);
  if(b<=l || r<=a) return; 
  if(l<=a && b<=r){
    (seg[k].d+=d)%=MOD;
    lazy_eval(k,a,b);
    return;
  }	
  int m=(a+b)/2;
  update(l,r,d,2*k+1,a,m);
  update(l,r,d,2*k+2,m,b);
  update_node(k);
}

ll get(int l,int r,int k=0,int a=0,int b=N){
  lazy_eval(k,a,b);
  if(b<=l || r<=a)return -INF;
  if(l<=a && b<=r){return seg[k].mx;}

  int m=(a+b)/2;
  ll vl=get(l,r,2*k+1,a,m);
  ll vr=get(l,r,2*k+2,m,b);
  update_node(k);
  //cout<<a<<","<<b<<":"<<vl<<","<<vr<<endl;
  return max(vl,vr);
}

