const int MAXN = 5e3 + 5;

int b[MAXN][205], n, m;
long long a[MAXN], sum[MAXN][MAXN];
int l[MAXN];
int stack[MAXN], top;


int main() {
	scanf("%d%d", &n, &m);
	for(int i = 1; i <= n - 1; i++) scanf("%lld", &a[i]);
	for(int i = 1; i <= n; i++) for(int j = 1; j <= m; j++) scanf("%d", &b[i][j]);

	for(int j = 1; j <= m; j++) {
		top = 0;
		stack[top++] = 0;
		for(int i = 1; i <= n; i++) {
			while(top > 1 && b[stack[top - 1]][j] < b[i][j]) top--;
			l[i] = stack[top - 1];
			stack[top++] = i;
		}
		top = 0;
		stack[top++] = n + 1;
		for(int i = n; i >= 1; i--) {
			while(top > 1 && b[stack[top - 1]][j] < b[i][j]) top--;
			int r = stack[top - 1];
			sum[l[i] + 1][i] += b[i][j];
			sum[l[i] + 1][r] -= b[i][j];
			sum[i + 1][i] -= b[i][j];
			sum[i + 1][r] += b[i][j];
			stack[top++] = i;
		}
	}
	for(int i = 2; i <= n - 1; i++) a[i] += a[i - 1];
	long long ans = 0;
	for(int i = 1; i <= n; i++) for(int j = 1; j <= n; j++) {
		sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
		if(i <= j) {
			long long cur = a[j - 1] - a[i - 1];
			cur = sum[i][j] - cur;
			if(ans < cur) ans = cur;
		}
	}
	printf("%lld\n", ans);
	return 0;
}

