void update(Long val, Long x, Long y, Long xx, Long yy, Long n){
	if(((vis[x][y][xx]>>yy)&1ll) == 1) return;
	vis[x][y][xx] |= (1ll<<yy);
	precal[x][y] += val;
	for(Long i = 0; i < 2; i++){
		Long u = x + dx[i];
		Long v = y + dy[i];
		if(0 <= u && u < n && 0 <= v && v < n){
			update(val,u,v,xx,yy,n);
		}
	}
	return;
}

