            auto from = s.lower_bound(b[i][j].second);
            auto to = from;
            from--;
            dp[b[i][j].second+1][*to] += b[i][j].first;
            dp[*from+1][*to] -= b[i][j].first;
            dp[*from+1][b[i][j].second] += b[i][j].first;
            dp[b[i][j].second+1][b[i][j].second] -= b[i][j].first;
            s.insert(b[i][j].second);
