	{
		memset(tmp,0,sizeof(tmp));
		while (now<=tot&&op[now].x==i) tmp[op[now].l]+=op[now].c,tmp[op[now].r+1]-=op[now].c,now++;
		for (int j=1;j<=n;j++) tmp[j]+=tmp[j-1],s[j]+=tmp[j],ans=j<i?ans:max(ans,s[j]-dis[j]+dis[i]);
	}
	printf("%lld",ans);
