#include <bits/stdc++.h>
using namespace std;
#define LL long long
int n, m;
const int N = 11000;
const int M = 300;
LL A[N];
int B[N][M];
int top[M], sta[M][N];

int lb[N], rb[N], lc[N], rc[N], tot;
LL val[N], tag[N], ans;
void upd(int t)
{
    val[t] = max(val[lc[t]], val[rc[t]]);
}
void psdw(int t)
{
    tag[lc[t]] += tag[t];
    val[lc[t]] += tag[t];
    tag[rc[t]] += tag[t];
    val[rc[t]] += tag[t];
    tag[t] = 0;
}
int build(int l, int r)
{
    int t = ++ tot;
    lb[t] = l; rb[t] = r;
    if (l != r)
    {
        lc[t] = build(l, (l + r) / 2);
        rc[t] = build((l + r) / 2 + 1, r);
        upd(t);
    }
    else val[t] = A[l];
    return t;
}
void add(int t, int l, int r, int v)
{
    // if (t == 1) {cerr << l << " " << r << " " << v << endl;}
    if (l <= lb[t] && rb[t] <= r)
    {
        tag[t] += v; val[t] += v;
        return;
    }
    psdw(t);
    if (l <= rb[lc[t]]) add(lc[t], l, r, v);
    if (r >= lb[rc[t]]) add(rc[t], l, r, v);
    upd(t);
}
LL query(int t, int l, int r)
{
    if (l <= lb[t] && rb[t] <= r) return val[t];
    LL v = -1e18;
    psdw(t);
    if (l <= rb[lc[t]]) v = max(v, query(lc[t], l, r));
    if (r >= lb[rc[t]]) v = max(v, query(rc[t], l, r));
    return v;
}
int main()
{
    scanf("%d%d", &n, &m);
    for (int i = 2; i <= n; ++ i)
    {
        scanf("%lld", &A[i]);
        A[i] += A[i - 1];
    }
    for (int i = 1; i <= n; ++ i)
        for (int j = 1; j <= m; ++ j)
            scanf("%d", &B[i][j]);
    build(1, n);
    for (int i = 1; i <= n; ++ i)
    {
        for (int j = 1; j <= m; ++ j)
        {
            while (top[j] && B[i][j] >= B[sta[j][top[j]]][j])
            {
                add(1, sta[j][top[j] - 1] + 1, sta[j][top[j]], -B[sta[j][top[j]]][j]);
                top[j] --;
            }
            top[j] ++;
            sta[j][top[j]] = i;
            add(1, sta[j][top[j] - 1] + 1, sta[j][top[j]], B[sta[j][top[j]]][j]);
        }
        ans = max(ans, -A[i] + query(1, 1, i));
    }
    printf("%lld\n", ans);
}

