#define ll long long
#define maxn 5005
using namespace std;
int arr[maxn],brr[maxn][205];
int L[maxn][205];
ll seg[maxn<<2],tag[maxn<<2];
void push(int p,int lch,int rch) {
	seg[lch] += tag[p];		tag[lch] += tag[p];
	seg[rch] += tag[p];		tag[rch] += tag[p];
	tag[p] = 0;
}
void modify(int l,int r,int ql,int qr,int p,int add) {
	if(l == ql && r == qr) {
		seg[p] += add;
		tag[p] += add;
	}
	else {
		int mid = (l+r)>>1 , lch = p<<1 , rch = p<<1|1;
		push(p,lch,rch);
		if(qr <= mid)
			modify(l,mid,ql,qr,lch,add);
		else if(ql > mid)
			modify(mid+1,r,ql,qr,rch,add);
		else {
			modify(l,mid,ql,mid,lch,add);
			modify(mid+1,r,mid+1,qr,rch,add);
		}
		seg[p] = max(seg[lch],seg[rch]);
	}
}
ll query(int l,int r,int ql,int qr,int p) {
	if(l == ql && r == qr)
		return seg[p];
	else {
		int mid = (l+r)>>1 , lch = p<<1 , rch = p<<1|1;
		push(p,lch,rch);
		if(qr <= mid)
			return query(l,mid,ql,qr,lch);
		else if(ql > mid)
			return query(mid+1,r,ql,qr,rch);
		else
			return max(query(l,mid,ql,mid,lch),query(mid+1,r,mid+1,qr,rch));
	}
}
