			int now = brr[i][j] , k = i-1;
			for(;k>=1;k--) {
				if(brr[k][j] > now)		break;
				modify(1,n,L[k][j],k,1,now - brr[k][j]);
				k = L[k][j];
			}
			L[i][j] = k + 1;
			modify(1,n,i,i,1,now);
