LL blt(I t,I st=1,I ed=n,I id=1)
{
	if(st==ed)
		return tree[t][id]=b[t][st];
	I piv=(st+ed)>>1;
	return tree[t][id]=max(blt(t,st,piv,(id<<1)),blt(t,piv+1,ed,(id<<1)|1));
}
LL rmq(I t,I x0,I x1,I st=1,I ed=n,I id=1)
{
	if(st>x1||ed<x0)
		return 0;
	if(x0<=st&&ed<=x1)
		return tree[t][id];
	I piv=(st+ed)>>1;
	return max(rmq(t,x0,x1,st,piv,(id<<1)),rmq(t,x0,x1,piv+1,ed,(id<<1)|1));
}
