    for(int i = 1; i <= n; i++)
    {
        memset(mars, 0, sizeof(mars));
        for(int j = 1; j <= m; j++)
        {
            int last = i - 1;
            while(!st[j].empty() > 0 && ma[st[j].top()][j] < ma[i][j])
            {
                mars[st[j].top() + 1] += ma[i][j] - ma[last][j];
                mars[last + 1] -= ma[i][j] - ma[last][j];
                last = st[j].top();
                if(st[j].top() > 0)
                    st[j].pop();
                else
                    break;
            }
            st[j].push(i);
            v[i] += ma[i][j];
        }
        for(int j = 1; j <= i; j++)
        {
            mars[j] += mars[j - 1];
            v[j] += mars[j];
        }
        for(int i1 = 1; i1 <= i; i1++)
            ans = max(ans, v[i1] - (sp[i] - sp[i1]));
    }
