#define fto(i, l, r) for(int i = l; i <= r; ++i)
#define fdto(i, r, l) for(int i = r; i >= l; --i)

typedef long long ll;

const int MAXN = 5005;
const int MAXM = 205;
const int MAXK = 20;

int n, m, k, a[MAXN], b[MAXN][MAXM];
int st[MAXM][MAXK][MAXN];
ll x[MAXN], maxVal[MAXN];

int query(int j, int l, int r) {
    int level = log2(r-l+1);
    return max(st[j][level][l], st[j][level][r-(1<<level)+1]);
}

void solve(int l, int r, int kmin, int kmax) {
    if (l > r) return;

    int mid = (l+r)/2;
    int best = -1;

    fdto(i, min(kmax, mid), kmin) {
        ll val = 0;
        fto(j, 0, m-1)
            val += query(j, i, mid);
        val -= x[mid] - x[i];
        if (val >= maxVal[mid]) {
            maxVal[mid] = val;
            best = i;
        }
    }

//    printf("%d %lld %d\n", mid, maxVal[mid], best);

    solve(l, mid-1, kmin, best);
    solve(mid+1, r, best, kmax);
}

int main() {
    scanf("%d%d", &n, &m);
    fto(i, 1, n-1) scanf("%d", &a[i]);
    fto(i, 0, n-1)
        fto(j, 0, m-1) scanf("%d", &b[i][j]);

    x[0] = 0;
    fto(i, 1, n-1) x[i] = x[i-1] + a[i];

    k = log2(n);
    fto(j, 0, m-1) {
        fto(i, 0, n-1)
            st[j][0][i] = b[i][j];
        fto(level, 1, k) {
            int sz = 1<<level;
            fto(i, 0, n-sz)
                st[j][level][i] = max(st[j][level-1][i], st[j][level-1][i + sz/2]);
        }
    }

    solve(0, n-1, 0, n-1);

    //fto(i, 0, n-1) printf("%lld %d\n", maxVal[i], bestVal[i]);

    ll ans = 0;
    fto(i, 0, n-1)
        ans = max(ans, maxVal[i]);
    printf("%lld", ans);

    return 0;
}

