void calc_s()
{
	for(int i = 1; i <= n; i++)
		s[i][0] += s[i - 1][0];
	for(int j = 1; j <= n; j++)
		s[0][j] += s[0][j - 1];
	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= n; j++)
			s[i][j] = s[i - 1][j] + s[i][j - 1] - s[i - 1][j - 1] + s[i][j];
}

void calc(int *b)
{
	static int lef[MAXN], rig[MAXN];
	stack<int> sta1, sta2;
	for(int i = 1; i <= n; i++)
	{
		while(!sta1.empty() && b[sta1.top()] <= b[i])
			sta1.pop();
		lef[i] = sta1.empty() ? 0 : sta1.top();
		sta1.push(i);
	}
	for(int i = n; i >= 1; i--)
	{
		while(!sta2.empty() && b[sta2.top()] < b[i])
			sta2.pop();
		rig[i] = sta2.empty() ? n + 1 : sta2.top();
		sta2.push(i);
	}
	for(int i = 1; i <= n; i++)
		add(lef[i] + 1, i, i, rig[i] - 1, b[i]);
}

