    long long ans = 0;
    for(int j = 1; j <= m; ++ j) {
        st[j].push_back(make_pair(INF, -1));
    }

    for(int i = 1; i <= n; ++ i) {
        long long tmp = 0;
        for(int j = 1; j <= m; ++ j) {
            scanf("%d", a + j);
            tmp += a[j];
        }
        ans = max(ans, tmp);

        for(int j = 1; j <= m; ++ j) {
            while (a[j] >= st[j].back().first) {
                int r = st[j].back().second;
                int v = st[j].back().first;
                st[j].pop_back();
                int l = st[j].back().second;
                modify(1, 0, n, l, r, -v);
            }
            modify(1, 0, n, st[j].back().second, i, a[j]);
            st[j].push_back(make_pair(a[j], i));
        }

        if (i > 0) {
            modify(1, 0, n - 1, 0, i, -x[i - 1]);
        }
        ans = max(ans, query(1, 0, n - 1, 0, i));
    }
    cout << ans << endl;
}

