void buildSp(){
	for(int k = 1; k <= m; k++){
		for(int i = 1; i <= n; i++) sp[k][0][i] = b[i][k];

		for(int j = 1; j < 13; j++){
			for(int i = 1; i <= n; i++){
				if(i + (1 << (j - 1)) > n) break;
				sp[k][j][i] = max(sp[k][j - 1][i], sp[k][j - 1][i + (1 << (j - 1))]);
			}
		}
	}
}

int query(int k, int i, int j){
	int p = lg[j - i + 1];
	return max(sp[k][p][i], sp[k][p][j - (1 << p) + 1]);
}

void calc(int l, int r, int optL, int optR){
	if(l > r) return;
	int mid = (l + r) >> 1;
	int opt; long long val;
	opt = val = -1;

	for(int i = max(mid, optL); i <= optR; i++){
		long long tmp = 0;
		for(int j = 1; j <= m; j++) tmp += query(j, mid, i);

		tmp -= pref[i - 1] - pref[mid - 1];

		if(val < tmp){
			val = tmp, opt = i;
		}
	}

	ans = max(ans, val);
	calc(l, mid - 1, optL, opt);
	calc(mid + 1, r, opt, optR);
}

