  	  matrix[left[i][j]][right[i][j]+1]-=b[i][j];
  	  matrix[i+1][i]-=b[i][j];
  	  matrix[i+1][right[i][j]+1]+=b[i][j];
  	}
  }
  for(regi i=1;i<=n;++i){
  	for(regi j=1;j<=n;++j)
    	matrix[i][j]+=matrix[i][j-1];
    for(regi j=1;j<=n;++j)
    	matrix[i][j]+=matrix[i-1][j];
    for(regi r=1;r<=n;++r)
      max=std::max(max,matrix[i][r]-a[r]+a[i]);
  }
  printf("%lld\n",max);
