typedef long long ll;

const ll llinf = 1e18;

class segment_tree
{
  vector<ll> ST, lazy;
public:
  segment_tree(int n)
  {
    ST.assign(4 * n + 5, -llinf);
    lazy.assign(4 * n + 5, 0);
  }
#define lc id << 1
#define rc id << 1 | 1
  void dolazy(int id, int l, int r)
  {
    ST[id] += lazy[id];
    if (l != r){
      lazy[lc] += lazy[id];
      lazy[rc] += lazy[id];
    }
    lazy[id] = 0;
  }

  void update(int id, int l, int r, int L, int R, ll v)
  {
    dolazy(id, l, r);
    if (l > R || L > r || L > R) return;
    if (L <= l && r <= R){
      ST[id] += v;
      if (l != r){
        lazy[lc] += v;
        lazy[rc] += v;
      }
      return;
    }
    int mid = (l + r) / 2;
    update(lc, l, mid, L, R, v); update(rc, mid + 1, r, L, R, v);
    ST[id] = max(ST[lc], ST[rc]);
  }

  ll getmax(int id, int l, int r, int L, int R)
  {
    dolazy(id, l, r);
    if (l > R || L > r) return -llinf;
    if (L <= l && r <= R) return ST[id];
    int mid = (l + r) / 2;
    return max(getmax(lc, l, mid, L, R), getmax(rc, mid + 1, r, L, R));
  }
};

