class RangeAdd
{
private:
    vector<vector<long long> > data;
public:
    RangeAdd(int h, int w){
        data.assign(h+1, vector<long long>(w+1, 0));
    }
    void add(int y1, int x1, int y2, int x2, long long val){
        data[y1][x1] += val;
        data[y1][x2+1] -= val;
        data[y2+1][x1] -= val;
        data[y2+1][x2+1] += val;
    }
    void get(vector<vector<long long> >& ans){
        int h = data.size() - 1;
        int w = data[0].size() - 1;
        for(int y=0; y<h; ++y){
            for(int x=1; x<w; ++x)
                data[y][x] += data[y][x-1];
        }
        for(int y=1; y<h; ++y){
            for(int x=0; x<w; ++x){
                data[y][x] += data[y-1][x];
            }
        }
        ans.swap(data);
        data.clear();
    }
};

