ll getmax(ll *T, ll l, ll r)
{
	ll ret = 0;

	for(l+=sz, r+=sz; l<=r; ){
		if(l & 1) ret = max(ret, T[l]);
		if(~r & 1) ret = max(ret, T[r]);
		l = l + 1 >> 1;
		r = r - 1 >> 1;
	}

	return ret;
}

ll cost(ll l, ll r)
{
	ll i, s;

	s = A[l] - A[r];

	for(i=1; i<=k; i++){
		s += getmax(B[i], l, r);
	}

	return s;
}

void dnc(ll s, ll e, ll l, ll r)
{
	if(s > e) return;

	ll m, i, v, x, t;

	m = s + e >> 1;
	v = -1e18; x = l;

	for(i=l; i<=r && i<=m; i++){
		t = cost(i, m);
		if(t > v) v = t, x = i;
	}

	ans = max(ans, v);

	dnc(s, m - 1, l, x);
	dnc(m + 1, e, x, r);
}

