template <typename T>
struct SparseTable
{
    using F = function<T(T, T)>;

    int n;
    int l;
    vector<vector<T>> dat;
    vector<int> d;

    const F f;
    const T e;

    SparseTable(int n, const F f, const T e) : n(n), f(f), e(e){
        dat.resize(n);
        d.resize(n + 1);
        int j = 0;
        for(l = 0; l <= n; l++){
            while(j <= n && j < (1 << l)){
                d[j] = l;
                j++;
            }
            if((1 << l) > n){
                for(int i = 0; i < n; i++){
                    dat[i].resize(l);
                }
                break;
            }
        }
    }

    void set(int i, T x){
        dat[i][0] = x;
    }

    void build(){
        for(int j = 1; j < l; j++){
            for(int i = 0; i <= n - (1 << j); i++){
                dat[i][j] = f(dat[i][j - 1], dat[i + (1 << (j - 1))][j - 1]);
            }
        }
    }

    T query(int l, int r){
        if(r <= l) return e;
        return f(dat[l][d[r - l] - 1], dat[r - (1 << (d[r - l] - 1))][d[r - l] - 1]);
    }
};

void MonotoneMaxima(int a, int b, int l, int r, vector<SparseTable<ll>> &sp, ll *s, ll *d, int m){
    if(a == b) return;
    int c = (a + b) / 2;
    int arg = -1;
    for(int i = max(l, c); i < r; i++){
        ll t = 0;
        for(int j = 0; j < m; j++){
            t += sp[j].query(c, i + 1);
        }
        cout << c << " " << i << "    " << t << endl;
        if(arg == -1 || t - s[i] + s[c] > d[c]){
            arg = i;
            d[c] = t - s[i] + s[c];
        }
    }
    cout << endl;
    cout << c << " " << arg << " " << d[c] << endl;
    MonotoneMaxima(a, c, l, arg + 1, sp, s, d, m);
    MonotoneMaxima(c + 1, b, arg, r, sp, s, d, m);
}

