typedef long long int lli;

const int N = 5005;
const int logN = 13;
const int M = 205;
int n, m;

lli a[N];
lli b[N][M];
lli dp[N][N];
lli sparseT[N][logN];

void buildSparseT() {
	//Set the values in sparseT[*][0] beforehand
	for(int j = 1; j < logN; j++) {
		for(int i = 0; i + (1 << j) <= N; i++) {
			sparseT[i][j] = max(sparseT[i][j-1], sparseT[i + (1 << (j-1))][j-1]);
		}
	}
}

lli getMax(int l, int r) { //[l, r)
	if(l == r-1) return sparseT[l][0];
	else {
		int powe = (int)(log2(r-l)+0.00001);
		return max(sparseT[l][powe], sparseT[r-(1 << powe)][powe]);
	}
}

int main() {
	ios_base::sync_with_stdio(false);

	cin >> n >> m;
	a[0]=0;
	for(int i = 1; i < n; i++) cin >> a[i];
	for(int i = 1; i < n; i++) a[i] += a[i-1];
	for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) {
		cin >> b[i][j];
	}

	for(int i = 0; i < n; i++) for(int j = 0; j < n; j++) {
		dp[i][j] = 0;
	}

	for(int mi = 0; mi < m; mi++) {
		int val = -1;
		for(int i = 0; i < n; i++) {
			sparseT[i][0] = b[i][mi];
		}
		buildSparseT();
		for(int i = 0; i < n; i++) {
			int leftHigh, rightHigh;
			int low = 0;
			int high = i-1;
			//Get Left High (number first left of b[i][-] that is >= to it).
			if(i == 0 || getMax(0, i) < b[i][mi]) {
				leftHigh = -1;
			} else {
				while(high - low > 1) {
					int mid = (low+high)/2;
					int val = getMax(mid, i);

					if(val >= b[i][mi]) {
						low = mid;
					} else {
						high = mid;
					}
				}
				if(getMax(high, i) >= b[i][mi]) leftHigh = high;
				else leftHigh = low;
			}


			//Get Right High (number first right of b[i][-] that is > than it).
			low = i+1;
			high = n-1;
			if(i == n-1 || getMax(i+1, n) <= b[i][mi]) {
				rightHigh = n;
			} else { 
				while(high - low > 1) {
					int mid = (low+high)/2;
					int val = getMax(i+1, mid+1); //+1 to include the upper bound
					if(val > b[i][mi]) {
						high = mid;
					} else {
						low = mid;
					}
				}
				if(getMax(i+1, low+1) > b[i][mi]) rightHigh = low;
				else rightHigh = high;
			}

			//Apologies for the confusing i/j index inconsistencies
			dp[i][i] += b[i][mi];
			if(leftHigh != -1) dp[leftHigh][i] -= b[i][mi];
			if(rightHigh != n) dp[i][rightHigh] -= b[i][mi];
			if(leftHigh != -1 && rightHigh != n) dp[leftHigh][rightHigh] += b[i][mi];
		}
	}

	for(int i = n-1; i >= 0; i--) {
		for(int j = 0; j < n; j++) {
			if(i == n-1) dp[i][j] = dp[i][j] + dp[i][j-1];
			else if(j == 0) dp[i][j] = dp[i][j] + dp[i+1][j];
			else dp[i][j] = dp[i][j] + dp[i][j-1] + dp[i+1][j] - dp[i+1][j-1];
		}
	}
	for(int i = 0; i < n; i++) for(int j = i; j < n; j++) dp[i][j] -= (a[j]-a[i]);

	lli ans = 0;
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < n; j++) {
			ans = max(ans, dp[i][j]);
		}
	}

	cout << ans << endl;

	return 0;
}

