using namespace std;

int n, m, LOG[5010];
long long a[5010], b[5010][210], d[5010];
long long rmq[210][5010][15], res;

long long get_max(int i, int L, int R)
{
    int log = LOG[R - L + 1];
    return max(rmq[i][L][log], rmq[i][R - (1 << log) + 1][log]);
}

long long cost(int L, int R)
{
//    assert(L <= R);
    long long ans = 0;
    for (int i = 1; i <= m; ++i) ans += get_max(i, L, R);
    return ans + d[L] - d[R];
}

void divide(int L, int R, int from, int to)
{
    if (L > R) return;
    int mid = L + R >> 1;
    long long maxval = - 1e18, best = 0;
    for (int i = from; i <= min(mid, to); ++i)
        if (maxval < cost(i, mid)) maxval = cost(i, mid), best = i;
    res = max(res, maxval);
    divide(L, mid - 1, from, best);
    divide(mid + 1, R, best, to);

}

