    ans = vel(n,-1);
    ind = vel(n);
    vel sum(n, 0);
    rep(i, n - 1) { int a; cin >> a; sum[i + 1] = sum[i] + a; }
    vvel b(n, vel(m));
    rep(i, n) {
        rep(j, m) { cin >> b[i][j]; }
    }
    int k = 1;
    int i = 0;
    while (i < n - 1) {
        sol1(sum, b, i);
        if (i >= k) {
            sol_ran(sum, b, i - k, i);
        }
        i += k;
    }
    sol1(sum, b, n - 1);
    sol_ran(sum, b, i - k, n - 1);
    int ret = 0;
    rep(i, n) { mmax(ret, ans[i]); }
    cout << ret << endl;
    return 0;
}

