inline void solve(int * a) {
	const auto max = [&](int x,int y) {
		return a[x] > a[y] ? x : y;
	};
	const auto rgmx = [&](int x,int y) {
		const int lg = std::__lg(y - x + 1);
		return max(st[lg][x], st[lg][y - (1 << lg) + 1]);
	};
	std::function<void(int, int)> solve = [&](int l,int r) {
		if(l > r) return ;
		int o = rgmx(l, r);
		solve(l, o - 1);
		solve(o + 1, r);
		add(l, o, o, r, a[o]);
	};
	rep(i, 1, n) st[0][i] = i;
	rep(i, 1, 14) for(int j = 1;j + (1 << i) - 1 <= n;++j) {
		st[i][j] = max(st[i - 1][j], st[i - 1][j + (1 << i - 1)]);
	}
	solve(1, n);
}
