struct Stack {
	int data[maxn], cur;
	int top() { return data[cur - 1]; }
	int upper() { return data[cur]; }
	void pop() { cur--; }
	void push(int val) { data[cur++] = val; }
	bool empty() { return cur == 0; }
} stack[maxm];
void update(int u, int v, int val) {
	sum[u] += val;
	sum[v + 1] -= val;
}
