template<typename T>
struct sum2d{
	int n,m;
	ll mod;
	vector<vector<T>>sum;
	bool flag=false;

	sum2d(){}
	sum2d(int n,int m,ll mod=-1)
		:n(n),m(m),mod(mod),sum(vector<vector<T>>(n+2,vector<T>(m+2))){}

	void add(int x,int y,T t){
		assert(!flag);
		x++;y++;
		sum[x][y]+=t;
	}

	void add(int x1,int y1,int x2,int y2,T t){
		assert(!flag);
		x1++;y1++;x2++;y2++;
		sum[x1][y1]+=t;
		sum[x1][y2+1]-=t;
		sum[x2+1][y1]-=t;
		sum[x2+1][y2+1]+=t;
		if(mod!=-1){
			sum[x1][y1]%=mod;
			(sum[x1][y2+1]+=mod)%=mod;
			(sum[x2+1][y1]+=mod)%=mod;
			sum[x2+1][y2+1]%=mod;
		}
	}

	void calc(){
		flag=true;
		rep(i,n+1)for(int j=1;j<=m;j++){
			sum[i][j]+=sum[i][j-1];
			if(mod!=-1)sum[i][j]%=mod;
		}
		rep(i,m+1)for(int j=1;j<=n;j++){
			sum[j][i]+=sum[j-1][i];
			if(mod!=-1)sum[j][i]%=mod;
		}
	}

	T get(int x1,int y1,int x2,int y2){
		if(!flag)calc();
		x1++;y1++;x2++;y2++;
		T res=sum[x2][y2]-sum[x1-1][y2]-sum[x2][y1-1]+sum[x1-1][y1-1];
		if(mod!=-1){
			while(res<0)res+=mod;
			res%=mod;
		}
		return res;
	}

	T get(int x,int y){
		return get(x,y,x,y);
	}

	T imos(int x,int y){
		if(!flag)calc();
		x++;y++;
		return sum[x][y];
	}
};
