}
void update(int k,int x){
	k+=N-1;
	dat[k].first=x;
	while(k){
		k=(k-1)/2;
		dat[k]=max(dat[k*2+1],dat[k*2+2]);
	}
}
P query(int a,int b,int k=0,int l=0,int r=N){
	if(b<=l||r<=a)return P(0,0);
	if(a<=l&&r<=b)return dat[k];
	P lb=query(a,b,k*2+1,l,(l+r)/2);
	P rb=query(a,b,k*2+2,(l+r)/2,r);
	return max(lb,rb);
}


