template <typename T, class Operator>
struct SegTree
{
	vector<T> tree;
	Operator op;
	T def;
	int s;
	void init(int size, T val, Operator opr)
	{
		s=size;
		op=opr;
		tree.clear();
		tree.resize(4*size,val);
		def=val;
	}

	void add(int pos, T value)
	{
		add(pos,value,0,s,0);
	}

	// [low, hi) は全体の範囲
	void add(int pos, T value, int low, int hi, int i)
	{
		while(1)
		{
			tree[i]=op(tree[i],value);
			if(low+1<hi){
				int mid=(low+hi)/2;
				if(pos<mid){
					i=2*i+1;
					hi=mid;
				}
				else
				{
					i=2*i+2;
					low=mid;
				}
			}
			else
			{
				break;
			}
		}
	}

	// [a,b) を取得
	T get(int a, int b)
	{
		return get(a,b,0,s,0);
	}

	T get(int a, int b, int low, int hi, int i)
	{
		if(hi<=a||b<=low||hi<=low){
			return def;
		}
		if(a<=low&&hi<=b){
			return tree[i];
		}
		int mid=(low+hi)/2;
		return op(get(a,b,low,mid,2*i+1),get(a,b,mid,hi,2*i+2));
	}

	// 補助関数
	bool check(int a, int b, int low, int hi, int i, int v)
	{
		if(hi<=a||b<=low||hi<=low){
			return true;
		}
		if(a<=low&&hi<=b){
			return tree[i]%v==0;
		}
		int mid=(low+hi)/2;
		return check(a,b,low,mid,2*i+1,v)&&check(a,b,mid,hi,2*i+2,v);
	}
};

template<class T>
struct Max
{
	T operator()(T a, T b){
		return max(a,b);
	}
};
const int L=5002;
LL A[L];
int B[L][200];
LL table[L][L];
SegTree<P,Max<P> > tree;

void search(int s,int e){
	if(s>=e)return;
	P p=tree.get(s,e);
	table[s][p.second]+=p.first;
	table[s][e]-=p.first;
	table[p.second+1][p.second]-=p.first;
	table[p.second+1][e]+=p.first;
	search(s,p.second);
	search(p.second+1,e);
}
int main() {
