	}
	for(int i=1;i<=N;i++){
		for(int j=1;j<=N;j++){
			table[i][j]+=table[i][j-1];
		}
	}
	for(int i=1;i<=N;i++){
		for(int j=1;j<=N;j++){
			table[i][j]+=table[i-1][j];
		}
	}
