void pushDown(int id, int l, int r){
	if(lz[id] != 0){
		st[id] += lz[id];
		if(l < r){
			lz[id << 1] += lz[id];
			lz[id << 1 | 1] += lz[id];
		}
		lz[id] = 0;
	}
}
void update(int id, int l, int r, int i, int j, ll x){
	pushDown(id, l, r);
	if(l > j || r < i || i > j){
		return;
	}
	if(l >= i & r <= j){
		lz[id] += x;
		pushDown(id, l, r);
		return;
	}
	int mid = (l + r) >> 1;
	update(id << 1, l, mid, i, j, x);
	update(id << 1 | 1, mid + 1, r, i, j, x);
	st[id] = max(st[id << 1], st[id << 1 | 1]);
}
ll get(int id, int l, int r, int i, int j){
	pushDown(id, l, r);
	if(l > j || r < i || i > j){
		return -INF;
	}
	if(l >= i && r <= j){
		return st[id];
	}
	int mid = (l + r) >> 1;
	return max(get(id << 1, l, mid, i, j), get(id << 1 | 1, mid + 1, r, i, j));
}

