ll ans[N];

ll query(int l,int r,int x)
{
    int y = logn[r-l+1];
    return max(dp[l][y][x],dp[r+1-(1<<y)][y][x]);
}

void go_(int l,int r,int optl,int optr)
{
    if(l>r)
        return ;
    int mid = (l+r)/2;
    pll p = {-INF,-INF};
    for(int i=optl;i<=min(mid,optr);++i)
    {
        ll u = 0;
        for(int j=1;j<=m;++j)
            u += query(i,mid,j);
        amax(p,make_pair(u-A[mid]+A[i],(ll)-i));
    }
    // cout<<mid<<" ";
    // cout<<p<<"\n";
    ans[mid] = p.F;
    go_(l,mid-1,optl,-p.S);
    go_(mid+1,r,-p.S,optr);
}

