void calc(int l,int r,int bl,int br){
	if(l > r)return;
	int mid = (l + r)/2,bst = bl,best;
	long long temp = 0,temp1 = 0;
	for(;bst <= mid;bst++){
		temp1 = find(bst,mid) - cs[mid - 1] + cs[bst - 1];
		if(temp < temp1)temp = temp1,best = bst;
	}
	ans = max(ans,temp);
	calc(l,mid - 1,bl,best);
	calc(mid + 1,r,best,br);
}
