  REP(i,m) p[i] = 0;
  REP(i,m) ans += b[i][0];

  REP(ii,n-1) {
    const int i = ii + 1;

    REP(j,m) {
      if(b[i][j] >= b[p[j]][j]) {
        p[j] = i;
