      }
    }

    int s = i;
    REP(j,m) s = min(s, p[j]);

    bool adv = true;
    while(adv) {
      adv = false;

      int next = i;

      ll diff = 0;
      REP(j,m) if(p[j] == s) {
        if(pq[j].empty()) {
          next = min(next, s);
        } else {
          auto f = pq[j].top();
