inline void flesh(int t, int l, int r) {
	xds[t] += laz[t];
	if(l < r) {
		laz[t << 1] += laz[t];
		laz[t << 1 | 1] += laz[t];
	}
	laz[t] = 0;
}
void add(int u, int v, int w, int t, int l, int r) {
	flesh(t, l, r);
	if(u <= l and r <= v) {
		laz[t] += w;
	} else {
		const int x = (l + r) >> 1;
		flesh(t << 1, l, x), flesh(t << 1 | 1, x + 1, r);
		if(u <= x) add(u, v, w, t << 1, l, x);
		if(v > x) add(u, v, w, t << 1 | 1, x + 1, r);
		xds[t] = max(xds[t << 1], xds[t << 1 | 1]);
	}
	flesh(t, l, r);
}
int sol(int u, int v, int t, int l, int r) {
	flesh(t, l, r);
	if(u <= l and r <= v) {
		return xds[t];
	} else {
		int a = -1000000000000LL;
		const int x = (l + r) >> 1;
		if(u <= x) a = max(a, sol(u, v, t << 1, l, x));
		if(v > x) a = max(a, sol(u, v, t << 1 | 1, x + 1, r));
		return a;
	}
}
