void get_nxt() {
    rep (i, 1, n) {
        top = 0;
        per (j, n, 1) {
            while(top && d[i][st[top]] <= d[i][j]) top--;
            nxt[i][j] = ((!st[top]) ? n + 1 : st[top]);
            st[++top] = j;
        }
    }
}

ll get_add(int i, int j) {return d[i][pos[i][j]] - d[i][pos[i][j - 1]];}
void chmin(ll &x, ll y) {x = (x > y ? y : x);}
void chmax(ll &x, ll y) {x = (x < y ? y : x);}

void update_sta(int status) {
    rep(i, 1, m) {
        while(pos[i][cur[i]] < status) cur[i]++;
        if(pos[i][cur[i]] == status) {
            add[status] += d[i][pos[i][cur[i] - 1]];
            continue;
        }

        int tmp = cur[i], nowp = pos[i][tmp];
        add[nowp] -= get_add(i, tmp);

        top = 0; st[++top] = status;
        for(int now = nxt[i][status]; now < nowp; )
            st[++top] = now, now = nxt[i][now];
        while(top) pos[i][--cur[i]] = st[top--];

        d[i][pos[i][cur[i] - 1]] = 0;
        for(int j = cur[i]; j <= tmp; j++)
            add[pos[i][j]] += get_add(i, j);
    }
}

