    n = read(); m = read();
    for(int i = 1; i < n; i++) A[i] = (ll)read();
    rep(i, 1, n)
        rep(j, 1, m)
            d[j][i] = (ll)read();
    rep(i, 1, m) pos[i].clear();
    rep(i, 1, m)
        for(int j = 1; j <= n; j++)
            pos[i].push_back(0);
    ans = 0; get_nxt();
    rep(i, 1, m) {
        pos[i].push_back(1);
