        for(int j = 2; j <= n; j++)
            if(d[i][j] > d[i][pos[i][cur[i]]])
                pos[i].push_back(j), cur[i]++;
        pos[i].push_back(n + 1);
        for(int j = n + 1; j <= cur[i]; j++)
            add[pos[i][j]] += get_add(i, j);
        cur[i] = n;
    }
}

