    for (; x>0; x-=-x&x) {
        for (int y=_y; y>0; y-=-y&y) {
            ret += bit[x][y];
        }
    }
    return ret;
}

void add (int x, int _y, int val) {
    for (; x<MAXN; x+=-x&x) {
        for (int y=_y; y<MAXN; y+=-y&y) {
            bit[x][y] += val;
        }
    }
}

void add (int xl, int xr, int yl, int yr, int val) {
    xl++, xr++, yl++, yr++;
    add(xl, yl, val);
    add(xr+1, yl, -val);
    add(xl, yr+1, -val);
    add(xr+1, yr+1, val);
}

void build_seg () {
