int qrymx (int l, int r) {
    int mx =  0;
    for (l+=n, r+=n; l<r; l>>=1, r>>=1) {
        if (l&1) {
            mx = max(mx, seg[l++]);
        }
        if (r&1) {
            mx = max(mx, seg[--r]);
        }
    }
    return mx;
}

int search_l (int id, int val) {
    int l = -1, r = id;
    while (l < r - 1) {
        int mid = (l + r) >> 1;
        if (qrymx(mid, id) >= val) {
            l = mid;
        } else {
            r = mid;
        }
    }
    return l+1;
}

int search_r (int id, int val) {
    int l = id, r = n;
    while (l < r - 1) {
        int mid = (l + r) >> 1;
        if (qrymx(id+1, mid+1) > val) {
            r = mid;
        } else {
            l = mid;
        }
    }
    return r-1;
}
