	for(int L = 0; L < n; L++)
	{
		LL ans = 0;
		for(int j = 0; j < m; j++)
		{
			opt[j] = b[L][j];
			ans += opt[j];
		}	
		best = max(best,ans);

		LL dist = 0;
		for(int R = L+1; R < n; R++) //improve [L,R-1] by including the Rth restaurant
		{
			for(int j = 0; j < m; j++)
				if(opt[j] < b[R][j]) //new opportunity to spend a ticket here
				{
					ans += b[R][j]-opt[j];
					opt[j] = b[R][j];
				}
			dist += a[R-1];
			best = max(best,ans-dist);
		}
	}
	return best;
}
