const int N = 5005, M = 202, LG = 14;
int n, m, B[M][N], Log[N];
long long Mx, A[N], dp[N][N];
pair < int , int > MX[LG][N];
inline int RMQ(int l, int r)
{
    int &lg = Log[r - l];
    return (max(MX[lg][l], MX[lg][r - (1 << lg)]).second);
}
void Solve(int l, int r)
{
    if (r < l) return ;
    int i = RMQ(l, r + 1);
    dp[l][i] += MX[0][i].first;
    dp[i + 1][i] -= MX[0][i].first;
    dp[l][r + 1] -= MX[0][i].first;
    dp[i + 1][r + 1] += MX[0][i].first;
    Solve(l, i - 1); Solve(i + 1, r);
}
int main()
{
    scanf("%d%d", &n, &m);
    for (int i = 2; i <= n; i++)
        scanf("%d", &A[i]), A[i] += A[i - 1];
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            scanf("%d", &B[j][i]);
    for (int i = 2; i < N; i++)
        Log[i] = Log[i >> 1] + 1;
    for (int j = 1; j <= m; j++)
    {
        for (int i = 1; i <= n; i++)
            MX[0][i] = {B[j][i], i};
        for (int h = 1; h < LG; h++)
            for (int i = 1; i + (1 << h) <= n + 1; i++)
                MX[h][i] = max(MX[h - 1][i], MX[h - 1][i + (1 << h - 1)]);
        Solve(1, n);
    }
    for (int i = 1; i < N; i++)
        for (int j = 1; j < N; j++)
            dp[i][j] += dp[i - 1][j] + dp[i][j - 1] - dp[i - 1][j - 1];
    for (int i = 1; i <= n; i++)
        for (int j = i; j <= n; j++)
            Mx = max(Mx, dp[i][j] - A[j] + A[i]);
