const int N = 5010, M = 210, LOG = 12;
const ll inf = -1e18;
ll d[N], best[N];
int rmq[M][N][LOG+2], val[M], a[N][M], logm[N];
int n, m;

void pre_rmq(int n){
    int i, j, t;
    for(i = 1;i <= m; i++)
        for(j = 1; j <= n; j++)
            rmq[i][j][0] = a[j][i];
    for(i = 2; i <= n; i++)
        logm[i] = logm[i>>1] + 1;
    for(t = 0; t < LOG; t++){
        for(i = 1;i <= m; i++)
            for(j = 1; j + (1<<(t + 1)) - 1 <= n; j++)
                rmq[i][j][t+1] = max(rmq[i][j][t], rmq[i][j+(1<<t)][t]);
    }
}

void refresh(int x, int y){
    int p = logm[y - x + 1], i;
    for(i = 1;i <= m; i++)
        val[i] = max(rmq[i][x][p], rmq[i][y - (1<<p) + 1][p]);
}

void solve(int l, int r, int optL, int optR){
    if(l > r)
        return;
    int mid = (l + r) >> 1;
    int opt = mid;
    if(optL > mid)
        refresh(mid, optL - 1);
    else
        rep(i, 1, m + 1)
            val[i] = 0;
    ll act = 0;
    rep(i, 1, m + 1)
        act += val[i];
    best[mid] = inf;
    for(int i = max(optL, mid); i <= optR; i++){
        rep(j, 1, m + 1){
            if(a[i][j] > val[j]){
                act += a[i][j] - val[j];
                val[j] = a[i][j];
            }
        }
        if(act - d[i] > best[mid])
            best[mid] = act - d[i], opt = i;
    }
    best[mid] += d[mid];
    solve(l, mid - 1, optL, opt);
    solve(mid + 1, r, opt, optR);
}

int main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);
    cin >> n >> m;
    for(int i = 2; i <= n; i++)
        cin >> d[i], d[i] += d[i-1];
    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= m; j++)
            cin >> a[i][j];
    pre_rmq(n);
    solve(1, n, 1, n);
    ll ans = 0;
    rep(i, 1, n + 1)
        ans = max(ans, best[i]);
    cout << ans << endl;
    return 0;
}

