int bst[M];
int nxt[N][M];
int v[N][M];
int sz[N];
int main(){
    scanf("%d %d" , &n , &m);
    for(int i = 1 ; i < n ; ++i){
        scanf("%d" , a + i);
    }
    for(int i = 1 ; i <= n ; ++i){
        for(int j = 1 ; j <= m ; ++j){
            scanf("%d" , &b[i][j]);
        }
    }
    for(int j = 1 ; j <= m ; ++j){
        stack < int > s;
        while(!s.empty()){
            s.pop();
        }
        for(int i = n ; i >= 1 ; --i){
            while(!s.empty() && b[s.top()][j] <= b[i][j]){
                s.pop();
            }
            if(s.empty()){
                nxt[i][j] = n + 1;
            }
            else{
                nxt[i][j] = s.top();
            }
            s.push(i);
        }
    }
    ans = 0;
    for(int i = 1 ; i <= n ; ++i){
        long long sum = 0;
        for(int j = i ; j <= n ; ++j){
            sz[j] = 0;
        }
        for(int j = 1 ; j <= m ; ++j){
            bst[j] = b[i][j];
            sum += bst[j];
            if(nxt[i][j] <= n){
                v[nxt[i][j]][sz[nxt[i][j]]++] = j;
            }
        }
        ans = max(ans , sum);
        long long dist = 0;
        for(int r = i + 1 ; r <= n ; ++r){
            dist += a[r - 1];
            for(int j = 0 ; j < sz[r] ; ++j){
                int idx = v[r][j];
                sum -= bst[idx];
                bst[idx] = b[r][idx];
                sum += bst[idx];
                int nx = nxt[r][idx];
                if(nx <= n){
                    v[nx][sz[nx]++] = idx;
                }
            }
            ans = max(ans , sum - dist);
        }
    }
    printf("%lld\n" , ans);
}

