        sum[i] += a[i];
    }
    deque<int> que[m];
    ll ans = 0;
    int now = n-1;

    drep(i,n){
        // cout << endl;
        rep(j,m){
            while(que[j].size()>0 && b[i][j] >= b[que[j][0]][j]){
                que[j].pop_front();
            }
            int r = n;
            if(que[j].size()>0){
                r = que[j][0];
            }
            update_(i,r-1,b[i][j],0,0,nn-1,j);
            que[j].push_front(i);
        }

        while(i<now){
            ll bef = -(sum[now] - sum[i]);
            rep(j,m){
                bef += query_(now,now,0,0,nn-1,j);
                // cout << query_(now,now,0,0,nn-1,j) << ' ';
