ll ans;

void solve(int l,int r,int lx,int rx) {
  if (l>r) return;
  int m=((l+r)>>1),id=0;
  ll now=-inf;
  for(int i=lx;i<=min(rx,m);i++) {
  	ll s=calc(i,m);
  	if (s>now) {
  		now=s;id=i;
	  }
  }
  ans=max(ans,now);
  solve(l,m-1,lx,id);
  solve(m+1,r,id,rx);
}

