struct Node{    
    ll value;
    ll lazy;
};

Node T[N * 4 + 512];

void push(int node, int cl, int cr){
    T[node].value += T[node].lazy;
    if(cl != cr){
        T[node * 2].lazy += T[node].lazy;
        T[node * 2 + 1].lazy += T[node].lazy;
    }
    T[node].lazy = 0;
}

int n;
void update(int node, int cl, int cr, int tl, int tr, ll fy){   
    push(node, cl, cr);
    if(cr < tl)
        return;
    if(cl > tr)
        return;
    if(cl >= tl && cr <= tr){
        T[node].lazy = fy;
        push(node, cl, cr);
        return;
    }
    int mid = (cl + cr) / 2;
    update(node * 2, cl, mid, tl, tr, fy);
    update(node * 2 + 1, mid + 1, cr, tl, tr, fy);
    T[node].value = max(T[node * 2].value, T[node * 2 + 1].value);
}
void upd(int l, int r, ll d){
    update(1, 1, n, l, r, d);
}

