int power(int a,int b,int m = MOD){
	if(b == 0) return 1;
	if(b == 1) return a;
	int x = power(a,b/2,m)%m;
	x = (x*x)%m;
	if(b%2) return (x*a)%m;
	return x;
}
ll n, m, arr[N], cost[N][N];
ll dp[N][N], prevmax[N][N];
void dnc(ll row, ll s, ll e, ll l, ll r)
{
	if(s>e)
		return;
	ll mid=(s+e)/2;
	ll opt=-1;
	dp[row][mid]=-1e18;
	for(ll a=max(l, mid+1); a<=r; a++)
	{
		ll newcost=dp[row+1][a]+cost[a][row]+arr[mid-1]-arr[a-1];
		if(newcost>dp[row][mid])
		{
			dp[row][mid]=newcost;
			opt=a;
		}
	}
	if(dp[row+1][mid]+prevmax[mid+1][row]>dp[row][mid])
	{
		dp[row][mid]=dp[row+1][mid]+prevmax[mid][row];
		opt=-1;
	}
	if(opt==-1)
	{
		dnc(row, s, mid-1, l, r);
		dnc(row, mid+1, e, l, r);
	}
	else
	{
		dnc(row, s, mid-1, l, opt);
		dnc(row, mid+1, e, opt, r);
	}
