template<typename V> class segtree{
private:
    int n,sz; vector<V> node, lazy;
public:
    segtree(vector<V>& v){
        sz = (int)v.size(); n = 1;
        while(n < sz) n *= 2;
        node.resize(2*n-1); lazy.resize(2*n-1, 0);
        rep(i,sz) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1],node[i*2+2]);
    }
    void eval(int k, int l, int r){
        if(lazy[k] != 0) {
            node[k] += lazy[k];
            if(r - l > 1) {
                lazy[2*k+1] += lazy[k]; lazy[2*k+2] += lazy[k];
            }
            lazy[k] = 0;
        }
    }
    void range(int a, int b, V x, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b){
            lazy[k] += x; eval(k, l, r);
        }else{
            range(a, b, x, 2*k+1, l, (l+r)/2); range(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1],node[2*k+2]);
        }
    }
    V query(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return numeric_limits<V>::max();
        if(a <= l && r <= b) return node[k];
        V vl = query(a, b, 2*k+1, l, (l+r)/2), vr = query(a, b, 2*k+2, (l+r)/2, r);
        return min(vl,vr);
    }
    void print(){rep(i,sz)cout<<query(i,i+1)<< " ";cout<<endl;}
};


int main(){
    int n,m;
    cin >> n >> m;
    vector<segtree<ll> >segs;
    vector<ll> a(n-1);
    vector<ll>s(n-1);
    for(int i=0;i<n-1;i++){
        cin >> a[i];
        s[i+1] = s[i] + a[i];
    }
    vector<vector<ll> > b(n,vector<ll>(m));
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            cin >> b[i][j];
        }
    }
    for(int i=0;i<m;i++){
        vector<ll> c(n);
        for(int j=0;j<n;j++){
            c[j] = -b[j][i];
        }
        segtree<ll> seg(c);
        segs.push_back(seg); 
    }
    int x = 0,y=1;
    ll ma = -1;
    while(1){
        //cout << x << " " << y << " " << ma << endl;
        if(x==y-1){
            ll tmp = 0;
            rep(i,m){
                tmp += segs[i].query(x,y);
            }
            ma = max(ma,-tmp-s[y-1]+s[x]);
            //cout << ma << endl;
            if(x==n-1){
                break;
            }
            y++;
        }else{
            ll tmp = 0;
            rep(i,m){
                tmp += segs[i].query(x,y);
            }
            ma = max(ma,-tmp-s[y-1]+s[x]);

            if(y==n){
                x++;
            }else{
                tmp = 0;
                ll tmp2 = 0;
                rep(i,m){
                    tmp += segs[i].query(x+1,y);
                }
                rep(i,m){
                    tmp2 += segs[i].query(x,y+1);
                }
                if(-tmp2-s[y-1]+s[x+1]>=-tmp-s[y]+s[x]){
                    y++;
                }else{
                    x++;
                }
            }
        }
    }
    cout << ma << endl;
    return 0;
}

