const int MAXN = 5e3 + 1, MAXM = 201;

int n, m;
ll a[MAXN], b[MAXM][MAXN];

int s[MAXN], top = 0;
ll mat[MAXN][MAXN], w[MAXN];
int L[MAXM][MAXN], R[MAXM][MAXN];

inline void Modify(int i, int j) {
    mat[L[i][j]][j] += b[i][j];
    mat[j + 1][R[i][j] + 1] += b[i][j];
    mat[L[i][j]][R[i][j] + 1] -= b[i][j];
    mat[j + 1][j] -= b[i][j]; 
}

void Calc() {
    for (int i = 1; i <= m; ++i) {
        top = 0;
        for (int j = 1; j <= n; ++j) {
            while (top and w[top] < b[i][j])
                --top;
            L[i][j] = top ? s[top] + 1 : 1;
            s[++top] = j; w[top] = b[i][j];
        }
        top = 0;
        for (int j = n; j; --j) {
            while (top and w[top] < b[i][j])
                --top;
            R[i][j] = top ? s[top] - 1 : n;
            s[++top] = j; w[top] = b[i][j];
        }
        for (int j = 1; j <= n; ++j) 
            Modify(i, j);
    }
}

main() {
    scanf("%lld%lld", &n, &m);
    for (int i = 2; i <= n; ++i) {
        int x;
        scanf("%lld", &x);
        a[i] = a[i - 1] + x;
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            scanf("%lld", &b[j][i]);

	Calc();

    ll ans = 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j)
            mat[i][j] += mat[i - 1][j] + mat[i][j - 1] - mat[i - 1][j - 1];
        for (int j = i; j <= n; ++j)
            ans = std::max(ans, mat[i][j] - a[j] + a[i]);
    }

    printf("%lld\n", ans);

    return 0;
}

