int n, M, powers[5005];
ll dist[5005], arr[5005][205], ans[5005], best_coupon[202], sparse[202][20][5005];

ll rmq(int j, int l, int r){
    int k = powers[r-l+1];
    return max(sparse[j][k][l], sparse[j][k][r-(1<<k)+1]);
}


void DnC(int l, int r, int optima_l, int optima_r){

    if(l > r)   return;

    int mid = (l+r)/2, optima_mid = -1;
    ans[mid] = -(ll)1e16;

    for(int j=1;j<=M;j++)
        best_coupon[j] = rmq(j, mid, max(optima_l, mid));

// cout<<"now at "<<l<<" "<<r<<" "<<optima_l<<" "<<optima_r<<endl;
// cout<<"best_coupon: ";for(int j=1;j<=M;j++) cout<<best_coupon[j]<<" ";cout<<endl;

    for(int k=max(optima_l, mid);k<=optima_r;k++){

        ll temp = -(dist[k]-dist[mid]);
        for(int j=1;j<=M;j++){
            best_coupon[j] = max(best_coupon[j], arr[k][j]);
            temp += best_coupon[j];
        }

        if(temp > ans[mid]){
            ans[mid] = temp;
            optima_mid = k;
        }
    }

// cout<<"for "<<l<<" "<<r<<" "<<optima_l<<" "<<optima_r<<" found "<<mid<<" "<<optima_mid<<endl;

    DnC(l, mid-1, optima_l, optima_mid);
    DnC(mid+1, r, optima_mid, optima_r);
}



