inline void modify(int i,int l,int r,int k,int t) {
	if (l==r) mx[i]=t;
	else {
		int mid=(l+r)>>1;
		k<=mid?modify(lc,l,mid,k,t):modify(rc,mid+1,r,k,t);
		mx[i]=max(mx[lc],mx[rc]);
	}
