inline void add(int i,int l,int r,int L,int R,int t) {
	if (L<=l&&r<=R) add(i,t);
	else {
		int mid=(l+r)>>1;
		pushdown(i);
		if (L<=mid) add(lc,l,mid,L,R,t);
		if (mid<R) add(rc,mid+1,r,L,R,t);
		mx[i]=max(mx[lc],mx[rc]);
	}
