void dfs(int x,int l,int r) {
    if(l > r) return;
    int p = Query(x,l,r);
    sum[l][p] += B[p][x];
    sum[l][r + 1] -= B[p][x];
    sum[p + 1][p] -= B[p][x];
    sum[p + 1][r + 1] += B[p][x];
    dfs(x,l,p - 1);dfs(x,p + 1,r);
}
