			dp[s][e] = dp[s][e - 1];
		for (int i = 1; i <= m; i++) {
			// add col[i] and update
			last = 0;
			sum[e] += b[e][i];
			while (st[i].size() && b[st[i].top()][i] < b[e][i]) {
				sum[st[i].top()] += last;
				last = b[st[i].top()][i];
				sum[st[i].top()] -= last;
				st[i].pop();
			}
			if (st[i].size()) {
				sum[st[i].top()] -= b[e][i];
				sum[st[i].top()] += last;
			}
			st[i].push(e);
		}
		// update from sum
		for (int s = e; s >= 1; s--) {
			sum[s] += sum[s + 1];
			dp[s][e] += sum[s];
		}
	}
	// ans
	ll ans = 0;
	for (int i = 1; i <= n; i++) {
		ll f = 0;
		for (int t = i; t <= n; t++) {
			ans = max(ans, dp[i][t] - f);
			f += a[t];
		}
	}
	cout << ans << "\n";
}

