void solve(int l, int r, int x) {
	P opt = seg[x].query(l, r + 1);
	imos[opt.second][l] += opt.first;
	if (opt.second + 1 < N) imos[opt.second][opt.second + 1] -= opt.first;
	if (r + 1 < N) {
		imos[r + 1][l] -= opt.first;
		imos[r + 1][opt.second + 1] += opt.first;
	}
	if (l < opt.second) solve(l, opt.second - 1, x);
	if (opt.second < r) solve(opt.second + 1, r, x);
}
