llong seg[1 << 14];
llong add[1 << 14];

void lazy(int i) {
    seg[i << 1 | 0] += add[i];
    add[i << 1 | 0] += add[i];
    seg[i << 1 | 1] += add[i];
    add[i << 1 | 1] += add[i];
    add[i] = 0;
}

void update(int i, int s, int e, int x, int y, llong v) {
    if (e < x || y < s) return;
    if (x <= s && e <= y) {
        seg[i] += v;
        add[i] += v;
        return;
    }
    lazy(i);
    int m = (s + e) / 2;
    update(i << 1, s, m, x, y, v);
    update(i << 1 | 1, m + 1, e, x, y, v);
    seg[i] = max(seg[i << 1], seg[i << 1 | 1]);
}

llong query(int i, int s, int e, int x, int y) {
    if (e < x || y < s) return -inf;
    if (x <= s && e <= y) return seg[i];
    int m = (s + e) / 2;
    return max(query(i << 1, s, m, x, y), 
        query(i << 1 | 1, m + 1, e, x, y)) + add[i];
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    cin >> n >> m;
    for (int i = 1; i <= m; ++i)
        st[i].emplace_back(n + 1, inf);
    for (int i = 2; i <= n; ++i) {
        cin >> A[i];
        A[i] += A[i - 1];
