    for (int i = n; i > 0; --i) {
        for (int j = 1; j <= m; ++j) {
            int v = B[i][j];
            while (st[j].back().second <= v) {
                llong pi, pv, ni, nv;
                tie(pi, pv) = st[j].back();
                st[j].pop_back();
                tie(ni, nv) = st[j].back();
                update(1, 1, n, pi, ni - 1, -pv);
            }
            llong idx, val;
            tie(idx, val) = st[j].back();
            st[j].emplace_back(i, v);
            update(1, 1, n, i, idx - 1, v);
        }
        ans = max(ans, query(1, 1, n, i, n) + A[i]);
    }
    printf("%lld\n", ans);
    return 0;
}

