node comb (node aa,node bb) {
        if (aa.mx < bb.mx)
                swap(aa,bb);
        else if (aa.mx == bb.mx && aa.id > bb.id)
                swap(aa,bb);
        return aa;
}
void build (int v = 1,int tl = 1,int tr = n) {
        if (tl == tr) {
                for (int i = 1; i <= m; i ++) {
                        t[v][i].mx = b[tl][i];
                        t[v][i].id = tl;
                }
        }
        else {
                int tm = (tl + tr) >> 1;
                build (v * 2,tl,tm);
                build (v * 2 + 1,tm + 1,tr);
                for (int i = 1; i <= m; i ++) {
                        t[v][i] = comb(t[v * 2][i],t[v * 2 + 1][i]);
                }
        }
}
node get (int l,int r,int x,int v = 1,int tl = 1,int tr = n) {
        if (l > r)
                return cur;
        if (tl == l && tr == r)
                return t[v][x];

        int tm = (tl + tr) >> 1;
        return comb(get(l,min(r,tm),x,v * 2,tl,tm),get(max(l,tm + 1),r,x,v * 2 + 1,tm + 1,tr));
}
ll calc (ll l,ll r) {
        ll res = 0;
        for (ll k = 1; k <= m; k ++) {
                res += get(l,r,k).mx;
