    for (int k = 1; k < LG; ++k) {
        for (int i = 1; i + (1 << k) - 1 <= n; ++i) {
            int left = rmq[ticket][i][k - 1];
            int right = rmq[ticket][i + (1 << (k - 1))][k - 1];
            rmq[ticket][i][k] =
                (b[left][ticket] < b[right][ticket] ? right : left);
        }
    }
