const int N = (int) 5005, M = 205, mod = (int) 0;
int prof[N][M], pt[M], s[N], cur[N], cmx[M], mx[N][M];
int seg[N << 2], ch[N << 2];

void build(int v, int b, int e) {
    seg[v] = ch[v] = 0;
    if (e - b == 1) {
        return;
    }
    int m = b + e >> 1, l = v << 1, r = l | 1;
    build(l, b, m);
    build(r, m, e);
}


void update(int i, int j, int x, int v, int b, int e) {
    if (i >= e || b >= j) return;
    if (i <= b && e <= j) {
        ch[v] += x;
        seg[v] += x;
        return;
    }
    int m = b + e >> 1, l = v << 1, r = l | 1;
    update(i, j, x, l, b, m);
    update(i, j, x, r, m, e);
    seg[v] = max(seg[l], seg[r]) + ch[v];
}

int n, m;
int solve(int l, int r) {
    if (r - l == 1) {
        int res = 0;
        for (int j = 0; j < m; ++j)
            res += prof[l][j];
        return res;
    }
    int mid = l + r >> 1;
    int res = 0;
    res = max(res, solve(l, mid));
    res = max(res, solve(mid, r));
    for (int j = 0; j < m; ++j) {
        mx[mid - 1][j] = prof[mid - 1][j];
        pt[j] = mid - 1;
    }
    for (int j = mid - 2; j >= l; --j) {
        for (int i = 0; i < m; ++i) {
            mx[j][i] = max(mx[j + 1][i], prof[j][i]);
        }
    }
    build(1, l, mid);
    for (int j = l; j < mid; ++j) {
        cur[j] = s[j];
        for (int i = 0; i < m; ++i)
            cur[j] += mx[j][i];
        update(j, j + 1, cur[j], 1, l, mid);
    }
    memset(cmx, 0, sizeof cmx);

    for (int j = mid; j < r; ++j) {
        for (int i = 0; i < m; ++i) {
            if (prof[j][i] > cmx[i])
                update(pt[i] + 1, mid, prof[j][i] - cmx[i], 1, l, mid);
            cmx[i] = max(cmx[i], prof[j][i]);
            while (pt[i] >= l && cmx[i] >= mx[pt[i]][i]) {
                update(pt[i], pt[i] + 1, cmx[i] - mx[pt[i]][i], 1, l, mid);
                pt[i]--;
            }
        }
        res = max(res, -s[j] + seg[1]);
    }
    return res;
}

