template <class T>
struct SparseTable {
    int N;

    vector<vector<T>> table;
    vector<int> logs;

    T op(T a, T b) {
        return max(a, b);
    }

    void ComputeLogs(int N) {
        logs.resize(N + 1);
        logs[0] = logs[1] = 0;
        for (int i = 2; i <= N; i++) {
            logs[i] = logs[i / 2] + 1;
        }
    }

    void BuildSparseTable(const vector<T>& A) {
        N = A.size();
        ComputeLogs(N);

        table = vector<vector<T>> (logs[N] + 1, vector<T>(N));

        for (int i = 0; i <= logs[N]; i++) {
            int curLen = 1 << i; // 2^i
            for (int j = 0; j + curLen <= N; j++) {
                if (curLen == 1) {
                    table[i][j] = A[j];
                } else {
                    table[i][j] = op(table[i - 1][j], table[i - 1][j + (curLen / 2)]);
                }
            }
        }
    }

    int GetOp(int l, int r) {
        if (l > r)
            swap(l, r);
        int p = logs[r - l + 1];
        int pLen = 1 << p; // 2^p
        return op(table[p][l], table[p][r - pLen + 1]);
    }
};

// Memory
SparseTable<int> RMQ[200];

int64 GetDist(int i, int j) {
    if (i < j)
        swap (i, j);
    return pref[i] - pref[j];
}

int64 calc(int l, int r, int optl, int optr) {
    if (l > r)
        return 0;

    int m = (l + r) >> 1;

    int64 bst = -1;
    int bsto = -1;

    //debug() << l << " " << r << ": " << optl << " " << optr;

    for (int o = optl; o <= optr; o++) {
        int64 cur = -GetDist(o, m);
        for (int i = 0; i < M; i++) {
            cur += RMQ[i].GetOp(o, m);
        }

        if (cur > bst) {
            bst = cur;
            bsto = o;
        }
    }

    if (bsto == -1)
        return 0;

    return max(bst, max(calc(l, m - 1, optl, bsto), calc(m + 1, r, bsto, optr)));
}

