    REP(b, N + 1) REP(a, N) m[a + 1][b] += m[a][b];

    //debug(m);

    vec sumA(N);
    sumA[0] = 0;
    REP(i, N - 1) sumA[i + 1] = sumA[i] + A[i];

    int ans = 0;
    REP(a, N){
        FOR(b, a, N){
            ans = max(ans, m[a][b] - sumA[b] + sumA[a]);
        }
    }

    cout << ans;

    return 0;
}

