#define llint long long
#define inf 1e18

using namespace std;
typedef pair<llint, llint> P;

struct SegTree{
	llint size;
	vector<P> seg;

	SegTree(){}
	SegTree(llint size){
		this->size = size;
		seg.resize(1<<(size+1));
	}

	void init()
	{
		for(llint i = 0; i < (1<<(size+1)); i++) seg[i] = make_pair(-inf, -inf);
	}

	void update(llint i, P val)
	{
		i += (1 << size);
		seg[i] = val;
		while(i > 1){
			i /= 2;
			seg[i] = max(seg[i*2], seg[i*2+1]);
		}
	}

	P query(llint a, llint b, llint k, llint l, llint r)
	{
		if(b < l || r < a) return make_pair(-inf, -inf);
		if(a <= l && r <= b) return seg[k];
		P lval = query(a, b, k*2, l, (l+r)/2);
		P rval = query(a, b, k*2+1, (l+r)/2+1, r);
		return max(lval, rval);
	}
	P query(llint a, llint b)
	{
		return query(a, b, 1, 0, (1<<size)-1);
	}
};

llint N, M;
llint A[5005];
llint sumA[5005];
llint cost[5005][5005];
SegTree seg[205];

void calc(llint m, llint l, llint r)
{
	if(l > r) return;

	P opt = seg[m].query(l, r);
	cost[l][opt.second] += opt.first;
	cost[opt.second+1][r+1] += opt.first;
	cost[l][r+1] -= opt.first;
	cost[opt.second+1][opt.second] -= opt.first;

	calc(m, l, opt.second-1);
	calc(m, opt.second+1, r);
}

int main(void)
{
	cin >> N >> M;
	for(int i = 1; i <= N-1; i++) cin >> A[i];
	for(int i = 1; i <= N-1; i++) sumA[i] = sumA[i-1] + A[i];

	for(int i = 1; i <= M; i++) seg[i] = SegTree(13);
	for(int i = 1; i <= N; i++){
		for(int j = 1; j <= M; j++){
			int B;
			cin >> B;
			seg[j].update(i, make_pair(B, i));
		}
	}

	for(int i = 1; i <= M; i++){
		calc(i, 1, N);
	}


	for(int i = 1; i <= N; i++){
		llint sum = 0;
		for(int j = 1; j <= N; j++){
			sum += cost[i][j];
			cost[i][j] = sum + cost[i-1][j];
		}
	}

	llint ans = -inf;
	for(int i = 1; i <= N; i++){
		for(int j = 1; j <= N; j++){
			if(i > j) continue;
			ans = max(ans, cost[i][j] - (sumA[j-1] - sumA[i-1]));
		}
	}
	cout << ans << endl;

	return 0;
}

