int n, m;
int a[5000];
LL sum[5000];
int b[5000][200];
int st[13][5000][200];
int lg[5001];

void stBuild() {
    int cur = 0;
    for (int i = 1; i <= 5000; ++i) {
        while ((2 << cur) < i) {
            ++cur;
        }
        lg[i] = cur;
    }
    forn(i, n) forn(j, m) {
        st[0][i][j] = b[i][j];
    }
    forn(i, 12) {
        forn(j, n - (2 << i) + 1) forn(k, m) {
            st[i + 1][j][k] = max(st[i][j][k], st[i][j + (1 << i)][k]);
        }
    }
}

int stGet(int from, int to, int pos) {
    int len = lg[to - from + 1];
    return max(st[len][from][pos], st[len][to - (1 << len) + 1][pos]);
}

LL ans = 0;

void solve(int from, int to, int lo, int hi) {
    if (from > to) {
        return;
    }
    int mid = (from + to) >> 1;
    lo = max(lo, mid);
    int bb[m];
    LL cur = 0;
    forn(i, m) {
        bb[i] = stGet(mid, lo, i);
        cur += bb[i];
    }
    cur -= sum[lo] - sum[mid];
    LL best = cur;
    int bestInd = lo;
    for (int ind = lo + 1; ind <= hi; ++ind) {
        forn(i, m) {
            if (b[ind][i] > bb[i]) {
                cur += b[ind][i] - bb[i];
                bb[i] = b[ind][i];
            }
        }
        cur -= a[ind - 1];
        if (cur > best) {
            best = cur;
            bestInd = ind;
        }
    }
    ans = max(ans, best);
    solve(from, mid - 1, lo, bestInd);
    solve(mid + 1, to, bestInd, hi);
}

