  int getmax(int l, int r) {
    int d = log2[r-l];
    return std::max(max[d][l], max[d][r-(1<<d)]);
  }
} rmq[MAXM];

int N, M;
long long A[MAXN];
int B[MAXN][MAXM];

int top;
data st[MAXN];

long long getans(int l, int r) {
  int i;
  long long res(-(A[r]-A[l]));
  for (i=0; i<M; ++i) {
    res += rmq[i].getmax(l, r+1);
  }
  return res;
}

void exec() {
  int i, j;
  long long ans(0);
  int l, r, mid;
  scanf("%d%d", &N, &M);
  for (i=1; i<N; ++i) {
    scanf("%lld", &A[i]);
    A[i] += A[i-1];
  }
  for (i=0; i<N; ++i)
    for (j=0; j<M; ++j)
      scanf("%d", &B[j][i]);
  for (j=0; j<M; ++j)
    rmq[j].exec(B[j], N);
  for (i=0; i<N; ++i) {
    while (top && st[top-1].r >= i) {
      l = std::max(st[top-1].l, i);
      if (getans(i, l) >= getans(st[top-1].x, l))
  	--top;
      else {
  	r = st[top-1].r;
  	while (l+1 < r) {
  	  mid = l + (r-l) / 2;
  	  (getans(i, mid) >= getans(st[top-1].x, mid)? r : l) = mid;
  	}
  	st[top-1].r = l+1;
  	if (r != st[top-1].r)
  	  st[top] = data(r, st[top-1].r, i), ++top;
  	break;
      }
    }
    if (top == 0)
      st[top++] = data(0, N, i);
    for (j=0; j<top; ++j)
      if (st[j].l <= i && i < st[j].r)
  	ans = std::max(ans, getans(st[j].x, i));
  }
  printf("%lld\n", ans);
}

