void calc_s()
{
	for(int i = 1; i <= n; i++)
		s[i][0] += s[i - 1][0];
	for(int j = 1; j <= n; j++)
		s[0][j] += s[0][j - 1];
	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= n; j++)
			s[i][j] = s[i - 1][j] + s[i][j - 1] - s[i - 1][j - 1] + s[i][j];
}

