}

void calc(int *b)
{
	static int lef[MAXN], rig[MAXN];
	stack<int> sta1, sta2;
	for(int i = 1; i <= n; i++)
	{
		while(!sta1.empty() && b[sta1.top()] <= b[i])
			sta1.pop();
		lef[i] = sta1.empty() ? 0 : sta1.top();
		sta1.push(i);
	}
	for(int i = n; i >= 1; i--)
	{
		while(!sta2.empty() && b[sta2.top()] < b[i])
			sta2.pop();
		rig[i] = sta2.empty() ? n + 1 : sta2.top();
		sta2.push(i);
	}
	for(int i = 1; i <= n; i++)
		add(lef[i] + 1, i, i, rig[i] - 1, b[i]);
}

