struct Tournament {
  static const int off = 1 << 13;

  struct Node {
    llint p, v;
    void add(llint x) { p += x; v += x; }
  };

  Node tree[off << 1];

  Tournament() {
    memset(tree, 0, sizeof tree);
  }

  void prop(int i) {
    tree[2 * i].add(tree[i].p);
    tree[2 * i + 1].add(tree[i].p);
    tree[i].p = 0;
  }

  void merge(int i) {
    tree[i].v = max(tree[2 * i].v, tree[2 * i + 1].v);
  }

  void build(int i = 1) {
    if (i >= off) return;
    build(2 * i);
    build(2 * i + 1);
    merge(i);
  }

  void add(int l, int r, llint v, int lo = 0, int hi = off, int i = 1) {
    if (lo >= r || hi <= l) return;
    if (lo >= l && hi <= r) {
      tree[i].add(v);
      return;
    }

    prop(i);
    add(l, r, v, lo, (lo + hi) / 2, 2 * i);
    add(l, r, v, (lo + hi) / 2, hi, 2 * i + 1);
    merge(i);
  }

  llint getmax() { return tree[1].v; }
} t;

