void izracunaj(int lo, int hi, int optL, int optR){
	if (lo > hi)
		return;
	int mid = (lo + hi) / 2;
	int opt = -1;
	dp[mid] = -INFL;

	for (int i = optL; i <= min(mid, optR); ++i){
		if (rmq::query(i, mid + 1) - c[i][mid] > dp[mid]){
			dp[mid] = rmq::query(i, mid + 1) - c[i][mid];
			opt = i;
		}
	}

	izracunaj(lo, mid - 1, optL, opt);
	izracunaj(mid + 1, hi, opt, optR);
}

