void solve(int l, int r,int i){
  ll most = 0;
   int opt = 0;
  if(l == r)return;

  for(int j = l; j < r; j++){
    if(most < intable[j][i]){
      opt = j;
      most = intable[j][i];
    }
  }

  table[l][opt] = table[l][opt] + most;
  table[l][r] = table[l][r] - most;
  table[opt+1][opt] = table[opt+1][opt] - most;
  table[opt+1][r] = table[opt+1][r] + most;
  solve(l,opt,i);
  solve(opt+1,r,i);
  return;
}

