int getst(int d,int l,int r){
    int k=nlg[r-l+1];
    return max(st[d][l][k],st[d][r-(1<<k)+1][k]);
}
void solve(int l,int r,int pl,int pr){
    if(l>r)return ;
    int mid=l+r>>1,p=0;
    for(int i=pl;i<=min(mid,pr);i++){
        LL res=sum[i]-sum[mid];
        for(int j=1;j<=m;j++)
        res+=getst(j,i,mid);
        if(res>ans[mid])
        ans[mid]=res,p=i;
    }
    solve(l,mid-1,pl,p);
    solve(mid+1,r,p,pr);
}
