void add(int i1, int i2, int j1, int j2, int x) {
	for (int i = i1; i < i2; i++) {
		for (int j = j1; j < j2; j++) {
			val[i][j] += x;
		}
	}
} 

void resolve() {
	cerr << "resolved" << endl;
}

void apply(vector<int> a) {
	vector<int> l(n);
	vector<int> r(n);
	{
		vector<int> st;
		for (int i = 0; i < n; i++) {
			while (!st.empty() && a[st.back()] <= a[i]) {
				st.pop_back();
			}
			if (st.empty()) {
				l[i] = -1;
			} else {
				l[i] = st.back();
			}
			st.push_back(i);
		}
	}
	{
		vector<int> st;
		for (int i = n - 1; i >= 0; i--) {
			while (!st.empty() && a[st.back()] < a[i]) {
				st.pop_back();
			}
			if (st.empty()) {
				r[i] = n;
			} else {
				r[i] = st.back();
			}
			st.push_back(i);
		}
	}
	for (int i = 0; i < n; i++) {
		add(l[i] + 1, i + 1, i, r[i], a[i]);
	}
}

