		apply(a[i]);
	}
	resolve();
	int ans = -INF;
	for (int i = 0; i < n; i++) {
		int cs = 0;
		for (int j = i; j < n; j++) {
			ans = max(ans, val[i][j] - cs);
			if (j + 1 < n) {
				cs += cost[j];
			}
		}
	}
	// cerr << val[0][n - 1] << endl;
	cout << ans << endl;
}

