#define mp make_pair

const int N = (int)5e3 + 10;
const int M = 204;
int n, m;
ll a[N];
ll d[N];
ll b[N][M];
ll ans = 0;
vector<pil> c[M];

int main()
{
//    freopen("input.txt", "r", stdin);

    scanf("%d%d", &n, &m);
    for (int i = 1; i < n; i++)
    {
        scanf("%lld", &d[i]);
        a[i] = -d[i];
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            scanf("%lld", &b[i][j]);
    for (int l = n - 1; l >= 0; l--)
    {
        for (int i = 0; i < m; i++)
        {
            a[l] += b[l][i];
            while(!c[i].empty())
            {
                int p = c[i].back().first;
                if (b[p][i] <= b[l][i])
                {
                    a[p] -= c[i].back().second;
                    c[i].pop_back();
                    continue;
                }
                a[p] -= c[i].back().second;
                c[i].back().second = b[p][i] - b[l][i];
                a[p] += c[i].back().second;
                break;
            }
            c[i].push_back(mp(l, b[l][i]));
        }
        ll sum = d[l];
        for (int r = l; r < n; r++)
        {
            sum += a[r];
            ans = max(ans, sum);
        }
    }
    printf("%lld\n", ans);

    return 0;
}

