const int N = 5e3 + 5, M = 205;

int n, m, a[N], b[M][N], L[N], R[N]; ll sum[N][N], pre[N];

void Init(int *a, int *b) {
	static int stk[N], top;
	stk[top = 0] = 0;
	For (i, 1, n) {
		while (top && a[i] > a[stk[top]]) -- top; 
		b[i] = stk[top] + 1; stk[++ top] = i;
	}
}

int main () {

	File();

	n = read(); m = read();

	For (i, 1, n - 1) a[i] = read();
	For (i, 1, n) For (j, 1, m) b[j][i] = read();

	For (i, 1, m) {
		Init(b[i], L); rev(b[i]);
		Init(b[i], R); rev(b[i]); rev(R);
		For (j, 1, n) R[j] = n - R[j] + 1;
		For (j, 1, n) {
			int l = L[j], r = R[j], v = b[i][j];
			sum[l][j] += v; sum[l][r + 1] -= v; sum[j + 1][j] -= v; sum[j + 1][r + 1] += v;
		}
	}

	For (i, 1, n) pre[i] = pre[i - 1] + a[i - 1];

	ll ans = 0;
	For (i, 1, n) For (j, 1, n) {
		sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
		if (i <= j) chkmax(ans, sum[i][j] - (pre[j] - pre[i]));
	}
	printf ("%lld\n", ans);

	return 0;

}

