const ll INF = (1LL << 40);

struct State {
    vector<ll> how_to;
    ll pos_cost, real_cost;
};

ll calc_cost(State s) {
    ll res = 0;
    res += accumulate(s.how_to.begin(), s.how_to.end(), 0);
    res += s.pos_cost;
    return res;
}

// s1優先
State compose(State s1, State s2) {
    State state;
    state.how_to = vector<ll>(s1.how_to.size());
    for (int i = 0; i < s1.how_to.size(); i++) {
        state.how_to[i] = max(s1.how_to[i], s2.how_to[i]);
    }
    state.pos_cost = s2.pos_cost;
    ll cost = calc_cost(state);
    if (cost > s1.real_cost) {
        state.real_cost = cost;
    } else {
        state.real_cost = s1.real_cost;
        state.pos_cost = s1.pos_cost;
    }
    return state;
}

// 初期値を与えたSegment-treeによるRMQの実装
struct SegmentTree {
    int end;
    vector<State> dat;
    State dummy;

    SegmentTree(vector<State> d, State dum) {
        dummy = dum;

        end = 1;
        while (end < d.size()) end *= 2;

        dat = vector<State>(2 * end - 1);
        for (int i = 2 * end - 2; i >= 0; i--) {
            if (end - 1 <= i && i < end + d.size() - 1) {   // 葉でかつdに属す
                dat[i] = d[i - end + 1];
            } else if (i * 2 + 2 >= dat.size()) {   // 葉でかつdに属さない
                dat[i] = dum;
            } else {
                dat[i] = compose(dat[i * 2 + 1], dat[i * 2 + 2]);
            }
        }
    }

    State query(int lb, int ub, int k, int v_lb, int v_ub) {
        if (v_ub <= lb || ub <= v_lb) return dummy;

        if (lb <= v_lb && v_ub <= ub) return dat[k];
        else {
            State val1 = query(lb, ub, k * 2 + 1, v_lb, (v_lb + v_ub) / 2),
                  val2 = query(lb, ub, k * 2 + 2, (v_lb + v_ub) / 2, v_ub);
            return compose(val1, val2);
        }
    }
};

