	Array a(n,0);
	REP(i, n - 1)cin >> a[i + 1], a[i + 1] += a[i];
	vector<vector<P>> b(m, vector<P>(n));
	REP(i, n)REP(j, m)cin >> b[j][i].first;
	REP(i, m)REP(j, n)b[i][j].second = j;
	P id = { -INF,-1 };
	auto merge = [](P a, P b) {return max(a, b); };

	auto f = [](auto f, ll l,ll r,SegmentTree<P,decltype(merge)>& seg) -> void {
		if (l == r)return;
		P mx = seg.query(l, r);
		imos[l][mx.second] += mx.first;
		imos[l][r] -= mx.first;
		imos[mx.second+1][mx.second] -= mx.first;
		imos[mx.second+1][r] += mx.first;
		f(f, l, mx.second, seg);
		f(f, mx.second + 1, r, seg);
	};
	REP(i, m) {
		SegmentTree<P, decltype(merge)> seg(merge, id, b[i]);
		f(f, 0, n, seg);
	}
	REP(i, n)REP(j, n) imos[i][j + 1] += imos[i][j];
	REP(i, n)REP(j, n)imos[i + 1][j] += imos[i][j];
	ll ans = 0;
	REP(i, n) rep(j, i, n) chmax(ans, imos[i][j] - (a[j] - a[i]));
