	cin>>N>>M;
	for (ll i=1;i<N;++i)cin>>A[i];
	for (ll i=1;i<=N;++i)for (ll j=1;j<=M;++j)cin>>G[i][j];

	for (ll j=1;j<=M;++j){
		V.clear();
		V.pb(1e9,0);
		for (ll i=1;i<=N;++i){ 
			// Updates are all update[something][i];
			ll val = G[i][j];

			while (SZ(V) && V.back().f < val){
				pi p = V.back();V.pop_back();
				ll st=V.back().s+1;
				// Update everything from st to p (inclusive)
				ll c = val - p.f;
				// cout<<"Updated "<<i<<" from "<<st<<" to "<<p.s<< " as "<<c<<'\n';
				updates[st][i] += c;
				updates[p.s+1][i] -= c;
			}
			updates[i][i] += val;
			updates[i+1][i] -= val;
			V.pb(val,i);
		}
		// break;
	}
	for (ll i=1;i<=N;++i)for (ll j=1;j<=M;++j)updates[i][j] += updates[i-1][j];
	// for (ll i=1;i<=N;++i){
	// 	for (ll j=1;j<=N;++j)cout<<updates[i][j]<<' ';cout<<'\n';
	// }cout<<'\n';

	ll ans = 0;
	ll cur = 0;
	for (ll st = 1;st<=N;++st){
		cur = updates[st][st];
		// cout<<"Happiness from "<<st<<" to "<<st<<" is "<<cur<<'\n';
		ans=max(ans,cur);
		for (ll ct = st+1;ct<=N;++ct){
			cur += updates[st][ct];
			cur -= A[ct-1];
			// cout<<"Happiness from "<<st<<" to "<<ct<<" is "<<cur<<'\n';
			ans=max(ans,cur);
		}
	}
	cout<<ans;
}

