int main(int argc, char const *argv[]) {
  // dp[l][r] := m枚についてmax[l:r]の和
  // 値の更新は高々mn回
  ll n, m;std::cin >> n >> m;
  vll a(n, 0);
  for(int i=1;i<n;i++){
    ll tmp;scanf("%lld", &tmp);
    a[i] = a[i-1] + tmp;
  }
  vvl d = VV(m, n, 0, ll);
  //どこまで影響するか
  vvl e = VV(m, n, 0, ll);
  vvl pre = VV(m, n, -1, ll);
  for(int i=0;i<n;i++){
    for(int j=0;j<m;j++) {
      scanf("%lld", &d[j][i]);
    }
  }
  vvl num = VV(n, n, 0, ll);
  ll ans = 0;
  vll event(n, 0);

  for(int l=n-1;l>=0;l--){
    //新しく入ってきた200要素がどこまで影響するか
    for(int i=0;i<m;i++){
      if(l==n-1) {
        e[i][l] = n - 1;
        event[l] += d[i][l];
      }else{
        ll t = l;
        while(t<n-1){
          if(d[i][t+1]<=d[i][l]) {
            event[t+1] -= (d[i][t+1] - (pre[i][t+1]==-1?0:d[i][pre[i][t+1]]));
            t = e[i][t+1];
          }else break;
        }
        event[l] += d[i][l];
        if(t!=n-1&&t==l) event[t+1] -= d[i][l];
        if(t!=n-1&&t!=l) event[t+1] -= (d[i][l] - d[i][pre[i][t+1]]);
        if(t!=n-1) pre[i][t+1] = l;
        e[i][l] = t;
      }
    }
    ll h = 0, cost = 0;
    for(int r=l;r<n;r++){
      if(l!=r) cost += a[r] - a[r-1];
      h += event[r];
      ans = max(ans, h - cost);
      /*
      if(ans < h - cost){
        std::cout << h << " " << cost << " " << l << " " << r << '\n';
      }
      */
    }
  }
  std::cout << ans << '\n';
  return 0;
}

