    for (int i = 0; i < M; i++) {
        set<pair<int, int>> S;
        for (int a = N - 1; a >= 0; a--) {
            auto it = S.lower_bound(make_pair(B[a][i] + 1, 0));
            if (it == S.end()) {
                S.emplace(B[a][i], a);
            } else {
                C[a][i] = it->second;
                while (it != S.begin()) {
                    S.erase(prev(it));
                }
                S.emplace(B[a][i], a);
            }
        }
    }
    vector<vector<bool>> used(N, vector<bool>(M));
    vector<Int> diff(N);
    for (int i = 1; i < N; i++) {
        diff[i] = -A[i - 1];
    }
    Int ans = 0;
    for (int start = 0; start < N; start++) {
        for (int i = 0; i < M; i++) {
            int a = start;
            int b = C[start][i];
            while (b < N && !used[b][i]) {
                diff[b] += B[b][i] - B[a][i];
                used[b][i] = true;
                a = b;
                b = C[b][i];
            }
        }
        Int tmp = 0;
        for (int i = 0; i < M; i++) {
            tmp += B[start][i];
        }
