class BiOp {
public:
	ll operator()(ll a, ll b) const {
		return max(a, b);
	}
};

template<typename T, typename BiOp>
struct SegmentTree {
	vector<T> data;
	T e;
	BiOp op;
	int size;
	SegmentTree() {}
	SegmentTree(int n, T e, BiOp op) : e(e), op(op) {
		size = 1;
		while (size < n) size *= 2;
		data.resize(2 * size - 1);
		for (int i = 0; i < 2 * size - 1; i++) data[i] = e;
	}

	void update(int k, T v) {
		k += size - 1;
		data[k] = v;
		while (k > 0) {
			k = (k - 1) / 2;
			data[k] = op(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}

	T query(int a, int b, int k, int l, int r) const {
		if (b <= l || r <= a) return e;
		if (a <= l && r <= b) return data[k];
		return op(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	T query(int a, int b) {
		return query(a, b, 0, 0, size);
	}

	T get(int i) {
		return data[i + size - 1];
	}
};
