int n,m,A[N],B[N][N],ss[N][N],tpp[N];
ll tree[N<<1],Add[N<<1];
inline void deal(int x,int y)
{
	tree[x]+=y; Add[x]+=y;
}
inline void pushup(int rt)
{
	tree[rt]=max(tree[rt<<1],tree[rt<<1|1]);
}
inline void pushdown(int rt)
{
	if(Add[rt])
	{
		deal(rt<<1,Add[rt]);
		deal(rt<<1|1,Add[rt]);
		Add[rt]=0;
	}
}
inline void updata(int L,int R,int x,int l,int r,int rt)
{
	if(L>R) return ;
  	if(L<=l&&r<=R) 
	{
		deal(rt,x); return ;
	}int mid=(l+r)>>1; pushdown(rt);
	if(mid>=L) updata(L,R,x,l,mid,rt<<1);
	if(mid<R) updata(L,R,x,mid+1,r,rt<<1|1);
	pushup(rt);
}
inline void built(int l,int r,int rt)
{
	if(l==r){tree[rt]=A[l]; return ;}
	int mid=(l+r)>>1;
	built(l,mid,rt<<1); built(mid+1,r,rt<<1|1);
	pushup(rt);
}
inline ll query(int L,int R,int l,int r,int rt)
{
	if(L>R) return 0;
	if(L<=l&&r<=R) return tree[rt];
	int mid=(l+r)>>1; pushdown(rt);
	if(mid<L) return query(L,R,mid+1,r,rt<<1|1);
	if(mid>=R) return query(L,R,l,mid,rt<<1);
	return max(query(L,R,l,mid,rt<<1),query(L,R,mid+1,r,rt<<1|1));
}
