        stack < pair < int, int > > s;
        s.push({1e12, n + 1});
        for (int j = n; j >= 0; j--){
            auto x = s.top();
            while(x.F <= b[j][i]){
                s.pop();
                x = s.top();
            }
            nxt[j][i] = x.S;
            dif[j][i] = x.F - b[j][i];
