        b[ n + 1 ][ j ] = inf ;
    }
}

void solve ( ) {
    long long ans = 0 ;
    for ( int i = 1 ; i <= k ; ++ i ) {
        ans += b[ 1 ][ i ] ;
        st[ i ].push ( n + 1 ) ;
    }
    imp = -1 ;
    for ( int i = 1 ; i <= 15 ; ++ i ) { imp *= 10 ; }
    w.init ( 1 , 1 , n ) ;
    for ( int i = n ; i >= 1 ; -- i ) {
        long long sm = 0 ;
        for ( int j = 1 ; j <= k ; ++ j ) {
            while ( b[ i ][ j ] >= b[ st[ j ].top ( ) ][ j ] ) {
                int nxt = st[ j ].top ( ) ;
                st[ j ].pop ( ) ;
                w.update ( 1 , 1 , n , nxt , st[ j ].top ( ) - 1 , b[ i ][ j ] - b[ nxt ][ j ] ) ;
            }
            st[ j ].push ( i ) ;
            sm += b[ i ][ j ] ;
        }
        w.update ( 1 , 1 , n , i , i , sm - dist[ i ] - imp ) ;
        long long aux = w.query ( ) + dist[ i ] ;
        ans = max ( ans , aux ) ;
