  ll B[N][M]; rep(i,N) rep(j,M) cin >> B[i][j];

  imos.resize(N+1); rep(i,N+1) imos[i].resize(N+1,0);
  SegTree st(N); 
  rep(j,M) {
    rep(i,N) st.update(i, {i,B[i][j]});
    dfs(0,N,st);
  }

  ll sum[N][N] = {};
  rep(i,N) rep(j,N) {
    sum[i][j] += imos[i][j];
    if (i>0) sum[i][j] += sum[i-1][j];
    if (j>0) sum[i][j] += sum[i][j-1];
    if (i>0&&j>0) sum[i][j] -= sum[i-1][j-1];
  }
