ll solve(vec<ll>& A,vvec<ll>& B){
    int N = A.size(),M = B[0].size();
    if(A.empty()) return 0;
    if(A.size()==1){
        ll sum = 0;
        for(int i=0;i<M;i++) sum += B[0][i];
        return sum;
    }
    vec<ll> LA,RA;
    vvec<ll> LB,RB;
    ll res = 0;
    for(int i=0;i<N;i++){
        if(i<N/2){
            LA.push_back(A[i]);
            vec<ll> l;
            for(int j=0;j<M;j++){
                l.push_back(B[i][j]);
            }
            LB.push_back(l);
        }else{
            RA.push_back(A[i]);
            vec<ll> r;
            for(int j=0;j<M;j++){
                r.push_back(B[i][j]);
            }
            RB.push_back(r);
        }
    }
    res = max({res,solve(LA,LB),solve(RA,RB)});
    reverse(LA.begin(),LA.end());
    reverse(LB.begin(),LB.end());
    res = max(res,calc(M,LA,LB,RA,RB));
    return res;
}

