const int N = 5000+5;
const int M = 200+5;
const int LOG = 18;

int n,m;
ll a[N];
ll ans;
int bestL, bestR;
int b[N][M];
int ST[M][N][LOG];

void startSparseTable(){
	for(int k=0; k<m; k++){
		for(int i=0; i<n; i++){
			ST[k][i][0] = b[i][k];
		}
		for(int d=1; 1<<d <= n; d++){
			int dis = 1<<(d-1);
			for(int i=0; i+2*dis-1 < n; i++){
				ST[k][i][d] = max(ST[k][i][d-1],ST[k][i+dis][d-1]);
			}
		}
	}
}

int getMax(int k, int x, int y){
	if(x == y) return b[x][k];
	int d = y-x+1;
	int bit = 31 - __builtin_clz(d);
	int dis = 1<<bit;
	return max(ST[k][x][bit],ST[k][y-dis+1][bit]);
}

ll compute(int L, int R){
	ll act = 0LL;
	for(int i=0; i<m; i++){
		act += getMax(i,L,R);
	}
	act -= a[R] - a[L];
	return act;
}

void solve(int L, int R, int optL, int optR){
	if(L > R) return;
	int mi = (L+R)/2;
	ll midAns = 0LL;
	int midBest = optL;
	for(int i=max(mi,optL); i<=optR; i++){
		ll cand = compute(mi,i);
		if(midAns < cand){
			midBest = i;
			midAns = cand; 
		}
	}
	if(ans < midAns){
		ans = midAns;
		bestL = mi;
		bestR = midBest;
	}
	if(L < R){
		solve(L,mi-1,optL,midBest);
		solve(mi+1,R,midBest,optR);
	}
}

