	for(int i=1; i<n; i++) a[i] += a[i-1];
	for(int i=0; i<n; i++){
		for(int j=0; j<m; j++){
			ri(b[i][j]);
		}
	}
	startSparseTable();
	ans = 0LL;
	solve(0,n-1,0,n-1);
	printf("%lld\n",ans);
	return 0;
}

