	{

		imos[i].resize(n);
		for (int j = 0; j < n; ++j)
		{
			if(j == 0){
				imos[i][j] = b[j][i];
			}else{
				imos[i][j] = max(imos[i][j-1], b[j][i]);

			}
		}
	}
