void solve(int l, int r)
{
    if (l + 1 == r)
    {
        int si = 0;
        for (int j = 0; j < m; j++)
        {
            si += b[l][j];
        }
        ans = max(ans, si);
        return;
    }
    int mid = (l + r) / 2;
    solve(l, mid);
    solve(mid, r);
    for (int j = 0; j < m; j++)
    {
        c[mid - 1][j] = b[mid - 1][j];
        c[mid][j] = b[mid][j];
    }
    for (int p = mid - 2; p >= l; p--)
    {
        for (int j = 0; j < m; j++)
        {
            c[p][j] = max(b[p][j], c[p + 1][j]);
        }
    }
    for (int p = mid + 1; p < r; p++)
    {
        for (int j = 0; j < m; j++)
        {
            c[p][j] = max(b[p][j], c[p - 1][j]);
        }
    }
    int len = 0;
    for (int i = l; i < mid; i++)
    {
        len += a[i];
    }
    int i = l;
    for (int R = mid; R < r; R++)
    {
        while (i + 1 < mid)
        {
            int si1 = 0, si2 = 0;
            si1 = -len;
            si2 = -len + a[i];
            for (int j = 0; j < m; j++)
            {
                si1 += max(c[i][j], c[R][j]);
                si2 += max(c[i + 1][j], c[R][j]);
            }
            if (si2 > si1)
            {
                i++;
            }
            else
            {
                break;
            }
        }
        int si1 = 0;
        si1 = -len;
        for (int j = 0; j < m; j++)
        {
            si1 += max(c[i][j], c[R][j]);
        }
        //cout << i << " " << R << " " << si1 << endl;
        ans = max(ans, si1);
        len += a[R];
    }
}

