ll get (ll l,ll r,ll x,ll v = 1,ll tl = 1,ll tr = n) {
        if (l > r)
                return -1;
        if (tl == l && tr == r)
                return t[v][x];

        ll tm = (tl + tr) >> 1;
        return max(get(l,min(r,tm),x,v * 2,tl,tm),get(max(l,tm + 1),r,x,v * 2 + 1,tm + 1,tr));
}
ll calc (ll l,ll r) {
        ll res = 0;
        for (ll k = 1; k <= m; k ++) {
                res += get(l,r,k);
        }
        return res;
}
void compute(ll l,ll r,ll L,ll R) {
        if (l > r || L == -1 || R == -1)
                return;
