void push(int v) {
  if (!st[v].add) {
    return;
  }
  st[2 * v].add += st[v].add;
  st[2 * v].val += st[v].add;
  st[2 * v + 1].add += st[v].add;
  st[2 * v + 1].val += st[v].add;
  st[v].add = 0;
}

void add(int v, int tl, int tr, int l, int r, long long toadd) {
  if (tl == l && tr == r) {
    st[v].add += toadd;
    st[v].val += toadd;
    return;
  }
  push(v);
  int tm = (tl + tr) / 2;
  if (l < tm) {
    add(2 * v, tl, tm, l, min(r, tm), toadd);
  }
  if (r > tm) {
    add(2 * v + 1, tm, tr, max(l, tm), r, toadd);
  }
  st[v].val = max(st[2 * v].val, st[2 * v + 1].val);
}

