struct aint {
    int n;
    vector<ll> data;
    vector<ll> add;

    void init(int _n) {
        n = _n;
        data = add = vector<ll>(n * 4 + 11, 0);
    }

    void update(int node, int l, int r, int qL, int qR, ll v) {
        if (qL <= l && r <= qR) {
            add[node] += v;
            data[node] += v;
            return;
        }

        int mid = (l + r) >> 1;
        if (qL <= mid)
            update(lSon, l, mid, qL, qR, v);
        if (qR > mid)
            update(rSon, mid + 1, r, qL, qR, v);

        data[node] = max(data[lSon], data[rSon]) + add[node];
    }


};

