#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<int, int> pii;

int N, M;
LL S[5050], ans;

struct SegTree{
    LL Max[20202];

    void update(int id, int s, int e, int t, LL v){
        if (e < t || t < s) return;
        if (s == e){
            Max[id] = v;
            return;
        }
        int mid = (s+e)/2;
        update(id*2, s, mid, t, v);
        update(id*2+1, mid+1, e, t, v);
        Max[id] = max(Max[id*2], Max[id*2+1]);
    }

    LL RMQ(int id, int s, int e, int ts, int te){
        if (e < ts || te < s) return 0;
        if (ts <= s && e <= te) return Max[id];
        int mid = (s+e)/2;
        return max(RMQ(id*2, s, mid, ts, te), RMQ(id*2+1, mid+1, e, ts, te));
    }
} T[220];

void DNC(int s, int e, int l, int r){
    if (s > e) return;
    int mid = (s+e)/2;
    LL Max=-(1ll<<60), p;
    for (int i=max(mid, l); i<=r; i++){
        LL sum=0;
        for (int j=1; j<=M; j++) sum += T[j].RMQ(1, 1, N, mid, i);
        sum -= S[i] - S[mid];
        if (Max < sum) Max = sum, p = i;
    }
    ans = max(ans, Max);
    DNC(s, mid-1, l, p);
    DNC(mid+1, e, p, r);
}

