using namespace std;

const int kN = 5000 + 5;
const int kM = 200 + 5;
const long long kInf = 1'000'000'000;
long long s[kN];
int b[kN][kM], a[kN];

struct Sparse {
    int sp[14][kN];

    Sparse() = default;

    Sparse(const vector<int> &v) {
        for (int i = 0; i < v.size(); ++i) sp[0][i] = v[i];
        for (int i = 1; (1 << i) <= v.size(); ++i) {
            for (int j = 0; j + (1 << i) <= v.size(); ++j)
                sp[i][j] = max(sp[i - 1][j], sp[i - 1][j + (1 << (i - 1))]);
        }
    }

    int Query(int l, int r) {
        int p = 31 - __builtin_clz(r - l + 1);
        return max(sp[p][l], sp[p][r - (1 << p) + 1]);
    }
} sp[kM];

long long DivideConquer(int l, int r, int fl, int fr, int m) {
    if (l > r) return -kInf;
    int md = (l + r) >> 1;
    long long kp = -kInf;
    int fm = -1;
    for (int i = fl; i <= min(fr, md); ++i) {
        long long dist = s[md] - s[i], val = 0;
        for (int j = 0; j < m; ++j) val += sp[j].Query(i, md);
        if (val - dist > kp) {
            kp = val - dist;
            fm = i;
        }
    }
    long long res = max(DivideConquer(l, md - 1, fl, fm, m), DivideConquer(md + 1, r, fm, fr, m));
    return max(res, kp);
}

