template <class T> struct CumulativeSum2D {
	bool built = false;
	vector<vector<T>> A;

	CumulativeSum2D(int h, int w) : A(h + 1, vector<T>(w + 1)) {}

	void add(int y, int x, T v) {
		A[y + 1][x + 1] += v;
	}

	void add(int t, int b, int l, int r, T v) {
		A[t][l] += v;
		A[b][r] += v;
		A[t][r] -= v;
		A[b][l] -= v;
	}

	void build() {
		for (size_t y = 0; y < A.size(); y++) {
			for(size_t x = 1; x < A[y].size(); x++) {
				A[y][x] += A[y][x - 1];
			}
		}
		for (size_t y = 1; y < A.size(); y++) {
			for(size_t x = 0; x < A[y].size(); x++) {
				A[y][x] += A[y - 1][x];
			}
		}
		built = true;
	}

	T query(int t, int b, int l, int r) {
		assert(built);
		return (A[b][r] - A[b][l] - A[t][r] + A[t][l]);
	}

	T query_hw(int t, int l, int h, int w) {
		return query(t, t+h, l, l+w);
	}
};

ll solve() {
	int n = ri(), m = ri();
	vector<int> A(n);
	rep(i, 1, n) A[i] = ri() + A[i-1];

	vvi B(n, vi(m));
	rep(i, n) rep(j, m) B[i][j] = ri();

	SegTreeMax<pii> seg(n);
	CumulativeSum2D<ll> csum(n, n);

	rep(j, m) {
		out('#', j);
		rep(i, n) seg.set(i, {B[i][j], i});
		seg.build();

		function<void(int, int)> rec = [&](int l, int r) {
			if (l == r) return;
			int t, i;
			tie(t, i) = seg.query(l, r);
			out(i,r,l,i+1,t);
			csum.add(i, r, l, i+1, t);
			rec(l, i);
			rec(i+1, r);
		};
		rec(0, n);
	}

	csum.build();
	out(csum.A);

	int ans = -1e9;
	rep(i, n) rep(j, i, n) {
		ll cand = csum.A[j][i] - (A[j]-A[i]);
		amax(ans, cand);
	}
	return ans;
}

