        }
    } 
    for(int i=0;i<m;i++){
        vector<ll> c(n);
        for(int j=0;j<n;j++){
            c[j] = -b[j][i];
        }
        segtree<ll> seg(c);
        segs.push_back(seg); 
    }
    int x = 0,y=1;
    ll ma = -1;
    while(1){
        //cout << x << " " << y << " " << ma << endl;
        if(x==y-1){
            ll tmp = 0;
            rep(i,m){
                tmp += segs[i].query(x,y);
            }
            ma = max(ma,-tmp-s[y-1]+s[x]);
            //cout << ma << endl;
            if(x==n-1){
                break;
            }
