const int MAXN=5000;
const int MAXM=200;

int n,m;
int d[MAXN-1];
int x[MAXN][MAXM];

int stck[MAXM][MAXN],nstck[MAXM];

ll sval[4*MAXN];
ll slazy[4*MAXN];
void smod(int x,int l,int r,int L,int R,ll BY) {
	if(L<=l&&r<=R) {
		sval[x]+=BY;
		slazy[x]+=BY;
	} else {
		int m=l+(r-l)/2;
		if(L<=m) smod(2*x+1,l,m,L,R,BY);
		if(m+1<=R) smod(2*x+2,m+1,r,L,R,BY);
		sval[x]=slazy[x]+max(sval[2*x+1],sval[2*x+2]);
	}
	//printf("smod(%d..%d,%d..%d,%lld) -> %lld\n",l,r,L,R,BY,sval[x]);
}

ll lft[MAXN]; int mark[MAXN],curmark; int q[MAXN],nq;
void smod(int pos,ll by) { if(mark[pos]!=curmark) mark[pos]=curmark,lft[pos]=0,q[nq++]=pos; lft[pos]+=by; }
void spush() { REP(i,nq) smod(0,0,n-1,0,q[i],lft[q[i]]); ++curmark; nq=0; }

void run() {
	scanf("%d%d",&n,&m);
	REP(i,n-1) scanf("%d",&d[i]);
	REP(i,n) REP(j,m) scanf("%d",&x[i][j]);
	n=MAXN,m=MAXM; REP(i,n-1) d[i]=rand(); REP(i,n) REP(j,m) x[i][j]=rand();

	ll ret=0;
	REP(k,m) nstck[k]=0;
	memset(sval,0,sizeof(sval)); memset(slazy,0,sizeof(slazy));
	memset(lft,0,sizeof(lft)); memset(mark,-1,sizeof(mark)); curmark=0; nq=0;
	REP(i,n) {
		REP(k,m) {
			int was=0;
			while(nstck[k]>0) {
				int j=stck[k][nstck[k]-1];
				if(x[j][k]>x[i][k]) {
					smod(j,-(x[i][k]-was));
					break;
				} else {
					smod(j,-(x[j][k]-was));
					was=x[j][k];
					--nstck[k];
				}
			}
			stck[k][nstck[k]++]=i;
		}
		ll only=0; REP(k,m) only+=x[i][k]; smod(i,+only);
		spush();
		ll cur=sval[0];
		if(cur>ret) ret=cur;
		if(i!=n-1) smod(i,-d[i]);
	}
	printf("%lld\n",ret);
}

int main() {
	run();
	return 0;
}

