typedef struct indexNode{
  int index;
  int val;
} node;

node max(node a,node b){
  return a.val>b.val?a:b;
}

typedef struct RMQ{
  node *a;
  int size;
} segTree;

segTree* newRMQ(const int n){
  int k=1;
  while(k<n) k*=2;
  segTree *s=(segTree *)malloc(sizeof(segTree));
  s->a=(node *)calloc(2*k,sizeof(node));
  s->size=k;
  int i;
  for(i=0;i<k;i++) s->a[i+k]=(node){i,-1};
  for(i=k-1;i>=1;i--) s->a[i]=max(s->a[2*i],s->a[2*i+1]);
  return s;
}

void update(segTree *s,int x,int v){
  node *a=s->a;
  x+=s->size;
  a[x].val=v;
  x/=2;
  while(x>=1){
    a[x]=max(a[2*x],a[2*x+1]);
    x/=2;
  }
}

node find(segTree *s,int l,int r){
  node res={-1,-1};
  for(l+=s->size,r+=s->size;l<r;l>>=1,r>>=1){
    if(l&1) res=max(res,s->a[l++]);
    if(r&1) res=max(res,s->a[--r]);
  }
  return res;
}

typedef long long int int64;

typedef struct range{
  int l,r;
} range;

#define POS(i,j) ((i)*(n+1)+(j))

void run(void){
  int n,m;
  scanf("%d%d",&n,&m);
  int *a=(int *)calloc(n,sizeof(int));
  int i,j;
  for(i=0;i<n-1;i++) scanf("%d",a+i);
  int *b=(int *)calloc(n*m,sizeof(int));
  for(i=0;i<n*m;i++) scanf("%d",b+i);
  segTree *seg=newRMQ(n);
  int64 *dp=(int64 *)calloc((n+1)*(n+1),sizeof(int64));
  for(i=0;i<m;i++){
    for(j=0;j<n;j++) update(seg,j,b[j*m+i]);
    range stack[32];
    int top=0;
    stack[top++]=(range){0,n};
    while(top>0){
      const range t=stack[--top];
      if(t.r<=t.l) continue;
      const node v=find(seg,t.l,t.r);
      dp[POS(t.l,v.index+1)]+=v.val;
      dp[POS(v.index+1,v.index+1)]-=v.val;
      dp[POS(t.l,t.r+1)]-=v.val;
      dp[POS(v.index+1,t.r+1)]+=v.val;
      if(v.index-t.l<=t.r-v.index-1){
	stack[top++]=(range){v.index+1,t.r};
	stack[top++]=(range){t.l,v.index};
      } else {
	stack[top++]=(range){t.l,v.index};
	stack[top++]=(range){v.index+1,t.r};
      }
    }
  }
  for(i=0;i<n;i++) for(j=0;j<n;j++) dp[POS(i+1,j)]+=dp[POS(i,j)];
  for(j=0;j<n;j++) for(i=0;i<n;i++) dp[POS(i,j+1)]+=dp[POS(i,j)];
  int64 max=0;
  for(i=0;i<n;i++){
    if(max<dp[POS(i,i+1)]) max=dp[POS(i,i+1)];
    int64 d=0;
    for(j=i+2;j<n+1;j++){
      d+=a[j-2];
      int64 val=dp[POS(i,j)]-d;
      if(max<val) max=val; 
    }
  }
  printf("%lld\n",max);
}

int main(void){
  run();
  return 0;
}

