map < int, long long > s[N];
map < int, long long > e[N]; 

void upd(map < int, long long > &f, int i, int val){
  for(; i < N; i += i & -i) f[i] += val;
}

long long get(map < int, long long > &f, int i){
  long long ret = 0;
  for(; i > 0; i &= i - 1) if(f.count(i)) ret += f[i];
  return ret;
}

int main(){

  scanf("%d%d", &n, &m);

  for(int i = 2; i <= n; ++i){
    scanf("%lld", c + i);
    c[i] += c[i - 1];
  }

  for(int i = 1; i <= n; ++i){
    for(int j = 1; j <= m; ++j){
      scanf("%d", &a[i][j]);
    }
  }

  for(int j = 1; j <= m; ++j){
    stack < int > st;

    vector < int > l(n + 1, 0), r(n + 1, 0);

    for(int i = 1; i <= n; ++i){
      while(st.size() && a[st.top()][j] <= a[i][j]){
        r[st.top()] = i - 1;
        st.pop();
      }
      if(st.empty()) l[i] = 1;
      else l[i] = st.top() + 1;
      st.push(i);
    }

    while(!st.empty()) {
      r[st.top()] = n;
      st.pop();
    }

    for(int i = 1; i <= n; ++i){
      if(i - l[i] < r[i] - i){
        for(int x = l[i]; x <= i; ++x){
          upd(s[x], i, a[i][j]);
          upd(s[x], r[i] + 1, -a[i][j]);
        }
      }
      else{
        for(int x = i; x <= r[i]; ++x){
          upd(e[x], l[i], a[i][j]);
          upd(e[x], i + 1, -a[i][j]);
        }
      }
    }

  }
  long long ans = 0;

  for(int i = 1; i <= n; ++i){
    long long current = 1e18;
    for(int j = n; j >= i; --j){
      if(j < n && ans >= current + c[j + 1] - c[j]){
        current += c[j + 1];
        current -= c[j];
        continue;
      }
      current = get(s[i], j) + get(e[j], i) - c[j] + c[i];
      ans = max(ans, current);
    }
  }

  cout << ans;

	return 0;
}

