typedef long long ll;
typedef pair<ll,ll> pll;
int n, m;
ll A[5100], B[210][5100];
ll psum[5100][5100];

struct RMQ {
    pll tree[17000];
    int key = 8192;
    void init() {
        int i;
        for (i=0;i<key*2;i++) tree[i] = pll(0,0);
    }
    void upd(int idx, pll val) {
        idx+=key;
        while(idx>0) {
            tree[idx] = max(tree[idx],val);
            idx>>=1;
        }
    }
    pll getv(int s, int e) {
        pll res = pll(0,0);
        s+=key;e+=key;
        while(s<=e) {
            if (s&1) res = max(res,tree[s++]);
            if (~e&1) res = max(res,tree[e--]);
            s>>=1;e>>=1;
        }
        return res;
    }
} it;

void dnc(int s, int e, int idx) {
    if (s>e) return;
    int m = it.getv(s,e).second;
    psum[s][m]+=B[idx][m];
    psum[s][e+1]-=B[idx][m];
    psum[m+1][m]-=B[idx][m];
    psum[m+1][e+1]+=B[idx][m];
    dnc(s,m-1,idx); dnc(m+1,e,idx);
}

void calc(int idx) {
    int i;
    it.init();
    for (i=0;i<n;i++) it.upd(i,pll(B[idx][i],i));
    dnc(0,n-1,idx);
}

