#define inf 1000000007
#define MAXN 5007
#define MAXK 207

int n , k ;
int a[ MAXN ] ;
int b[ MAXN ][ MAXK ] ;
long long dist[ MAXN ] ;

stack < int > st[ MAXK ] ;

class Tree {
public :
    long long mx[ 4 * MAXN ] ;
    void init ( int where , int IL , int IR ) {
        if ( IL == IR ) {
            mx[ where ] = - dist[ IL ] ;
            return ;
        }
        int mid = ( IL + IR ) / 2 ;
        init ( 2 * where , IL , mid ) ;
        init ( 2 * where + 1 , mid + 1 , IR ) ;
        mx[ where ] = max ( mx[ 2 * where ] , mx[ 2 * where + 1 ] ) ;
    }
    void update ( int where , int IL , int IR , int CURL , int CURR , int val ) {
        if ( CURL > CURR ) { return ; }
        if ( IR < CURL || CURR < IL ) { return ; }
        if ( CURL <= IL && IR <= CURR ) {
            mx[ where ] += val ;
            return ;
        }
        int mid = ( IL + IR ) / 2 ;
        if ( CURL <= mid ) {
            update ( 2 * where , IL , mid , CURL , CURR , val ) ;
        }
        if ( mid + 1 <= CURR ) {
            update ( 2 * where + 1 , mid + 1 , IR , CURL , CURR , val ) ;
        }
        mx[ where ] = max ( mx[ 2 * where ] , mx[ 2 * where + 1 ] ) ;
    }
    long long query ( ) { return mx[ 1 ] ; }
};
Tree w ;

void input ( ) {
    scanf ( "%d%d" , &n , &k ) ;
    for ( int i = 2 ; i <= n ; ++ i ) {
        scanf ( "%d" , &a[ i ] ) ;
        dist[ i ] = dist[ i - 1 ] + a[ i ] ;
    }
    for ( int i = 1 ; i <= n ; ++ i ) {
        for ( int j = 1 ; j <= k ; ++ j ) {
            scanf ( "%d" , &b[ i ][ j ] ) ;
        }
    }
    for ( int j = 1 ; j <= k ; ++ j ) {
        b[ n + 1 ][ j ] = inf ;
    }
}

void solve ( ) {
    long long ans = 0 ;
    for ( int i = 1 ; i <= k ; ++ i ) {
        ans += b[ 1 ][ i ] ;
        st[ i ].push ( n + 1 ) ;
    }
    w.init ( 1 , 1 , n ) ;

    for ( int i = n ; i >= 1 ; -- i ) {
        long long sm = 0 ;
        for ( int j = 1 ; j <= k ; ++ j ) {
            while ( b[ i ][ j ] > b[ st[ j ].top ( ) ][ j ] ) {
                int nxt = st[ j ].top ( ) ;
                st[ j ].pop ( ) ;
                w.update ( 1 , 1 , n , nxt , st[ j ].top ( ) - 1 , b[ i ][ j ] - b[ nxt ][ j ] ) ;
            }
            st[ j ].push ( i ) ;
            sm += b[ i ][ j ] ;
        }
        w.update ( 1 , 1 , n , i , i , sm ) ;
        long long aux = w.query ( ) - dist[ i ] ;
        ans = max ( ans , aux ) ;
    }
    printf ( "%lld\n" , ans ) ;
}


int main ( ) {
    ios_base :: sync_with_stdio ( false ) ;
    cin.tie ( NULL ) ;
    input ( ) ;
    solve ( ) ;
    return 0 ;
}

