struct IndexedValue{
	int value, index;
	bool operator<(IndexedValue other) const{return value<other.value;}
};

template IndexedValue const& std::max<IndexedValue>(IndexedValue const&,IndexedValue const&);

struct RMQ{
	using T=IndexedValue;
	auto static constexpr f=(T const&(*)(T const&,T const&))std::max<T>;

	std::vector<std::vector<T>> d;
	RMQ():d(){}
	RMQ(std::vector<T> x):d(){
		assign(std::move(x));
	}
	void assign(std::vector<T> x){
		d.assign(1,std::move(x));
		for(int step=1;step<(int)d.back().size();step<<=1){
			std::vector<T> const& a=d.back();
			std::vector<T> b(begin(a),end(a)-step);
			std::transform(begin(b),end(b),begin(a)+step,begin(b),f);
			d.push_back(std::move(b));
		}
	}
	T get(int l,int r)const{
		assert(l<r);
		int layer=std::__lg(r-l);
		return f(d[layer][l],d[layer][r-(1<<layer)]);
	}
	template<class U> T get(U lr)const{
		auto [l,r]=lr;
		return get(l,r);
	}
	T getrange(int l,int r)const{
		return get(std::minmax(l,r));
	}

};

RMQ maximum;
std::vector<std::vector<int64_t>> cost; //[right][left]=sum(maximum value of each ticket)

void process(int left, int right){ // updates the (cost) array.
	if(left==right) return;
	auto [value, index]=maximum.get(left, right);

	cost[index+1][left]+=value; cost[right+1][left]-=value;
	cost[index+1][index+1]-=value; cost[right+1][index+1]+=value;
	// will be accumulated (to suffix) later

	process(left, index); process(index+1, right);
}

int main(){
	std::ios::sync_with_stdio(0);std::cin.tie(0);
	int height, width; std::cin>>height>>width;
	std::vector<int> gap(height-1);for(auto & item: gap) std::cin>>item;
	std::vector<std::vector<int>> value(height);
	for(auto & row: value){
		row.resize(width);
		for(auto & item: row) std::cin>>item;
	}

	cost.resize(height+2);
	for(int i=0;i<cost.size();++i) cost[i].resize(i+1);

	for(int col=0;col<width;++col) {
		std::vector<IndexedValue> data(height);
		for(int row=0;row<height;++row) data[row]={value[row][col], row};
		maximum.assign(std::move(data));

		process(0, height);
	}

	for(auto & row: cost)
		for(int index=0;index+1<(int)row.size();++index) 
			row[index+1]+=row[index];
	for(int row=0;row+1<=height;++row) 
		for(int col=0;col<(int)cost[row].size();++col)
			cost[row+1][col]+=cost[row][col];

	int64_t result=0;
	for(int right=0;right<=height;++right){
		int64_t totalWalk=0;
		for(int left=right-1;left>=0;--left, totalWalk+=left>=0 ? gap[left] : 0)
			result=std::max(result,cost[right][left]-totalWalk);
	}
	std::cout<<result<<'\n';
}

