	for(int i = 1; i < n; i++) {
		std::cin >> a[i];
		a[i] += a[i-1];
	}
	SegmentTree<Node, long long, LazyContext> tree;
	tree.init(a);
	const long long INF = 1.1e9;
	std::vector<std::vector<std::pair<int, int>>> b(m, std::vector<std::pair<int, int>>(1, std::pair<int, int>(INF, 0)));
