pair <int, int> max(pair <int, int> a, pair <int, int> b)
{
      if(a.fr > b.fr) return a;
      if(a.fr < b.fr) return b;
      if(a.sc < b.sc) return a;
      return b;
}

int n, m, numlog[N], a[N][202];
pair <int, int> table[23][N][202];
ll pref[N], ans;


void build(int pos)
{
      for(int i = 0; i <= numlog[n]; i ++)
      {
            for(int j = 1; j <= n; j ++)
            {
                  if(i == 0)
                  {
                        table[i][j][pos] = mk(a[j][pos], j);
                        continue;
                  }
                  int d = min(j + (1 << (i - 1)), n);
                  table[i][j][pos] = max(table[i - 1][j][pos], table[i - 1][d][pos]);
            }
      }
}

pair <int, int> get(int l, int r, int pos)
{
      int curlog = numlog[r - l + 1];
      return max(table[curlog][l][pos], table[curlog][r - (1 << curlog) + 1][pos]);
}

