		vector<int> itbl;
		FOR(i, n) itbl.push_back(vp[i].first);
		vst[i].init(itbl);

		sort(vp.rbegin(), vp.rend());
		set<int> st;
		FOR(j, n) {
			int id = -vp[j].second;
			auto it = st.lower_bound(id);
			if (it == st.end()) {
				to[i][id] = -1;
			}  else {
				to[i][id] = *it;
			}
			st.insert(id);
		}
	}

	ll ans = 0;
	FOR(i, n) {
		set<int> st;
