int main(){
    int n, m;
    scanf("%d%d", &n, &m);
    for(int i=2;i<=n;i++){
        scanf("%d", &a[i]);
        sum[i] = sum[i-1] + a[i];
    }   
    for(int i=1;i<=n;i++) for(int j=1;j<=m;j++) scanf("%d", &b[i][j]);
    for(int j=1;j<=m;j++){
        stack<int> st;
        for(int i=1;i<=n;i++){
            while(!st.empty() && b[st.top()][j] < b[i][j]) st.pop();
            if(st.empty()) l[i] = 0;
            else l[i] = st.top();
            st.push(i);
        }
        while(!st.empty()) st.pop();
        for(int i=n;i>=1;i--){
            while(!st.empty() && b[st.top()][j] <= b[i][j]) st.pop();
            if(st.empty()) r[i] = n+1;
            else r[i] = st.top();
            st.push(i);
        }
        for(int i=1;i<=n;i++){
            l[i]++, r[i]--;
            dp[l[i]][i] += b[i][j];
            dp[l[i]][r[i]+1] -= b[i][j];
            dp[i+1][i] -= b[i][j];
            dp[i+1][r[i]+1] += b[i][j];
        }
    }
    ll ans = 0;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++){
            dp[i][j] += dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1];
            if(i <= j) ans = max(ans, dp[i][j] - (sum[j] - sum[i-1]));
        }
    }
    printf("%lld\n", ans);
}

