typedef long long ll;

const int MAXN = 5005;
const int MAXM = 205;

int n, m, a[MAXN], b[MAXN][MAXM];
ll x[MAXN], maxVal[MAXN];

void solve(int l, int r, int kmin, int kmax) {
    int mid = (l+r)/2;
    int best = -1;
    vector<int> maxB(m, 0);

    fdto(i, min(kmax, mid), kmin) {
        ll val = 0;
        fto(j, 0, m-1) {
            maxB[j] = max(maxB[j], b[i][j]);
            val += maxB[j];
        }
        val -= x[mid] - x[i];
        if (best == -1 || val > maxVal[mid]) {
            maxVal[mid] = val;
            best = i;
        }
    }

    if (l < r) {
        solve(l, mid, kmin, best);
        solve(mid+1, r, best, kmax);
    }
}

