    void init(int n, int ind)
    {
        index = ind;
        mum = 1;
        while (mum < n)
            mum <<= 1;
        for (int i = 0; i < mum * 2; i++)
            seg[i] = 0;
    }
    void add(int k, ll x)
    {
        k += mum - 1;
        seg[k] = x;
        while (k > 0) {
            k = (k - 1) / 2;
            //seg[k] = max(seg[k * 2 + 1], seg[k * 2 + 2]);
            if (B[seg[k * 2 + 1]][index] > B[seg[k * 2 + 2]][index]) {
                seg[k] = seg[k * 2 + 1];
            } else {
                seg[k] = seg[k * 2 + 2];
            }
        }
    }
    ll get(int a, int b, int k, int l, int r)
    {
        if (b <= l || r <= a)
            return 5000;
        if (a <= l && r <= b)
            return seg[k];
        else {
            ll vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
