typedef  tree< int , null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;
const int mod = 1e9 + 7;
const int N = 10000;
const int K = 250;
int q[N], t[N], nxt[N][K], dif[N][K], b[N][K], c[N][K];
int sum (int r)
{
	int result = 0;
	for (; r >= 0; r = (r & (r+1)) - 1)
		result += t[r];
	return result;
}

void inc (int i, int delta)
{
	for (; i < N; i = (i | (i+1)))
		t[i] += delta;
}

main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
   // freopen("input.txt", "r", stdin);
    int n, m;
    cin >> n >> m;
    for (int i = 2; i <= n; i++){
        int l;
        cin >> l;
        q[i] = q[i - 1] + l;
    }
    for (int i = 1; i <= n; i++){
        for (int j = 1; j <= m; j++){
            cin >> b[i][j];
        }
        nxt[i][0] = 1;
        dif[i][0] = b[i][1];
    }
    for (int i = 1; i <= m; i++){
        stack < pair < int, int > > s;
        s.push({1e12, n + 1});
        for (int j = n; j >= 0; j--){
            auto x = s.top();
            while(x.F <= b[j][i]){
                s.pop();
                x = s.top();
            }
            nxt[j][i] = x.S;
            dif[j][i] = x.F - b[j][i];
            s.push({b[j][i], j});
        }
    }
    for (int i = 1; i <= m; i++){
        int j = 0;
        while(j != n + 1){
            int x = dif[j][i];
            j = nxt[j][i];
            c[j][i] = x;
            inc(j, x);
        }
    }
    int ans = 0;
    for (int i = 1; i <= n; i++){
        for (int j = 1; j <= m; j++){
            int l = nxt[i][j];
            int z = dif[i][j];
            inc(i, -c[i][j]);
            inc(i, b[i][j]);
          //  inc(i, b[i][j]);
            while(z != c[l][j]){
                inc(l, -c[l][j]);
                inc(l, z);
                c[l][j] = z;
                z = dif[l][j];
                l = nxt[l][j];
            }
        }
        for (int j = i; j <= n; j++){
            ans = max(ans, q[i] - q[j] + sum(j) - sum(i - 1));
        }
    }
    cout << ans;
}

