typedef long long ll;

int N, M;
int lg[MAXN + 5], st[13][MAXM + 5][MAXN + 5];
void get_st() {
	for(int i=2;i<=N;i++)
		lg[i] = lg[i>>1] + 1;
	for(int p=1;p<=M;p++)
		for(int i=1;i<13;i++) {
			int k = (1 << (i - 1));
			for(int j=1;j<=N;j++)
				st[i][p][j] = max(st[i-1][p][j], st[i-1][p][j+k]);
		}
}
ll rmq(int id, int l, int r) {
	int k = lg[r - l + 1], p = (1<<k);
	return max(st[k][id][l], st[k][id][r-p+1]);
}
ll ans, A[MAXN + 5];
void solve(int opl, int opr, int l, int r) {
	if( l > r ) return ;
	int m = (l + r) >> 1, opm = opl;
	ll tmp = 0;
	for(int i=opl;i<=opr&&i<=m;i++) {
		ll x = 0;
		for(int j=1;j<=M;j++)
			x = (x + rmq(j, i, m));
		x -= (A[m] - A[i]);
		if( x > tmp )
			tmp = x, opm = i;
	}
	ans = max(ans, tmp);
	solve(opl, opm, l, m - 1);
	solve(opm, opr, m + 1, r);
}
int main() {
	scanf("%d%d", &N, &M);
	for(int i=2;i<=N;i++) scanf("%lld", &A[i]);
