typedef long long int64;
static const int MAXN = 5004;
static const int LOGN = 15;
static const int MAXM = 202;

int n, m, a[MAXN], b[MAXM][MAXN];

template <typename T> struct rmq {

std::pair<T, int> f[LOGN][MAXN];

void build(int n, T *arr) {
    for (int i = 0; i < n; ++i) f[0][i] = std::make_pair(arr[i], i);
    for (int j = 1; j < LOGN; ++j)
        for (int i = 0; i <= n - (1 << j); ++i)
            f[j][i] = std::max(f[j - 1][i], f[j - 1][i + (1 << (j - 1))]);
}

inline std::pair<T, int> query(int l, int r) {
    if (l == r) return f[0][l];
    int sz = sizeof(int) * 8 - __builtin_clz(r - l) - 1;
    return std::max(f[sz][l], f[sz][r - (1 << sz) + 1]);
}

};
rmq<int> quq;

int64 sum[MAXN][MAXN] = {{ 0 }};

void recursive_max(int l, int r)
{
    if (l > r) return;
    std::pair<int, int> p = quq.query(l, r);
    int m = p.second;
    // Add p.first to [l, m] * [m, r]
    sum[l][m] += p.first;
    sum[l][r + 1] -= p.first;
    sum[m + 1][m] -= p.first;
    sum[m + 1][r + 1] += p.first;
    recursive_max(l, m - 1);
    recursive_max(m + 1, r);
}

int main()
{
    scanf("%d%d", &n, &m);
    a[0] = 0;
    for (int i = 1; i < n; ++i) scanf("%d", &a[i]), a[i] += a[i - 1];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) scanf("%d", &b[j][i]);

    for (int i = 0; i < m; ++i) {
        quq.build(n, b[i]);
        recursive_max(0, n - 1);
    }

    // Postprocess 2-D prefix sums
    for (int i = 0; i < n; ++i)
        for (int j = 1; j < n; ++j) sum[i][j] += sum[i][j - 1];
    for (int j = 0; j < n; ++j)
        for (int i = 1; i < n; ++i) sum[i][j] += sum[i - 1][j];

    int64 ans = -1;
    for (int i = 0; i < n; ++i)
        for (int j = i; j < n; ++j)
            ans = std::max(ans, sum[i][j] - (a[j] - a[i - 1]));
    printf("%lld\n", ans);

    return 0;
}

