struct segmentTree{
    #define mid ((l + r) >> 1)
    ll d[N * 4], lazy[N * 4];
    void doLazy(int id, int l, int r){
        d[id] += lazy[id];
        if (l != r){
            lazy[id << 1] += lazy[id];
            lazy[id << 1 | 1] += lazy[id];
        }
        lazy[id] = 0;
    }
    void update(int id, int l, int r, int u, int v, int val){
        if (id == 1){
            cerr << "upd " << ' ' << u << ' ' << v << ' ' << val << endl;
        }
        assert(l <= r);
        doLazy(id, l, r);
        if (v < l || r < u)
            return;
        if (u <= l && r <= v){
            lazy[id] += val;
            doLazy(id, l, r);
            return;
        }
        update(id << 1, l, mid, u, v, val);
        update(id << 1 | 1, mid + 1, r, u, v, val);
        d[id] = max(d[id << 1], d[id << 1 | 1]);
    }
    ll get(int id, int l, int r, int u, int v){
        doLazy(id, l, r);
        if (v < l || r < u)
            return 0;
        if (u <= l && r <= v){
            return d[id];
        }
        return max(get(id << 1, l, mid, u, v),
                   get(id << 1 | 1, mid + 1, r, u, v));
    }
    void print(int id, int l, int r){
        doLazy(id, l, r);
        if (l == r){
            cerr << d[id] << ' ';
            return;
        }
        print(id << 1, l, mid);
        print(id << 1 | 1, mid + 1, r);
    }
    #undef mid;
} ST;

