const int N=5e3+100,M=210;
int gi() {
	int w=0;bool q=1;char c=getchar();
	while ((c<'0'||c>'9') && c!='-') c=getchar();
	if (c=='-') q=0,c=getchar();
	while (c>='0'&&c <= '9') w=w*10+c-'0',c=getchar();
	return q? w:-w;
}
int st[M][N],w[M][N],top[M];
LL dis[N],tag[N*4],mx[N*4];
#define lc (i<<1)
#define rc (lc|1)
inline void add(int i,LL t) { tag[i]+=t,mx[i]+=t; }
inline void modify(int i,int l,int r,int k,LL t) {
	if (l==r) mx[i]=t;
	else {
		int mid=(l+r)>>1;
		k<=mid?modify(lc,l,mid,k,t):modify(rc,mid+1,r,k,t);
		mx[i]=max(mx[lc],mx[rc]);
	}
}
inline void pushdown(int i) {
	if (tag[i]) {
		add(lc,tag[i]);
		add(rc,tag[i]);
		tag[i]=0;
	}
}
inline void add(int i,int l,int r,int L,int R,int t) {
	if (L<=l&&r<=R) add(i,t);
	else {
		int mid=(l+r)>>1;
		pushdown(i);
		if (L<=mid) add(lc,l,mid,L,R,t);
		if (mid<R) add(rc,mid+1,r,L,R,t);
		mx[i]=max(mx[lc],mx[rc]);
	}
}
int main()
{
	int n=gi(),m=gi(),i,j;LL ans=0,s;
	for (i=2;i<=n;i++) dis[i]=dis[i-1]+gi();
	for (i=1;i<=n;i++) {
		s=0;
		for (j=1;j<=m;j++) {
			s+=w[j][i]=gi();
			while (top[j]&&w[j][i]>w[j][st[j][top[j]]])
				add(1,1,n,st[j][top[j]-1]+1,st[j][top[j]],w[j][i]-w[j][st[j][top[j]]]),top[j]--;
			st[j][++top[j]]=i;
		}
		modify(1,1,n,i,s+dis[i]);
		ans=max(ans,mx[1]-dis[i]);
	}
	cout<<ans<<endl;
	return 0;
}

