struct Sparse_table{
	using T=ll;
    Sparse_table(const vector<T> &init){
		const int n=init.size();
		const int logn=31-__builtin_clz(n);
		data=vector<vector<T>>(logn+1,vector<T>(n));
		data[0]=init;
		rep(k,logn)rep(i,n+1-bit(k)){
			data[k+1][i]=vmerge(data[k][i],data[k][i+bit(k)]);
		}
    }

	T query(int l,int r){
		int i=31-__builtin_clz(r-l);
		T ans=vmerge(data[i][l],data[i][r-bit(i)]);
		return ans;
	}

	vector<vector<T>> data;
	inline T vmerge(T a,T b){return max(a,b);}
};

