using namespace std;
const int N = 5e3 + 3;
const int M = 205;
const int SN = 1 << 14;
int n , m;
int a[N];
int b[N][M];
long long ans;
int bst[M];
int nxt[N][M];
long long segtree[SN];
long long lazy[SN];
long long arr[N];
void build(int l , int r , int node){
    lazy[node] = 0;
    if(l == r){
        segtree[node] = arr[l];
    }
    else{
        int mid = l + r >> 1;
        build(l , mid , node + node);
        build(mid + 1 , r , node + node + 1);
        segtree[node] = max(segtree[node + node] , segtree[node + node + 1]);
    }
}
void push(int l , int r , int node){
    if(lazy[node]){
        segtree[node] += lazy[node];
        if(l != r){
            lazy[node + node] += lazy[node];
            lazy[node + node + 1] += lazy[node];
        }
        lazy[node] = 0;
    }
}
void update(int l , int r , int node , int ql , int qr , int val){
    push(l , r , node);
    if(l > qr || r < ql){
        return;
    }
    if(l >= ql && r <= qr){
        lazy[node] = val;
        push(l , r , node);
        return;
    }
    int mid = l + r >> 1;
    update(l , mid , node + node , ql , qr , val);
    update(mid + 1 , r , node + node + 1 , ql , qr , val);
    segtree[node] = max(segtree[node + node] , segtree[node + node + 1]);
}
int main(){
    scanf("%d %d" , &n , &m);
    for(int i = 1 ; i < n ; ++i){
        scanf("%d" , a + i);
    }
    for(int i = 1 ; i <= n ; ++i){
        for(int j = 1 ; j <= m ; ++j){
            scanf("%d" , &b[i][j]);
        }
    }
    for(int j = 1 ; j <= m ; ++j){
        stack < int > s;
        while(!s.empty()){
            s.pop();
        }
        for(int i = n ; i >= 1 ; --i){
            while(!s.empty() && b[s.top()][j] <= b[i][j]){
                s.pop();
            }
            if(s.empty()){
                nxt[i][j] = n + 1;
            }
            else{
                nxt[i][j] = s.top();
            }
            s.push(i);
        }
    }
    ans = 0;
    arr[0] = 0;
    a[0] = 0;
    memset(bst , 0 , sizeof(bst));
    for(int i = 1 ; i <= n ; ++i){
        arr[i] = arr[i - 1] - a[i - 1];
        for(int j = 1 ; j <= m ; ++j){
            if(b[i][j] > bst[j]){
                arr[i] -= bst[j];
                bst[j] = b[i][j];
                arr[i] += bst[j];
            }
        }
        ans = max(ans , arr[i]);
    }
    build(1 , n , 1);
    long long sum = 0;
    for(int i = 2 ; i <= n ; ++i){
        sum += a[i - 1];
        for(int j = 1 ; j <= m ; ++j){
            update(1 , n , 1 , i - 1 , nxt[i - 1][j] - 1 , -b[i - 1][j]);
            update(1 , n , 1 , i , nxt[i][j] - 1 , b[i][j]);
        }
        ans = max(ans , segtree[1] - sum);
    }
    printf("%lld\n" , ans);
}

