using namespace std;

const int inf = 1e9 + 7;
const int N = 5e3 + 5;

typedef long long ll;

pair <int, int> max(pair <int, int> a, pair <int, int> b)
{
      if(a.fr > b.fr) return a;
      if(a.fr < b.fr) return b;
      if(a.sc < b.sc) return a;
      return b;
}

int n, m, numlog[N], a[N][202];
pair <int, int> table[23][N][202];
ll pref[N], ans;


void build(int pos)
{
      for(int i = 0; i <= numlog[n]; i ++)
      {
            for(int j = 1; j <= n; j ++)
            {
                  if(i == 0)
                  {
                        table[i][j][pos] = mk(a[j][pos], j);
                        continue;
                  }
                  int d = min(j + (1 << (i - 1)), n);
                  table[i][j][pos] = max(table[i - 1][j][pos], table[i - 1][d][pos]);
            }
      }
}

pair <int, int> get(int l, int r, int pos)
{
      int curlog = numlog[r - l + 1];
      return max(table[curlog][l][pos], table[curlog][r - (1 << curlog) + 1][pos]);
}

int main()
{
      srand(time(NULL));
      scanf("%d %d", &n, &m);

      for(int i = 2; i <= n; i ++)
            numlog[i] = numlog[i / 2] + 1;

      for(int i = 1; i < n; i ++)
      {
            scanf("%lld", &pref[i]);
            pref[i] += pref[i - 1];
      }

      for(int i = 1; i <= n; i ++)
            for(int j = 1; j <= m; j ++)
                  scanf("%d", &a[i][j]);

      for(int i = 1; i <= m; i ++)
            build(i);

      if(n * 1ll * n * 1ll * m > 2e8)
      {
            int cnt = 0;
            while(cnt < 100000)
            {
                  int l = rand() % n + 1, r = rand() % n + 1, mx = 0, mn = inf;
                  ll res = 0;
                  if(l > r) swap(l, r);

                  for(int i = 1; i <= m; i ++)
                  {
                        res += get(l, r, i).fr;
                        mn = min(get(l, r, i).sc, mn);
                        mx = max(get(l, r, i).sc, mx);
                  }

                  res -= pref[mx - 1] - pref[mn - 1];
                  ans = max(ans, res);
                  cnt ++;
            }
            for(int i = 1; i <= n; i ++)
            {
                  for(int j = 1; j <= m; j ++)
                  {
                        int pos = get(i, n, j).sc;
                        ll res = 0;
                        for(int k = 1; k <= m; k ++)
                              res += get(i, pos, k).fr;
                        res -= pref[pos - 1] - pref[i - 1];
                        ans = max(ans, res);
                  }
            }
      }
      else
      {
            for(int i = 1; i <= n; i ++)
            {
                  for(int j = i; j <= n; j ++)
                  {
                        ll res = 0;
                        for(int k = 1; k <= m; k ++)
                              res += get(i, j, k).fr;
                        res -= pref[j - 1] - pref[i - 1];
                        ans = max(ans, res);
                  }
            }
      }

      cout << ans << endl;
}

