ll dp[maxn]; // dp[i]: max value if we end at loc i



ll qry(int l, int r) {
    ll walk = a[r-1]-a[l-1];
    ll res = 0;
    for (int i=1; i<=m; i++) {
	res += t[i].qry(1,1,n,l,r);
    }
    return res - walk;
}


// compute dp[tl],dp[tl+1]...dp[tr], assuming optimal starting loc is in [ql,qr]
void solve(int tl, int tr, int ql, int qr) {
    if (tl>tr) return;
    int tm = (tl+tr)/2;

    int opt = 0;
    ll best = -inf;

    // compute dp[tm]
    for (int i=ql; i<=min(tm, qr); i++) {
	dp[tm] = max(dp[tm], qry(i, tm));
	if (dp[tm] > best) {
	    best = dp[tm];
	    opt = i;
	}
    }

    solve(tl,tm-1,ql,opt);
    solve(tm+1,tr,opt,qr);
}


