int has[6000][6000];
void rui(int Y1, int Y2, int X1, int X2, int x){
	has[Y1][X1] += x;has[Y1][X2+1] -= x;
	has[Y2+1][X1] -= x;has[Y2+1][X2+1] += x;
}

void dfs(int l, int r, int k){
	if(l >= r)return ;
	P p = get(l, r, 0, 0, segn);
	rui(l+1, p.se+1, p.se+1, r, p.fi);
	dfs(l, p.se, k);
	dfs(p.se+1, r, k);
}

