template<typename T>
struct SegTree {
	T init_val;
	int n;
	vector<T> dat;

	SegTree() {}
	SegTree(int _n, T init_val) {
		init(_n, init_val);
	}

	void init(int _n, T iniv) {
		init_val = iniv;
		n = 1;
		while (n < _n) n *= 2;
		dat.resize(n * 2 - 1, init_val);
	}

	void update(int k, T x) {
		k += n - 1;
		chmax(dat[k], x);
		while (k > 0) {
			k = (k - 1) / 2;
			chmax(dat[k], max(dat[k * 2 + 1], dat[k * 2 + 2]));
		}
	}

	T query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return dat[k];
		return max( query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r) );
	}

	T query(int a, int b) {
		return query(a, b, 0, 0, n);
	}
};

int N, M;
int A[5000], B[5000][200];
ll d[5000], imos[5001][5001];
SegTree<pii> st[2000];

// 2点(x1,y1),(x2, y2)を囲む長方形領域にaddを加算
void imos_add(int x1, int y1, int x2, int y2, ll add) {
	if (x1 > x2) swap(x1, x2);
	if (y1 > y2) swap(y1, y2);


	imos[y1][x1] += add;
	imos[y1][x2 + 1] -= add;
	imos[y2 + 1][x1] -= add;
	imos[y2 + 1][x2 + 1] += add;
}

void imos_calc() {
	REP(i, N) FOR(j, 1, N) imos[i][j] += imos[i][j - 1];
	REP(j, N) FOR(i, 1, N) imos[i][j] += imos[i - 1][j];
}


void solve(int x, int l, int r) { // [l,r]
	pii now = st[x].query(l, r + 1);
	int num = now.fi, m = now.se;

	imos_add(m, m, r, l, num);

	if (l != m) solve(x, l, m - 1);
	if (r != m) solve(x, m + 1, r);
}

int main() {
	cin >> N >> M;
	REP(i, N - 1) scanf("%d", &A[i]);
	REP(i, N) REP(j, M) scanf("%d", &B[i][j]);

	REP(i, N - 1) d[i + 1] = d[i] + A[i];

	REP(i, M) st[i] = SegTree<pii>(N, pii(-1, 0));
	REP(j, M) REP(i, N) st[j].update(i, pii(B[i][j], i));

	REP(i, M) solve(i, 0, N - 1);
	imos_calc();

	ll ans = 0;
	REP(i, N) FOR(j, i, N) chmax(ans, imos[i][j] - d[j] + d[i]);
	cout << ans << endl;

	return 0;
}

