#include <bits/stdc++.h>
using namespace std;
const int N = 5001, M = 201;

int n, m, a[N], b[N][M], l[N], r[N];
long long ans, dp[N][N];
void add(int x1, int y1, int x2, int y2, int val) {
	dp[x1][y1] += val;
	dp[x2+1][y1] -= val;
	dp[x1][y2+1] -= val;
	dp[x2+1][y2+1] += val;
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n >> m;
	for(int i = 2; i <= n; i++) cin >> a[i];
	for(int i = 1; i <= n; i++) for(int j = 1; j <= m; j++) cin >> b[i][j];
	for(int j = 1; j <= m; j++) {
		stack<pair<int,int> > st;
		for(int i = 1; i <= n; i++) {
			while(!st.empty() && st.top().first < b[i][j]) st.pop(); // cannot be <=, or else intersect
			l[i] = (st.empty() ? 0 : st.top().second) + 1;
			st.emplace(b[i][j], i);
		}
		while(!st.empty()) st.pop();
		for(int i = n; i >= 1; i--) {
			while(!st.empty() && st.top().first < b[i][j]) st.pop();
			r[i] = (st.empty() ? n+1 : st.top().second) - 1;
			st.emplace(b[i][j], i);
		}
		for(int i = 1; i <= n; i++) add(l[i], i, i, r[i], b[i][j]);
	}
	for(int i = 1; i <= n; i++) for(int j = 1; j <= n; j++) dp[i][j] = dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1] + dp[i][j];
	for(int i = 1; i <= n; i++) {
		long long sum = 0;
		for(int j = i; j <= n; j++) {
			sum += a[j] * (j > i);
			ans = max(dp[i][j] - sum, ans);
		}
	}
	cout << ans;
}

