inline int max(int a, int b)
{
        return a > b ? a : b;
}
inline int min(int a, int b)
{
        return a > b ? b : a;
}

void build (int v = 1,int tl = 1,int tr = n) {
        if (tl == tr) {
                for (int i = 1; i <= m; i ++) {
                        t[v][i] = b[tl][i];
                }
        }
        else {
                int tm = (tl + tr) >> 1;
                build (v * 2,tl,tm);
                build (v * 2 + 1,tm + 1,tr);
                for (int i = 1; i <= m; i ++) {
                        t[v][i] = max(t[v * 2][i],t[v * 2 + 1][i]);
                }
        }
}
int get (int l,int r,int x,int v = 1,int tl = 1,int tr = n) {
        if (l > r || l > tr || tl > r)
                return -1;

        if (l <= tl && tr <= r)
                return t[v][x];

        int tm = (tl + tr) >> 1;
        return max(get(l,r,x,v + v,tl,tm),get(l,r,x,v + v + 1,tm + 1,tr));
}
ll calc (int  l,int  r) {
        ll res = 0;

        for (int  k = 1; k <= m; k ++) {
                res += get(l,r,k);
        }
        return res;
}
void compute(int l,int r,int L,int R) {

        if (l > r) return;


        int md = (l + r) >> 1;

        ll cur = -1;
        int opt = L;

        for (ll i = L; i <= min(md,R); i ++) {
                ll now = calc(i,md) - (p[md] - p[i]);
                if (now > cur)
                        cur = now,opt = i;
        }
        mx = max(mx,cur);
        compute(l,md - 1,L,opt);
        compute(md + 1,r,opt,R);
}
