void add(int px, int py, int qx, int qy, int x) {
	//cout << "! " << px << " " << py << " " << qx << " " << qy << endl;
	C[px][py] += x; C[qx + 1][qy + 1] += x;
	C[px][qy + 1] -= x; C[qx + 1][py] -= x;
}

void dfs(int L, int R) {
	if (L > R) return;
	long long G = X.query(L, R + 1); G *= -1;
	long long num = G / 10000, pos = G % 10000;
	add(L, L, R, R, num);
	add(L, L, pos - 1, pos - 1, -num);
	add(pos + 1, pos + 1, R, R, -num);
	dfs(L, pos - 1);
	dfs(pos + 1, R);
}

