#define dmax(_a, _b) ((_a) > (_b) ? (_a) : (_b))
#define cmax(_a, _b) (_a < (_b) ? _a = (_b) : 0)
struct Event{
	int x, l, r, val;
	inline bool operator <(const Event &e) const {
		return x == e.x ? val < e.val : x < e.x;
	}
