void Build(register int o, register int l, register int r){
	if (l == r) {
		t[o] = -s[l];
		return ;
	}
	register int o2 = o << 1, mid = l + r >> 1;
	Build(o2, l, mid);
	Build(o2 | 1, mid + 1, r);
	t[o] = dmax(t[o2], t[o2 | 1]);
	return ;
}
#define Pushdown(_oo, _oo2) {\
	t[_oo2] += tag[_oo]; \
	t[_oo2 | 1] += tag[_oo]; \
	tag[_oo2] += tag[_oo]; \
	tag[_oo2 | 1] += tag[_oo]; \
	tag[_oo] = 0; \
}
void Modify(register int o, register int l, register int r){
	//if (val == 3) fprintf(stdout, "%d [%d %d] %d %lld %lld\n", o, l, r, val, t[o], tag[o]);
	if (lbd <= l && r <= rbd) {
		t[o] += val;
		tag[o] += val;
	//if (val == 3) fprintf(stdout, "%d %d %d %d %lld %lld\n", o, l, r, val, t[o], tag[o]);
		return ;
	}
	register int o2 = o << 1, mid = l + r >> 1;
	if (tag[o]) Pushdown(o, o2);
	if (lbd <= mid) Modify(o2, l, mid);
	if (mid < rbd) Modify(o2 | 1, mid + 1, r);
	t[o] = dmax(t[o2], t[o2 | 1]);
	//if (val == 3) fprintf(stdout, "%d %d %d %d %lld\n", o, l, r, val, t[o], tag[o]);
	return ;
}
void Query(register int o, register int l, register int r){
	if (lbd <= l && r <= rbd) {
		//fprintf(stderr, "%d %d %d %lld %lld\n", o, l, r, t[o], tag[o]);
		cmax(nowmax, t[o]);
		return ;
	}
	register int o2 = o << 1, mid = l + r >> 1;
	if (tag[o]) Pushdown(o, o2);
	if (lbd <= mid) Query(o2, l, mid);
	if (mid < rbd) Query(o2 | 1, mid + 1, r);
	return ;
}
