ll val = 0;

void push(int n , int s , int e) {
	if (lazy[n]) {
		seg[n].sum += lazy[n];
		if (s != e) {
			lazy[2 * n]  += lazy[n];
			lazy[2 * n + 1] += lazy[n];
		}
		lazy[n] = 0;
	}
	for (int i = 1; i <= m ; ++i) {
		if (mLazy[n][i] > seg[n].mx[i]) {
			seg[n].sum -= seg[n].mx[i];
			seg[n].mx[i] = mLazy[n][i];
			seg[n].sum += seg[n].mx[i];
		}
		if (s != e) {
			seg[2 * n].mx[i] = max(seg[2 * n].mx[i], (int)mLazy[n][i]);
			seg[2 * n + 1].mx[i] = max(seg[2 * n + 1].mx[i], (int)mLazy[n][i]);
		}
		mLazy[n][i] = 0;
	}
}
void update(int n , int s , int e) {
	push(n, s, e);
	if (s > r || e < l)return;
	if (s >= l && e <= r) {
		if (type == 1) {
			lazy[n] += val;
		} else {
			mLazy[n][ticket] = val;
		}
		/*if (s == 2 && e == 2) {
			cout << n << " WHAT " << seg[n].sum << " " << val << " " << seg[n].mx[ticket] << " " << ticket << endl;
		}*/
		push(n, s, e);
		return;
	}
	update(2 * n, s, (s + e) / 2);
	update(2 * n + 1, (s + e) / 2 + 1, e);
	seg[n] = max(seg[2 * n], seg[2 * n + 1]);
}
int get(int n , int s , int e , int at) {
	push(n, s, e);
	if (s > at || e < at)return 0;
	if (s == e) {
		return seg[n].sum;
	}
	return max(get(2 * n, s, (s + e) / 2, at), get(2 * n + 1, (s + e) / 2 + 1, e, at));
}
