using namespace std;

using ll = long long;
const int MAXN = 5050;
const int MAXM = 220;
const ll INF = 1e18;

int N, M;
int A[MAXN];
int B[MAXN][MAXM];

ll tr[MAXN << 2];
ll lazy[MAXN << 2];

void build(int v, int l, int r) {
   tr[v] = -INF;
   if (l < r) {
      int md = (l + r) >> 1;
      build(v << 1, l, md);
      build(v << 1 | 1, md + 1, r);
   }
}

void push(int v, int l, int r) {
   if (lazy[v]) {
      tr[v] += lazy[v];
      if (l < r) {
         lazy[v << 1] += lazy[v];
         lazy[v << 1 | 1] += lazy[v];
      }
      lazy[v] = 0;
   }
}

void add(int v, int l, int r, int L, int R, ll val) {
   push(v, l, r);
   if (L > r || R < l) return;
   if (L <= l && r <= R) {
      lazy[v] = val;
      push(v, l, r);
      return;
   }
   int md = (l + r) >> 1;
   add(v << 1, l, md, L, R, val);
   add(v << 1 | 1, md + 1, r, L, R, val);
   tr[v] = max(tr[v << 1], tr[v << 1 | 1]);
}

void print(int v, int l, int r) {
   push(v, l, r);
   if (l == r) {
      cerr << tr[v] << "\n";
   } else {
      int md = (l + r) >> 1;
      print(v << 1, l, md);
      print(v << 1 | 1, md + 1, r);
   }
   if (v == 1) cerr << "\n";
}
