const int Maxm = 2e2 + 10;
const ll Inf = 1e16;

ll a[Maxn], ps[Maxn], A[Maxn][Maxm], val[Maxn][Maxm];

stack<int> st[Maxm];


ll seg[4 * Maxn];
ll lazy[4 * Maxn];

void shift(int id){
	if(lazy[id] == 0) return ;
	for(int i = 0; i <= 1; i++){
		lazy[id << 1 | i] += lazy[id];
		seg[id << 1 | i] += lazy[id];
	}
	lazy[id] = 0;
}

void add(int id, int l, int r, int val, int L, int R){
	if(r <= L || l >= R) return ;
	if(l <= L && R <= r){
		seg[id] += val;
		lazy[id] += val;
		return ;
	}
	int mid = (L + R) >> 1;
	shift(id);
	add(id << 1, l, r, val, L, mid);
	add(id << 1 | 1, l, r, val, mid, R);
	seg[id] = max(seg[id << 1], seg[id << 1 | 1]);
	return ;
}

ll get_max(int id, int l, int r, int L, int R){
	if(r <= L || R <= l) return -Inf;
	if(l <= L && R <= r){
		return seg[id];
	}
	int mid = (L + R) >> 1;
	shift(id);
	return max(get_max(id << 1, l, r, L, mid),
		get_max(id << 1 | 1, l, r, mid, R));
}


