class sparse_table {
	vector<vector<ll>> dat;
	vector<int> logTable;
	int n;

	ll zero_element() const {
		return numeric_limits<ll>::min();
	}
	ll prop(ll a, ll b) const {
		return max(a, b);
	}

public:
	void init(vector<int>& a) {
		n = sz(a);
		logTable.resize(n + 1);
		logTable[0] = logTable[1] = 0;
		for (int i = 2; i <= n; i++) logTable[i] = logTable[i >> 1] + 1;

		int logN = logTable[n];
		dat.resize(logN + 1, vector<ll>(n, zero_element()));
		FOR(i, n) dat[0][i] = a[i];
		for (int i = 1; i <= logN; i++) {
			int l = 1 << i;
			for (int j = 0; j + l <= n; j++) {
				dat[i][j] = prop(dat[i - 1][j], dat[i - 1][j + l / 2]);
			}
		}
	}

	ll query(int l, int r) {
		int k = logTable[r - l];
		return prop(dat[k][l], dat[k][r - (1 << k)]);
	}

};

