          e[x].emplace_back(i + 1, -a[i][j]);
        }
      }
    }

  }

  long long ans = 0;

  for(int i = 1; i <= n; ++i){
    for(int j = 1; j <= n; ++j){
      s[i][j] += s[i][j - 1];
    }
  }


  for(int i = 1; i <= n; ++i){
    memset(sum, 0, sizeof sum);

    for(auto p : e[i]){
      sum[p.first] += p.second;
    }

    for(int j = 1; j <= i; ++j){
      sum[j] += sum[j - 1];

      ans = max(ans, sum[j] + s[j][i] - c[i] + c[j]);
    }
  }

  cout << ans;

	return 0;
}

