typedef long long ll;
ll n,MS,a[N],b[N];
ll dp[K][M][N];//color, range,start
ll ans[N];
int Q(int l,int r,int col){
    int sz=log2(r-l+1);
    int v1=dp[col][sz][l];
    int v2=dp[col][sz][r+1-(1<<sz)];
    return max(v1,v2);
}
void gen(int l,int r,int optl,int optr){
    if(l>r)return;
    int m=(l+r)/2;
    pair<ll,ll>bes={LLONG_MIN,LLONG_MIN};
    for(int i=optl;i<=min(m,optr);i++){
        ll val=0;
        for(int c=1;c<=MS;c++)val+=Q(i,m,c);
        val-=(b[m]-b[i]);
        pair<ll,ll>cur={val,i};
        bes=max(cur,bes);
    }
    //cout<<m<<' '<<bes.first<<' '<<bes.second<<'\n';
    ans[m]=bes.first;
    int opt=bes.second;
    gen(l,m-1,optl,opt);
    gen(m+1,r,opt,optr);
}
