class Seg{
public: 


  struct T{
    bool type; //0 - empty   , 1 - update
    Int value;
    T():type(0),value(0){}
    T(bool type,Int value):type(type),value(value){}
  };

  //比較可能な主データ型
  struct D{
    Int value;
    Int idx;
    D():value(0){} /*適切な値にする!!!!!!*/
    D(Int value,Int idx):value(value),idx(idx){}
  };

  D INF = D(-(1LL<<55),-(1LL<<55)); /*!!!!!!!!!!!!!!!!!!!!!!!!*/

  Int n;
  vector<D> dat;
  vector<T> td;

  Seg(){n=-1;}
  Seg(Int n_){
    n=1;
    while(n<n_)n*=2;
    td.resize(2*n-1,T());
    dat.resize(2*n-1,D());
  }

  D merge(D a,D b){
    if(a.value < b.value) return b;
    return a;
  }

  void delay(Int k){
  }

  D update(Int k,D x){
    dat[k] = x;
    return dat[k];
  }

  //[a,b)の値をx加算　add(a,b,x)
  D query(Int a,Int b,D x,bool flg=true,Int k=0,Int l=0,Int r=-1){
    if(r==-1) r=n, assert(a <= n && b <= n);
    if(r<=a||b<=l) return flg? dat[k]:INF;
    if(a<=l&&r<=b) return flg? update(k,x):dat[k];

    delay(k);
    D vl = query(a,b,x,flg,k*2+1,l,(l+r)/2);
    D vr = query(a,b,x,flg,k*2+2,(l+r)/2,r);
    if(flg) dat[k] = merge(vl,vr);
    return merge(vl,vr);
  }

  //[a,b)の最小値を得る　find(a,b);
  D find(Int a,Int b){
    D res = query(a,b,{},false);
    return res;
  }
};


class CumulativeSum{
public:
  vector<Int> sum;
  CumulativeSum(){}
  CumulativeSum(vector<Int> A){
    Int n = A.size();
    sum.resize(n+1,0);
    for(Int i=1;i<=n;i++) sum[i] += sum[i-1] + A[i-1];
  }
  Int get(Int l,Int r){assert(l<=r && l>=0 && r<=(Int)sum.size());return sum[r] - sum[l];} //[l,r)
};

