long long hitung(long long x){
	int r = -1;
	long long ret = 0;
	priority_queue<pair<long long, int>> pq[m];
	// debug(x);
	for(int i = 0; i < n; i++){
		while(r + 1 < n && pref[r + 1] - pref[i] <= x){
			r += 1;
			for(int j = 0; j < m; j++)
				pq[j].push({b[r][j], r});
		}
		long long sum = 0;
		// debug(r);
		for(int j = 0; j < m; j++){
			while(!pq[j].empty() && pq[j].top().s < i)
				pq[j].pop();
			assert(!pq[j].empty());
			sum += pq[j].top().f;
		}
		ret = max(ret, sum);
	}
	return ret - x;
}

