int main(){
    long long marxism = -10000000000000;
    vector<stack<int> > ms;//monotonic stack;
    vector<int> dis;
    vector<long long> cf;//distance between shops,0:0->1;chafenshuzu
    vector< vector<int> > tickets;
    int shop,tic;
    scanf("%d %d",&shop,&tic);
    /*initialization*/
    cf.assign(shop-1,0);
    tickets.assign(tic,vector<int>());
    ms.assign(tic,stack<int>());
    dis.reserve(shop);
    /*done*/
    for (register int i = 1;i<shop;++i){
        int temp;scanf("%d",&temp);
        dis.push_back(-temp);
    }
    //convert the distance into "chafen" form;
    for (register int i = 0;i<shop;++i){
        for (register int j = 0;j<tic;++j){
            int temp;scanf("%d",&temp);
            tickets[j].push_back(temp);
        }
    }
    //get the tickets'value
    //tickets[i][j]:the value of ticket i in the shop j
    for (register int i = shop-1;i>=0;--i){
	long long result = 0;
        //enumerate start point from tail to head;
        for (register int j = 0;j<ms.size();++j){
            //process the "chafenshuzu" of each ticket.
            int cur = tickets[j][i],prev = 0;//prev is the previous shop,used to determine how large to shrink in the next shop;
            while (!ms[j].empty()){
                if (cur>tickets[j][ms[j].top()]){//the one we have is greater than the top of the stack;
                    cf[ms[j].top()-1] -=(tickets[j][ms[j].top()]-prev);
                    prev = tickets[j][ms[j].top()];
                    ms[j].pop();
                }
                else{
                    cf[ms[j].top()-1] -=(cur-prev);
                    break;
                }
            }
	    result += cur;
	    if (i) cf[i-1] +=cur;
            ms[j].push(i);
        }
	//update the 'chafen' completed;
        marxism = max(marxism,result);
        for (register int j = i;j<shop-1;++j){
            result +=  dis[j];
            result +=  cf[j];
            marxism = max(marxism,result);
        }
    }
    printf("%lld",marxism);
}

