void sol1(vel& sum, vvel& b, int i) {//O(nm)
    int n = ans.size();
    int m = b[0].size();
    vel mb(m,-1);
    for (int j = i; j < n; j++) {
        int qans = sum[i] - sum[j];
        rep(ind, m) {
            mmax(mb[ind], b[j][ind]);
            qans += mb[ind];
        }
        if (qans > ans[i]) {
            ans[i] = qans;
            ind[i] = j;
        }
    }
}
void sol_ran(vel& sum, vvel& b, int st,int to) {//O(nm+(y-x)(to-st)m)
    int x = ind[st];
    int y = ind[to];
    int m = b[0].size();
    vel stb(m, -1);
    for (int i = to; i < x; i++) {
        rep(j, m) {mmax(stb[j], b[i][j]);}
    }
    for (int i = to - 1; i >= st; i--) {
        rep(j, m) {mmax(stb[j], b[i][j]);}
        vel mb = stb;//mbは[i,x)
        for (int j = x; j <= y; j++) {
            int qans = sum[i] - sum[j];
            rep(ind, m) {
                mmax(mb[ind], b[j][ind]);
                qans += mb[ind];
            }
            if (qans > ans[i]) {ans[i] = qans;}
        }
    }
}
