void build(int v, int l, int r) {
   tr[v] = -INF;
   if (l < r) {
      int md = (l + r) >> 1;
      build(v << 1, l, md);
      build(v << 1 | 1, md + 1, r);
   }
}

void push(int v, int l, int r) {
   if (lazy[v]) {
      tr[v] += lazy[v];
      if (l < r) {
         lazy[v << 1] += lazy[v];
         lazy[v << 1 | 1] += lazy[v];
      }
      lazy[v] = 0;
   }
}

void add(int v, int l, int r, int L, int R, ll val) {
   push(v, l, r);
   if (L > r || R < l) return;
   if (L <= l && r <= R) {
      lazy[v] = val;
      push(v, l, r);
      return;
   }
   int md = (l + r) >> 1;
   add(v << 1, l, md, L, R, val);
   add(v << 1 | 1, md + 1, r, L, R, val);
   tr[v] = max(tr[v << 1], tr[v << 1 | 1]);
}

