void solve(int l,int r,int L,int R)//[l,r]のoptは[L,R]
{
	if(l>r) return;
	int t=(l+r)/2;
	int start=max(L,t);
	for(int i=0;i<m;i++) mx[i]=seg[i].get(t,start+1);
	ll sum=0;
	for(int i=0;i<m;i++) sum+=mx[i];
	int pos=start;
	ll now=sum-S[start];
	for(int i=start;i<=R;i++)
	{
		for(int j=0;j<m;j++)
		{
			if(mx[j]<B[i][j])
			{
				sum+=B[i][j]-mx[j];
				mx[j]=B[i][j];
			}
		}
		if(now<=sum-S[i])
		{
			now=sum-S[i];
			pos=i;
		}
	}
	//printf("%d %d : %lld\n",t,pos,now);
	ans[t]=now+S[t];
	solve(l,t-1,L,pos);
	solve(t+1,r,pos,R);
}
