      cin >> b[i][j];
    }
  }
  segment_tree tree(N);
  tree.update(1, 1, N, 1, 1, llinf);
  ll res = 0;
  for (int i = 1; i <= M; ++i){
    st[i].pb(1);
    res += b[1][i];
  }
  tree.update(1, 1, N, 1, 1, res);
  for (int i = 2; i <= N; ++i){
