const int N = 5006;
const int Lg = 13;
const int M = 205;
const ll inf = (ll)1e18;
int n, m, mat[M][N][Lg];
ll dp[N], a[N];

ll Query(int x, int l, int r) {
  int k = __lg(r - l + 1);
  return max(mat[x][l][k], mat[x][r - (1 << k) + 1][k]);
}
ll calc(int l, int r) {
  ll sm = 0;
  for (int i = 1; i <= m; i++)sm += Query(i, l, r);
  return sm - (a[r] - a[l]);
}

void go(int l, int r, int ql, int qr) {
  if (l > r)return;
  int mid = l + (r - l) / 2;
  ll val = LLONG_MIN, pos = 0;
  for (int i = ql; i <= min(mid, qr); i++) {
    ll ret = calc(i, mid);
    if (ret > val) {
      val = ret;
      pos = i;
    }
  }
  dp[mid] = val;
  go(l, mid - 1, ql, pos);
  go(mid + 1, r, pos, qr);
}
