#include <bits/stdc++.h>
#define int long long
using namespace std;

typedef pair<int,int> P;

int N, M, A[5005], B[5005][205], C[5005][5005];
map<P,int> point;

int getdis(int l, int r){ // [ l, r ]
  return A[r] - A[l];
}

void dfs(int l, int r, int x){ // [ l, r ]

  int m, maxv = 0;

  for(int i=l;i<=r;i++){

    if( maxv < B[i][x] ){
      maxv = B[i][x];
      m = i;
    }

  }

  C[l][m] += maxv;

  C[l][r+1] -= maxv;

  C[m+1][m] -= maxv;

  C[m+1][r+1] += maxv;

  if( l != m ) dfs( l, m - 1, x );

  if( m != r ) dfs( m + 1, r, x );

}

signed main(){

  cin>>N>>M;

  for(int i=1;i<N;i++){
    cin>>A[i];
    A[i] += A[i-1];
  }

  for(int i=0;i<N;i++){
    for(int j=0;j<M;j++){
      cin>>B[i][j];
    }
  }

  for(int i=0;i<M;i++) dfs( 0, N-1, i );

  for(int i=0;i<N;i++){

    for(int j=1;j<N;j++){

      C[i][j] += C[i][j-1];

    }

  }

  for(int i=0;i<N;i++){

    for(int j=1;j<N;j++){

      C[j][i] += C[j-1][i];

    }

  }

  int ans = 0;

  for(int i=0;i<N;i++){

    for(int j=i;j<N;j++){

      ans = max( ans, C[i][j] - getdis( i, j ) );

    }

  }

  cout<<ans<<endl;

  return 0;
}

