using namespace std;

const int MAXN = 5000;
const int MAXM = 200;
int n, m;
int a[MAXN+1];
int b[MAXM+1][MAXN+1];
int ans;

class Seg{
  private:
    int arr[MAXN*4+5];
  public:
    int id;
    void build(int now=1, int l=1, int r=n) {
      if (l == r) {
        arr[now] = b[id][l];
        return;
      }
      int mid = l + r >> 1;
      build(now*2  , l, mid);
      build(now*2+1,mid+1,r);
      arr[now] = max(arr[now*2], arr[now*2+1]);
    }
    int qry(int ql, int qr, int now=1, int l=1, int r=n) {
      if (ql <= l && r <= qr) {
        return arr[now];
      } else if (l > qr || r < ql) return 0;
      int mid = l + r >> 1, tmp = 0;
      tmp = max(tmp, qry(ql, qr, now*2  , l, mid));
      tmp = max(tmp, qry(ql, qr, now*2+1,mid+1,r));
      return tmp;
    }
} seg[MAXM+1];

void cal(int l, int r, int sl, int sr) {
  int mid = l + r >> 1, tmp = 0;
  pii mmax = pii(-1, -1);
  for (int i = sl; i <= min(mid, sr); i++) {
    tmp = a[i] - a[mid];
    for (int j = 1; j <= m; j++)
      tmp += seg[j].qry(i, mid);
    mmax = max(mmax, pii(tmp, i));
  }
  ans = max(ans, mmax.ff);
  if (mid > l)
    cal(l, mid-1, sl, mmax.ss);
  if (mid < r)
    cal(mid+1, r, mmax.ss, sr);
}

