  }
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++)
      cin >> b[j][i];
  for (int i = 1; i <= m; i++)
    seg[i].id = i, seg[i].build();
  cal(1, n, 1, n);
  cout << ans << "\n";
}

