inline void input()
{
	n = read<int>(), m = read<int>();
	for(int i = 1; i < n; ++i) a[i] = read<int>();
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j)
			b[j][i] = read<int>();
}

LL s[MAXN + 5][MAXN + 5];

inline void add_matrix(int x0, int x1, int y0, int y1, int val)
{
	if(x0 > x1 || y0 > y1) return;
	s[x0][y0] += val;
	s[x0][y1 + 1] -= val;
	s[x1 + 1][y0] -= val;
	s[x1 + 1][y1 + 1] += val;
}

inline void calc_ctb(int k)
{
	int *val = b[k];
	static int lst[MAXN + 5], nxt[MAXN + 5];
	static vector<int> stk;

	stk.clear();
	stk.push_back(0);
	for(int i = 1; i <= n; ++i)
	{
		while(SZ(stk) > 1 && val[i] > val[stk.back()]) stk.pop_back();
		lst[i] = stk.back();
		stk.push_back(i);
	}

	stk.clear();
	stk.push_back(n + 1);
	for(int i = n; i >= 1; --i)
	{
		while(SZ(stk) > 1 && val[i] >= val[stk.back()]) stk.pop_back();
		nxt[i] = stk.back();
		stk.push_back(i);
	}

	for(int i = 1; i <= n; ++i) add_matrix(lst[i] + 1, i, i, nxt[i] - 1, val[i]);
}

inline void solve_ctb()
{
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= n; ++j)
			s[i][j] += s[i - 1][j] + s[i][j - 1] - s[i - 1][j - 1];
}

inline void solve()
{
	for(int i = 1; i <= m; ++i) calc_ctb(i);
	solve_ctb();

	LL ans = 0;
	for(int i = 1; i <= n; ++i)
	{
		LL res = 0;
		for(int j = i; j <= n; ++j)
			chkmax(ans, s[i][j] - res), res += a[j];
	}
	printf("%lld\n", ans);
}

