      for(int i = 1; i <= n; i ++)
      {
            for(int j = 1; j <= m; j ++)
            {
                  int pos = get(i, n, j).sc;
                  ll res = 0;
                  for(int k = 1; k <= m; k ++)
                        res += get(i, pos, k).fr;
                  res -= pref[pos - 1] - pref[i - 1];
                  ans = max(ans, res);
            }
      }

      cout << ans << endl;
}

