        }
    }
    for (int i = n - 1; i >= 0; i--)
    {
        for (int j = n - 1; j >= 0; j--)
        {
            g[i][j] = g[i][j] + g[i + 1][j] + g[i][j + 1] - g[i + 1][j + 1];
        }
    }
    for (int i = 0; i < n; i++)
    {
        int len = 0;
        for (int j = i; j < n; j++)
        {
            ans = max(ans, g[i][j] - len);
            len += a[j];
        }
    }
    cout << ans;
}

