#include <iostream>
#include <vector>
#include <algorithm>
#include <map>
#include <cassert>
using namespace std;
using ll = long long;
template<class T> using vec = vector<T>;
template<class T> using vvec = vector<vec<T>>;

ll calc(int M,vec<ll>& LA,vvec<ll>& LB,vec<ll>& RA,vvec<ll>& RB){
    int nl = LA.size(),nr = RA.size();
    vec<map<ll,ll>> m(M,map<ll,ll>());
    for(int j=0;j<M;j++) for(int i=0;i<nr;i++) m[j][RB[i][j]]++;
    ll res = 0;

    auto inc = [&](int i){
        for(int j=0;j<M;j++) m[j][RB[i][j]]++;
    };

    auto dec = [&](ll i){
        for(int j=0;j<M;j++){
            m[j][RB[i][j]]--;
            if(m[j][RB[i][j]]<=0) m[j].erase(RB[i][j]);
        }
    };

    auto getsum = [&](){
        ll res = 0;
        for(int j=0;j<M;j++) res += m[j].rbegin()->first;
        return res;
    };

    auto check = [&](int i){
        ll res = RA[i]-RA[i-1]-getsum();
        dec(i);
        res += getsum();
        inc(i);
        return res>0;
    };

    int r = nr-1;
    ll distl = RA[0]-LA[0];
    for(int l=0;l<nl;l++){
        for(int j=0;j<M;j++) m[j][LB[l][j]]++;
        if(l!=0) distl += LA[l-1]-LA[l];
        while(r>0 && check(r)){
            dec(r);
            r--;
        }
        res = max(res,getsum()-distl-(RA[r]-RA[0]));
    }
    return res;
}

ll solve(vec<ll>& A,vvec<ll>& B){
    int N = A.size(),M = B[0].size();
    if(A.empty()) return 0;
    if(A.size()==1){
        ll sum = 0;
        for(int i=0;i<M;i++) sum += B[0][i];
        return sum;
    }
    vec<ll> LA,RA;
    vvec<ll> LB,RB;
    ll res = 0;
    for(int i=0;i<N;i++){
        if(i<N/2){
            LA.push_back(A[i]);
            vec<ll> l;
            for(int j=0;j<M;j++){
                l.push_back(B[i][j]);
            }
            LB.push_back(l);
        }else{
            RA.push_back(A[i]);
            vec<ll> r;
            for(int j=0;j<M;j++){
                r.push_back(B[i][j]);
            }
            RB.push_back(r);
        }
    }
    res = max({res,solve(LA,LB),solve(RA,RB)});
    reverse(LA.begin(),LA.end());
    reverse(LB.begin(),LB.end());
    res = max(res,calc(M,LA,LB,RA,RB));
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N,M;
    cin >> N >> M;
    vec<ll> A(N);
    for(int i=1;i<N;i++){
        cin >> A[i];
        A[i] += A[i-1];
    }
    vvec<ll> B(N,vec<ll>(M,0));
    for(int i=0;i<N;i++) for(int j=0;j<M;j++) cin >> B[i][j];
    cout << solve(A,B) << endl;
}

