namespace Seg {
	static const int maxP = 16389;
	#define lc (x << 1)
	#define rc (x << 1 | 1)

	LL a[maxP], tag[maxP];

	inline void pushup(int x) {
		a[x] = max(a[lc], a[rc]);
	}

	inline void totag(int x, LL d) {
		a[x] += d;
		tag[x] += d;
	}

	inline void pushdown(int x) {
		if (tag[x]) {
			totag(lc, tag[x]);
			totag(rc, tag[x]);
			tag[x] = 0;
		}
	}

	void build(int x, int l, int r) {
		if (l == r) {
			a[x] = dis[l];
			return;
		}
		tag[x] = 0;
		int mid = (l + r) >> 1;
		build(lc, l, mid);
		build(rc, mid+1, r);
		pushup(x);
	}

	void add(int x, int l, int r, int tl, int tr, LL d) {
		if (tl <= l && r <= tr) {totag(x, d); return;}
		int mid = (l + r) >> 1;
		pushdown(x);
		if (tl <= mid) add(lc, l, mid, tl, tr, d);
		if (mid < tr) add(rc, mid+1, r, tl, tr, d);
		pushup(x);
	}

	LL get(int x, int l, int r, int tl, int tr) {
		if (tl <= l && r <= tr) return a[x];
		int mid = (l + r) >> 1;
		pushdown(x);
		if (tr <= mid) return get(lc, l, mid, tl, tr);
		if (mid < tl) return get(rc, mid+1, r, tl, tr);
		return max(get(lc, l, mid, tl, mid), get(rc, mid+1, r, mid+1, tr));
	}

	void build() {build(1, 1, n);}
	void add(int l, int r, LL d) {add(1, 1, n, l, r, d);}
	LL get(int l, int r) {return get(1, 1, n, l, r);}

	#undef lc
	#undef rc
}

int main() {

	n = ri(), m = ri();
	dis[1] = 0; rep (i, 2, n) dis[i] = dis[i - 1] + rl();
	rep (i, 1, n) rep (j, 1, m) a[i][j] = ri();

	Seg::build();

	rep (i, 1, n) {
		rep (j, 1, m) {
			Seg::add(i, i, a[i][j]);
			int cur = i - 1;
			for (; Top[j] && a[i][j] >= a[stack[j][Top[j]]][j]; cur = stack[j][--Top[j]]) 
				Seg::add(stack[j][Top[j] - 1] + 1, cur, a[i][j] - a[stack[j][Top[j]]][j]);
			stack[j][++Top[j]] = i;
		}
		LL d = Seg::get(1, i);
		ans = max(ans, d - dis[i]);
	}

	printf("%lld\n", ans);

	return 0;
}

