void init(int n){
	seg_n = 1;
	while(seg_n<n) seg_n<<=1;
	rep(i, 2*seg_n-1) dat[i] = -INF;
}

// v[k] <- a
void update(int k, ll a){
	k += seg_n - 1;
	dat[k] = a;
	while(k>0){
		k = (k-1)/2;
		dat[k] = max(dat[k*2+1], dat[k*2+2]);
	}
}

// min(v[a], v[a+1],..., v[b-1])
// to use: query(a, b, 0, 0, seg_n);
ll rmq(int a, int b, int k, int l, int r){
	if(r <= a || b <= l) return -INF;
	if(a <= l && r <= b) return dat[k];
	return max(rmq(a, b, k*2+1, l, (l+r)/2), rmq(a, b, k*2+2, (l+r)/2, r));
}

void g(int l, int r){
	if(l>=r) return;
	ll mx = rmq(l, r, 0, 0, seg_n);
	ll p = lower_bound(v, v+n, P(mx, l))->snd;
	//cerr<<l<<" "<<r<<" "<<mx<<" "<<p<<endl;
	s[l][p] += mx;
	s[l][r] -= mx;
	s[p+1][p] -= mx;
	s[p+1][r] += mx;
	g(l, p);
	g(p+1, r);
}

void f(int item){
	//cerr<<item<<endl;
	rep(i, n) v[i] = P(b[item][i], i);
	sort(v, v+n);
	//rep(i, n) cerr<<v[i].fst<<" "<<v[i].snd<<endl;
	//while(1);
	init(n);
	rep(i, n) update(i, b[item][i]);
	g(0, n);
}

