		b[i][n + 1] = INF;
		s[t = 1] = n + 1;
		for (int j = n; j; --j) {
			while (b[i][j] >= b[i][s[t]]) --t;
			nxt[i][j] = s[t];
			s[++t] = j;
		}
	}
	for (int i = n; i; --i) a[i] = -op[i - 1];
	for (int i = 1; i <= m; ++i) Q[i].push_back(n + 1);
	for (int i = 1, j, k, l, r; i <= n; ++i) {
		a[i] += op[i - 1];
		for (j = 1; j <= m; ++j) {
			while (Q[j].front() < i) k = Q[j].front(), Q[j].pop_front();
			if (Q[j].front() != n + 1) a[Q[j].front()] += b[j][k];
			for (l = i, r = Q[j].front(), t = 0; l && l < r; l = nxt[j][l]) s[++t] = l;
			while (t) {
				if (Q[j].front() != n + 1) a[Q[j].front()] -= b[j][s[t]];
