typedef long long LL;
const int N = 5007;
const int M = 202;

LL G[N][N], D[N];
int b[M][N], pre[N], suf[N], ip[N], is[N];
int n, m;

inline void add(int l, int m, int r, int val) {
  G[l][m] += val;
  G[l][r + 1] -= val;
  G[m + 1][m] -= val;
  G[m + 1][r + 1] += val;
}

int main() {
  scanf("%d%d", &n, &m);
  for (int i = 2; i <= n; i ++) {
    scanf("%lld", &D[i]);
    D[i] += D[i - 1];
  }
  for (int i = 1; i <= n; i ++)
    for (int j = 1; j <= m; j ++) scanf("%d", &b[j][i]);
  for (int j = 1; j <= m; j ++) {
    for (int i = 1; i <= n; i ++) {
      if (b[j][i] > pre[i - 1]) {pre[i] = b[j][i]; ip[i] = i;}
      else {pre[i] = pre[i - 1]; ip[i] = ip[i - 1];}
    }
    for (int i = n; i >= 1; i --) {
      if (b[j][i] >= suf[i + 1]) {suf[i] = b[j][i]; is[i] = i;}
      else {suf[i] = suf[i + 1]; is[i] = is[i + 1];}
    }
    for (int i = 1, l, r; i <= n; i ++) {
      if (ip[i] != i) l = ip[i] + 1;
      else l = 1;
      if (is[i] != i) r = is[i] - 1;
      else r = n;
      add(l, i, r, b[j][i]);
    }
  }
  LL ans = 0;
  for (int i = 1; i <= n; i ++)
    for (int j = 1; j <= n; j ++) {
      G[i][j] += G[i - 1][j] + G[i][j - 1] - G[i - 1][j - 1];
      if (i <= j) ans = max(ans, D[i] - D[j] + G[i][j]);
    }
  printf("%lld\n", ans);
  return 0;
}

