const int maxn = 5e3 + 10;
const int maxm = 200 + 10;

int n, m;
ll a[maxn];
int b[maxn][maxm][10];
ll answer = 0;

ll get(int s, int t){
	ll A = 0, B = 0;
	int len = log2(t-s+1);
	for (int i = 1; i <= m; i++)
		A += max(b[s][i][len], b[t-(1<<len)+1][i][len]);
	B = a[t-1] - a[s-1];
	return A - B;
}

void dp_cal(int l, int r, int lo, int hi){
	if (r <= l)
		return;
	int mid = (l + r) >> 1;
	int opt = lo;
	for (int i = lo; i <= min(hi,mid); i++)
		if (get(i, mid) > get(opt, mid))
			opt = i;
	answer = max(answer, get(opt, mid));
	dp_cal(l, mid, lo, opt);
	dp_cal(mid+1, r, opt, hi);
}

int main(){
	ios_base::sync_with_stdio(false);
	cin >> n >> m;
	for (int i = 1; i <= n-1; i++){
		cin >> a[i];
