		for (int j = 1; j <= m; j++)
			cin >> b[i][j][0];
	for (int k = 1; k <= 9; k++)
		for (int i = 1; i + (1<<(k-1)) <= n; i++)
			for (int j = 1; j <= m; j++)
				b[i][j][k] = max(b[i][j][k-1], b[i+(1<<(k-1))][j][k-1]);
	dp_cal(1, n+1, 1, n);
	cout << answer << '\n';
}

