inline int Rd() {
	int x = 0; char ch = getchar();
	while(ch < '0' || ch > '9') ch = getchar();
	while(ch >= '0' && ch <= '9') x = x * 10 + ch - '0', ch = getchar();
	return x;
}
inline void ChkMax(long long &aa, long long bb) {
	if(aa < bb) aa = bb;
	return;
}

int main() {
	n = Rd(), m = Rd();
	for(reg int i = 2; i <= n; ++i) {
		dis[i] = Rd();
		dis[i] += dis[i - 1];
	}
	for(reg int i = 1; i <= n; ++i) {
		for(reg int j = 1; j <= m; ++j) {
			p[i][j] = Rd();
			if(upper[j] < p[i][j]) upper[j] = p[i][j];
		}
	}
	long long maxp = 0;
	for(reg int i = 1; i <= m; ++i) maxp += upper[i];
	reg long long ans = 0, cur_p = 0;
	for(reg int i = 1; i <= n; ++i) {
		cur_p = 0;
		memset(cur_max, 0, sizeof cur_max);
		for(reg int j = i; j <= n; ++j) {
			for(reg int k = 1; k <= m; ++k) {
				if(p[j][k] > cur_max[k]) {
					cur_p += p[j][k] - cur_max[k];
					cur_max[k] = p[j][k];
				}
			}
			if(maxp - (dis[j] - dis[i]) <= ans) break;
			ChkMax(ans, cur_p - (dis[j] - dis[i]));
		}
	}
	cout << ans << endl;
