ll ans, a[maxn], c[maxn][maxn];
void add(int lx, int rx, int ly, int ry, int val)
{
	c[lx][ly] += val;
	c[lx][ry + 1] -= val;
	c[rx + 1][ly] -= val;
	c[rx + 1][ry + 1] += val;
} 
int main()
{
	scanf("%d%d", &n, &m);
	for(int i = 2; i <= n; ++i) 
	{
		scanf("%lld", &a[i]);
		a[i] += a[i - 1];
	}
