	for(int j = 1; j <= m; ++j)
	{
		top = 0;
		for(int i = 1; i <= n; ++i)
		{
			while(top && b[sta[top - 1]][j] <= b[i][j]) --top;
			if(top) l[i][j] = sta[top - 1];
			else l[i][j] = 0;
			sta[top++] = i;
		}
		top =  0;
		for(int i = n; i; --i)
		{
			while(top && b[sta[top - 1]][j] < b[i][j]) --top;
			if(top) r[i][j] = sta[top - 1];
			else r[i][j] = n + 1;
			sta[top++] = i;
		}
	}
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j)
			add(l[i][j] + 1, i, i, r[i][j] - 1, b[i][j]);
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= n; ++j)
		{
			c[i][j] = c[i][j] + c[i - 1][j] + c[i][j - 1] - c[i - 1][j - 1];
			if(i <= j) ans = max(ans, c[i][j] - (a[j] - a[i]));
		}
	cout << ans << endl;
	return 0;
}

