using namespace std;

int n,m,d[201][5010],it[201][20010];
long long s[5010][5010],a[5010];

void tree_build(int tree,int p,int l,int r)
{
    if (l==r)
    {
        it[tree][p]=l;
        return;
    }
    tree_build(tree,p*2,l,(l+r)/2);
    tree_build(tree,p*2+1,(l+r)/2+1,r);
    if (d[tree][it[tree][p*2]]>d[tree][it[tree][p*2+1]]) it[tree][p]=it[tree][p*2];
    else it[tree][p]=it[tree][p*2+1];
}

int get(int tree,int p,int l,int r,int a,int b)
{
    if (r<a or l>b) return 0;
    if (l>=a and r<=b)
        return it[tree][p];
    int x1=get(tree,p*2,l,(l+r)/2,a,b),x2=get(tree,p*2+1,(l+r)/2+1,r,a,b);
    if (d[tree][x1]>d[tree][x2])return x1;
    else return x2;
}

void array_build(int ind,int l,int r)
{
    if (r<l) return;
    int opt=get(ind,1,1,n,l,r);
    s[l][opt]+=d[ind][opt];
    s[l][r+1]-=d[ind][opt];
    s[opt+1][opt]-=d[ind][opt];
    s[opt+1][r+1]+=d[ind][opt];
    array_build(ind,l,opt-1);
    array_build(ind,opt+1,r);
}

int main()
{
    //freopen("input.txt","r",stdin);
