    for (int i=1;i<=n;i++)
        for (int j=1;j<=m;j++)
            scanf("%d",&d[j][i]);
    for (int i=1;i<=m;i++)
        tree_build(i,1,1,n);
    for (int i=1;i<=m;i++)
        array_build(i,1,n);
    for (int i=1;i<=n;i++)
    {
        for (int j=1;j<=n;j++)
            s[i][j]+=s[i][j-1];
        for (int j=1;j<=n;j++)
            s[i][j]+=s[i-1][j];
    }
    long long res=-1;
    for (int i=1;i<=n;i++)
        for (int j=i;j<=n;j++)
