void prepare()
{
	int cur = 1, val = -1;
	for (int i=1;i<=5000;i++)
	{
		if (i == cur)	
		{
			cur *= 2;
			val++;
		}	
		log_2[i] = val;
	}
}

int val(int l,int r)
{
	int d = (r-l+1);
	int z = log_2[d];
	int ans = (a[l] - a[r]);
	for (int k=1;k<=m;k++)
		ans += max(rmq[k][l][z],rmq[k][r-(1<<z)+1][z]);			
	return ans;		
}

void cal(int l,int r,int opt_l,int opt_r)
{
	if (l > r)
		return;
	int mi = (l+r)/2;
	int opt_val = -1e18, pos = -1;
	for (int i=opt_l;i<=min(mi,opt_r);i++)
	{
		int cost = val(i,mi);
		if (cost > opt_val)
		{
			opt_val = cost;
			pos = i;
		}
	}
	f[mi] = opt_val;
	cal(l,mi-1,opt_l,pos);
	cal(mi+1,r,pos,opt_r);
}

