void f(int s, int e, int p, int q) {
	if(s > e || p > q) return;
	int m = (s+e) >> 1;
	ll hc = -INFLL; int hi = p;
	memset(MX, 0, (M+2)<<2);
	ll sum = 0;
	for(int i = p; i <= q; i++) {
