ll build(ll curr_k, ll ind = 0, ll cl = 0, ll cr = maxn - 1){
	if(cl > cr){
		return 0;
	} else if(cl == cr){
		seg[curr_k][ind] = val[curr_k][cl];
		return seg[curr_k][ind];
	}

	ll mid = (cl + cr) / 2;

	seg[curr_k][ind] = build(curr_k, 2 * ind + 1, cl, mid);
	seg[curr_k][ind] = std::max(seg[curr_k][ind], build(curr_k, 2 * ind + 2, mid + 1, cr));

	return seg[curr_k][ind];
}

ll query(ll curr_k, ll ql, ll qr, ll ind = 0, ll cl = 0, ll cr = maxn - 1){
	if(ql <= cl and cr <= qr){
		return seg[curr_k][ind];
	} else if(cr < ql or qr < cl){
		return 0;
	}

	ll mid = (cl + cr) / 2;

	ll v = query(curr_k, ql, qr, 2 * ind + 1, cl, mid);;
	v = std::max(v, query(curr_k, ql, qr, 2 * ind + 2, mid + 1, cr));

	return v;
}

