using namespace std;

template <typename T>
class SegmentTree {
	using func_t = function<T(T, T)>;
	const int n;
	const T id;
	func_t merge;
	vector<T> data;
	int size(int n) {
		int res;
		for (res = 1; res < n; res <<= 1);
		return res;
	}
	T sub(int l, int r, int node, int lb, int ub) {
		if (ub <= l || r <= lb) return id;
		if (l <= lb && ub <= r) return data[node];
		return merge(sub(l, r, node * 2, lb, (lb + ub) / 2), sub(l, r, node * 2 + 1, (lb + ub) / 2, ub));
	}
public:
	SegmentTree(int n_, T id_, func_t merge_) :
		n(size(n_)), id(id_), merge(merge_), data(size(n_) * 2, id_) {}
	SegmentTree(const vector<T>& data_, T id_, func_t merge_) :
		n(size(data_.size())), id(id_), merge(merge_), data(size(data_.size()) * 2, id_) {
		for (int i = 0; i < data_.size(); i++)
			data[i + n] = data_[i];
		for (int i = n - 1; i >= 0; i--)
			data[i] = merge(data[i * 2], data[i * 2 + 1]);
	}
	void Update(int p, T val) {
		p += n;
		data[p] = val;
		while (p >>= 1) data[p] = merge(data[p * 2], data[p * 2 + 1]);
	}
	void Add(int p, T val) {
		p += n;
		data[p] += val;
		while (p >>= 1) data[p] = merge(data[p * 2], data[p * 2 + 1]);
	}
	T Find(int l, int r) {
		return sub(l, r + 1, 1, 0, n);
	}
};

signed main()
{
	int N, M;
	cin >> N >> M;
	vector<int> A(N - 1), S(N);
	vector<vector<int>> B(N, vector<int>(M));
	vector<SegmentTree<int>> sts(M, SegmentTree<int>(N, 0, [](int x, int y) { return max(x, y); }));
	for (int i = 0; i < N - 1; i++) {
		cin >> A[i];
		S[i + 1] = S[i] + A[i];
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < M; j++) {
			cin >> B[i][j];
			sts[j].Update(i, B[i][j]);
		}
	}
	int res = 0, tmp = 0;
	int l = 0, r = 0;
	for (int i = 0; i < M; i++) {
		tmp += B[0][i];
	}
	res = tmp;
	for (int i = 0; i < N; i++) {
		int val = -(S[i] - S[0]);
		for (int j = 0; j < M; j++) {
			val += sts[j].Find(0, i);
		}
		if (val > res) {
			res = val;
			r = i;
		}
	}
	for (int i = 0; i <= r; i++) {
		int val = -(S[r] - S[i]);
		for (int j = 0; j < M; j++) {
			val += sts[j].Find(i, r);
		}
		if (val >= res) {
			res = val;
			l = i;
		}
	}
	cout << res << endl;
	return 0;
}

