    REP(i, N - 1)
    {
        lint tmp;
        cin >> tmp;
        As[i + 2] = As[i + 1] + tmp;
    }

    REP(n, N) REP(m, M) cin >> B[m][n + 1];

    memset(s, 0, sizeof(s));
    REP(m, M)
    {
        set<int> used;
        used.insert(0);
        used.insert(N + 1);
        priority_queue<pint, vector<pint>> pq;
        FOR(i, 1, N + 1) pq.push(pint(B[m][i], i));
        while (!pq.empty())
        {
            pint pa = pq.top();
            pq.pop();

            int n = pa.second;
            int r = *used.lower_bound(n);
            int l = *prev(used.lower_bound(n)) + 1;

            s[l][n] += pa.first;
