    for(int i = 2; i <= n; i++){
        int a;
        scanf("%d", &a);
        pref[i] = pref[i - 1] + a;
        lg[i] = lg[i / 2] + 1;
    }
    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= m; j++){
            scanf("%lld", &b[i][j]);
            mx[i][j][0] = b[i][j];
        }
    }
    for(int i = 1; i <= m; i++){
        for(int j = 1; j <= lg[n]; j++){
            for(int t = 1; t <= n - (1 << j) + 1; t++){
                mx[t][i][j] = max(mx[t][i][j - 1], mx[t + (1 << j) - 1][i][j - 1]);
            }
        }
    }
    for(int i = 1; i <= n; i++){
