void solve (int n)
{
    int m;
    cin >> m;

    vll pos(n);
    forn (i, n) if (i != 0)
    {
        int a;
        cin >> a;
        pos[i] = pos[i - 1] + a;
    }

    vvi cost(n, vi(m));
    forn (i, n) forn (j, m) cin >> cost[i][j];

    vvi lft(n, vi(m, -1)), rgt(n, vi(m, n));

    vector<vll> pref(n + 1, vll(n + 1));

    forn (j, m)
    {
        vii active;
        forn (i, n)
        {
            while (!active.empty() && cost[i][j] > active.back().fst)
            {
                rgt[active.back().snd][j] = i;
                active.pop_back();
            }
            lft[i][j] = (active.empty() ? -1 : active.back().snd);
            active.pb(mp(cost[i][j], i));
        }

        forn (i, n)
        {
//            int pl = i - 1, pr = i + 1;
//            while (pl >= 0 && cost[pl][j] < cost[i][j])
//                --pl;
//            while (pr < n && cost[pr][j] < cost[i][j])
//                ++pr;
//            lft[i][j] = pl;
//            rgt[i][j] = pr;

            // (lft[i][j], rgt[i][j])
            assert(lft[i][j] + 1 <= rgt[i][j] - 1);
            // add to [lft[i][j] + 1, i] x [i, rgt[i][j] - 1]
            int l1 = lft[i][j] + 1, r1 = i + 1;
            int l2 = i, r2 = rgt[i][j];
            pref[r1][r2] += cost[i][j];
            pref[r1][l2] -= cost[i][j];
            pref[l1][r2] -= cost[i][j];
            pref[l1][l2] += cost[i][j];
        }
    }

    vector<vll> value(n, vll(n));
    for (int i = n; i > 0; i--)
    for (int j = n; j > 0; j--)
    {
        value[i - 1][j - 1] += pref[i][j];
        pref[i][j - 1] += pref[i][j];
        pref[i - 1][j] += pref[i][j];
        pref[i - 1][j - 1] -= pref[i][j];
    }

    ll ans = 0;
    forn (j, n) forn (i, j)
    {
        // val at [i, j]
        ll cur = value[i][j];
        cur -= pos[j] - pos[i];
        ans = max(ans, cur);
    }

    cout << ans << '\n';
}

