void solve() {
    cin >> N >> M;
    A.resize(N - 1);
    REP(i, N - 1) {
        cin >> A[i];
        cum[i + 1] = cum[i] + A[i];
    }
    REP(j, M) val[j].resize(N);
    REP(i, N) REP(j, M) { cin >> val[j][i]; }
    auto f = [](int a, int b) { return max(a, b); };
    vector<DisjointSparseTable<int>> tables;
    REP(j, M) tables.emplace_back(val[j], f);
    // REP(j, M) { tables[j] = new DisjointSparseTable(val[j], f); }
    vector<int> mxR(N, 0);
    vector<int> mnL(N + 1, N);
    // update mxR
    REP(i, N) {
        int mx = i + 1;
        REP(j, M) {
            int ok = i + 1, ng = N + 1;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (mid == i + 1) {
                    ok = mid;
                    break;
                } else if (tables[j].query(i + 1, mid) < val[j][i])
                    ok = mid;
                else
                    ng = mid;
            }
            chmax(mx, ok);
        }
        mxR[i] = mx;
    }
    // update mnL
    REPR(i, N) {
        int mn = i;
        REP(j, M) {
            int ok = i, ng = -1;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (tables[j].query(mid, i) < val[j][i])
                    ok = mid;
                else
                    ng = mid;
            }
            chmin(mn, ok);
        }
        mnL[i + 1] = mn;
    }
    ll ans = 0;
    // REP(i, N) {
    //     DEBUG(i);
    //     DEBUG(mxR[i]);
    //     DEBUG(mnL[i + 1]);
    // }
    REP(l, N) {
        FOR(r, l + 1, N + 1) {
            if (mxR[l] >= r && mnL[r] <= l) {
                ll cost = cum[r - 1] - cum[l];
                ll res = 0;
                REP(j, M) { res += tables[j].query(l, r); }
                chmax(ans, res - cost);
            }
        }
    }
    print(ans);
}

