inline ll min(ll a, ll b) {
    return (a > b) ? b : a;
}

inline ll max(ll a, ll b) {
    return (a > b) ? a : b;
}

const int N = 5e3 + 7;;
const int inf = 1e9 + 7;
const ll linf = 1e18 + 9;
const double eps = 1e-004;

ll a[N];
int n, m;
ll numlog[N], pref[N];
ll b[N][203], ans;
ll table[203][20][N];

void build (int pos) {
    for (int i = 0; i <= numlog[n]; i++) {
        int curlen = (1 << i);
        for (int j = 1; j <= n; j++) {
            if (!i) {
                table[pos][i][j] = b[j][pos];
                continue;
            }
            table[pos][i][j] = max(table[pos][i - 1][j], table[pos][i - 1][j + curlen / 2]);
        }
    }
}

int get (int pos, int l, int r) {
    int curlog = numlog[r - l + 1];
    return max(table[pos][curlog][l], table[pos][curlog][r - (1 << curlog) + 1]);
}

void divide (int l, int r, int optl, int optr) {
    if (l > r) return ;
    int mid = (l + r) >> 1, opt = -1;
    ll c = 0, res;
    for (int i = optl; i <= min(mid, optr); i++) {
        res = 0;
        for (int j = 1; j <= m; j++)
            res += get(j, i, mid);
        res -= pref[mid - 1] - pref[i - 1];
        if (res > c) {
            c = res;
            opt = i;
        }
    }
    ans = max(ans, c);
    divide(l, mid - 1, optl, opt);
    divide(mid + 1, r, opt, optr);
}

void pre () {
    scanf ("%d %d", &n, &m);
    for (int i = 2; i < N; i++) {
        numlog[i] = numlog[i / 2] + 1;
    }
    for (int i = 1; i < n; i++) {
        scanf ("%I64d", &a[i]);
        pref[i] = pref[i - 1] + a[i];
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            scanf ("%I64d", &b[i][j]);
        }
    }
    for (int i = 1; i <= m; i++) {
        build(i);
    }
}

