	for (int i = n; i; i--) {
		modify(1, 1, n, i, i, -A[i]);
		for (int j = 1; j <= m; j++) {
			while (top[j] && B[i][j] > B[q[top[j]][j]][j]) {
				modify(1, 1, n, q[top[j]][j], q[top[j] - 1][j] - 1, -B[q[top[j]][j]][j]);
				top[j]--;
			}
			modify(1, 1, n, i, q[top[j]][j] - 1, B[i][j]);
			q[++top[j]][j] = i;
		}
		ans = max(ans, getmax(1, 1, n, i, n) + A[i - 1]);
	}
	printf("%lld\n", ans);
	return 0;
}

