    for (int i=2;i<=n;i++)
        scanf("%lld",&a[i]) , a[i] += a[i-1];
    for (int i=1;i<=n;i++)
        for (int j=1;j<=m;j++)
            scanf("%d",&b[j][i]);
}
inline void solve(void)
{
    for (int i=1;i<=m;i++)
    {
        for (int j=1;j<=n;j++)
        {
            while ( top && b[i][j] >= b[i][st[top]] )
                R[i][st[top]] = j-1 , top--;
            st[++top] = j;
        }
        while ( top ) R[i][st[top]] = n , top--;
        for (int j=n;j>=1;j--)
        {
            while ( top && b[i][j] >= b[i][st[top]] )
                L[i][st[top]] = j+1 , top--;
            st[++top] = j;
        }
        while ( top ) L[i][st[top]] = 1 , top--;
        for (int j=1;j<=n;j++)
        {
            sum[L[i][j]][j] += b[i][j];
