ll ans; 
struct SegTree
{
	struct Tree { ll tag, mx; } t[N << 2];
	void clear(int p, int l, int r)
		{
			t[p].tag = 0, t[p].mx = 0;
			if(l == r) return;
			int mid = (l + r) >> 1; 
			clear(p << 1, l, mid), clear(p << 1 | 1, mid + 1, r); 
		}
	void modify(int p, int l, int r, int ql, int qr, int x)
		{
			if(ql <= l && r <= qr) return (void) (t[p].tag += x, t[p].mx += x);
			int mid = (l + r) >> 1;
			if(ql <= mid) modify(p << 1, l, mid, ql, qr, x);
			if(mid < qr) modify(p << 1 | 1, mid + 1, r, ql, qr, x);
			t[p].mx = max(t[p << 1].mx, t[p << 1 | 1].mx) + t[p].tag; 
		}
	ll query(int p, int l, int r, int ql, int qr)
		{
			if(ql <= l && r <= qr) return t[p].mx;
			int mid = (l + r) >> 1; ll ans = 0;
			if(ql <= mid) ans = query(p << 1, l, mid, ql, qr);
			if(mid < qr) ans = max(ans, query(p << 1 | 1, mid + 1, r, ql, qr));
			return ans + t[p].tag; 
		}
} T; 

