class range {private: struct I{int x;int operator*(){return x;}bool operator!=(I& lhs){return x<lhs.x;}void operator++(){++x;}};I i,n;
public:range(int n):i({0}),n({n}){}range(int i,int n):i({i}),n({n}){}I& begin(){return i;}I& end(){return n;}};

int N, M;
ll A[5020], B[210][5020];
ll lm[210][5020], rm[210][5020];

ll solve(int fr, int to) {
  if (to - fr == 1) {
    ll sum = 0;
    for (int i : range(M)) sum += B[i][fr];
    return sum;
  }
  int mid = (fr + to) / 2;
  ll ret = max(solve(fr, mid), solve(mid, to));

  for (int j : range(mid - fr + 1)) {
    for (int i : range(M)) {
      if (j == 0) lm[i][j] = 0;
      else lm[i][j] = max(lm[i][j - 1], B[i][mid - j]);
    }
  }
  for (int j : range(to - mid + 1)) {
    for (int i : range(M)) {
      if (j == 0) rm[i][j] = 0;
      else rm[i][j] = max(rm[i][j - 1], B[i][mid + j - 1]);
    }
  }

  /*
  for (int i : range(M)) {
    for (int j : range(mid - fr + 1)) cout << lm[i][j] <<" ";
    cout << endl;
  }
  for (int i : range(M)) {
    for (int j : range(to - mid + 1)) cout << rm[i][j] <<" ";
    cout << endl;
  }
  */

  int ptr2 = to - mid;
  for (int ptr1 = 1; ptr1 <= mid - fr; ++ptr1) {
    ll curr_cost = -A[mid + ptr2 - 1] + A[mid - ptr1];
    //cout << "#" << curr_cost << endl;
    for (int i : range(M)) {
      curr_cost += max(lm[i][ptr1], rm[i][ptr2]);
      //cout << max(lm[i][ptr1], rm[i][ptr2]) << endl;
    }
    ret = max(ret, curr_cost);
    //cout << curr_cost << endl;

    while (ptr2 >= 2) {
      ptr2--;
      assert(ptr2 >= 1);
      ll cand_cost = -A[mid + ptr2 - 1] + A[mid - ptr1];
      for (int i : range(M)) cand_cost += max(lm[i][ptr1], rm[i][ptr2]);

      if (cand_cost >= curr_cost) {
        curr_cost = cand_cost;
        ret = max(ret, curr_cost);
      } else {
        ptr2++;
        break;
      }
    }
  }

  // cout<<"#"<<fr<<" "<<to<<" => "<<ret<<endl;

  return ret;
}

int main() {
  while (scanf("%d%d", &N, &M) != EOF) {
    A[0] = 0;
    for (int i : range(N - 1)) {
      ll x;
      scanf("%lld", &x);
      A[i + 1] = A[i] + x;
    }
    for (int i : range(N)) {
      for (int j : range(M)) {
        scanf("%lld", &B[j][i]);
      }
    }

    ll ret = solve(0, N);
    printf("%lld\n", ret);
  }
}

