			ans[t][pre[t] + 1] += tmp[i].value;
			ans[t][t + 1] -= tmp[i].value;
			ans[nxt[t]][pre[t] + 1] -= tmp[i].value;
			ans[nxt[t]][t + 1] += tmp[i].value;
			nxt[pre[t]] = nxt[t];
			pre[nxt[t]] = pre[t];
		}
	}
	for (int i = 1; i <= n; i++)
	for (int j = 1; j <= n; j++)
		ans[i][j] += ans[i - 1][j] + ans[i][j - 1] - ans[i - 1][j - 1];
	long long finalans = 0;
	for (int i = 1; i <= n; i++)
	for (int j = i; j <= n; j++)
		finalans = max(finalans, ans[j][i] - dist[j] + dist[i]);
	cout << finalans << endl;
	return 0;
}

