void update(int v, ll val)
{
	mx[v] += val;
	lazy[v] += val;
}

void shift(int v)
{
	update(2 * v, lazy[v]);
	update(2 * v + 1, lazy[v]);
	lazy[v] = 0;
}

void merge(int v)
{
	mx[v] = max(mx[2 * v], mx[2 * v + 1]);
}

void add(int l, int r, ll val, int s = 0, int e = n, int v = 1)
{
	if (l >= e || r <= s)
		return;
	if (l <= s && e <= r)
	{
		update(v, val);
		return;
	}
	shift(v);
	int mid = (s + e) / 2;
	add(l, r, val, s, mid, 2 * v);
	add(l, r, val, mid, e, 2 * v + 1);
	merge(v);
}

