#define MIN(a,b) (((a)<(b))?(a):(b))
#define MAX(a,b) (((a)>(b))?(a):(b))

long N, M;
long A[5001];
long B[5001][201];

long solve(long s) {
	long i, j;
	long max_B[201] = {0};
	long umai;
	long max_umai = -INF;
	long cost;

	for(i=s;i<=N;i++) {
		umai = 0;
		for(j=1;j<=M;j++) {
			max_B[j] = MAX(max_B[j], B[i][j]);
			umai += max_B[j];
		}
		cost = 0;
		for(j=s;j<i;j++) {
			cost += A[j];
		}
		max_umai = MAX(max_umai, umai-cost);
	}

	return max_umai;
}

int main() {
	long i, j;
	long ans = -INF;

	sl(N); sl(M);
	for(i=1;i<N;i++) {
		sl(A[i]);
	}
	for(i=1;i<=N;i++) {
		for(j=1;j<=M;j++) {
			sl(B[i][j]);
		}
	}

	for(i=1;i<=N;i++) {
		ans = MAX(ans, solve(i));
	}

	pl(ans);

	return 0;
}

