    scanf("%lld%lld",&n,&m);
    for(i=2;i<=n;i++){
        scanf("%lld",&a[i]);
        a[i]+=a[i-1];
    }
    for(i=1;i<=m;i++){sinit(bseg[i]);}
    for(i=1;i<=n;i++){
        for(j=1;j<=m;j++){
            scanf("%lld",&pd.val);
            pd.pod=i;
            //printf("%lld %lld:%lld\n",i,j,pd.val);
            upd(i,pd,bseg[j]);
        }
    }
    for(i=1;i<=m;i++){
        qp=0;qqp=0;
        ns.st=1;
        ns.fi=n;
        qpush(ns);
        while(qp-qqp>0){
            ns=qpop();
            od=query(ns.st,ns.fi+1,1,1,ssize+1,bseg[i]);
            //printf("<%lld>%lld %lld:%lld %lld\n",i,ns.st,ns.fi,od.val,od.pod);
            //if(qp>100){break;}
            map[ns.st][od.pod]+=od.val;
            map[ns.st][ns.fi+1]-=od.val;
            map[od.pod+1][od.pod]-=od.val;
            map[od.pod+1][ns.fi+1]+=od.val;
            if(ns.st!=od.pod){
                ls.st=ns.st;
                ls.fi=od.pod-1;
                qpush(ls);
            }
            if(ns.fi!=od.pod){
                rs.st=od.pod+1;
                rs.fi=ns.fi;
                qpush(rs);
            }
        }
    }
    for(i=1;i<=n;i++){
        for(j=1;j<=n;j++){
            map[i][j]+=map[i][j-1];
        }
    }
    for(i=1;i<=n;i++){
        for(j=1;j<=n;j++){
            map[j][i]+=map[j-1][i];
        }
    }
    for(i=1;i<=n;i++){
        for(j=i;j<=n;j++){
            r=llmax(map[i][j]-a[j]+a[i],r);
        }
    }
    printf("%lld\n",r);
    return 0;
}

#include <stdio.h>

#define N	5000
#define M	5000
#define N_	(1 << 13)	/* N_ = pow2(ceil(log2(N))) */

long long max(long long a, long long b) { return a > b ? a : b; }

long long st[N_ * 2], lz[N_]; int h_, n_;

void put(int i, long long x) {
	st[i] += x;
	if (i < n_)
		lz[i] += x;
}

void pus(int i) {
	if (lz[i]) {
		put(i << 1, lz[i]), put(i << 1 | 1, lz[i]);
		lz[i] = 0;
	}
}

void pul(int i) {
	if (!lz[i])
		st[i] = max(st[i << 1], st[i << 1 | 1]);
}

void push(int i) {
	int h;

	for (h = h_; h > 0; h--)
		pus(i >> h);
}

void pull(int i) {
	while (i > 1)
		pul(i >>= 1);
}

void update(int l, int r, int x) {
	int l_ = l += n_, r_ = r += n_;

	push(l_), push(r_);
	for ( ; l <= r; l >>= 1, r >>= 1) {
		if ((l & 1) == 1)
			put(l++, x);
		if ((r & 1) == 0)
			put(r--, x);
	}
	pull(l_), pull(r_);
}

int main() {
	static int aa[N], bb[N][M], qu[M][N], cnt[M];
	int n, m, i, j;
	long long ans;

	scanf("%d%d", &n, &m);
	for (i = 0; i < n - 1; i++)
		scanf("%d", &aa[i]);
	for (i = 0; i < n; i++)
		for (j = 0; j < m; j++)
			scanf("%d", &bb[i][j]);
	h_ = 0;
	while (1 << h_ < n)
		h_++;
	n_ = 1 << h_;
	ans = 0;
	for (i = 0; i < n; i++) {
		for (j = 0; j < m; j++) {
			int b, b_;

			b = bb[i][j];
			update(i, i, b);
			while (cnt[j] && (b_ = bb[qu[j][cnt[j] - 1]][j]) <= b) {
				update(cnt[j] == 1 ? 0 : qu[j][cnt[j] - 2] + 1, qu[j][cnt[j] - 1], b - b_);
				cnt[j]--;
			}
			qu[j][cnt[j]++] = i;
		}
		ans = max(ans, st[1]);
		if (i < n - 1)
			update(0, i, -aa[i]);
	}
	printf("%lld\n", ans);
	return 0;
}

