import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static int m;

	static void solve()
	{
		int n = ni();
		m = ni();
		int[] a = na(n-1);
		int[][] b = new int[n][];
		for(int i = 0;i < n;i++){
			b[i] = na(m);
		}
		long[][] imos = new long[n+2][n+2];
		for(int i = 0;i < m;i++){
			int[] row = new int[n];
			for(int j = 0;j < n;j++)row[j] = b[j][i];
			int[] pw = enumPrevWall(row);
			int[] nw = enumNextWall(row);
			for(int j = 0;j < n;j++){
				// [pw[j]+1,j]*[j,nw[j]-1]
				add(imos, pw[j]+1, j, j, nw[j]-1, row[j]);
			}
		}
		for(int i = 0;i <= n;i++){
			for(int j = 0;j <= n;j++){
				imos[i][j+1] += imos[i][j];
			}
		}
		for(int i = 0;i <= n;i++){
			for(int j = 0;j <= n;j++){
				imos[j+1][i] += imos[j][i];
			}
		}

		long[] xs = new long[n];
		for(int i = 0;i < n-1;i++){
			xs[i+1] = xs[i] + a[i];
		}

		long max = 0;
		for(int i = 0;i < n;i++){
			for(int j = i;j < n;j++){
				max = Math.max(max,-(xs[j]-xs[i])+imos[i][j]); 
			}
		}
		out.println(max);
	}

	static void add(long[][] imos, int r1, int r2, int c1, int c2, long v)
	{
		imos[r1][c1] += v;
		imos[r1][c2+1] -= v;
		imos[r2+1][c1] -= v;
		imos[r2+1][c2+1] += v;
	}

	public static int[] enumPrevWall(int[] a)
	{
		int n = a.length;
		int[] L = new int[n];
		for(int i = 0;i < n;i++){
			L[i] = i-1;
			while(L[i] >= 0 && a[L[i]] < a[i])L[i] = L[L[i]];
		}
		return L;
	}

	public static int[] enumNextWall(int[] a)
	{
		int n = a.length;
		int[] L = new int[n];
		for(int i = n-1;i >= 0;i--){
			L[i] = i+1;
			while(L[i] < n && a[L[i]] <= a[i])L[i] = L[L[i]];
		}
		return L;
	}


	static long max = 0;

	// all, prefix, suffix

	static long[][] dfs(int l, int r, int[][] b, int[] a)
	{
		if(r-l == 1){
			long[][] rets = new long[3][m+1];
			long t = 0;
			for(int i = 1;i <= m;i++){
				t += b[l][m-i];
				rets[0][i] = t;
				rets[1][i] = t;
				rets[2][i] = t;
			}
			max = Math.max(max, rets[0][m]);
			tr(rets, l, max);
			return rets;
		}

		int h = (l+r)/2;
		long[][] L = dfs(l, h, b, a);
		long[][] R = dfs(h, r, b, a);
		tr("L", L);
		tr("R", R);
		for(int i = 1;i < m;i++){
			int j = m-i;
			max = Math.max(max, L[2][i]+R[1][j]-a[h-1]);
			tr(l, r, max, i, j);
		}
		long[][] rets = new long[3][m+1];
		for(int i = 0;i <= m;i++){
			rets[0][i] = Long.MIN_VALUE;
			rets[1][i] = L[1][i];
			rets[2][i] = R[2][i];
			for(int j = 0;j <= i;j++){
				rets[1][i] = Math.max(rets[1][i], L[0][j]+R[1][i-j]-a[h-1]);
				rets[2][i] = Math.max(rets[2][i], L[2][j]+R[0][i-j]-a[h-1]);
				rets[0][i] = Math.max(rets[0][i], L[0][j]+R[0][i-j]-a[h-1]);
			}
		}
		return rets;
	}

