	static class segtree
	{ 
		int n;
		int[][] tr;
		void build()
		{
			for(int i=n-1;i>0;i--)
				if(tr[0][i<<1]>tr[0][(i<<1)|1]) {
					tr[0][i]=tr[0][i<<1];
					tr[1][i]=tr[1][i<<1];
				}
				else {
					tr[0][i]=tr[0][(i<<1)|1];
					tr[1][i]=tr[1][(i<<1)|1];	
				}
		}
		int[] query(int l,int r)
		{
			r++; // both are inclusive
			int[] res=new int[2];
			for(l+=n,r+=n;l<r;l>>=1,r>>=1)
			{
				if(l%2!=0) 
				{
					if(tr[0][l]>res[0])
					{
						res[0]=tr[0][l];
						res[1]=tr[1][l];
					}
					l++;
				}
				if(r%2!=0)
				{
					r--;
					if(tr[0][r]>res[0])
					{
						res[0]=tr[0][r];
						res[1]=tr[1][r];
					}
				}
			}
			return res;
		}
	}
	static segtree a[];
	static int[][]b;
