			for(int j=0; j<m; j++)
				b[i][j]=ni();
		for(int i=0; i<m; i++)
		{
			a[i]=new segtree();
			a[i].n=n;
			a[i].tr=new int[2][2*n];
			for(int j=0; j<n; j++) {
				a[i].tr[0][j+n]=b[j][i];
				a[i].tr[1][j+n]=j;
			}
			a[i].build();
		}
		grid=new long[n+1][n+1];
		for(int i=0; i<m; i++)
			update(0,n-1,i);
		for(int i=0; i<n; i++)
			for(int j=1; j<n; j++)
				grid[i][j]+=grid[i][j-1];
		for(int i=1; i<n; i++)
			for(int j=0; j<n; j++)
				grid[i][j]+=grid[i-1][j];
		long ans=0;
