	static void update(int i, int j, int no)
	{
		if(i>j)
			return;
		if(i==j)
		{
			grid[i][i]+=b[i][no];
			grid[i+1][i+1]+=b[i][no];
			grid[i+1][i]-=b[i][no];
			grid[i][i+1]-=b[i][no];
			return;
		}
		int te[]=a[no].query(i,j);
		grid[i][te[1]]+=te[0];
		grid[te[1]+1][j+1]+=te[0];
		grid[i][j+1]-=te[0];
		grid[te[1]+1][te[1]]-=te[0];
		update(i,te[1]-1,no);
		update(te[1]+1,j,no);
	}
