import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    static long[][] table;

    static long best = 0;


    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        long[] dist = new long[n];
        for (int i = 1; i < n ; i++) {
            dist[i] = dist[i-1] + in.nextLong();
        }

        int[][] table = new int[m][n+1];
        for (int i = 0; i < n ; i++) {
            for (int j = 0; j < m ; j++) {
                table[j][i] = in.nextInt();
            }
        }

        int[] nextIdx = new int[n];
        int[] prevIdx = new int[n];

        long[][] imos = new long[n+10][n+10];

        for (int mi = 0; mi < m ; mi++) {
            Stack<Integer> stk = new Stack();

            for (int j = 0; j < n ; j++) {
                while (stk.size() >= 1 && table[mi][stk.peek()] < table[mi][j]) {
                    stk.pop();
                }
                prevIdx[j] = stk.size() >= 1 ? stk.peek()+1 : 0;
                stk.push(j);
            }
            stk.clear();
            for (int j = n-1 ; j >= 0 ; j--) {
                while (stk.size() >= 1 && table[mi][stk.peek()] < table[mi][j]) {
                    stk.pop();
                }
                nextIdx[j] = stk.size() >= 1 ? stk.peek()-1 : n-1;
                stk.push(j);
            }

//            debug("==");
//            debug(prevIdx);
//            debug(nextIdx);

            List<int[]> rows = new ArrayList<>();
            for (int i = 0; i < n  ; i++) {
                rows.add(new int[]{i, table[mi][i]});
            }
            Collections.sort(rows, (a, b) -> b[1] - a[1]);
            for (int[] r : rows) {
                int here = r[0];
                int L = prevIdx[r[0]];
                int R = nextIdx[r[0]];
                imos[L][here] += r[1];
                imos[here+1][R+1] += r[1];
                imos[L][R+1] -= r[1];
                imos[here+1][here] -= r[1];
            }
        }

        int imo = imos.length-1;
        for (int i = 0; i <= imo ; i++) {
            for (int j = 1; j <= imo ; j++) {
                imos[i][j] += imos[i][j-1];
            }
        }
        for (int j = 0; j <= imo ; j++) {
            for (int i = 1 ; i <= imo ; i++) {
                imos[i][j] += imos[i-1][j];
            }
        }

        long best = 0;
        for (int i = 0; i < n ; i++) {
            for (int j = i ; j < n ; j++) {
                long D = dist[j] - dist[i];
                best = Math.max(best, imos[i][j] - D);
            }
        }
        out.println(best);
        out.flush();
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int[] nextInts(int n) {
            int[] ret = new int[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextInt();
            }
            return ret;
        }

        private int[][] nextIntTable(int n, int m) {
            int[][] ret = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextInt();
                }
            }
            return ret;
        }

        private long[] nextLongs(int n) {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

        private long[][] nextLongTable(int n, int m) {
            long[][] ret = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextLong();
                }
            }
            return ret;
        }

        private double[] nextDoubles(int n) {
            double[] ret = new double[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextDouble();
            }
            return ret;
        }

        private int next() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            if ('a' <= c && c <= 'z') {
                return (char) c;
            }
            if ('A' <= c && c <= 'Z') {
                return (char) c;
            }
            throw new InputMismatchException();
        }

        public String nextToken() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public long nextLong() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

    static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Stack;
import java.util.StringTokenizer;

public class Main {

	static class TaskF {

		public void solve(int testNumber, InputReader in, PrintWriter out) {
			int N = in.nextInt();
			int M = in.nextInt();
			long[] A = new long[N];
			for (int i = 1; i < N; ++i) {
				A[i] = in.nextInt();
			}
			int[][] B = new int[M][N];// (4*N)*(4*M)<=40KB*800B=32MB
			for (int i = 0; i < N; ++i) {
				for (int j = 0; j < M; ++j) {
					B[j][i] = in.nextInt();
				}
			}

			int[][] a = new int[N][2];// 4*2*N<=80KB
			int[] mate = new int[N];// 4*N<=40KB
			boolean[] vis = new boolean[N];// 4*N<=40KB

			ArrayList<int[]>[] pq = new ArrayList[N + 1];
			for (int i = 0; i < pq.length; ++i) {
				pq[i] = new ArrayList<>(200);
			}
			for (int i = 0; i < M; ++i) {
				for (int j = 0; j < N; ++j) {
					a[j][0] = j;
					a[j][1] = B[i][j];
				}
				B[i] = null;
				Arrays.sort(a, new Comparator<int[]>() {
					@Override
					public int compare(int[] o1, int[] o2) {
						return Integer.compare(o1[1], o2[1]);
					}
				});
				Arrays.fill(vis, false);
				for (int j = 0; j < N; ++j) {
					mate[j] = j;
				}
				for (int j = 0; j < N; ++j) {
					int idx = a[j][0];
					int l = idx, r = idx;
					if (idx > 0 && vis[idx - 1]) {
						l = mate[idx - 1];
					}
					if (idx + 1 < N && vis[idx + 1]) {
						r = mate[idx + 1];
					}
					pq[l].add(new int[] { idx, a[j][1] });
					pq[idx + 1].add(new int[] { r + 1, a[j][1] });
					pq[l].add(new int[] { r + 1, -a[j][1] });
					pq[idx + 1].add(new int[] { idx, -a[j][1] });
					vis[idx] = true;
					if (idx > 0 && idx + 1 < N && vis[idx - 1] && vis[idx + 1]) {
						mate[l] = r;
						mate[r] = l;
					} else if (idx > 0 && vis[idx - 1]) {
						mate[l] = idx;
						mate[idx] = l;
					} else if (idx + 1 < N && vis[idx + 1]) {
						mate[r] = idx;
						mate[idx] = r;
					}
				}
			}
			long[] sum = new long[N];
			for (int i = 0; i < N; ++i) {
				if (i > 0)
					A[i] += A[i - 1];
			}
			long best = 0;
			long[] lazy = new long[N + 1];
			for (int i = 0; i < N; ++i) {
				Arrays.fill(lazy, 0);
				for (int[] q : pq[i]) {
					lazy[q[0]] += q[1];
				}
				for (int j = i; j < N; ++j) {
					if (j > 0)
						lazy[j] += lazy[j - 1];
					sum[j] += lazy[j];
					best = Math.max(best, sum[j] - (A[j] - A[i]));
				}
			}
			out.println(best);
		}
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}

	InputStream is;
	PrintWriter out;
	String INPUT = "";

	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskF solver = new TaskF();
		solver.solve(1, in, out);
		out.close();
	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public InputReader(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream), 32768);
			tokenizer = null;
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}

}

import java.io.*;
import java.util.*;
/*
 * Heart beats fast
 * 		Colors and promises
 * 			How to be brave
 * 				How can I love when I am afraid...
 */
public class Main
{
	static class segtree
	{ 
		int n;
		int[][] tr;
		void build()
		{
			for(int i=n-1;i>0;i--)
				if(tr[0][i<<1]>tr[0][(i<<1)|1]) {
					tr[0][i]=tr[0][i<<1];
					tr[1][i]=tr[1][i<<1];
				}
				else {
					tr[0][i]=tr[0][(i<<1)|1];
					tr[1][i]=tr[1][(i<<1)|1];	
				}
		}
		int[] query(int l,int r)
		{
			r++; // both are inclusive
			int[] res=new int[2];
			for(l+=n,r+=n;l<r;l>>=1,r>>=1)
			{
				if(l%2!=0) 
				{
					if(tr[0][l]>res[0])
					{
						res[0]=tr[0][l];
						res[1]=tr[1][l];
					}
					l++;
				}
				if(r%2!=0)
				{
					r--;
					if(tr[0][r]>res[0])
					{
						res[0]=tr[0][r];
						res[1]=tr[1][r];
					}
				}
			}
			return res;
		}
	}
	public static void main(String[]args) throws Exception
	{
		int n=ni(),m=ni();
		long[]d=new long[n];
		for(int i=1; i<n; i++)
			d[i]=d[i-1]+ni();
		int[][]b=new int[n][m];
		for(int i=0; i<n; i++)
			for(int j=0; j<m; j++)
				b[i][j]=ni();
		long[][]grid=new long[n+1][n+1];
		segtree a=new segtree();
		a.tr=new int[2][2*n];
		a.n=n;
		deque hol=new deque();
		deque hor=new deque();
		int l,r;
		for(int i=0; i<m; i++)
		{
			for(int j=0; j<n; j++) {
				a.tr[0][j+n]=b[j][i];
				a.tr[1][j+n]=j;
			}
			a.build();
			hol.add(0);
			hor.add(n-1);
			while(hol.notempty())
			{
				l=hol.poll();
				r=hor.poll();
				if(l==r)
				{
					grid[l][l]+=b[l][i];
					grid[l+1][l+1]+=b[l][i];
					grid[l+1][l]-=b[l][i];
					grid[l][l+1]-=b[l][i];
				}
				else if(l<r)
				{
					int[]te=a.query(l,r);
					grid[l][te[1]]+=te[0];
					grid[te[1]+1][r+1]+=te[0];
					grid[l][r+1]-=te[0];
					grid[te[1]+1][te[1]]-=te[0];
					hol.add(l);
					hol.add(te[1]+1);
					hor.add(te[1]-1);
					hor.add(r);
				}
