/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            TaskF solver = new TaskF();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class TaskF {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int m = in.readInt();
            int[] a = new int[n];
            long[] presumOfA = new long[n];
            for (int i = 1; i < n; i++) {
                a[i] = in.readInt();
                presumOfA[i] = presumOfA[i - 1] + a[i];
            }

            ArrayIndex aiNM = new ArrayIndex(n + 1, m + 1);
            int[] b = new int[aiNM.totalSize()];
            int[] l = new int[aiNM.totalSize()];
            int[] r = new int[aiNM.totalSize()];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    b[aiNM.indexOf(i, j)] = in.readInt();
                }
            }

            ArrayIndex aiNN = new ArrayIndex(n + 1, n + 1);
            long[] intervals = new long[aiNN.totalSize()];
            IntDeque deque = new IntDeque(n);
            for (int i = 1; i <= m; i++) {
                deque.clear();
                for (int j = 1; j <= n; j++) {
                    while (!deque.isEmpty() && b[aiNM.indexOf(deque.peekLast(), i)] <= b[aiNM.indexOf(j, i)]) {
                        deque.removeLast();
                    }
                    if (deque.isEmpty()) {
                        l[aiNM.indexOf(j, i)] = 1;
                    } else {
                        l[aiNM.indexOf(j, i)] = deque.peekLast() + 1;
                    }
                    deque.addLast(j);
                }
                deque.clear();
                for (int j = n; j >= 1; j--) {
                    while (!deque.isEmpty() && b[aiNM.indexOf(deque.peekFirst(), i)] < b[aiNM.indexOf(j, i)]) {
                        deque.removeFirst();
                    }
                    if (deque.isEmpty()) {
                        r[aiNM.indexOf(j, i)] = n;
                    } else {
                        r[aiNM.indexOf(j, i)] = deque.peekFirst() - 1;
                    }
                    deque.addFirst(j);
                }
            }


            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    int x = l[aiNM.indexOf(i, j)];
                    int y = r[aiNM.indexOf(i, j)];
                    intervals[aiNN.indexOf(i, y)] += b[aiNM.indexOf(i, j)];
                    intervals[aiNN.indexOf(x - 1, y)] -= b[aiNM.indexOf(i, j)];
                    intervals[aiNN.indexOf(i, i - 1)] -= b[aiNM.indexOf(i, j)];
                    intervals[aiNN.indexOf(x - 1, i - 1)] += b[aiNM.indexOf(i, j)];
                }
            }

            // push down
            for (int i = n + n; i >= 0; i--) {
                for (int j = 1; j <= n; j++) {
                    int k = i - j;
                    if (k < 1 || k > n) {
                        continue;
                    }
                    if (j + 1 <= n) {
                        intervals[aiNN.indexOf(j, k)] += intervals[aiNN.indexOf(j + 1, k)];
                    }
                    if (k + 1 <= n) {
                        intervals[aiNN.indexOf(j, k)] += intervals[aiNN.indexOf(j, k + 1)];
                    }
                    if (j + 1 <= n && k + 1 <= n) {
                        intervals[aiNN.indexOf(j, k)] -= intervals[aiNN.indexOf(j + 1, k + 1)];
                    }
                }
            }

            long ans = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = i; j <= n; j++) {
                    long profit = intervals[aiNN.indexOf(i, j)] - (presumOfA[j - 1] - presumOfA[i - 1]);
                    ans = Math.max(ans, profit);
                }
            }

            out.println(ans);
        }

    }

    static class IntDeque {
        int[] data;
        int bpos;
        int epos;
        int cap;

        public IntDeque(int cap) {
            this.cap = cap + 1;
            this.data = new int[this.cap];
        }

        public boolean isEmpty() {
            return epos == bpos;
        }

        public int peekFirst() {
            return data[bpos];
        }

        private int last(int i) {
            return (i == 0 ? cap : i) - 1;
        }

        private int next(int i) {
            int n = i + 1;
            return n == cap ? 0 : n;
        }

        public int peekLast() {
            return data[last(epos)];
        }

        public int removeFirst() {
            int t = bpos;
            bpos = next(bpos);
            return data[t];
        }

        public int removeLast() {
            return data[epos = last(epos)];
        }

        public void addLast(int val) {
            data[epos] = val;
            epos = next(epos);
        }

        public void addFirst(int val) {
            data[bpos = last(bpos)] = val;
        }

        public void clear() {
            bpos = epos = 0;
        }

        public String toString() {
            StringBuilder builder = new StringBuilder();
            for (int i = bpos; i != epos; i = next(i)) {
                builder.append(data[i]).append(' ');
            }
            return builder.toString();
        }

    }

    static class ArrayIndex {
        int[] dimensions;

        public ArrayIndex(int... dimensions) {
            this.dimensions = dimensions;
        }

        public int totalSize() {
            int ans = 1;
            for (int x : dimensions) {
                ans *= x;
            }
            return ans;
        }

        public int indexOf(int a, int b) {
            return a * dimensions[1] + b;
        }

    }

    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(long c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
}

import java.util.Arrays;

class SegmentTreeRMQPos {
  public int M, H, N;
  public int[] st;
  public int[] pos;

  public SegmentTreeRMQPos(int n) {
    N = n;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new int[M];
    pos = new int[M];
    for (int i = 0; i < N; i++)
      pos[H + i] = i;
    Arrays.fill(st, 0, M, Integer.MAX_VALUE);
    for (int i = H - 1; i >= 1; i--)
      propagate(i);
  }

  public SegmentTreeRMQPos(int[] a) {
    N = a.length;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new int[M];
    pos = new int[M];
    for (int i = 0; i < N; i++) {
      st[H + i] = a[i];
      pos[H + i] = i;
    }
    Arrays.fill(st, H + N, M, Integer.MAX_VALUE);
    for (int i = H - 1; i >= 1; i--)
      propagate(i);
  }

  public void update(int pos, int x) {
    st[H + pos] = x;
    for (int i = (H + pos) >>> 1; i >= 1; i >>>= 1)
      propagate(i);
  }

  private void propagate(int i) {
    if (st[2 * i] <= st[2 * i + 1]) {
      st[i] = st[2 * i];
      pos[i] = pos[2 * i];
    } else {
      st[i] = st[2 * i + 1];
      pos[i] = pos[2 * i + 1];
    }
  }

  public int minpos;
  public int minval;

  public int min(int l, int r) {
    minpos = -1;
    minval = Integer.MAX_VALUE;
    min(l, r, 0, H, 1);
    return minval;
  }

  private void min(int l, int r, int cl, int cr, int cur) {
    if (l <= cl && cr <= r) {
      if (st[cur] < minval) {
        minval = st[cur];
        minpos = pos[cur];
      }
    } else {
      int mid = cl + cr >>> 1;
      if (cl < r && l < mid)
        min(l, r, cl, mid, 2 * cur);
      if (mid < r && l < cr)
        min(l, r, mid, cr, 2 * cur + 1);
    }
  }
}


public class Main {


  private static void solve() {
    int n = ni();
    int m = ni();

    long[] a = new long[n];
    for (int i = 1; i < n; i++) {
      a[i] = a[i - 1] + ni();
    }
    int[][] b = ntable(n, m);
    long[][] imos = new long[n + 1][n + 1];

    for (int j = 0; j < m; j ++) {
      System.gc();
      SegmentTreeRMQPos st = new SegmentTreeRMQPos(n);
      for (int i = 0; i < n; i ++) {
        st.update(i, -b[i][j]);
      }
      rec(imos, 0, n, st);
    }
    sum(imos);

    long ret = Long.MIN_VALUE;
    for (int min = 0; min < n; min ++) {
      for (int max = min; max < n; max ++) {
        long now = imos[min][max] - (a[max] - a[min]);
        ret = Math.max(ret, now);
      }
    }
    System.out.println(ret);
  }

  private static void sum(long[][] imos) {
    int n = imos.length - 1;
    for (int i = 0; i < n; i ++) {
      for (int j = 1; j < n; j ++) {
        imos[i][j] += imos[i][j - 1];
      }
    }

    for (int i = 1; i < n; i ++) {
      for (int j = 0; j < n; j ++) {
        imos[i][j] += imos[i - 1][j];
      }
    }
  }

  private static void rec(long[][] imos, int left, int right, SegmentTreeRMQPos st) {
    if (left >= right) return;
    st.min(left, right);
    int opt = st.minpos;

    int y1 = left;
    int x1 = opt;
    int y2 = opt + 1;
    int x2 = right;
    int v = -st.minval;
    imos[y1][x1] += v;
    imos[y2][x1] += -v;
    imos[y1][x2] += -v;
    imos[y2][x2] += v;

    rec(imos, opt + 1, right, st);
    rec(imos, left, opt, st);
  }

