    int[][] b = nlist(n, m);
    SegmentTreeRMQPos[] st = new SegmentTreeRMQPos[m];
    for (int i = 0; i < m; i ++) {
      int[] c = Arrays.copyOf(b[i], n);
      for (int j = 0; j < n; j ++) {
        c[j] = -c[j];
      }
      st[i] = new SegmentTreeRMQPos(c);
    }
    for (int i = 0; i < m; i ++) {
      rec(imos, 0, n, b[i], st[i]);
    }
    sum(imos);


    long ret = Long.MIN_VALUE;
    for (int min = 0; min < n; min ++) {
      for (int max = min; max < n; max ++) {
