  private static void sum(long[][] imos) {
    int n = imos.length - 1;
    for (int i = 0; i < n; i ++) {
      for (int j = 1; j < n; j ++) {
        imos[i][j] += imos[i][j - 1];
      }
    }

    for (int i = 1; i < n; i ++) {
      for (int j = 0; j < n; j ++) {
        imos[i][j] += imos[i - 1][j];
      }
    }
  }

  private static void rec(long[][] imos, int left, int right, int[] b, SegmentTreeRMQPos st) {
    if (left >= right) return;
    st.min(left, right);
