import java.util.Arrays;

class SegmentTreeRMQPos {
  public int M, H, N;
  public int[] st;
  public int[] pos;

  public SegmentTreeRMQPos(int n) {
    N = n;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new int[M];
    pos = new int[M];
    for (int i = 0; i < N; i++)
      pos[H + i] = i;
    Arrays.fill(st, 0, M, Integer.MAX_VALUE);
    for (int i = H - 1; i >= 1; i--)
      propagate(i);
  }

  public SegmentTreeRMQPos(int[] a) {
    N = a.length;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new int[M];
    pos = new int[M];
    for (int i = 0; i < N; i++) {
      st[H + i] = a[i];
      pos[H + i] = i;
    }
    Arrays.fill(st, H + N, M, Integer.MAX_VALUE);
    for (int i = H - 1; i >= 1; i--)
      propagate(i);
  }

  public void update(int pos, int x) {
    st[H + pos] = x;
    for (int i = (H + pos) >>> 1; i >= 1; i >>>= 1)
      propagate(i);
  }

  private void propagate(int i) {
    if (st[2 * i] <= st[2 * i + 1]) {
      st[i] = st[2 * i];
      pos[i] = pos[2 * i];
    } else {
      st[i] = st[2 * i + 1];
      pos[i] = pos[2 * i + 1];
    }
  }

  public int minpos;
  public int minval;

  public int minx(int l, int r) {
    minval = Integer.MAX_VALUE;
    minpos = -1;
    if (l >= r)
      return minval;
    while (l != 0) {
      int f = l & -l;
      if (l + f > r)
        break;
      int v = st[(H + l) / f];
      if (v < minval) {
        minval = v;
        minpos = pos[(H + l) / f];
      }
      l += f;
    }

    while (l < r) {
      int f = r & -r;
      int v = st[(H + r) / f - 1];
      if (v < minval) {
        minval = v;
        minpos = pos[(H + r) / f - 1];
      }
      r -= f;
    }
    return minval;
  }
}


public class Main {


  private static void solve() {
    int n = ni();
    int m = ni();

    long[] a = new long[n];
    for (int i = 1; i < n; i++) {
      a[i] = a[i - 1] + ni();
    }
    int[][] b = ntable(n, m);
    long[][] imos = new long[n + 1][n + 1];

    SegmentTreeRMQPos st = new SegmentTreeRMQPos(n);
    for (int j = 0; j < m; j++) {
      for (int i = 0; i < n; i++) {
        st.update(i, -b[i][j]);
      }
      rec(imos, 0, n, st);
    }
    sum(imos);

    long ret = Long.MIN_VALUE;
    for (int min = 0; min < n; min++) {
      for (int max = min; max < n; max++) {
        long now = imos[min][max] - (a[max] - a[min]);
        ret = Math.max(ret, now);
      }
    }
    System.out.println(ret);
  }

  private static void sum(long[][] imos) {
    int n = imos.length - 1;
    for (int i = 0; i < n; i++) {
      for (int j = 1; j < n; j++) {
        imos[i][j] += imos[i][j - 1];
      }
    }

    for (int i = 1; i < n; i++) {
      for (int j = 0; j < n; j++) {
        imos[i][j] += imos[i - 1][j];
      }
    }
  }

  private static void rec(long[][] imos, int left, int right, SegmentTreeRMQPos st) {
    if (left >= right)
      return;
    st.minx(left, right);
    int opt = st.minpos;

    int y1 = left;
    int x1 = opt;
    int y2 = opt + 1;
    int x2 = right;
    int v = -st.minval;
    imos[y1][x1] += v;
    imos[y2][x1] += -v;
    imos[y1][x2] += -v;
    imos[y2][x2] += v;

