				int l = idx, r = idx;
				if (idx > 0 && vis[idx - 1]) {
					l = mate[idx - 1];
				}
				if (idx + 1 < N && vis[idx + 1]) {
					r = mate[idx + 1];
				}
				sum[l][idx] += a[j][1];
				sum[idx + 1][r + 1] += a[j][1];
