public class Main {
    static long best = 0;

    static long[][] imos = new long[5001][5001];

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        long[] dist = new long[n];
        for (int i = 1; i < n ; i++) {
            dist[i] = dist[i-1] + in.nextLong();
        }

        int[][] table = new int[m][n];
        for (int i = 0; i < n ; i++) {
            for (int j = 0; j < m ; j++) {
                table[j][i] = in.nextInt();
            }
        }

        int[] nextIdx = new int[n];
        int[] prevIdx = new int[n];


        int[] stk = new int[10000];
        for (int mi = 0; mi < m ; mi++) {
            int head = 0;
            for (int j = 0; j < n ; j++) {
                while (head >= 1 && table[mi][stk[head-1]] < table[mi][j]) {
                    head--;
                }
                prevIdx[j] = head >= 1 ? stk[head-1]+1 : 0;
                stk[head++] = j;
            }
            head = 0;
            for (int j = n-1 ; j >= 0 ; j--) {
                while (head >= 1 && table[mi][stk[head-1]] < table[mi][j]) {
                    head--;
                }
                nextIdx[j] = head >= 1 ? stk[head-1]-1 : n-1;
                stk[head++] = j;
            }

            List<int[]> rows = new ArrayList<>();
            for (int i = 0; i < n  ; i++) {
                rows.add(new int[]{i, table[mi][i]});
            }
            Collections.sort(rows, (a, b) -> b[1] - a[1]);
            for (int[] r : rows) {
                int here = r[0];
                int L = prevIdx[r[0]];
                int R = nextIdx[r[0]];
                imos[L][here] += r[1];
                imos[here+1][R+1] += r[1];
                imos[L][R+1] -= r[1];
                imos[here+1][here] -= r[1];
            }
        }

        int imo = imos.length-1;
        for (int i = 0; i <= imo ; i++) {
            for (int j = 1; j <= imo ; j++) {
                imos[i][j] += imos[i][j-1];
            }
        }
        for (int j = 0; j <= imo ; j++) {
            for (int i = 1 ; i <= imo ; i++) {
                imos[i][j] += imos[i-1][j];
            }
        }

        long best = 0;
        for (int i = 0; i < n ; i++) {
            for (int j = i ; j < n ; j++) {
                long D = dist[j] - dist[i];
                best = Math.max(best, imos[i][j] - D);
            }
        }
        out.println(best);
        out.flush();
    }

