				if (idx > 0 && vis[idx - 1]) {
					l = mate[idx - 1];
				}
				if (idx + 1 < N && vis[idx + 1]) {
					r = mate[idx + 1];
				}
				pq.add(new Query(l, idx, a[j][1]));
				pq.add(new Query(idx + 1, r + 1, a[j][1]));
				pq.add(new Query(l, r + 1, -a[j][1]));
				pq.add(new Query(idx + 1, idx, -a[j][1]));
				vis[idx] = true;
				if (idx > 0 && idx + 1 < N && vis[idx - 1] && vis[idx + 1]) {
					mate[l] = r;
