					mate[idx] = l;
				} else if (idx + 1 < N && vis[idx + 1]) {
					mate[r] = idx;
					mate[idx] = r;
				}
			}
		}
		long[] sum = new long[N];
		for (int i = 0; i < N; ++i) {
			if (i > 0)
				A[i] += A[i - 1];
		}
		long best = 0;
		long[] lazy = new long[N + 1];
		for (int i = 0; i < N; ++i) {
			Arrays.fill(lazy, 0);
			while (!pq.isEmpty() && pq.peek().i <= i) {
				Query q = pq.poll();
				lazy[q.j] += q.add;
			}
			for (int j = 1; j < N; ++j) {
				lazy[j] += lazy[j - 1];
			}
			for (int j = 0; j < N; ++j)
				sum[j] += lazy[j];
			for (int j = i; j < N; ++j) {
				best = Math.max(best, sum[j] - (A[j] - A[i]));
			}
		}
