	void solve() {
		int N = ni();
		int M = ni();
		long[] A = new long[N];// 8*N<=4*10^4=40KB
		for (int i = 1; i < N; ++i) {
			A[i] = ni();
		}
		int[][] B = new int[M][N];// (4*N)*(4*M)<=40KB*800B=32MB
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j < M; ++j) {
				B[j][i] = ni();
			}
		}
		int[][] a = new int[N][2];// 4*2*N<=80KB
		int[] mate = new int[N];// 4*N<=40KB
		boolean[] vis = new boolean[N];// 4*N<=40KB
		class Query implements Comparable<Query> {
			int j;
			long add;

			public Query(int j_, long add_) {
				j = j_;
				add = add_;
			}

			public int compareTo(Query arg0) {
				return Integer.compare(j, arg0.j);
			};
		}
		ArrayList<Query>[] pq = new ArrayList[N + 1];
		for (int i = 0; i < pq.length; ++i)
			pq[i] = new ArrayList<>();
		for (int i = 0; i < M; ++i) {
			for (int j = 0; j < N; ++j) {
				a[j][0] = j;
				a[j][1] = B[i][j];
			}
			B[i] = null;
			Arrays.sort(a, new Comparator<int[]>() {
				@Override
				public int compare(int[] o1, int[] o2) {
					return Integer.compare(o1[1], o2[1]);
				}
			});
			Arrays.fill(vis, false);
			for (int j = 0; j < N; ++j) {
				mate[j] = j;
			}
			for (int j = 0; j < N; ++j) {
				int idx = a[j][0];
				int l = idx, r = idx;
				if (idx > 0 && vis[idx - 1]) {
					l = mate[idx - 1];
				}
				if (idx + 1 < N && vis[idx + 1]) {
					r = mate[idx + 1];
				}
				pq[l].add(new Query(idx, a[j][1]));
				pq[idx + 1].add(new Query(r + 1, a[j][1]));
				pq[l].add(new Query(r + 1, -a[j][1]));
				pq[idx + 1].add(new Query(idx, -a[j][1]));
				vis[idx] = true;
				if (idx > 0 && idx + 1 < N && vis[idx - 1] && vis[idx + 1]) {
					mate[l] = r;
					mate[r] = l;
				} else if (idx > 0 && vis[idx - 1]) {
					mate[l] = idx;
					mate[idx] = l;
				} else if (idx + 1 < N && vis[idx + 1]) {
					mate[r] = idx;
					mate[idx] = r;
				}
			}
		}
		long[] sum = new long[N];
		for (int i = 0; i < N; ++i) {
			if (i > 0)
				A[i] += A[i - 1];
		}
		long best = 0;
		long[] lazy = new long[N + 1];
		for (int i = 0; i < N; ++i) {
			Arrays.fill(lazy, 0);
			for (Query q : pq[i]) {
				lazy[q.j] += q.add;
			}
			for (int j = 1; j < N; ++j) {
				lazy[j] += lazy[j - 1];
			}
			for (int j = 0; j < N; ++j)
				sum[j] += lazy[j];
			for (int j = i; j < N; ++j) {
				best = Math.max(best, sum[j] - (A[j] - A[i]));
			}
		}
		out.println(best);
	}

