            for (int i = 0; i < n - 1; i++)
                a[i + 1] = a[i] + rl;
            var b = Enumerate(n, x => new long[m]);
            for (int i = 0; i < n; i++)
                for (int j = 0; j < m; j++)
                    b[i][j] = rl;
            var imos = Enumerate(5002, x => new long[5002]);
            var C = new long[n];

            for (int j = 0; j < m; j++)
