class Solve{
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        string[] str = Console.ReadLine().Split(' ');
        int N = int.Parse(str[0]);
        int M = int.Parse(str[1]);
        long[] A = new long[N-1];
        str = Console.ReadLine().Split(' ');
        for(int i=0;i<N-1;i++){
            A[i] = int.Parse(str[i]);
        }
        long[,] B = new long[N,M];
        for(int i=0;i<N;i++){
            str = Console.ReadLine().Split(' ');
            for(int j=0;j<M;j++){
                B[i,j] = int.Parse(str[j]);
            }
        }
        long max = 0;
        long[] currentMax = new long[M];
        long sum = 0;
        long DistanceSum = 0;
        for(int i=0;i<N;i++){
            if(i > 0){
                DistanceSum += A[i-1];
            }
            for(int j=0;j<M;j++){
                if(B[i,j] > currentMax[j]){
                    sum += B[i,j] - currentMax[j];
                    currentMax[j] = B[i,j];
                }
            }
            max = Math.Max(max,sum-DistanceSum);
        }
        sb.Append(max+"\n");
    }
}

