            str = Console.ReadLine().Split(' ');
            for(int j=0;j<M;j++){
                B[i,j] = int.Parse(str[j]);
            }
        }
        Map = new long[N,N];
        for(int i=0;i<M;i++){
            long[] C = new long[N];
            for(int j=0;j<N;j++){
                C[j] = B[j,i];
            }
            RangeMinimumQuerry RMQ = new RangeMinimumQuerry(C);
            F(RMQ,0,N-1);
        }
        long max = 0;
        for(int i=0;i<N;i++){
            for(int j=0;j<N;j++){
                Map[i,j] += (i == 0 ? 0 : Map[i-1,j]) + (j == 0 ? 0 : Map[i,j-1]) - ((i == 0 || j == 0) ? 0 : Map[i-1,j-1]);
            }
        }
        for(int i=0;i<N;i++){
            for(int j=i;j<N;j++){
                max = Math.Max(max,Map[i,j]+A[i]-A[j]);
