public class RangeMinimumQuerry{
    int N;
    public long[] A;
    int[,] MinL;
    int[,] MinR;
    //log2 1 << p <= i を満たす最大のp
    int[] ln;
    public RangeMinimumQuerry(long[] A0){
        A = A0;
        N = A.Length;
        ln = new int[N+1];
        int p = -1;
        for(int i=0;i<=N;i++){
            if(1 << (p+1) <= i){
                p++;
            }
            ln[i] = p;
        }
        p++;
        MinL = new int[p,N];
        MinR = new int[p,N];
        for(int i=0;i<N;i++){
            MinL[0,i] = i;
            MinR[0,i] = i; 
        }
        for(int i=1;i<p;i++){
            for(int j=0;j<N;j++){
                if(j + (1 << (i-1)) < N){
                    if(Judge(A[MinR[i-1,j+(1 << (i-1))]],A[MinR[i-1,j]])){
                        MinR[i,j] = MinR[i-1,j+(1 << (i-1))];
                    }
                    else{
                        MinR[i,j] = MinR[i-1,j];
                    }
                }
                else{
                    MinR[i,j] = MinR[i-1,j];
                }
                if(j - (1 << (i-1)) >= 0){
                    if(Judge(A[MinL[i-1,j-(1 << (i-1))]],A[MinL[i-1,j]])){
                        MinL[i,j] = MinL[i-1,j-(1 << (i-1))];
                    }
                    else{
                        MinL[i,j] = MinL[i-1,j];
                    }
                }
                else{
                    MinL[i,j] = MinL[i-1,j];
                }
            }
        }
    }
    public int Querry(int L,int R){
        int l = MinR[ln[R-L+1],L];
        int r = MinL[ln[R-L+1],R];
        if(Judge(A[l],A[r])){
            return l;
        }
        else{
            return r;
        }
    }
    //小さい順なら x < y
    public bool Judge(long x,long y){
        return x > y;
    }
}

