public class Program
{
    public void Proc() {

        Reader.IsDebug = false;
        int[] inpt = Reader.ReadLine().Split(' ').Select(a=>int.Parse(a)).ToArray();

        this.MiseCount = inpt[0];
        this.TicketCount = inpt[1];

        this.Kyori = Reader.ReadLine().Split(' ').Select(a=>long.Parse(a)).ToArray();

        this.Map = new long[this.MiseCount, this.TicketCount];

        long totalKyori = Kyori.Sum();
        long totalOisisa = 0;
        // キー：チケット、Value：店
        Dictionary<int, int> useTicketMise = new Dictionary<int, int>();
        for(int i=0; i<MiseCount; i++) {
            long[] tmp = Reader.ReadLine().Split(' ').Select(a=>long.Parse(a)).ToArray();
            for(int j=0; j<tmp.Length; j++) {
                this.Map[i,j] = tmp[j];
                if(useTicketMise.ContainsKey(j)) {
                    int mise = useTicketMise[j];
                    if(tmp[j] > this.Map[mise, j]) {
                        totalOisisa-= this.Map[mise,j];
                        totalOisisa+=tmp[j];
                        useTicketMise[j] = i;
                    }
                } else {
                    useTicketMise.Add(j, i);
                    totalOisisa+=tmp[j];
                }
            }
        }
        long ans = totalOisisa - totalKyori;
        for(int i=MiseCount-1; i>=1; i--) {
            totalKyori-=Kyori[i-1];
            int[] target = useTicketMise.Where(a=>a.Value == i).Select(a=>a.Key).ToArray();
            foreach(int key in target) {
                totalOisisa -= this.Map[i, key];
                int maxIdx = 0;
                long maxVal = this.Map[0, key];
                for(int j=0; j<i; j++) {
                    if(this.Map[j, key] > maxVal) {
                        maxVal = this.Map[j,key];
                        maxIdx = j;
                    }
                }
                totalOisisa+=maxVal;
                useTicketMise[key] = maxIdx;
            }
            ans = Math.Max(ans, totalOisisa-totalKyori);
        }
        Console.WriteLine(ans);
    }

    private long[] Kyori;

    // 1番目のインデックス；店、2番目のインデックス：チケット
    private long[,] Map;


    private int MiseCount;
    private int TicketCount;


    public class Reader {
        public static bool IsDebug = true;
        private static System.IO.StringReader SReader;
        private static string InitText = @"


2 3
