            var a = new long[n];
            for (int i = 0; i < n - 1; i++)
                a[i] = sc.Long();
            var b = Enumerate(n, x => sc.Long(m));
            var rand = new Random();
            var otaku = Enumerate(n, x => x).OrderBy(x => rand.Next()).ToArray();
            var max = Math.Min(n, 1500);
            var ans = 0L;
            for (int i = 0; i < max; i++)
