#include<bits/stdc++.h>
using namespace std;
const int N = 5005, M = 202, LG = 14;
int n, m, B[M][N], Log[N];
long long A[N], dp[N][N];
pair < int , int > MX[LG][N];
inline int GetMax(int l, int r)
{
    int lg = Log[r - l + 1];
    return (max(MX[lg][l], MX[lg][r - (1 << lg) + 1]).second);
}
int main()
{
    scanf("%d%d", &n, &m);
    for (int i = 2; i <= n; i ++)
        scanf("%d", &A[i]), A[i] += A[i - 1];
    for (int i = 1; i <= n; i ++)
        for (int j = 1; j <= m; j ++)
            scanf("%d", &B[j][i]);
    for (int i = 2; i < N; i ++)
        Log[i] = Log[i >> 1] + 1;
    for (int j = 1; j <= m; j ++)
    {
        for (int i = 1; i <= n; i ++)
            MX[0][i] = {B[j][i], i};
        for (int h = 1; h < LG; h ++)
            for (int i = 1; i + (1 << h) - 1 <= n; i ++)
                MX[h][i] = max(MX[h - 1][i], MX[h - 1][i + (1 << h - 1)]);
        queue < pair < int , int > > qu;
        qu.push({1, n});
        while (qu.size())
        {
            int l = qu.front().first;
            int r = qu.front().second;
            qu.pop();
            if (r < l) continue;
            int i = GetMax(l, r);
            dp[l][i] += B[j][i];
            dp[l][r + 1] -= B[j][i];
            dp[i + 1][i] -= B[j][i];
            dp[i + 1][r + 1] += B[j][i];
            qu.push({l, i - 1});
            qu.push({i + 1, r});
        }
    }
    for (int i = 1; i <= n; i ++)
        for (int j = 1; j <= n; j ++)
            dp[i][j] += dp[i - 1][j] + dp[i][j - 1] - dp[i - 1][j - 1];
    long long Mx = 0;
    for (int i = 1; i <= n; i ++)
        for (int j = i; j <= n; j ++)
            Mx = max(Mx, dp[i][j] - A[j] + A[i]);
    return !printf("%lld\n", Mx);
}

