fn fill(tab: &mut Vec<Vec<i64>>, l: usize, r: usize, v: &Vec<i64>) {
    if l >= r {
        return;
    }
    let mut k = 0;
    let mut max = 0;
    for i in l..r {
        if v[i] > max {
            k = i;
            max = v[i];
        }
    }
    tab[l][k] += max;
    tab[l][r] -= max;
    tab[k + 1][k] -= max;
    tab[k + 1][r] += max;
    fill(tab, l, k, v);
    fill(tab, k + 1, r, v);
}

