struct SegT {
    v: Vec<usize>,
    n: usize
}

impl SegT {
    fn from_vec(xs: Vec<usize>) -> SegT {
        let l = xs.len();
        let mut n = 1;
        while n < l {
            n *= 2;
        }
        let mut v = vec![0; 2 * n - 1];
        for i in 0..l {
            v[i + n - 1] = xs[i];
        }
        for i in 1..n {
            let p = n - i - 1;
            v[p] = std::cmp::max(v[2 * p + 1], v[2 * p + 2]);
        }
        SegT{v: v, n: n}
    }

    fn max(&self, l: usize, r: usize) -> usize {
        let mut ret = 0;
        let mut i = l;
        while i <= r {
            let mut p = self.n + i - 1;
            let mut s = 1;
            let mut t = i;
            while t % 2 == 0 && t > 0 {
                p = (p - 1) / 2;
                s *= 2;
                t /= 2;
            }
            ret = std::cmp::max(ret, self.v[p]);
            i += s;
        }
        ret
    }
}

