fn run() {
    input! {
        n: usize,
        m: usize,
        a: [i64; n - 1],
        b: [[i64; m]; n],
    }
    let mut dp = vec![vec![0; n + 1]; n + 1];
    for i in 0..m {
        let mut s = segment_tree::PURQ::new(n, (0, 0), std::cmp::max);
        for j in 0..n {
            s.update_tmp(j, (b[j][i], j));
        }
        s.update_all();
        let mut stack = vec![];
        stack.push((0, n - 1));
        while let Some((l, r)) = stack.pop() {
            let (v, k) = s.find(l, r + 1);
            dp[l][k] += v;
            dp[k + 1][k] -= v;
            dp[l][r + 1] -= v;
            dp[k + 1][r + 1] += v;
            if l < k {
                stack.push((l, k - 1));
            }
            if k < r {
                stack.push((k + 1, r));
            }
        }
    }
    for i in 0..n {
        for j in 1..n {
            dp[i][j] += dp[i][j - 1];
        }
    }
    for i in 1..n {
        for j in 0..n {
            dp[i][j] += dp[i - 1][j];
        }
    }
    let mut d = a.clone();
    d.push(0);
    for i in (0..(n - 1)).rev() {
        d[i] += d[i + 1];
    }
    let mut ans = 0;
    for l in 0..n {
        for r in l..n {
            let v = dp[l][r] - (d[l] - d[r]);
            ans = std::cmp::max(ans, v);
        }
    }
    println!("{}", ans);
}

