fn main() {
    define! {
        n: usize
        m: usize
    }
    let position = read_values::<i64>();
    let restaurants: Vec<Vec<i64>> = read_lines(n, |str| str.split(' ').map(|x| x.parse::<i64>().unwrap()).collect::<Vec<_>>());
    let mut memo: Vec<Vec<i64>> = vec![vec![0i64; n + 1]; n + 1];
    for t in 0 .. m {
        let mut stack = Vec::<usize>::new();
        for (next, restaurant) in restaurants.iter().enumerate() {
            let value = restaurant[t];
            while let Some(&mid) = stack.last() {
                if restaurants[mid][t] <= value {
                    stack.pop();
                    if let Some(&prev) = stack.last() {
                        memo[prev + 1][mid] += restaurants[mid][t];
                        memo[mid + 1][next] += restaurants[mid][t]; 
                        memo[mid + 1][mid] -= restaurants[mid][t];
                        memo[prev + 1][next] -= restaurants[mid][t];
                    }else {
                        memo[0][mid] += restaurants[mid][t];
                        memo[mid + 1][next] += restaurants[mid][t];
                        memo[mid + 1][mid] -= restaurants[mid][t];
                        memo[0][next] -= restaurants[mid][t];
                    }
                }else {
                    break;
                }
            }
            stack.push(next);
        }
        while let Some(mid) = stack.pop() {
            if let Some(&prev) = stack.last() {
                memo[prev + 1][mid] += restaurants[mid][t];
                memo[mid + 1][n] += restaurants[mid][t];
                memo[mid + 1][mid] -= restaurants[mid][t];
                memo[prev + 1][n] -= restaurants[mid][t];
            }else {
                memo[0][mid] += restaurants[mid][t];
                memo[mid + 1][n] += restaurants[mid][t];
                memo[mid + 1][mid] -= restaurants[mid][t];
                memo[0][n] -= restaurants[mid][t];
            }
        }
    }
    for i in 1 ..= n {
        for j in 0 ..= n {
            memo[i][j] += memo[i - 1][j];
        }
    }
    for i in 0 ..= n {
        for j in 1 ..= n {
            memo[i][j] += memo[i][j - 1];
        }
    }
    let mut diff = vec![0i64];
    for pos in position {
        diff.push(diff.last().unwrap() + pos);
    }
    freeze!(diff);
    let mut result = 0i64;
    for i in 0 .. n {
        for j in i .. n {
            result = max(result, diff[i] - diff[j] + memo[i][j]);
        }
    }
    println!("{}", result);
}

