use std::cmp::*;
use std::collections::*;
use std::collections::Bound::*;

trait InputValue {
    fn parse(s: &str) -> Self;
}

fn read<T: InputValue>() -> T {
    let mut buf = String::new();
    let _ = stdin().read_line(&mut buf);
    T::parse(&buf.trim())
}

fn readnc<T: InputValue>() -> Vec<T> {
    let mut vec = vec![];
    let line: String = read();
    for token in line.split_whitespace() {
        vec.push(T::parse(token));
    }
    vec
}

fn readn<T: InputValue>(n: usize) -> Vec<T> {
    let mut vec = vec![];
    for _ in 0..n {
        vec.push(read());
    }
    vec
}

macro_rules! parse_single_value {
    ($($t:ty),*) => {
        $(
            impl InputValue for $t {
                fn parse(s: &str) -> $t { s.parse().unwrap() }
            }
        )*
	}
}
parse_single_value!(i32, i64, f32, f64, usize, String);

macro_rules! parse_tuple {
	($($t:ident),*) => {
		impl<$($t),*> InputValue for ($($t),*) where $($t: InputValue),* {
			fn parse(s: &str) -> ($($t),*) {
				let mut tokens = s.split_whitespace();
				let t = ($($t::parse(tokens.next().unwrap())),*);
				t
			}
		}
	}
}
parse_tuple!(A, B);
parse_tuple!(A, B, C);

// ===

fn main() {
    let (n, m): (usize, usize) = read();
    let distances: Vec<i32> = readnc();
    let mut dimos: Vec<i32> = vec![];
    dimos.push(0);

    let mut last = 0;
    for di in distances {
        last += di;
        dimos.push(last);
    }

    let mut value: Vec<Vec<i32>> = vec![vec![0; n]; m];
    for i in 0..n {
        let v: Vec<i32> = readnc();
        for j in 0..m {
            value[j][i] = v[j];
        }
    }

    let mut table: Vec<Vec<i64>> = vec![];
    for i in 0..5005 {
        table.push(vec![0; i+5]);
    }

    for j in 0..m {
        let val = &value[j];
        let mut row: Vec<(&i32, usize)> = val.into_iter().zip((0..n).into_iter()).collect();
        row.sort_by(|a, b| a.0.cmp(b.0));
        row.reverse();


        let mut tree: BTreeSet<i32> = BTreeSet::new();
        tree.insert(-1 as i32);
        tree.insert(n as i32);

        for (&val, idx) in row {
            let ty: i32 = larger(idx as i32, n as i32, &tree) as i32;
            let fx: i32 = (smaller(-1 as i32, idx as i32, &tree) + 1) as i32;
            let ty = ty as usize;
            let fx = fx as usize;

            // println!("({},{}),({},{})",idx,ty,fx,idx);

            let v = val as i64;
            table[idx][fx] += v;
            table[idx][idx+1] -= v;
            table[ty][fx] -= v;
            table[ty][idx+1] += v;

            tree.insert(idx as i32);
        }
    }

    for i in 0..table.len() {
        for j in 1..table[i].len() {
            table[i][j] += table[i][j-1];
        }
    }
    for j in 0..table.len() {
        for i in 1..table.len() {
            if j < table[i].len() && j < table[i-1].len() {
                table[i][j] += table[i-1][j];
            }
        }
    }

    let mut ans: i64 = 0;
    for i in 0..n {
        for j in 0..(i+1) {
            let d: i64 = (dimos[i] - dimos[j]) as i64;
            ans = max(ans, table[i][j] - d);
        }
    }

    println!("{}", ans);
}

fn larger<T : std::cmp::Ord + Copy>(num: T, max: T, tree: &BTreeSet<T>) -> T {
    let mut range = tree.range((Excluded(&num), Unbounded));
    if let Some(&nx) = range.next() {
        nx
    } else {
        max
    }
}

fn smaller<T : std::cmp::Ord + Copy>(min: T, num: T, tree: &BTreeSet<T>) -> T {
    let mut range = tree.range((Unbounded, Excluded(&num))).rev();
    if let Some(&pv) = range.next() {
        pv
    } else {
        min
    }
}
